INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What are common causes of hallucination in LLM systems, and how does RAG help mitigate them?', '{"subcategory": "Root Causes of LLM Hallucinations & Retrieval Grounding Mitigation", "key_points": [{"id": "KP1", "description": "Identify primary root causes of hallucinations in Large Language Models.", "required": true, "acceptable_evidence": ["Technical keywords: parametric memory limitations, statistical next-token prediction, knowledge cutoffs, exposure bias, out-of-distribution prompts, compression loss.", "Explains that LLMs predict tokens based on probabilistic distribution rather than factual retrieval, leading to plausible-sounding confabulations when training data is sparse, outdated, or absent.", "Highlights lack of source-attribution mechanisms in standalone autoregressive decoding."]}, {"id": "KP2", "description": "Explain how Retrieval-Augmented Generation (RAG) grounds model outputs via external context injection.", "required": true, "acceptable_evidence": ["Technical keywords: non-parametric knowledge base, grounded prompt injection, in-context learning, provenance, source citations.", "Details how RAG supplies authoritative, deterministic enterprise documents directly into the prompt context window, constraining the LLM generation space.", "Explains that forcing the model to cite specific chunk IDs or quotes eliminates reliance on stale parametric weights."]}, {"id": "KP3", "description": "Detail prompt constraints and strict negative rejection fallback mechanisms.", "required": true, "acceptable_evidence": ["Technical keywords: system prompt constraints, strict boundary enforcement, I don''t know fallback, zero-shot guardrails, citation verification.", "Explains configuring system prompts with explicit negative constraints: ''Answer strictly using only the provided context. If the answer cannot be found in the context, explicitly respond: I do not have enough information to answer.''", "Describes runtime verification checking generated assertions against retrieved text tokens."]}], "critical_failures": ["Claims hallucinations occur solely due to low model parameter counts and can be completely eliminated by increasing model size without retrieval.", "Fails to mention prompt negative fallback instructions or source context constraints as RAG grounding mechanisms.", "Asserts that fine-tuning is superior to RAG for dynamic real-time knowledge grounding without risk of hallucination."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What are effective approaches to reduce hallucinations in LLM-based systems before and during data retrieval and generation?', '{"subcategory": "Pre-Retrieval, In-Retrieval, and Post-Generation Hallucination Prevention Pipeline", "key_points": [{"id": "KP1", "description": "Implement pre-retrieval query optimization to prevent semantic drift and ambiguity.", "required": true, "acceptable_evidence": ["Technical keywords: HyDE (Hypothetical Document Embeddings), query rewriting, multi-query expansion, intent classification, query routing.", "Explains transforming ambiguous user queries into clear, search-optimized variants before hitting the vector store to avoid retrieving irrelevant noise.", "Describes extracting filters (dates, department, product codes) into structured metadata constraints."]}, {"id": "KP2", "description": "Enforce high-precision retrieval filtering and cross-encoder reranking during retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid search (dense + BM25), cosine thresholding, cross-encoder reranking, context pruning, lost-in-the-middle mitigation.", "Details setting hard similarity score thresholds (e.g. cosine > 0.70) to drop low-confidence chunks.", "Explains applying a cross-encoder (e.g., BGE-Reranker, Cohere) to evaluate full query-document attention pairs, ensuring only top relevant chunks enter the prompt."]}, {"id": "KP3", "description": "Deploy post-generation verification, hallucination detection, and fallback gating.", "required": true, "acceptable_evidence": ["Technical keywords: self-consistency checks, LLM-as-a-judge, NLI (Natural Language Inference) entailment, Faithfulness evaluation, fallback routing.", "Details evaluating generated text with NLI models (premise = context, hypothesis = answer) to detect factual contradictions or ungrounded claims.", "Explains automated escalation to human support or returning canned disclaimers if faithfulness falls below threshold (e.g. < 0.85)."]}], "critical_failures": ["Claims hallucination prevention is solved entirely during generation by lowering model temperature to 0.", "Omits retrieval-stage filtering and reranking, passing raw top-k vector matches directly into generation.", "Fails to establish post-generation entailment or verification checks."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'EASY', 'SPECIFIC', 60, 'What are the advantages of using Milvus, and how does it support scalability, multi-tenancy, and performance?', '{"subcategory": "Milvus Vector Database: Distributed Cloud-Native Architecture, Partitioning & Performance", "key_points": [{"id": "KP1", "description": "Explain Milvus distributed architecture separating compute nodes and cloud-native storage.", "required": true, "acceptable_evidence": ["Technical keywords: coordinator nodes (RootCoord, QueryCoord, DataCoord), QueryNodes, DataNodes, MinIO/S3 object storage, Apache Pulsar/Kafka message bus.", "Explains disaggregated storage-compute separation enabling independent auto-scaling of search workers (QueryNodes) and index building workers (DataNodes).", "Details persistent write-ahead logging (WAL) via Kafka/Pulsar streaming log broker."]}, {"id": "KP2", "description": "Detail multi-tenancy implementation using Collections, Partitions, and Partition Keys.", "required": true, "acceptable_evidence": ["Technical keywords: collections, physical partitions, partition keys, tenant_id metadata scalar filtering, RBAC data isolation.", "Explains that Milvus supports multi-tenancy through partition keys where queries are routed directly to specific partition segments, avoiding full collection scans.", "Contrasts collection-level isolation (strict security, higher overhead) with partition-key tenancy (millions of tenants, low resource footprint)."]}, {"id": "KP3", "description": "Analyze ANN indexing strategies (HNSW, IVF-Flat, SCaNN) and high-throughput query performance.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW (Hierarchical Navigable Small World), IVF_FLAT, IVF_SQ8, M, efConstruction, efSearch, GPU indexing (Knowhere).", "Explains HNSW graph indexing providing low-latency ($<15ms$) high-recall search by navigating multi-layer proximity graphs.", "Details vector quantization (SQ8) memory compression trade-offs vs raw vector recall."]}], "critical_failures": ["Confuses Milvus with an embedded vector store like Chroma or FAISS, failing to recognize its distributed microservice architecture.", "Claims Milvus multi-tenancy can only be achieved by running separate physical database clusters for each tenant.", "Asserts that vector indices cannot be modified or recomputed once created in Milvus."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'EASY', 'SPECIFIC', 60, 'What are the differences between Pinecone and Milvus in terms of indexing and performance?', '{"subcategory": "Architectural Comparison: Pinecone vs Milvus on Indexing, Multi-Tenancy & Performance", "key_points": [{"id": "KP1", "description": "Compare infrastructure operational models: fully managed proprietary SaaS (Pinecone) vs distributed open-source / cloud-native (Milvus).", "required": true, "acceptable_evidence": ["Technical keywords: serverless vs pod-based architecture, open-source distributed vs proprietary black-box, VPC peering, self-hosted Kubernetes (Milvus Operator), vendor lock-in.", "Contrasts Pinecone''s turnkey zero-ops managed SaaS with Milvus''s customizable deployment on Kubernetes/EKS with local storage and object store backends.", "Highlights enterprise compliance and data sovereignty advantages of self-hosting Milvus in private VPCs."]}, {"id": "KP2", "description": "Contrast indexing mechanisms and parameter configurability between Pinecone and Milvus.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, IVF_FLAT, SCaNN, Knowhere engine, proprietary ANN graph index, efSearch tuning, build-time vs query-time index parameters.", "Explains that Milvus exposes low-level index controls ($M$, $efConstruction$, $efSearch$, clustering centroids $nlist$, quantization) across multiple algorithms.", "Explains that Pinecone abstracts index algorithms behind proprietary graph/clustering implementations with limited algorithmic parameter tuning."]}, {"id": "KP3", "description": "Evaluate multi-tenancy strategies and cost-performance trade-offs at scale.", "required": true, "acceptable_evidence": ["Technical keywords: namespaces (Pinecone) vs partition keys (Milvus), metadata filtering throughput, p99 latency under concurrent write/read load, cost per million vectors.", "Explains Pinecone namespaces provide metadata-isolated logical partitions suitable for moderate multitenancy, but can face cost scaling under billions of vectors.", "Details Milvus partition key routing achieving high QPS across massive multitenant datasets with lower total cost of ownership on commoditized hardware."]}], "critical_failures": ["Claims Pinecone is open-source software that can be self-hosted in an on-premises air-gapped data center.", "Asserts that Milvus does not support metadata filtering or multi-tenancy.", "Claims there is zero latency difference between serverless API calls over public internet and in-cluster VPC Milvus deployment."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What are the key considerations when designing a RAG system, particularly in terms of data quality, retrieval accuracy, and prompt design?', '{"subcategory": "Comprehensive RAG Architectural Design: Data Ingestion Quality, Hybrid Retrieval & Prompt Engineering", "key_points": [{"id": "KP1", "description": "Architect data quality pipelines across ingestion, document parsing, cleaning, and structural normalization.", "required": true, "acceptable_evidence": ["Technical keywords: OCR, layout-aware parsing, Docling, Unstructured, boilerplate stripping, table structure preservation (HTML/Markdown tables), metadata enrichment.", "Explains that raw text extraction fails on tables and multi-column documents, necessitating layout-aware parsers to retain semantic bounding boxes and tabular headers.", "Details enriching each chunk with structured metadata (document_id, section_hierarchy, timestamp, access_tier)."]}, {"id": "KP2", "description": "Design high-precision retrieval using hybrid search and cross-encoder reranking.", "required": true, "acceptable_evidence": ["Technical keywords: dense semantic search, sparse lexical BM25, Reciprocal Rank Fusion (RRF), cross-encoder reranking, cosine similarity thresholding.", "Explains combining dense embeddings (concept matching) with BM25 (exact keyword/part-number matching) using RRF: $RRF(d) = \\sum \\frac{1}{60 + r_i(d)}$.", "Details filtering candidate pools (e.g. top-50) down to top-5 using a cross-encoder to resolve relevance before context construction."]}, {"id": "KP3", "description": "Engineer robust prompt context windows incorporating system guardrails and citation tracking.", "required": true, "acceptable_evidence": ["Technical keywords: token budget allocation, lost-in-the-middle layout, XML delimiter tagging (<context>, <query>), strict negative rejection constraints, source attribution.", "Explains placing critical instructions at prompt boundaries and organizing context chunks in structured XML blocks with explicit source IDs.", "Instructs the LLM to refuse answering if the retrieved chunks do not provide conclusive evidence."]}, {"id": "KP4", "description": "Analyze operational trade-offs across relevance recall, latency SLAs, and infrastructure cost.", "required": false, "acceptable_evidence": ["Technical keywords: p95 latency budget, embedding API costs, cross-encoder latency overhead (100-300ms), cache hit rate (Semantic Cache).", "Explains balancing reranker quality against latency budgets, employing semantic caching in Redis for frequent queries to reduce end-to-end response time."]}], "critical_failures": ["Recommends passing unstructured raw text chunks without layout cleaning or tabular preservation directly to the vector store.", "Relies purely on vector similarity search without lexical or reranking stages for mission-critical enterprise queries.", "Fails to provide prompt rejection constraints to handle insufficient context."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What are the key differences between an Agentic AI solution and a standard Retrieval-Augmented Generation (RAG) system, and what does Agentic AI mean to you in a production context?', '{"subcategory": "Architectural Evolution: Standard RAG Pipelines vs Production Agentic AI Systems", "key_points": [{"id": "KP1", "description": "Contrast linear DAG pipeline execution of Standard RAG with cyclic reasoning loops of Agentic AI.", "required": true, "acceptable_evidence": ["Technical keywords: static DAG vs cyclic control loop, ReAct (Reason + Act), dynamic multi-step planning, iterative reflection, StateGraph.", "Explains that Standard RAG is a deterministic one-shot pipeline: Query $\\rightarrow$ Retrieve $\\rightarrow$ Augment $\\rightarrow$ Generate.", "Details Agentic AI as an autonomous state machine that evaluates intermediate results, decides if additional retrieval is needed, decomposes queries into sub-tasks, and refines plans dynamically."]}, {"id": "KP2", "description": "Explain tool orchestration and transactional external system execution in production Agentic AI.", "required": true, "acceptable_evidence": ["Technical keywords: tool calling / function calling, Model Context Protocol (MCP), external APIs, database CRUD operations, environment actuation.", "Contrasts RAG''s read-only knowledge synthesis with an agent''s ability to mutate enterprise state (e.g. creating tickets, executing SQL queries, booking appointments).", "Explains schema validation and deterministic argument parsing prior to tool execution."]}, {"id": "KP3", "description": "Detail state management, checkpointing, error recovery, and Human-in-the-Loop (HITL) governance in production.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph checkpointing, thread persistence, time-travel debugging, HITL interrupts, audit logging, rollback mechanisms.", "Explains how stateful graphs maintain conversational context and multi-turn execution history in persistent backends (PostgreSQL/Redis).", "Details enforcing human approval gates before high-impact or financial actions are triggered."]}, {"id": "KP4", "description": "Analyze production trade-offs between Standard RAG and Agentic systems in latency, cost, and non-determinism.", "required": false, "acceptable_evidence": ["Technical keywords: multi-turn latency compounding, token consumption bloat, loop guardrails (max_iterations), prompt injection attack surface.", "Explains that while agents solve complex multi-hop queries, they introduce latency (3-10s vs <1.5s for RAG) and risk infinite execution loops without hard guardrails."]}], "critical_failures": ["Claims Agentic AI is simply Standard RAG with a larger LLM context window.", "Fails to recognize that Agentic AI utilizes cyclic reasoning loops and dynamic tool calling rather than linear retrieval.", "Ignores safety risks and the necessity of Human-in-the-Loop (HITL) authorization for write actions in production."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What are the key steps involved in building a RAG pipeline, including data preprocessing, embedding, retrieval, and reranking?', '{"subcategory": "End-to-End RAG Pipeline Architecture: Preprocessing, Embeddings, Retrieval & Cross-Encoder Reranking", "key_points": [{"id": "KP1", "description": "Detail data preprocessing and semantic-preserving document chunking.", "required": true, "acceptable_evidence": ["Technical keywords: document parsing (Docling/PyMuPDF), text normalization, recursive character splitting, semantic chunking, chunk size (500-1000 tokens), chunk overlap (10-20%).", "Explains parsing PDF/HTML layouts, stripping extraneous headers/footers, and splitting text with sliding window overlap to maintain context across chunk boundaries.", "Details attaching deterministic metadata tags (title, section, last_updated) for filtered indexing."]}, {"id": "KP2", "description": "Explain embedding generation and high-dimensional vector database indexing.", "required": true, "acceptable_evidence": ["Technical keywords: bi-encoder embedding models (e.g., all-MiniLM-L6-v2, BGE-large, text-embedding-3-small), vector database (Milvus/Pinecone/pgvector), HNSW indexing, cosine similarity.", "Explains converting text chunks independently into dense vector representations ($d=384$ to $1536$) and populating an ANN index.", "Details query vectorization at inference time to perform approximate nearest neighbor candidate retrieval."]}, {"id": "KP3", "description": "Explain the role and mathematical mechanism of cross-encoder reranking.", "required": true, "acceptable_evidence": ["Technical keywords: bi-encoder vs cross-encoder, full cross-attention, query-document concatenation `[CLS] query [SEP] doc [SEP]`, BGE-Reranker, Cohere Rerank, scoring relevance logit.", "Explains why bi-encoders trade representation precision for search speed, necessitating a cross-encoder second pass where query and document tokens attend to each other simultaneously across all transformer layers.", "Details taking top-30 candidate chunks from vector/hybrid search, scoring them via cross-encoder, and selecting top-3 to 5 chunks for context injection."]}, {"id": "KP4", "description": "Evaluate the latency versus quality trade-off introduced by reranking stages.", "required": false, "acceptable_evidence": ["Technical keywords: latency overhead (100-250ms), throughput bottlenecks, GPU acceleration, candidate pool sizing.", "Explains that reranking adds computational overhead per request, making candidate pool sizing critical (e.g. reranking 20 chunks adds $\\sim 80ms$, reranking 100 chunks adds $>300ms$)."]}], "critical_failures": ["Claims cross-encoders compute separate vector embeddings for queries and documents in isolation.", "Omits the reranking stage or claims bi-encoder vector similarity provides optimal semantic relevance on complex multi-clause queries.", "Ignores chunk overlap during preprocessing, causing broken semantic clauses across document boundaries."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What are the limitations of using AWS Lambda for preprocessing and embedding, and how did you address them?', '{"subcategory": "Serverless Preprocessing & Embedding on AWS Lambda: Execution Limits & Containerized Solutions", "key_points": [{"id": "KP1", "description": "Identify core architectural limitations of AWS Lambda for ML document processing and embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: 15-minute execution timeout, 10 GB ephemeral `/tmp` storage, 10 GB memory limit, 250 MB unzipped deployment package limit, cold starts, lack of GPU acceleration.", "Explains that massive document batches (1000-page PDFs) exceed Lambda''s 15-minute execution limit and memory limits during heavy OCR or embedding operations.", "Details model loading latency caused by large PyTorch / SentenceTransformer binaries during container cold starts."]}, {"id": "KP2", "description": "Detail architectural mitigations using Lambda Container Images, EFS, and external inference endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Lambda container images (up to 10 GB), Amazon EFS mount for shared model cache, provisioned concurrency, offloading to Amazon Bedrock or SageMaker Serverless Inference.", "Explains packaging heavy dependencies (PyTorch, transformers) in Docker container images hosted on ECR up to 10 GB.", "Details mounting an Amazon EFS volume to store model weights locally across warm invocations, or calling Bedrock Titan / SageMaker endpoints for embedding generation to keep Lambda purely orchestrational."]}, {"id": "KP3", "description": "Architect asynchronous distributed chunking workflows via AWS Step Functions and SQS.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Step Functions distributed map state, SQS message queuing, S3 event triggers, Dead Letter Queues (DLQ), idempotency.", "Details breaking large multi-page PDF ingestion into parallel tasks: Step Functions fans out page-level extraction to separate Lambda workers.", "Explains DLQ error routing and S3 checkpointing ensuring partial failure recovery without restarting entire batch jobs."]}], "critical_failures": ["Claims AWS Lambda can easily run 2-hour heavy PyTorch batch processing jobs with dedicated GPU acceleration out-of-the-box.", "Fails to address the 15-minute execution timeout or package size limits when discussing heavy embedding dependencies.", "Recommends synchronous single-Lambda processing for enterprise-scale multi-gigabyte document corpora."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between traditional RAG, agentic RAG, and graph-based RAG approaches?', '{"subcategory": "Architectural Paradigms: Traditional RAG vs Agentic RAG vs Graph-Based RAG (GraphRAG)", "key_points": [{"id": "KP1", "description": "Analyze Traditional RAG: linear pipeline, deterministic top-k vector retrieval, and context augmentation.", "required": true, "acceptable_evidence": ["Technical keywords: linear DAG, bi-encoder similarity, top-k chunks, fixed context injection, low latency (<1s), single-turn fact lookup.", "Explains that Traditional RAG executes a single-step vector retrieval and passes retrieved text to the prompt, excelling at straightforward question answering.", "Highlights limitations: cannot perform multi-hop reasoning, lacks self-correction, fails on global thematic questions across entire corpora."]}, {"id": "KP2", "description": "Analyze Agentic RAG: dynamic query routing, multi-step iterative search, and self-reflective evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct loops, query decomposition, tool use, LangGraph state machine, self-correction, corrective RAG (CRAG).", "Explains that Agentic RAG inspects retrieval quality; if retrieved chunks are irrelevant or incomplete, the agent rewrites queries, queries alternative sources, and synthesizes multi-part answers.", "Trade-offs: higher latency (2-8 seconds), higher LLM token cost, potential execution loops without strict termination criteria."]}, {"id": "KP3", "description": "Analyze Graph-based RAG (GraphRAG): knowledge graph entity extraction, relationship traversal, and community summarization.", "required": true, "acceptable_evidence": ["Technical keywords: Knowledge Graphs, Neo4j, entity-relation-entity triples, community detection (Leiden algorithm), global dataset queries, multi-hop path traversal.", "Explains how GraphRAG structures unstructured text into connected knowledge graphs, enabling complex multi-hop relational queries (''How are entities X and Y connected through vendor Z?'').", "Trade-offs: extremely high ingestion cost and indexing latency due to entity extraction LLM calls, high graph schema maintenance overhead."]}], "critical_failures": ["Claims GraphRAG and Traditional RAG use identical indexing and differ only in prompt formatting.", "Asserts that Agentic RAG has the same latency and operational cost as Traditional RAG.", "Fails to identify multi-hop relational discovery as the core advantage of GraphRAG over vector similarity."]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between using RAG for unstructured data versus querying structured data directly from SQL databases?', '{"subcategory": "Data Modality Trade-Offs: RAG on Unstructured Text vs Deterministic SQL on Structured Data", "key_points": [{"id": "KP1", "description": "Contrast probabilistic semantic retrieval over unstructured text with deterministic relational querying in SQL.", "required": true, "acceptable_evidence": ["Technical keywords: unstructured semantic search vs structured ACID queries, vector similarity vs exact relational algebra, probabilistic vs deterministic guarantees.", "Explains that RAG is optimized for unstructured prose, policies, and manuals where meaning is linguistic and query targets are contextual.", "Explains that SQL is strictly required for aggregations, arithmetic, financial ledgers, and exact relational filtering (e.g. SUM, AVG, COUNT, JOIN) where probabilistic vector search yields erroneous results."]}, {"id": "KP2", "description": "Detail hybrid Text-to-SQL architecture with schema linking and query validation.", "required": true, "acceptable_evidence": ["Technical keywords: Text-to-SQL, schema linking, DDL prompt injection, read-only database credentials, AST / sqlglot validation, SQL injection prevention.", "Explains using an LLM to generate SQL by injecting schema definitions, table foreign keys, and few-shot examples into context.", "Details validating generated SQL queries against a parser/linter before execution to block destructive statements (DROP, UPDATE, DELETE) and syntax errors."]}, {"id": "KP3", "description": "Architect unified enterprise systems combining unstructured RAG and structured SQL querying.", "required": true, "acceptable_evidence": ["Technical keywords: query routing agent, metadata-driven hybrid systems, post-query LLM synthesis, latency and compute trade-offs.", "Details using an intent classifier / supervisor agent: routing numeric/tabular questions to SQL engines and policy/text questions to vector stores.", "Explains passing structured SQL result tables back to the LLM to format comprehensive user-facing natural language responses."]}], "critical_failures": ["Recommends using vector embeddings and similarity search to calculate accurate mathematical sums or financial aggregations on tabular data.", "Allows raw LLM-generated SQL queries to execute directly on production databases without read-only restrictions or syntax validation.", "Claims structured SQL databases are obsolete and should be completely replaced by vector stores."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between using a dedicated vector database versus extending a relational database with vector capabilities?', '{"subcategory": "Vector Architecture: Dedicated Vector DBs (Milvus, Pinecone) vs Relational Vector Extensions (pgvector)", "key_points": [{"id": "KP1", "description": "Evaluate dedicated vector databases (Milvus, Pinecone, Qdrant) for massive scale and specialized search operations.", "required": true, "acceptable_evidence": ["Technical keywords: distributed storage-compute disaggregation, billions of vectors, high QPS, dedicated HNSW/IVF acceleration, SIMD/GPU optimizations, dynamic partition keys.", "Explains that dedicated vector stores are architected specifically for vector-first workloads, scaling query nodes independently and sustaining thousands of queries per second over 50M+ vectors.", "Highlights specialized features such as hardware vector acceleration, automatic quantization, and native multi-tenancy."]}, {"id": "KP2", "description": "Evaluate relational database vector extensions (PostgreSQL with pgvector) for operational simplicity and transactional ACID consistency.", "required": true, "acceptable_evidence": ["Technical keywords: pgvector, ACID transactions, relational JOINs, unified infrastructure, IVFFlat / HNSW index in Postgres, maintenance_work_mem, shared_buffers.", "Explains pgvector allows storing embeddings directly alongside core relational entity tables in existing Postgres instances, eliminating dual-write sync issues and reducing infrastructure sprawl.", "Enables executing single-query relational filtering combined with vector ordering: `SELECT * FROM docs WHERE tenant_id = 5 ORDER BY embedding <=> query_vec LIMIT 5;`."]}, {"id": "KP3", "description": "Analyze performance break-even points, indexing memory overhead, and architectural selection criteria.", "required": true, "acceptable_evidence": ["Technical keywords: memory footprint (HNSW graph in RAM), vacuum overhead, write amplification, scale threshold (<1M-5M vectors vs >20M vectors).", "Explains pgvector works exceptionally well under 1-5 million vectors where Postgres shared buffers can accommodate HNSW indices in RAM.", "Details how at 10M-50M+ vectors, Postgres suffers from severe memory contention, slow index builds, and replication bottlenecks, making dedicated vector databases (Milvus) the superior choice."]}], "critical_failures": ["Claims pgvector provides superior query throughput and horizontal scaling compared to distributed Milvus clusters at 100 million vector scale.", "Ignores transactional consistency and zero-ETL benefits of pgvector for small-to-medium datasets already housed in Postgres.", "Asserts that dedicated vector databases can easily execute complex ACID relational joins across disparate relational tables."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between using a simple RAG pipeline versus a multi-agent system for complex workflows?', '{"subcategory": "Workflow Complexity Trade-Offs: Simple RAG Pipelines vs Multi-Agent Orchestration", "key_points": [{"id": "KP1", "description": "Evaluate simple RAG pipelines: low latency, deterministic execution, and operational predictability.", "required": true, "acceptable_evidence": ["Technical keywords: single-turn execution, deterministic DAG, low token consumption, sub-second latency (<1.5s), ease of debugging, straightforward evaluation.", "Explains that for standard informational Q&A where the required answer resides in a few document chunks, a simple RAG pipeline is cost-effective, reliable, and easily observable.", "Highlights minimal failure modes compared to multi-agent state machines."]}, {"id": "KP2", "description": "Evaluate multi-agent systems: task decomposition, dynamic planning, tool specialization, and iterative refinement.", "required": true, "acceptable_evidence": ["Technical keywords: supervisor-worker pattern, specialized role agents (researcher, coder, reviewer), stateful graph, sub-task delegation, tool execution.", "Explains that complex workflows requiring multi-source synthesis, code execution, validation, and step-by-step reasoning require specialized agents coordinating under a supervisor orchestrator.", "Details how individual agents can use isolated tools and tailored system prompts to perform distinct sub-tasks."]}, {"id": "KP3", "description": "Analyze production trade-offs in latency, compounding error rates, cost, and debugging complexity.", "required": true, "acceptable_evidence": ["Technical keywords: cascading errors, latency compounding (5-20s), exponential token usage, non-deterministic agent divergence, cycle limits.", "Explains that multi-agent systems suffer from compounding errors where one hallucinated intermediate step derails subsequent agents.", "Details cost and latency multiplication across multiple LLM reasoning calls, requiring strict maximum-hop limits and robust checkpointing."]}], "critical_failures": ["Recommends building a complex 5-agent system for simple single-turn factual document Q&A.", "Fails to address cascading failure risks, token cost explosion, and multi-second latency overhead in multi-agent workflows.", "Claims simple RAG can autonomously handle multi-step workflows requiring tool mutations and iterative code debugging."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What are your key interests within the generative AI space, and how do you plan to build on your experience with RAG and agent-based systems?', '{"subcategory": "Generative AI Systems Roadmapping: Advanced RAG, Agentic Autonomy & Model Optimization", "key_points": [{"id": "KP1", "description": "Articulate focus areas across advanced retrieval engineering and graph-augmented grounding.", "required": true, "acceptable_evidence": ["Technical keywords: GraphRAG, hybrid sparse-dense retrieval, semantic caching, contextual chunking, late interaction (ColBERT), agentic memory.", "Discusses advancing RAG beyond basic vector search into hybrid graph-vector topologies that enable global corpus reasoning and multi-hop relationship exploration.", "Highlights interest in token-efficient contextual retrieval and multi-vector representations."]}, {"id": "KP2", "description": "Detail practical roadmap for multi-agent orchestration, tool standards, and deterministic safety.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, Model Context Protocol (MCP), agentic workflows, HITL (Human-in-the-Loop), guardrail sandboxing, state persistence.", "Discusses scaling agentic automation from prototype scripts to resilient production state machines using LangGraph.", "Emphasizes adoption of standardized tool interfaces via MCP and robust safety governance for write-capable autonomous agents."]}, {"id": "KP3", "description": "Address production engineering rigor: evaluation frameworks, observability, and cost-efficiency.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS, DeepEval, OpenTelemetry, LangSmith/Arize Phoenix, SLIs/SLAs, prompt compression, small language model (SLM) routing.", "Emphasizes moving away from subjective prompt tinkering toward quantitative, automated CI/CD evaluation pipelines.", "Details optimizing cost and latency by routing routine tasks to fine-tuned distilled models while reserving frontier LLMs for complex reasoning."]}], "critical_failures": ["Provides vague non-technical generalities about ''making AI smarter'' without mentioning specific architectural systems (LangGraph, MCP, GraphRAG, evaluation).", "Ignores operational constraints like latency, cost, observability, and guardrails in production AI roadmaps.", "Fails to connect personal technical background to actionable architectural scaling."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What business problem did your RAG system solve, and how did it impact metrics such as average handling time and operational cost?', '{"subcategory": "Enterprise Business Impact: Call Center RAG Deployment, AHT Reduction & Operational ROI", "key_points": [{"id": "KP1", "description": "Identify the core business problem and knowledge fragmentation in customer call centers.", "required": true, "acceptable_evidence": ["Technical keywords: call center agent cognitive load, fragmented knowledge silos, outdated PDF manuals, long hold times, high Average Handle Time (AHT), inconsistent answers.", "Explains that call center support agents spent excessive time manually searching through hundreds of complex warranty, troubleshooting, and policy manuals while customers waited on hold.", "Details inconsistent customer guidance resulting in low First Call Resolution (FCR) and increased call escalation rates."]}, {"id": "KP2", "description": "Describe the end-to-end RAG architecture deployed to assist frontline agents.", "required": true, "acceptable_evidence": ["Technical keywords: ingestion pipeline, Docling parsing, vector database (Milvus), hybrid retrieval, cross-encoder reranking, Claude / Bedrock generation, agent UI copilot.", "Details an ingestion pipeline parsing technical documents into semantically coherent chunks stored in Milvus with hybrid BM25 and dense indexing.", "Explains providing call center agents with sub-2-second answers with exact page citations and clickable reference excerpts directly in their CRM desktop."]}, {"id": "KP3", "description": "Quantify measured operational metrics and business ROI impact.", "required": true, "acceptable_evidence": ["Technical keywords: Average Handle Time (AHT) reduction (e.g. 25-40%), First Contact Resolution (FCR) improvement, Customer Satisfaction (CSAT), operational cost savings.", "Quantifies tangible improvements: reducing AHT from 10 minutes to under 6.5 minutes per call, increasing FCR from 68% to 84%, and boosting CSAT scores.", "Details financial ROI from reduced agent onboarding time and decreased tier-2 escalation volume."]}], "critical_failures": ["Describes technical architecture in isolation without defining the underlying business problem or operational pain points.", "Fails to provide quantitative business metrics (AHT, FCR, CSAT, operational cost reduction).", "Presents the system as an unmonitored customer-facing chatbot when the use case was an agent-assist copilot with verification workflows."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What changes did you implement when evolving the system from a basic RAG pipeline to an agentic AI solution with task automation?', '{"key_points": [{"id": "KP1", "description": "Transition from passive retrieval to action execution: extending the pipeline beyond knowledge lookup to trigger transactional enterprise APIs (e.g. CRM ticket creation, booking service appointments).", "required": true, "acceptable_evidence": ["Technical keywords: task automation, tool invocation, external APIs, transactional execution, passive RAG vs active agent", "Explains evolving from static question-answering to automated end-to-end task fulfillment", "Integrates tools for querying customer CRM records and creating service dispatch tickets directly"]}, {"id": "KP2", "description": "Stateful workflow orchestration: implementing cyclic graphs (LangGraph StateGraph) with state schemas to support multi-turn dialogue, iterative reasoning, and dynamic branch routing.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, cyclic orchestration, state persistence, conditional edges, dialogue buffer", "Replaced linear sequential chains with cyclic state graphs capable of evaluating intermediate outputs and branching", "Persists conversation state across multiple turns so the agent can execute multi-step troubleshooting sequences"]}, {"id": "KP3", "description": "Safety guardrails and Human-in-the-Loop (HITL) integration: introducing Pydantic parameter validation, idempotency checks, and approval gates for irreversible actions.", "required": true, "acceptable_evidence": ["Technical keywords: HITL approval, LangGraph interrupt, Pydantic schema validation, idempotency, safety gates", "Implements validation gates before firing write operations to prevent unintended mutations", "Pauses execution to require human technician confirmation on high-consequence tasks"]}], "critical_failures": ["Describing simple prompt adjustments rather than architectural changes for API task automation", "Failing to explain stateful orchestration (e.g. LangGraph) required for multi-step agent actions", "Omitting validation guardrails and Human-in-the-Loop controls for automated tool execution"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What chunking strategies did you evaluate for document processing, and how did you determine the optimal approach and overlap ratio?', '{"subcategory": "Document Chunking Optimization: Strategy Evaluation, Sizing, Overlap Ratios & Context Preservation", "key_points": [{"id": "KP1", "description": "Compare evaluated chunking strategies: fixed-size, recursive character splitting, and semantic chunking.", "required": true, "acceptable_evidence": ["Technical keywords: fixed-size chunking, recursive character splitting, semantic similarity chunking, sentence splitting, layout/document structure awareness.", "Explains fixed-size chunking splits text rigidly at token boundaries, often severing sentences mid-thought.", "Details recursive character splitting respecting structural delimiters (`\\n\\n`, `\\n`, ` `, ``), keeping paragraphs intact.", "Details semantic chunking measuring cosine distance between consecutive sentence embeddings and creating breakpoints when topic shift exceeds a statistical threshold."]}, {"id": "KP2", "description": "Determine optimal chunk size and sliding window overlap ratio based on domain nuance.", "required": true, "acceptable_evidence": ["Technical keywords: token window budget, 256 vs 512 vs 1024 tokens, overlap ratio (10% to 20% / 50-100 tokens), context boundary preservation.", "Explains selecting 500-600 token chunks with a 15% (75 token) overlap as optimal balance: small enough for high embedding specificity, large enough to contain complete semantic concepts.", "Explains that overlap prevents critical entities or clause conditions located at chunk borders from being lost."]}, {"id": "KP3", "description": "Analyze retrieval quality and indexing cost trade-offs across chunking configurations.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval precision vs context recall, vector database storage bloat, embedding generation cost, reranker processing load.", "Explains small chunks (128 tokens) yield high vector similarity precision but lack sufficient context for LLM generation, requiring parent-document retrieval.", "Explains excessive overlap (>30%) balloons vector database index size and storage costs without improving retrieval recall."]}], "critical_failures": ["Claims fixed-size chunking without overlap has no negative impact on retrieval accuracy.", "Suggests setting chunk size equal to the maximum LLM context window (e.g. 100,000 tokens) for vector similarity search.", "Fails to explain how chunk overlap prevents information loss across split boundaries."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What chunking strategy did you use, and why did you choose recursive or semantic chunking over fixed-size chunking?', '{"subcategory": "Document Chunking Architectures: Recursive & Semantic Chunking vs Rigid Fixed-Size Splitting", "key_points": [{"id": "KP1", "description": "Explain structural limitations and failure modes of naive fixed-size chunking.", "required": true, "acceptable_evidence": ["Technical keywords: arbitrary token truncation, broken grammatical clauses, destroyed table rows, semantic context fracture.", "Explains that fixed-size splitters (e.g. every 500 characters) blindly cut through sentences, bullet points, and code blocks, generating fragmented chunks that distort embedding vectors.", "Highlights that vector representations of truncated phrases exhibit poor similarity match to user questions."]}, {"id": "KP2", "description": "Detail recursive character text splitting hierarchy and boundary preservation.", "required": true, "acceptable_evidence": ["Technical keywords: recursive splitting, separator hierarchy (`[''\\n\\n'', ''\\n'', ''. '', '' '', '''']`), paragraph coherence, tokenizers.", "Explains recursive splitters attempt to divide text by major natural boundaries (double newlines/paragraphs) first, falling back to sentences and spaces only when a paragraph exceeds maximum chunk size.", "Preserves topical cohesion by ensuring entire paragraphs or related lists remain grouped within a single chunk."]}, {"id": "KP3", "description": "Explain semantic chunking mechanism and why it provides superior retrieval grounding.", "required": true, "acceptable_evidence": ["Technical keywords: sentence embedding distance, sliding window cosine threshold, breakpoint detection, thematic boundary segmentation.", "Explains semantic chunking splits documents into individual sentences, generates embeddings for each, calculates cosine distance between adjacent sentences, and places boundaries where semantic similarity drops below a percentile threshold (e.g. 95th percentile).", "Ensures every chunk represents a coherent, single-topic concept regardless of character length."]}], "critical_failures": ["Asserts that recursive chunking relies on neural network embeddings to identify sentence boundaries.", "Fails to explain the hierarchical separator fallback logic in recursive splitting.", "Claims semantic chunking is computationally identical in speed and cost to character splitting."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What considerations go into selecting tools like Vertex AI Search for hybrid retrieval compared to traditional?', '{"subcategory": "Enterprise Search Platforms: Vertex AI Search vs Bespoke Open-Source Hybrid Retrieval", "key_points": [{"id": "KP1", "description": "Analyze Google Cloud Vertex AI Search: managed enterprise infrastructure, turnkey ingestion, and search ranking.", "required": true, "acceptable_evidence": ["Technical keywords: managed search engine, Google Search ranking models, multi-modal ingestion, automated OCR & layout parsing, zero-ops infrastructure.", "Explains Vertex AI Search provides a fully managed SaaS service bundling document parsing, vectorization, hybrid keyword-semantic search, and Google-quality ranking out-of-the-box.", "Highlights native integration with GCP BigQuery, Cloud Storage, and Google Workspace connectors."]}, {"id": "KP2", "description": "Analyze custom hybrid retrieval pipelines (e.g. Milvus / Elasticsearch + Cross-Encoder Rerankers).", "required": true, "acceptable_evidence": ["Technical keywords: open-source flexibility, custom embedding fine-tuning, domain-specific BM25 tuning, explicit RRF weighting, self-hosted cross-encoders, air-gapped deployment.", "Details custom pipelines allowing fine-grained control: selecting specialized domain embeddings (legal/biomedical), customizing tokenizers, tuning BM25 $k_1$ and $b$ parameters, and hosting in private VPCs.", "Contrasts full algorithmic transparency with Vertex AI Search''s proprietary black-box ranking."]}, {"id": "KP3", "description": "Evaluate architectural trade-offs: time-to-market, cost structure, data privacy, and customization.", "required": true, "acceptable_evidence": ["Technical keywords: operational overhead vs query pricing, vendor lock-in, data sovereignty, SLA guarantees, latency controls.", "Explains Vertex AI Search accelerates time-to-market with minimal engineering maintenance, but incurs per-query licensing costs and restricts custom ranking modifications.", "Details custom solutions demanding ongoing MLOps maintenance (index tuning, node sizing) but offering lower cost at massive query scale and complete data sovereignty."]}], "critical_failures": ["Claims Vertex AI Search is an open-source library that can be run on local developer laptops.", "Fails to articulate the trade-off between managed turnkey convenience and custom algorithmic control.", "Ignores cost scaling and vendor lock-in considerations when choosing between managed and bespoke search architectures."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What considerations guided your choice of tools such as LangChain, LangGraph, and like Milvus or Pinecone?', '{"subcategory": "Framework Orchestration Strategy: LangChain vs LangGraph vs Vector Stores (Milvus/Pinecone)", "key_points": [{"id": "KP1", "description": "Define distinct responsibilities: LangChain (compositional abstraction) vs LangGraph (stateful graph orchestration).", "required": true, "acceptable_evidence": ["Technical keywords: LCEL (LangChain Expression Language), linear chains, cyclic execution, StateGraph, checkpointing, multi-agent coordination.", "Explains LangChain is suited for linear, single-pass chains (prompt formatting, model calling, output parsing).", "Explains LangGraph is essential for complex agentic workflows requiring cycles, conditional routing, multi-turn state persistence, and human-in-the-loop approval interrupts."]}, {"id": "KP2", "description": "Analyze vector database selection: Milvus vs Pinecone based on infrastructure and multi-tenancy requirements.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed open-source Kubernetes vs Pinecone serverless SaaS, VPC security boundaries, partition key multitenancy, operational overhead.", "Explains choosing Milvus when enterprise policies mandate private VPC deployment on AWS EKS with billions of vectors, customizable HNSW indices, and tenant partition keys.", "Details choosing Pinecone for fast prototype deployments with zero infrastructure overhead and turnkey serverless scaling."]}, {"id": "KP3", "description": "Synthesize the unified architecture connecting orchestration with storage backends.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end integration, LangGraph agent nodes calling Milvus retriever tools, structured state schema, checkpoint persistence in Postgres.", "Details how LangGraph orchestrator nodes query Milvus via standardized retriever tools, update the centralized StateGraph schema with retrieved context, and invoke LLMs.", "Highlights decoupling orchestration logic from storage infrastructure for maintainability and vendor neutrality."]}], "critical_failures": ["Treats LangChain and LangGraph as mutually exclusive competitors rather than complementary layers within the same ecosystem.", "Claims LangChain linear chains are capable of managing complex stateful cycles and resumable checkpointing as cleanly as LangGraph.", "Fails to identify infrastructure ownership and operational burden differences between Milvus and Pinecone."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What considerations influenced your choice of infrastructure and tools such as AWS EKS, Docker, Bedrock, and like Milvus or Pinecone?', '{"key_points": [{"id": "KP1", "description": "Infrastructure orchestration choices: deploying core microservices (FastAPI ingestion, query orchestrator, guardrails) as Docker containers on AWS EKS with horizontal pod autoscaling (HPA) and managed nodegroups.", "required": true, "acceptable_evidence": ["Technical keywords: AWS EKS, Docker containers, Kubernetes, HPA, managed nodegroups, FastAPI", "Explains containerizing application components for portable CI/CD and autoscaling based on CPU/memory and request concurrency", "Details operational isolation between API serving pods and async worker pods"]}, {"id": "KP2", "description": "Foundation model hosting trade-offs: utilizing AWS Bedrock for managed serverless access to foundation models (Claude 3.5 Sonnet / Haiku) with built-in IAM security, SLAs, and zero infrastructure overhead compared to self-hosted LLMs.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, Claude 3.5 Sonnet, Claude 3 Haiku, IAM integration, managed LLM API, zero GPU maintenance", "Contrasts managed model endpoints against self-hosting open-weight models on expensive EC2 GPU instances (e.g. g5/p4d)", "Emphasizes VPC endpoints and enterprise compliance without data egress to public endpoints"]}, {"id": "KP3", "description": "Vector database selection trade-offs: choosing distributed Milvus on EKS or managed Pinecone based on self-hosted data ownership and VPC governance versus zero-ops serverless index management.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, Pinecone, self-hosted vs managed SaaS, VPC peering, data sovereignty, HNSW indexing", "Explains Milvus advantages for dedicated VPC isolation, high write throughput, and multi-tenancy partition keys", "Contrasts with Pinecone serverless simplicity and low maintenance overhead"]}, {"id": "KP4", "description": "Production operational integration: handling end-to-end security, latency SLAs, monitoring, and network topology across services.", "required": false, "acceptable_evidence": ["Technical keywords: AWS PrivateLink, VPC peering, CloudWatch, Prometheus, Grafana, OpenTelemetry", "Discusses latency budgeting across Kubernetes ingress, vector retrieval (<50ms), and Bedrock streaming tokens", "Covers secret management via AWS Secrets Manager and fine-grained IAM roles for service accounts (IRSA)"]}], "critical_failures": ["Failing to articulate the specific role and trade-off of AWS EKS, Bedrock, and the vector database in the architecture", "Confusing managed Bedrock model invocation with training models from scratch on EKS", "Ignoring VPC security, network isolation, or operational scalability considerations"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What considerations led you to choose specific tools like LangChain, sentence transformers, and Anthropic Claude for your RAG pipeline?', '{"subcategory": "Technology Stack Justification: LangChain, Sentence Transformers & Anthropic Claude in RAG", "key_points": [{"id": "KP1", "description": "Justify Sentence Transformers (e.g. all-MiniLM-L6-v2, BGE) for embedding generation.", "required": true, "acceptable_evidence": ["Technical keywords: local embedding inference, zero egress cost, deterministic latency, privacy/compliance, 384/768 dimensions, cosine similarity alignment.", "Explains selecting self-hosted Sentence Transformers over third-party APIs to eliminate external API network latency and avoid sending sensitive enterprise data to external third parties.", "Highlights cost-efficiency of running local CPU/GPU embedding inference during high-volume document batch ingestion."]}, {"id": "KP2", "description": "Justify Anthropic Claude for generation: extended context, reasoning fidelity, and prompt adherence.", "required": true, "acceptable_evidence": ["Technical keywords: Claude 3/3.5 Sonnet, 200k context window, low hallucination rate, XML tag parsing, instruction following, steerability.", "Explains Claude''s industry-leading adherence to complex system constraints and negative constraints (''Answer only using context, do not extrapolate'').", "Details Claude''s ability to handle long, multi-document contexts with minimal needle-in-a-haystack attention degradation."]}, {"id": "KP3", "description": "Justify LangChain as the modular orchestration and abstraction glue.", "required": true, "acceptable_evidence": ["Technical keywords: document loaders, text splitters, prompt templates, output parsers, retriever interfaces, vendor swappability.", "Details LangChain providing standardized interfaces to easily swap underlying embedding models, vector stores, or LLM providers without rewriting business logic.", "Explains utilizing built-in abstractions for prompt assembly, metadata extraction, and streaming token response handling."]}], "critical_failures": ["Claims Sentence Transformers is an LLM generation model rather than an embedding / bi-encoder representation model.", "Cannot articulate why Claude was selected over alternative models regarding instruction following and context handling.", "Fails to mention data privacy or latency/cost benefits when discussing self-hosted sentence transformers vs API embeddings."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What criteria did you use to balance keyword-based and semantic search, and how did you evaluate its effectiveness?', '{"subcategory": "Hybrid Search Balancing: Reciprocal Rank Fusion, Convex Combination & Retrieval Evaluation", "key_points": [{"id": "KP1", "description": "Explain criteria for balancing keyword-based (lexical/BM25) and semantic (dense vector) search.", "required": true, "acceptable_evidence": ["Technical keywords: lexical exact matching (acronyms, part numbers, error codes) vs dense semantic matching (intent, synonyms, conceptual queries), query intent classification.", "Explains that keyword search guarantees exact matches for technical terminology, product SKUs, and specific error codes where embeddings fail.", "Explains semantic search captures broad user phrasing, conceptual similarity, and multi-lingual queries where exact keywords are omitted."]}, {"id": "KP2", "description": "Detail candidate fusion mechanisms: Reciprocal Rank Fusion (RRF) and Alpha-Weighted Convex Combination.", "required": true, "acceptable_evidence": ["Technical keywords: RRF formula $RRF(d) = \\sum \\frac{1}{k + r(d)}$, constant $k=60$, alpha score weighting $\\alpha \\cdot S_{dense} + (1-\\alpha) \\cdot S_{sparse}$, score normalization (MinMax).", "Explains RRF merges ranked candidate lists based on relative position without requiring cross-score scale calibration, eliminating score distortion.", "Explains convex weighting requires normalizing BM25 and cosine scores before summing: $Score = 0.7 \\cdot Dense + 0.3 \\cdot Sparse$."]}, {"id": "KP3", "description": "Evaluate hybrid retrieval effectiveness using quantitative ranking metrics.", "required": true, "acceptable_evidence": ["Technical keywords: Recall@k, Precision@k, MRR (Mean Reciprocal Rank), NDCG@k, golden test dataset.", "Details benchmarking hybrid search against pure dense and pure sparse baselines across a curated ground-truth evaluation set.", "Demonstrates that hybrid retrieval consistently boosts Recall@10 (e.g. from 72% to 89%) and NDCG@5 compared to either standalone method."]}], "critical_failures": ["Claims semantic search completely renders keyword search obsolete in all enterprise domains.", "Fails to explain how rank fusion (RRF or score weighting) combines sparse and dense search results.", "Does not provide objective metrics (Recall@k, MRR, NDCG) to evaluate hybrid retrieval improvements."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What data is stored in long-term memory, and how does it support future retrieval and system performance?', '{"subcategory": "Agent Memory Architecture: Short-Term Working State vs Persistent Long-Term Knowledge Storage", "key_points": [{"id": "KP1", "description": "Distinguish between short-term conversational context and persistent long-term memory.", "required": true, "acceptable_evidence": ["Technical keywords: short-term scratchpad / active context window vs persistent long-term storage, working memory, episodic memory, semantic memory, user profiling.", "Explains short-term memory tracks active session dialogue turns, tool execution outputs, and scratchpad reasoning stored in-memory or session Redis caches.", "Explains long-term memory persists cross-session user preferences, historical interaction summaries, domain facts, and entity relationships across weeks or months."]}, {"id": "KP2", "description": "Detail what specific data is stored in long-term memory and storage technologies utilized.", "required": true, "acceptable_evidence": ["Technical keywords: user preferences, past query resolutions, extracted entity-attribute graphs, episodic interaction summaries, vector databases (Milvus/pgvector), NoSQL (DynamoDB/Redis), Knowledge Graphs.", "Details persisting structured entity records (e.g., user account IDs, vehicle models, unresolved claim statuses) and vectorized conversation summaries.", "Explains indexing summaries with timestamp and user_id metadata to enable fast deterministic filtering."]}, {"id": "KP3", "description": "Explain memory retrieval mechanisms, context budgeting, and privacy governance.", "required": true, "acceptable_evidence": ["Technical keywords: semantic similarity retrieval of memories, recency weighting, importance decay score, context window token budgeting, PII redaction, GDPR/CCPA data purging.", "Explains retrieving relevant long-term memories using hybrid semantic search and recency decay: $Score = \\alpha \\cdot Sim + \\beta \\cdot Recency$.", "Details redacting PII before long-term persistence and implementing TTL eviction policies to comply with privacy regulations."]}], "critical_failures": ["Confuses short-term conversational message history with persistent long-term vector/graph memory.", "Recommends stuffing entire historical multi-month chat logs directly into the LLM prompt without summarization or selective retrieval.", "Fails to mention data privacy, PII scrubbing, or user data eviction policies in persistent memory."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What data sources did you use for building your RAG system, and how did you preprocess and structure them for retrieval?', '{"subcategory": "Enterprise Knowledge Ingestion: Multi-Modal Data Sources, Preprocessing & Retrieval Structuring", "key_points": [{"id": "KP1", "description": "Identify diverse enterprise data sources and ingestion modalities.", "required": true, "acceptable_evidence": ["Technical keywords: unstructured PDFs (service manuals, warranties), HTML / Confluence wiki pages, JSON / XML API feeds, internal markdown docs, relational database exports.", "Details handling multi-format enterprise silos: complex multi-column PDFs with embedded diagrams, internal knowledge base wikis, and structured CRM customer logs.", "Explains automated S3 event-driven triggers capturing new or updated files for ingestion."]}, {"id": "KP2", "description": "Detail preprocessing, layout-aware parsing, and tabular structure extraction.", "required": true, "acceptable_evidence": ["Technical keywords: layout parsing (Docling, Unstructured, PyMuPDF), OCR (Tesseract/Textract), table extraction to Markdown/HTML, stripping headers/footers/page numbers.", "Explains extracting tables as structured Markdown or HTML syntax to preserve column-row relationships so numbers are not stripped of their header context.", "Details cleaning non-content artifacts (disclaimers, headers, page numbers) to avoid vector pollution."]}, {"id": "KP3", "description": "Structure extracted documents into metadata-enriched chunks for high-relevance retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: hierarchical metadata tagging (document_id, section_title, page_number, category, access_role, last_updated), recursive chunking, schema enforcement.", "Explains injecting hierarchical document breadcrumbs (e.g. `System > Electrical > Battery Charging > Troubleshooting`) directly into chunk text headers.", "Details attaching structured metadata payloads enabling strict pre-filtering (e.g. `filter: {''department'': ''engineering'', ''year'': 2026}`)."]}], "critical_failures": ["Flattens complex tabular documents into raw unformatted text strings, destroying tabular context and numerical meaning.", "Fails to attach structured metadata to chunks, making tenant or domain filtering impossible during retrieval.", "Ignores document parsing differences between text-heavy files, scanned PDFs, and wiki pages."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What data sources were used in your knowledge base, and how did you preprocess, clean, chunk, and embed unstructured content such as PDFs, HTML, and internal documentation?', '{"subcategory": "Unstructured Knowledge Ingestion: Preprocessing, Cleaning, Chunking & Embedding PDFs, HTML & Docs", "key_points": [{"id": "KP1", "description": "Clean and preprocess multi-format unstructured content (PDFs, HTML wikis, internal documentation).", "required": true, "acceptable_evidence": ["Technical keywords: layout parsing, Docling, BeautifulSoup, PyMuPDF, OCR, boilerplate stripping, Markdown conversion, table preservation.", "Explains parsing HTML by stripping script tags, navigation sidebars, and footers with BeautifulSoup to retain core body text in Markdown format.", "Details handling complex PDFs with Docling to preserve two-dimensional table structures and multi-column reading orders."]}, {"id": "KP2", "description": "Execute hierarchical or semantic chunking with metadata breadcrumbs.", "required": true, "acceptable_evidence": ["Technical keywords: recursive text splitting, semantic chunking, chunk size (500-800 tokens), overlap (10-15%), hierarchical context injection (document/section titles).", "Explains pre-pending chunk text with section breadcrumbs (`Document: EV Service Manual > Section: Battery Thermal Management`) to prevent context detachment.", "Details setting sliding window overlap to guarantee continuity across split boundaries."]}, {"id": "KP3", "description": "Generate dense vector embeddings and index into a production vector store with structured metadata.", "required": true, "acceptable_evidence": ["Technical keywords: bi-encoder embedding model (BGE, text-embedding-3, MiniLM), HNSW vector index, payload metadata filtering, batch embedding generation.", "Explains batch processing embeddings through high-throughput worker pools and populating vector indices with attached metadata (document_id, department, access_level).", "Details normalizing vector embeddings to unit length for fast inner-product cosine similarity search."]}], "critical_failures": ["Flattens unstructured multi-column PDFs without layout analysis, destroying reading order and tabular data.", "Fails to attach metadata to chunks, preventing filtered access control during retrieval.", "Treats raw HTML ingestion identically to plain text without stripping DOM boilerplate (navbars, scripts)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What do you think is the difference between fine tuning and RAG and what scenarios you use which one?', '{"subcategory": "Model Adaptation Strategy: Supervised Fine-Tuning (SFT/LoRA) vs Retrieval-Augmented Generation (RAG)", "key_points": [{"id": "KP1", "description": "Analyze core architectural differences between Fine-Tuning (parametric memory) and RAG (non-parametric external memory).", "required": true, "acceptable_evidence": ["Technical keywords: parametric weight updates vs non-parametric in-context retrieval, knowledge internalization vs runtime context injection, hallucination risks, catastrophic forgetting.", "Explains that Fine-Tuning modifies neural network weights to learn specific syntax, task tone, behavioral formats, or specialized jargon.", "Explains that RAG injects dynamic external documents into the LLM prompt at runtime, providing factual source ground truth without updating model weights."]}, {"id": "KP2", "description": "Define explicit production criteria and scenarios for selecting RAG over Fine-Tuning.", "required": true, "acceptable_evidence": ["Technical keywords: dynamic/frequently updated data, strict factual accuracy, source attribution/citations, audit compliance, low training cost.", "Explains choosing RAG when data changes frequently (daily product catalogs, real-time policy updates) because re-training fine-tuned models continuously is prohibitively expensive.", "Highlights RAG requirement when users demand verifiable page citations, document provenance, and strict verifiable grounding."]}, {"id": "KP3", "description": "Define production criteria and scenarios for selecting Fine-Tuning (or combining with RAG).", "required": true, "acceptable_evidence": ["Technical keywords: specialized output syntax (SQL, Cypher, structured JSON), domain vocabulary/tone, latency optimization (smaller distilled SLM), PEFT (LoRA/QLoRA).", "Explains choosing Fine-Tuning when teaching a model proprietary syntax (Text-to-SQL, domain-specific programming languages) or stylizing responses in a strict enterprise tone.", "Details using LoRA/QLoRA to distill a 70B teacher into an efficient 8B model to slash latency and compute cost, subsequently pairing it with RAG for up-to-date facts (Fine-Tuning for style, RAG for knowledge)."]}], "critical_failures": ["Claims Fine-Tuning is the preferred approach for injecting frequently updated dynamic facts and private documents into an LLM.", "Asserts that fine-tuning an LLM guarantees zero hallucinations on factual Q&A.", "Fails to distinguish between teaching style/format (Fine-Tuning) versus injecting external factual knowledge (RAG)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What embedding models and did you use, and how did you evaluate and choose between them?', '{"subcategory": "Embedding Model Selection & Evaluation: Dimensionality, MTEB Benchmarking & Index Compatibility", "key_points": [{"id": "KP1", "description": "Explain embedding representation mechanisms and conversion of text queries/documents into dense vector spaces.", "required": true, "acceptable_evidence": ["Technical keywords: bi-encoder architecture, token pooling (mean pooling / CLS pooling), semantic vector space, cosine distance, semantic clustering.", "Explains that transformer bi-encoders process text sequences and pool contextual token hidden states into fixed-dimensional vectors where semantic similarity correlates with geometric proximity.", "Details asymmetric query-document encoding (e.g. BGE or E5 instruction prefixes `query: ` vs `passage: `)."]}, {"id": "KP2", "description": "Evaluate embedding models on MTEB benchmarks, domain suitability, and trade-offs.", "required": true, "acceptable_evidence": ["Technical keywords: MTEB (Massive Text Embedding Benchmark), NDCG@10, all-MiniLM-L6-v2 (384-d), BGE-large (1024-d), text-embedding-3-small/large (1536/3072-d), Matryoshka representation learning.", "Explains benchmarking candidate models across MTEB retrieval tasks, balancing retrieval quality (NDCG@10) against vector dimension and memory consumption.", "Details Matryoshka embeddings allowing truncation from 1536-d to 512-d with minimal accuracy loss to save vector store RAM."]}, {"id": "KP3", "description": "Analyze infrastructure cost, inference latency, and vector database indexing compatibility.", "required": true, "acceptable_evidence": ["Technical keywords: RAM footprint in HNSW graph, latency per million tokens, GPU vs CPU batch throughput, API egress cost vs self-hosted ONNX/TensorRT.", "Explains that higher dimensions (1536-d vs 384-d) quadruple RAM requirements in HNSW vector indices, increasing vector database infrastructure spend.", "Details optimizing inference throughput using quantized models (INT8/FP16) or ONNX Runtime to maintain sub-30ms embedding latency."]}], "critical_failures": ["Assumes larger embedding dimensionality automatically guarantees superior enterprise retrieval without benchmarking domain specificity.", "Ignores vector database RAM overhead directly correlated with embedding dimensions in graph-based indices.", "Fails to explain the role of pooling (mean/CLS) in converting transformer token representations into sentence vectors."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What evaluation frameworks and metrics did you use to assess both retrieval and generation quality in your system, and how were these evaluations implemented?', '{"subcategory": "Dual-Track RAG Evaluation Frameworks: Component-Level Retrieval vs End-to-End Generation Metrics", "key_points": [{"id": "KP1", "description": "Isolate and evaluate retrieval component performance using objective ranking metrics.", "required": true, "acceptable_evidence": ["Technical keywords: Context Recall, Context Precision, Hit Rate@k, MRR (Mean Reciprocal Rank), NDCG@k, golden test dataset with ground-truth chunk IDs.", "Explains evaluating the retriever independently from the generator to prevent confounding error analysis.", "Details measuring whether the true supporting document chunks were retrieved within top-k results (Context Recall) and ranked near the top (Context Precision / MRR)."]}, {"id": "KP2", "description": "Evaluate generation component quality using automated LLM-as-a-judge frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas, DeepEval, Faithfulness (groundedness), Answer Relevance, Semantic Answer Similarity (SAS), LLM-as-a-judge with chain-of-thought.", "Explains Faithfulness: evaluating what percentage of claims in the generated response can be directly inferred from the retrieved context (hallucination detector).", "Explains Answer Relevance: evaluating whether the response directly addresses the user query without irrelevant fluff."]}, {"id": "KP3", "description": "Describe evaluation implementation, synthetic testset generation, and iterative system improvement loops.", "required": true, "acceptable_evidence": ["Technical keywords: synthetic test data generation (question-context-ground_truth triples), CI/CD regression gating, error triage diagnosis.", "Details building a representative golden dataset of 150-200 curated queries with expert-verified ground truth.", "Explains using evaluation score drops to drive specific pipeline fixes: low Context Recall triggers chunking/embedding changes; low Faithfulness triggers prompt constraint tightening."]}], "critical_failures": ["Evaluates RAG systems solely using BLEU or ROUGE against arbitrary reference texts without measuring retrieval precision or faithfulness.", "Fails to decouple retrieval evaluation from generation evaluation, making root-cause diagnosis impossible.", "Omits the Faithfulness metric as the primary mechanism for detecting generated hallucinations."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What evaluation metrics did you use across different stages such as input validation, retrieval, ranking, and generation?', '{"key_points": [{"id": "KP1", "description": "Input validation stage metrics: evaluating query intent classification accuracy, jailbreak/injection detection precision, and PII masking recall.", "required": true, "acceptable_evidence": ["Technical keywords: input validation metrics, intent classification accuracy, prompt injection detection rate, PII masking recall (Presidio), latency overhead", "Measures the accuracy of routing queries to appropriate sub-domains before retrieval", "Evaluates the percentage of adversarial inputs and sensitive personal data successfully intercepted"]}, {"id": "KP2", "description": "Retrieval stage metrics: assessing candidate recall and ranking across dense and sparse retrievers using Hit Rate@K, Recall@K, and MRR.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, Recall@K, Mean Reciprocal Rank (MRR), candidate pool coverage, top-k recall", "Quantifies whether gold-standard passages are retrieved in the top candidate pool (top-20 to top-50)", "Tracks the rank position of the first relevant chunk returned by vector and BM25 searches"]}, {"id": "KP3", "description": "Ranking/Reranking stage metrics: measuring NDCG@K, Precision@K, and cross-encoder score calibration on pruned top candidates.", "required": true, "acceptable_evidence": ["Technical keywords: NDCG@K, Precision@K (top-3/top-5), reranker score calibration, candidate noise filtering", "Evaluates how accurately the cross-encoder ranks the most relevant chunks at rank 1 and 2", "Measures precision improvements after pruning the candidate pool down to the final context window"]}, {"id": "KP4", "description": "Generation stage metrics: evaluating synthesis fidelity and prompt compliance using Faithfulness/Groundedness, Answer Relevance, and Semantic Similarity.", "required": false, "acceptable_evidence": ["Technical keywords: Faithfulness, Groundedness, Answer Relevance, Semantic Similarity, RAGAS, LLM-as-a-judge", "Measures whether all factual statements in the output are entailed by retrieved context", "Scores how directly the generated response addresses the original user question without irrelevant filler"]}], "critical_failures": ["Failing to detail metrics across the specific stages asked (input validation, retrieval, ranking, generation)", "Conflating retrieval metrics (Recall/MRR) with generation metrics (Faithfulness)", "Omitting input validation evaluation entirely"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What evaluation metrics do you use for retrieval systems, and how are recall@k, precision@k, and F1 score computed and interpreted?', '{"subcategory": "Information Retrieval Metrics: Recall@k, Precision@k & F1 Score Mathematical Formulation & Interpretation", "key_points": [{"id": "KP1", "description": "Define mathematical formulation and conceptual interpretation of Precision@k in retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: $Precision@k = \\frac{|\\text{Relevant Documents in Top } k|}{k}$, false positives, context window noise, prompt token efficiency.", "Explains Precision@k measures the fraction of retrieved top-k documents that are genuinely relevant to the query.", "Highlights that low Precision@k pollutes the LLM context window with irrelevant distractors, causing hallucinations and lost-in-the-middle degradation."]}, {"id": "KP2", "description": "Define mathematical formulation and conceptual interpretation of Recall@k in retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: $Recall@k = \\frac{|\\text{Relevant Documents in Top } k|}{|\\text{Total Relevant Documents in Corpus}|}$, false negatives, information omission, missing evidence.", "Explains Recall@k measures the proportion of all relevant documents existing in the corpus that were successfully captured in the top-k result list.", "Highlights that low Recall@k guarantees failure: if the critical fact is not retrieved, the generator cannot answer correctly."]}, {"id": "KP3", "description": "Formulate F1@k score and analyze the precision-recall trade-off when selecting top-k.", "required": true, "acceptable_evidence": ["Technical keywords: $F1@k = 2 \\cdot \\frac{Precision@k \\cdot Recall@k}{Precision@k + Recall@k}$, harmonic mean, top-k tuning, reranker integration.", "Explains that increasing $k$ (e.g. from 3 to 20) generally boosts Recall@k but depresses Precision@k as more marginal chunks are included.", "Details using cross-encoder reranking to solve this tension: retrieve at high $k$ (e.g. $k=30$) to maximize recall, then rerank and select top-3 to maximize precision before prompt injection."]}], "critical_failures": ["Inverts the formulas or conceptual definitions of Precision@k and Recall@k.", "Claims Precision@k can be accurately calculated without knowing the ground-truth relevance of retrieved documents.", "Fails to explain how varying $k$ affects the fundamental trade-off between precision and recall."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What evaluation strategies and metrics did you use to assess the performance of your RAG and agentic systems?', '{"key_points": [{"id": "KP1", "description": "Component-level RAG evaluation using established retrieval metrics: assessing vector and hybrid search accuracy via Hit Rate@K, MRR (Mean Reciprocal Rank), and NDCG.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, MRR (Mean Reciprocal Rank), NDCG@K, Precision@K, Recall@K", "Explains evaluating whether the gold chunk containing the required answer appears in top retrieval candidates (top-3/top-5)", "Contrasts retrieval accuracy before and after reranking"]}, {"id": "KP2", "description": "Triad/RAGAS end-to-end evaluation: measuring Context Relevance, Groundedness/Faithfulness, and Answer Relevance using automated LLM-as-a-judge pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS, DeepEval, TruLens, Faithfulness, Context Relevance, Answer Relevance, Semantic Similarity", "Explains checking if claims in the LLM response are strictly entailed by retrieved context (hallucination scoring)", "Details Context Relevance to verify retrieved context contains minimal noisy/irrelevant tokens"]}, {"id": "KP3", "description": "Agentic system metrics: evaluating multi-step reasoning, tool-calling precision, goal trajectory completion rate, and recursion guardrail breaches.", "required": true, "acceptable_evidence": ["Technical keywords: tool selection accuracy, argument validation rate, goal completion rate, step trajectory efficiency, cycle limit", "Evaluates whether the orchestrator routes to the correct tool with valid schema parameters", "Measures recovery from tool invocation errors and percentage of unresolved agent loops"]}, {"id": "KP4", "description": "Business and operational production metrics: tracking Average Handling Time (AHT), First Contact Resolution (FCR), token latency (TTFT), and cost per resolved query.", "required": false, "acceptable_evidence": ["Technical keywords: AHT (Average Handling Time), FCR (First Contact Resolution), TTFT (Time to First Token), p95 latency, cost per interaction", "References quantitative benchmarks (e.g. AHT reduction from 10 min to 6.5 min, FCR improvement to 84%)", "Mentions golden dataset curation (e.g. 100-200 synthetic + human-verified QA pairs) for regression testing"]}], "critical_failures": ["Providing only vague qualitative statements without concrete metrics (Hit Rate, Faithfulness, Tool Call Accuracy)", "Confusing retrieval evaluation (MRR/Hit Rate) with generation evaluation (Faithfulness/Answer Relevance)", "Ignoring agentic-specific workflow metrics such as tool-calling accuracy and execution trajectory"]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What factors did you consider when selecting technologies such as LangChain, LangGraph, Milvus, and AWS Bedrock for your RAG pipeline?', '{"subcategory": "Enterprise RAG Infrastructure Selection: LangChain, LangGraph, Milvus & AWS Bedrock", "key_points": [{"id": "KP1", "description": "Justify Amazon Bedrock as the secure foundation model and inference gateway.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, serverless LLM API, data privacy (no training on enterprise prompts), VPC endpoints (PrivateLink), Bedrock Guardrails, multi-model choice (Claude 3.5, Llama 3, Titan).", "Explains Bedrock guarantees strict enterprise data security compliance (SOC 2, HIPAA, ISO), routing traffic over AWS private backbones without data exposure to public endpoints.", "Highlights unified API access to frontier models (Claude 3.5 Sonnet) and native Bedrock Guardrails for PII redaction and safety filtering."]}, {"id": "KP2", "description": "Justify Milvus on AWS EKS as the scalable enterprise vector storage engine.", "required": true, "acceptable_evidence": ["Technical keywords: distributed Milvus on EKS, EBS GP3 / S3 storage disaggregation, HNSW indexing, partition keys, multi-tenant isolation, enterprise scale.", "Explains deploying Milvus via Helm/Operator on EKS ensures high-throughput ANN vector search across millions of enterprise vectors within private subnets.", "Details leveraging partition keys to isolate tenant and departmental records under strict RBAC."]}, {"id": "KP3", "description": "Justify LangChain and LangGraph for compositional orchestration and stateful agentic workflows.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain modular components (loaders, splitters, chains) + LangGraph stateful execution graphs, cyclic reasoning, persistence checkpointers.", "Explains combining LangChain''s document processing utilities with LangGraph''s robust stateful orchestration to handle multi-step query decomposition and fallback routing.", "Details persisting execution state in RDS PostgreSQL checkpointers for resumable multi-turn dialogues."]}], "critical_failures": ["Claims AWS Bedrock uses customer enterprise prompt data to train public foundation models.", "Cannot articulate the difference between running Milvus within a private EKS cluster versus using public third-party SaaS vector databases.", "Fails to justify the architectural synergy between Bedrock, Milvus, and LangGraph in an enterprise cloud environment."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'HARD', 'SPECIFIC', 120, 'What factors influenced your decision to transition from Pinecone to PGVector and later to Milvus, and what trade-offs did you consider?', '{"subcategory": "Vector Database Evolution & Migration Journey: Pinecone -> PGVector -> Distributed Milvus", "key_points": [{"id": "KP1", "description": "Phase 1 (Pinecone): Initial rapid prototyping, ease of setup, and subsequent limitations.", "required": true, "acceptable_evidence": ["Technical keywords: managed SaaS, fast POC time-to-market, cloud egress latency, spiraling costs at vector scale, lack of private VPC data governance.", "Explains starting with Pinecone for zero-ops prototype acceleration, validating retrieval viability within days.", "Details encountering limitations as data scaled: high monthly costs per index pod, latency overhead calling external SaaS APIs, and enterprise security restrictions on sending unencrypted proprietary data outside AWS VPC."]}, {"id": "KP2", "description": "Phase 2 (PGVector): Infrastructure consolidation, transactional consistency, and scaling boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL with pgvector extension, ACID compliance, unified relational data, zero dual-write overhead, HNSW in Postgres, memory contention.", "Explains migrating to PGVector in Amazon RDS to eliminate SaaS vendor lock-in, keep data strictly in-VPC, and query relational data and vector embeddings in a single ACID query.", "Details hitting performance ceilings beyond 3-5 million vectors: Postgres shared memory contention, massive vacuuming overhead, slow index builds, and query latency spikes under concurrent traffic."]}, {"id": "KP3", "description": "Phase 3 (Milvus): Transition to dedicated cloud-native distributed architecture for enterprise production.", "required": true, "acceptable_evidence": ["Technical keywords: distributed Milvus on EKS, storage-compute disaggregation, MinIO/S3 object storage, high QPS, low p99 latency (<20ms), partition keys.", "Explains migrating to Milvus to support 20M+ vectors with horizontal auto-scaling QueryNodes and dedicated GPU/SIMD HNSW index acceleration.", "Details achieving sub-20ms search latency, zero Postgres database resource degradation, and native multi-tenancy via partition keys."]}, {"id": "KP4", "description": "Analyze technical and operational trade-offs evaluated at each migration transition.", "required": false, "acceptable_evidence": ["Technical keywords: operational complexity (zero-ops SaaS vs shared DB vs Kubernetes cluster maintenance), total cost of ownership (TCO), migration data sync scripts.", "Summarizes trade-offs: SaaS convenience vs Relational consolidation vs Dedicated distributed power, justifying Milvus as the only option sustaining enterprise SLAs at scale."]}], "critical_failures": ["Claims PGVector outperforms dedicated Milvus clusters at 50 million vectors with high concurrent traffic.", "Cannot articulate why an organization would migrate away from a simple relational vector extension to a dedicated distributed vector database.", "Ignores data security, VPC isolation, and egress cost factors in the initial migration from external SaaS (Pinecone)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What frameworks have you used for LLM orchestration and retrieval, and how do tools like LangChain and LlamaIndex compare in your experience?', '{"subcategory": "LLM Orchestration Frameworks: Architectural Comparison of LangChain vs LlamaIndex", "key_points": [{"id": "KP1", "description": "Analyze core architectural philosophy: LangChain (general-purpose agent/chain orchestration) vs LlamaIndex (data-centric search/indexing).", "required": true, "acceptable_evidence": ["Technical keywords: action-oriented agent orchestration vs data-centric indexing, LCEL, document data structures, query engines, composable retrievers.", "Explains LangChain was built from an action/workflow perspective: chaining prompts, model invocations, tool calling, and autonomous agent loops.", "Explains LlamaIndex was purpose-built from a data perspective: ingesting, transforming, indexing, and executing structured/unstructured search over complex heterogeneous data structures."]}, {"id": "KP2", "description": "Compare retrieval and indexing abstractions: LlamaIndex query engines vs LangChain retrievers.", "required": true, "acceptable_evidence": ["Technical keywords: hierarchical node parsing, RouterQueryEngine, SubQuestionQueryEngine, auto-merging retriever, vector store retriever.", "Details LlamaIndex''s out-of-the-box advanced retrieval structures: parent-child chunk linking, recursive retrieval, knowledge graph indices, and semantic table querying.", "Contrasts with LangChain requiring developers to manually stitch together separate text splitters, vector stores, and custom chain logic."]}, {"id": "KP3", "description": "Evaluate selection criteria and hybrid enterprise integration patterns.", "required": true, "acceptable_evidence": ["Technical keywords: LlamaIndex for advanced search indexing + LangChain/LangGraph for multi-agent workflows, tool wrapping, production maintainability.", "Recommends using LlamaIndex when primary complexity lies in document understanding, hierarchical parsing, and multi-document query routing.", "Explains wrapping LlamaIndex query engines as specialized tools within LangGraph agent state machines, capitalizing on the core strengths of both frameworks."]}], "critical_failures": ["Claims LangChain and LlamaIndex are completely identical with no differences in architectural design or specialized focus.", "Fails to identify LlamaIndex''s specialized data indexing, node parsing, and hierarchical retrieval capabilities.", "Asserts that one framework must be completely chosen to the absolute exclusion of the other in enterprise systems."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What guardrails and optimization techniques did you implement in your system, such as re-ranking, query optimization, and conversation history handling?', '{"subcategory": "Runtime Guardrails & Query Optimization: Dynamic Rewriting, Guardrails & Context Hygiene", "key_points": [{"id": "KP1", "description": "Implement pre-retrieval query optimization and conversational contextualization.", "required": true, "acceptable_evidence": ["Technical keywords: conversational query rewriting, coreference resolution, multi-query expansion, HyDE, intent classification.", "Explains resolving pronouns and elliptical references in multi-turn chat (e.g. converting ''What is its battery warranty?'' into ''What is the battery warranty for Tesla Model Y?'').", "Details expanding queries into multi-perspective semantic variants to increase retrieval coverage."]}, {"id": "KP2", "description": "Enforce input/output security guardrails and PII sanitization.", "required": true, "acceptable_evidence": ["Technical keywords: NeMo Guardrails, Llama Guard, Presidio, prompt injection defense, jailbreak detection, regex/NER PII redaction, toxic content filtering.", "Details pre-execution interceptors scanning user input for adversarial prompt injections, system prompt leak attempts, and sensitive PII (SSN, credit cards).", "Explains post-generation output guardrails validating responses for toxicity, brand compliance, and leakage of internal system prompts."]}, {"id": "KP3", "description": "Optimize conversational history handling and context window token budgeting.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window buffer, recursive message summarization, token budget allocation, lost-in-the-middle prevention, state checkpointing.", "Explains maintaining recent conversation turns verbatim (e.g. last 3 turns) while recursively condensing earlier dialogue history into concise factual summaries.", "Details strict token allocation: allocating 20% tokens to conversation history, 60% to retrieved context, 10% to system instructions, and reserving 10% for generation."]}], "critical_failures": ["Allows raw conversational user inputs with unresolved pronouns to hit vector databases directly without coreference rewriting.", "Passes unredacted PII or unvalidated user inputs directly to the LLM without injection detection guardrails.", "Appends unbounded chat history into the LLM prompt until context window exhaustion occurs."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What happens in scenarios where multiple retrieved chunks have similar keyword matches, and how does your system resolve relevance?', '{"subcategory": "Disambiguation Architecture: Resolving Conflicting & Overlapping Chunks with Similar Keyword Matches", "key_points": [{"id": "KP1", "description": "Explain the root problem: high lexical collision among near-duplicate document versions or identical clause text.", "required": true, "acceptable_evidence": ["Technical keywords: keyword collision, version drift, polysemy, conflicting policy updates, obsolete documents, near-duplicate chunks.", "Explains that multiple retrieved chunks may share near-identical keyword matches (e.g. warranty terms from 2021, 2023, and 2025 manuals) causing keyword search to return conflicting answers.", "Highlights that pure BM25 or un-reranked vector search cannot distinguish temporal precedence or applicable jurisdiction."]}, {"id": "KP2", "description": "Resolve relevance using cross-encoder deep semantic attention and temporal metadata filtering.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder cross-attention, metadata filtering (`is_active: true`, `effective_date`, `version`), document authority score, recency boosting.", "Explains applying cross-encoder rerankers that examine full query-clause interaction, scoring true semantic fit above surface-level keyword frequency.", "Details using deterministic metadata filters to instantly discard outdated versions, or applying mathematical recency decay boosts: $FinalScore = Score_{retrieval} \\cdot e^{-\\lambda \\cdot \\Delta t}$."]}, {"id": "KP3", "description": "Implement contextual disambiguation and explicit LLM conflict synthesis prompts.", "required": true, "acceptable_evidence": ["Technical keywords: parent-document retrieval, surrounding paragraph context, conflict resolution prompting, clarifying follow-up question generation.", "Explains retrieving the parent document header to contextualize ambiguous chunks (e.g. Chunk A applies to ''Commercial Fleets'' while Chunk B applies to ''Personal Consumers'').", "Details prompting the LLM to highlight discrepancies or ask the user a clarifying question if multiple equally valid conflicting policies are retrieved."]}], "critical_failures": ["Assumes whichever chunk has the highest raw BM25 keyword count is automatically the correct answer.", "Fails to utilize document metadata (timestamps, version tags, categories) to resolve conflicts.", "Does not provide cross-encoder reranking or context expansion as disambiguation mechanisms."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What if it''s a more complex problem, like legal documents or law cases; how would you approach embedding those in the vector DB?', '{"subcategory": "Domain-Specific Legal RAG: Specialized Embeddings, Hierarchical Indexing & Statutory Precedence", "key_points": [{"id": "KP1", "description": "Identify domain challenges in legal document corpora: dense citations, cross-referencing, and subtle contractual language.", "required": true, "acceptable_evidence": ["Technical keywords: statutory hierarchy, precedent case law, cross-references (supra/infra), boilerplate clauses, dense multi-page definitions, jurisdictional nuance.", "Explains that standard embedding models fail on legal text because legally distinct concepts share near-identical vocabulary, while subtle wording (''shall'' vs ''may'') changes contractual obligations.", "Highlights high document length (100+ page contracts/appellate briefs) and extensive inter-document statutory citations."]}, {"id": "KP2", "description": "Select and fine-tune specialized legal embedding models and late-interaction representations.", "required": true, "acceptable_evidence": ["Technical keywords: domain-adapted embeddings (Legal-BERT, Law2Vec, voyage-law-2), contrastive fine-tuning on legal triples, late interaction (ColBERT).", "Explains deploying specialized legal embedding models trained on court decisions, statutory codes, and SEC filings to capture precise legal semantic nuances.", "Details fine-tuning embeddings using contrastive loss on query-case anchor triples (`(query, holding_passage, dissenting_passage)`)."]}, {"id": "KP3", "description": "Architect hierarchical parent-child indexing, citation graphs, and metadata structuring.", "required": true, "acceptable_evidence": ["Technical keywords: parent-child document retrieval, statutory section chunking, citation graph (Neo4j / NetworkX), metadata tagging (jurisdiction, court_level, decision_date, precedent_status).", "Explains chunking strictly along statutory articles, clauses, and sub-clauses rather than arbitrary character lengths.", "Details building a citation graph alongside the vector DB to traverse legal precedents and filter out overturned decisions (`is_precedent: true`)."]}], "critical_failures": ["Recommends naive 500-token fixed character chunking across legal contracts, severing contractual obligations from their definitions.", "Uses off-the-shelf general-domain embeddings without validating understanding of domain-specific legal terminology and statutory precedence.", "Fails to incorporate metadata filtering for jurisdiction, court hierarchy, or precedent validity."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What improvements would you make if you were to redesign your RAG system, based on challenges faced during implementation?', '{"subcategory": "Production RAG Retrospective: Architectural Bottlenecks, Lessons Learned & Redesign Roadmap", "key_points": [{"id": "KP1", "description": "Analyze implementation challenges faced in v1: naive chunking, retrieval noise, and high latency.", "required": true, "acceptable_evidence": ["Technical keywords: naive character chunking, tabular data corruption, retrieval noise/distractors, single-vector bottlenecks, lost-in-the-middle degradation, high p95 latency.", "Reflects on initial pitfalls: naive text chunking fractured technical tables and schematics, causing embedding distortion and hallucinated numerical answers.", "Details issues where pure vector retrieval returned semantically similar but factually irrelevant chunks, diluting the LLM''s attention."]}, {"id": "KP2", "description": "Architect redesign improvements across ingestion, hybrid search, and cross-encoder reranking.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware parsing (Docling), hierarchical parent-child chunking, hybrid search (dense + BM25 via RRF), cross-encoder reranker (BGE-Reranker).", "Details replacing naive splitters with Docling for structure-aware parsing and parent-document retrieval (indexing small 200-token child chunks for search, injecting 1000-token parent context into LLM).", "Details introducing hybrid BM25 + dense retrieval fused with RRF, followed by cross-encoder reranking to drastically improve Context Precision."]}, {"id": "KP3", "description": "Implement production observability, semantic caching, and automated evaluation guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: Redis semantic cache, asynchronous streaming, RAGAS / DeepEval automated regression CI/CD, OpenTelemetry / LangSmith tracing.", "Explains deploying a semantic cache in Redis to serve frequent repetitive queries in <100ms, slashing LLM inference costs by 30-40%.", "Details embedding automated RAGAS evaluation gates into GitHub Actions CI/CD to catch retrieval regressions before production releases."]}], "critical_failures": ["Claims the initial v1 RAG implementation had zero challenges or required no architectural adjustments.", "Fails to identify concrete technical enhancements (e.g. parent-document retrieval, reranking, hybrid search, semantic caching).", "Omits automated evaluation and observability when discussing production-readiness improvements."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What infrastructure and tools did you use to build and deploy your RAG system, and how did they integrate together?', '{"subcategory": "Full-Stack RAG Infrastructure: Containerized Microservices, Vector DB, Cloud & Model Layer", "key_points": [{"id": "KP1", "description": "Architect the ingestion and storage infrastructure layer on AWS.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3, AWS Lambda / Step Functions, Milvus on AWS EKS, EBS GP3 / S3 object storage, PostgreSQL RDS (metadata & checkpointers).", "Details storing raw source documents in S3, triggering asynchronous distributed extraction via Step Functions and Lambda container workers.", "Explains persisting vector indices in a distributed Milvus cluster deployed on EKS with persistent EBS storage and S3 segment backups."]}, {"id": "KP2", "description": "Architect the inference and API orchestration backend layer.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservices, Docker, AWS EKS / ALB (Application Load Balancer), LangGraph / LangChain, Amazon Bedrock (Claude 3.5 Sonnet / Titan Embeddings).", "Details exposing asynchronous FastAPI endpoints (`/v1/query`, `/v1/chat/stream`) containerized with Docker and orchestrated on Kubernetes behind an AWS ALB.", "Explains invoking Amazon Bedrock foundation models over private AWS VPC endpoints, streaming tokens back via Server-Sent Events (SSE)."]}, {"id": "KP3", "description": "Implement caching, observability, and infrastructure-as-code automation.", "required": true, "acceptable_evidence": ["Technical keywords: Redis / ElastiCache (semantic caching & session memory), Prometheus, Grafana, OpenTelemetry, Terraform / CloudFormation.", "Details deploying Redis ElastiCache for sub-50ms semantic caching and conversation session tracking.", "Explains provisioning all AWS resources declaratively using Terraform and monitoring p95 latency, token usage, and error budgets via Prometheus and Grafana dashboards."]}], "critical_failures": ["Describes an unscalable local setup (running everything on a single EC2 instance without Docker, EKS, or managed storage) as production architecture.", "Fails to explain how microservices, storage backends, and foundation models interconnect securely across VPC boundaries.", "Omits API gateway, load balancing, or asynchronous streaming considerations."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is a reranker, and how does a cross-encoder improve retrieval quality compared to a bi-encoder approach?', '{"subcategory": "Reranking Foundations: Bi-Encoder Vector Search vs Cross-Encoder Full Attention Mechanisms", "key_points": [{"id": "KP1", "description": "Define a reranker and explain why initial bi-encoder vector retrieval requires a second-stage pass.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval, bi-encoder compression bottleneck, vector dot product / cosine similarity, candidate retrieval vs precision ranking.", "Explains that a reranker is a scoring model that re-orders candidate documents retrieved in the initial search phase.", "Explains bi-encoders encode queries and documents independently into fixed-size vector representations, losing fine-grained cross-token interactions to enable fast approximate search."]}, {"id": "KP2", "description": "Explain the architectural mechanism of cross-encoders and contrast with bi-encoders.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder, full cross-attention across all transformer layers, joint token input `[CLS] query [SEP] document [SEP]`, classification head logit.", "Explains cross-encoders feed query and document tokens simultaneously into a single transformer model, allowing every query token to attend directly to every document token across all layers.", "Highlights that cross-encoders output a single calibrated relevance probability score without generating independent embeddings."]}, {"id": "KP3", "description": "Analyze retrieval quality improvements and computational latency trade-offs.", "required": true, "acceptable_evidence": ["Technical keywords: NDCG@5 boost, MRR improvement, computational complexity $O(N)$ vs precomputed $O(1)$, latency overhead (100-200ms), top-k selection.", "Explains cross-encoders significantly increase Context Precision and resolve complex semantic nuances that fool bi-encoders.", "Details why cross-encoders cannot be used for initial search across millions of documents (computationally prohibitive $O(N)$ transformer forward passes), making the two-stage retrieve-then-rerank pattern optimal."]}], "critical_failures": ["Claims cross-encoders produce vector embeddings that are stored and indexed in vector databases.", "Asserts that cross-encoders and bi-encoders have identical computational speed and memory complexity.", "Fails to explain that cross-encoders perform full joint cross-attention over query and document tokens simultaneously."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is hybrid chunking, and why did you choose to combine semantic and keyword-based chunking approaches in your system?', '{"subcategory": "Hybrid Chunking Strategies: Combining Semantic Boundary Detection with Structural Recursive Splitting", "key_points": [{"id": "KP1", "description": "Define hybrid chunking and why combining semantic and structural approaches outperforms standalone methods.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid chunking, structural recursive splitting + semantic similarity thresholding, document hierarchy preservation, variable length chunks.", "Explains hybrid chunking merges document structure awareness (markdown headers, paragraphs) with embedding-based semantic topic shift detection.", "Highlights that standalone recursive splitting can group unrelated thoughts if character limits allow, while pure semantic chunking can break structural tables or bulleted lists."]}, {"id": "KP2", "description": "Detail implementation mechanics of the hybrid chunking pipeline.", "required": true, "acceptable_evidence": ["Technical keywords: section-level structural splitting, sentence-level cosine distance evaluation, percentile breakpoint detection, minimum/maximum chunk length bounds.", "Details the two-pass process: Pass 1 parses document into high-level structural sections based on markdown/HTML headers; Pass 2 evaluates semantic distance between sentences within each section, splitting only when topic drift occurs while enforcing min/max token guardrails (e.g. 150 min, 600 max).", "Ensures chunks respect both human author structure and mathematical semantic uniformity."]}, {"id": "KP3", "description": "Analyze the impact on retrieval recall, precision, and downstream generation accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: high Context Precision, reduced noise, elimination of semantic fragmentation, embedding vector purity.", "Explains that hybrid chunks contain pure, single-topic concepts with complete contextual sentences, producing highly focused embedding vectors that match user queries with high cosine similarity.", "Prevents injecting unrelated paragraphs into the prompt, reducing LLM context confusion."]}], "critical_failures": ["Confuses hybrid chunking with hybrid search (BM25 + vector search).", "Claims hybrid chunking simply means running two different text splitters and indexing both sets of duplicate chunks.", "Fails to explain how structural boundaries and semantic distance metrics interact in hybrid chunking."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What is that golden data set like? Are you doing any one shot three short learnings here for hallucinations or how does it work?', '{"subcategory": "Ground Truth Calibration & Few-Shot Prompting: Curating Golden Datasets for Hallucination Detection", "key_points": [{"id": "KP1", "description": "Define the structure and composition of an enterprise RAG Golden Dataset.", "required": true, "acceptable_evidence": ["Technical keywords: Golden Dataset, curated evaluation tuples (query, retrieved_contexts, ground_truth_answer, ground_truth_contexts, metadata), SME validation.", "Explains that a golden dataset consists of 150-300 representative enterprise queries paired with verified factual answers and the exact supporting document chunk IDs.", "Details including diverse query archetypes: simple single-fact lookups, multi-document synthesis queries, negative out-of-scope queries, and adversarial prompt injections."]}, {"id": "KP2", "description": "Explain how few-shot in-context learning is applied to detect and evaluate hallucinations.", "required": true, "acceptable_evidence": ["Technical keywords: few-shot in-context learning, 1-shot / 3-shot prompting, LLM-as-a-judge, demonstration exemplars, Chain-of-Thought (CoT) reasoning.", "Explains injecting 2-3 explicit exemplar demonstrations into the evaluation prompt showing an input context, generated response, step-by-step reasoning, and final binary or calibrated score (`Faithful: Yes/No`).", "Demonstrates how few-shot calibration guides the evaluator LLM to catch subtle extrapolations and ungrounded factual assumptions."]}, {"id": "KP3", "description": "Detail automated hallucination benchmarking against the golden dataset in CI/CD pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: automated regression testing, Faithfulness threshold ($\\ge 0.90$), negative rejection accuracy, release gating.", "Details running the golden dataset across candidate prompt templates or retrieval parameter changes to measure hallucination rates before deployment.", "Ensures the system achieves 100% rejection accuracy on out-of-domain queries designed to trigger hallucinations."]}], "critical_failures": ["Claims a golden dataset consists solely of raw unannotated PDF documents without query-answer-context triples.", "Confuses few-shot learning for prompt evaluation with few-shot training/fine-tuning model weights.", "Fails to include negative/unanswerable queries in the golden evaluation dataset to measure hallucination fallbacks."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between keyword-based search and semantic search, and why did you combine them in a hybrid retrieval approach?', '{"subcategory": "Search Paradigms: Lexical Keyword Matching vs Dense Semantic Search & Hybrid Retrieval Synergy", "key_points": [{"id": "KP1", "description": "Analyze lexical keyword search (BM25 / TF-IDF): exact term matching, frequency weighting, and limitations.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, TF-IDF, inverted index, exact keyword matching, tokenizers/stemming, vocabulary mismatch problem, synonym failure.", "Explains BM25 scores documents based on term frequency and inverse document frequency with document length normalization.", "Strengths: exact matches for serial numbers, product codes, abbreviations, and rare proper nouns.", "Weaknesses: completely fails when queries use synonyms or conceptual paraphrasing without exact keyword overlap."]}, {"id": "KP2", "description": "Analyze dense semantic search: transformer embeddings, geometric proximity, and limitations.", "required": true, "acceptable_evidence": ["Technical keywords: dense vector embeddings, bi-encoder, cosine similarity / inner product, semantic intent, polysemy resolution, catastrophic failure on specific codes.", "Explains dense retrieval encodes semantic meaning into vector spaces, retrieving conceptually related documents even with zero shared keywords.", "Weaknesses: struggles with exact part numbers, specific codes (''Error-404-X''), and short acronyms where vector proximity clusters loosely."]}, {"id": "KP3", "description": "Synthesize why combining both in a hybrid retrieval architecture achieves superior enterprise recall and precision.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, Reciprocal Rank Fusion (RRF), complementary strengths, elimination of single-point retrieval failure.", "Explains that hybrid retrieval eliminates the blind spots of both approaches: BM25 guarantees precision for technical keywords, while dense search guarantees recall for conceptual inquiries.", "Details merging candidates via RRF ($RRF(d) = \\sum \\frac{1}{60 + r_i(d)}$) to construct a robust top-k candidate set for reranking."]}], "critical_failures": ["Claims semantic search completely eliminates the need for keyword search in all enterprise technical environments.", "Fails to identify exact alphanumeric codes (SKUs, error codes, part numbers) as the primary failure mode of dense embeddings.", "Does not explain how lexical and semantic results are merged into a unified candidate ranking."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between prompting, Retrieval-Augmented Generation (RAG), and fine-tuning, and when would you use each approach?', '{"subcategory": "AI Engineering Decision Framework: Prompt Engineering vs RAG vs Model Fine-Tuning", "key_points": [{"id": "KP1", "description": "Analyze Prompt Engineering: in-context instruction, few-shot examples, zero infrastructure overhead.", "required": true, "acceptable_evidence": ["Technical keywords: in-context learning, few-shot prompting, system instructions, rapid prototyping, zero training cost, context window limits.", "Explains prompt engineering uses pre-trained models out-of-the-box by optimizing instructions, delimiters, and few-shot exemplars.", "Best used for: quick experimentation, simple extraction, summarizing provided text, and defining output formatting without external knowledge needs."]}, {"id": "KP2", "description": "Analyze Retrieval-Augmented Generation (RAG): dynamic factual knowledge injection, external retrieval, verifiable citations.", "required": true, "acceptable_evidence": ["Technical keywords: external non-parametric knowledge, dynamic data freshness, source citations, vector search, low training compute, access control (RBAC).", "Explains RAG dynamically retrieves private, up-to-date enterprise documentation and injects it into context.", "Best used for: enterprise Q&A, customer support, legal/medical reference, and systems requiring verifiable source citations and daily data freshness."]}, {"id": "KP3", "description": "Analyze Fine-Tuning (SFT / PEFT): internalizing domain style, complex output schemas, and specialized syntax.", "required": true, "acceptable_evidence": ["Technical keywords: Supervised Fine-Tuning (SFT), LoRA/QLoRA, parameter updates, specialized task formatting (Text-to-SQL), latency/cost reduction via model distillation.", "Explains fine-tuning updates neural weights to master specialized task behavior, proprietary output schemas, or specific domain terminology.", "Best used for: domain-specific code generation, structured JSON/SQL generation, distilling 70B performance into 8B models, and enforcing strict conversational persona."]}, {"id": "KP4", "description": "Synthesize a decision matrix comparing cost, latency, data freshness, and maintenance complexity.", "required": false, "acceptable_evidence": ["Technical keywords: maintenance lifecycle, knowledge cutoff, data drift, deployment complexity.", "Details multi-dimensional trade-offs: Prompting (lowest cost, fastest) vs RAG (medium cost, dynamic data, high accuracy) vs Fine-Tuning (high training cost, static knowledge, high behavioral control)."]}], "critical_failures": ["Recommends Fine-Tuning as the primary solution for injecting dynamic, frequently changing enterprise facts.", "Claims RAG modifies model weights to permanently memorize ingested documents.", "Fails to articulate clear criteria for choosing between the three approaches."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between semantic RAG, graph RAG, and BM25 retrieval, and when would you use each?', '{"subcategory": "Advanced Retrieval Comparison: Semantic RAG vs GraphRAG vs Lexical BM25 Retrieval", "key_points": [{"id": "KP1", "description": "Analyze BM25 retrieval: term frequency / inverse document frequency, exact lexical matching, and operational simplicity.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, inverted index, term frequency saturation, document length normalization, exact keyword matching, low CPU cost.", "Explains BM25 matches explicit keywords with sub-millisecond execution, ideal for technical identifiers, part numbers, and error traces.", "Fails completely when queries express intent conceptually without matching document vocabulary."]}, {"id": "KP2", "description": "Analyze Semantic RAG: dense embedding similarity, vector nearest-neighbor search, and conceptual matching.", "required": true, "acceptable_evidence": ["Technical keywords: dense vector search, bi-encoder, HNSW index, semantic intent, synonym matching, localized chunk retrieval.", "Explains Semantic RAG retrieves text passages based on conceptual meaning, excelling at localized factual question answering.", "Fails on global corpus summarization (''What are the major themes across all 500 reports?'') and multi-hop relationship chains."]}, {"id": "KP3", "description": "Analyze GraphRAG: knowledge graph construction, entity-relationship extraction, community summaries, and multi-hop traversal.", "required": true, "acceptable_evidence": ["Technical keywords: Knowledge Graphs, Neo4j, entity extraction, relationship triples, community detection (Leiden algorithm), global thematic queries.", "Explains GraphRAG structures unstructured text into connected knowledge graphs, generating hierarchical community summaries across documents.", "Excels at multi-hop relational discovery and global thematic questions; trade-offs include high ingestion LLM cost and graph maintenance complexity."]}], "critical_failures": ["Claims BM25 uses neural embeddings to calculate cosine similarity.", "Fails to identify multi-hop relational reasoning and global corpus synthesis as the primary advantages of GraphRAG.", "Asserts that Semantic RAG can natively traverse complex interconnected entity graphs across disparate documents."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is the difference between simple RAG and Agentic RAG?', '{"subcategory": "Evolution of RAG: Linear Simple RAG vs Autonomous Stateful Agentic RAG", "key_points": [{"id": "KP1", "description": "Define Simple RAG: linear DAG architecture, one-shot retrieval, and fixed prompt injection.", "required": true, "acceptable_evidence": ["Technical keywords: linear DAG, one-shot retrieval, top-k vector search, static context augmentation, sub-second latency.", "Explains Simple RAG executes a single pass: Query $\\rightarrow$ Retrieve Top-K $\\rightarrow$ LLM Generate.", "Lacks feedback loops: if retrieved chunks are irrelevant or missing, the LLM hallucinates or returns an unhelpful answer with no recovery capability."]}, {"id": "KP2", "description": "Define Agentic RAG: cyclic reasoning loops, dynamic query formulation, and tool-augmented multi-step execution.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct loops, LangGraph state machine, query decomposition, Corrective RAG (CRAG), self-reflection, tool invocation.", "Explains Agentic RAG evaluates intermediate retrieval quality; if evidence is insufficient, it rewrites the query, searches secondary datastores, or breaks complex questions into sub-queries.", "Can invoke external calculation tools, database queries, and validation agents before producing a final answer."]}, {"id": "KP3", "description": "Evaluate operational trade-offs between Simple RAG and Agentic RAG in production.", "required": true, "acceptable_evidence": ["Technical keywords: latency overhead (1s vs 5-15s), token cost multiplication, infinite loop risks, stateful debugging, task complexity suitability.", "Explains Simple RAG is ideal for high-throughput, low-latency, straightforward factual Q&A.", "Explains Agentic RAG is necessary for multi-hop research, complex troubleshooting, and automated workflows, but incurs higher token costs and latency."]}], "critical_failures": ["Claims Agentic RAG is simply Simple RAG with a larger context window or higher temperature.", "Fails to identify cyclic execution, query reformulation, and self-evaluation loops as defining characteristics of Agentic RAG.", "Ignores latency, cost, and operational complexity trade-offs between the two architectures."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between using an evaluation framework (like RAG evaluation libraries) and LLM-as-a-judge, and how did you apply them in practice?', '{"subcategory": "RAG Evaluation Methodologies: Algorithmic Frameworks (Ragas/DeepEval) vs LLM-as-a-Judge Implementations", "key_points": [{"id": "KP1", "description": "Explain evaluation libraries (Ragas, DeepEval): standardized component metrics, mathematical formulations, and reproducibility.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas, DeepEval, Context Precision, Context Recall, Faithfulness, Answer Relevance, automated synthetic testset generation, standardized CI/CD pipelines.", "Explains evaluation frameworks provide standardized, turnkey implementations of decoupled retrieval and generation metrics.", "Details using automated testset generators to create synthetic question-context-ground_truth triples across enterprise document corpora."]}, {"id": "KP2", "description": "Explain bespoke LLM-as-a-Judge: customizable rubrics, Chain-of-Thought (CoT) reasoning, and domain-specific scoring.", "required": true, "acceptable_evidence": ["Technical keywords: LLM-as-a-judge, custom scoring prompt rubrics, Chain-of-Thought (CoT) evaluation, pairwise comparison (Arena style), reference-free vs reference-based scoring.", "Explains using an advanced LLM (e.g. GPT-4, Claude 3.5 Sonnet) with tailored enterprise rubrics, prompting the judge to output step-by-step reasoning before assigning scores (1-5 scale).", "Allows measuring organization-specific nuances (compliance tone, regulatory disclaimers, brand voice) that off-the-shelf libraries omit."]}, {"id": "KP3", "description": "Analyze practical application, judge bias mitigations, and cost-latency considerations.", "required": true, "acceptable_evidence": ["Technical keywords: position bias, verbosity bias, self-enhancement bias, calibration against human SME scores, judge cost management.", "Details mitigating judge biases by swapping prompt candidate order (position bias) and enforcing strict length normalization.", "Explains calibrating LLM judges against human SME ratings to achieve $>0.85$ Spearman correlation, and running evaluations in asynchronous batch pipelines."]}], "critical_failures": ["Claims LLM-as-a-judge and Ragas are mutually exclusive rather than recognizing that Ragas uses LLMs under the hood for scoring.", "Ignores common LLM judge biases (position bias, verbosity bias) and fails to mention calibration against human SME annotations.", "Cannot distinguish between retrieval evaluation metrics and generation evaluation metrics."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is the input to that hallucination detection system?', '{"subcategory": "Hallucination Detection Architecture: Input Feature Vector & Multi-Signal Verification Inputs", "key_points": [{"id": "KP1", "description": "Identify core text inputs provided to the hallucination detection engine.", "required": true, "acceptable_evidence": ["Technical keywords: user query ($Q$), retrieved context chunks ($C$), generated response ($A$), metadata/provenance attributes.", "Explains that hallucination detection operates on the primary triplet: User Query, Retrieved Context Passages, and Candidate Model Output.", "Emphasizes that hallucination cannot be evaluated on the generated response alone; it must be evaluated strictly against the source context."]}, {"id": "KP2", "description": "Detail extracted linguistic, entailment, and claim-level features.", "required": true, "acceptable_evidence": ["Technical keywords: atomic claim decomposition, Natural Language Inference (NLI) premise-hypothesis pairs, entailment vs contradiction logits, named entity verification.", "Explains breaking the generated response into discrete atomic factual statements ($a_1, a_2, \\dots, a_n$).", "Details feeding each atomic claim as a hypothesis against the retrieved context as a premise into an NLI model (e.g. DeBERTa-v3-large) to score entailment, neutral, and contradiction probabilities."]}, {"id": "KP3", "description": "Incorporate retrieval confidence signals and model token log probabilities.", "required": true, "acceptable_evidence": ["Technical keywords: vector similarity scores, cross-encoder reranker scores, token perplexity / log probabilities, attention weight entropy.", "Explains integrating retrieval confidence scores: if context chunks have low similarity scores, generation hallucination probability rises sharply.", "Details inspecting generator token log-probabilities to flag tokens produced with low model confidence."]}], "critical_failures": ["Claims the hallucination detection system only inspects the generated answer without comparing it to the retrieved context chunks.", "Fails to explain atomic claim decomposition or NLI entailment scoring.", "Ignores retrieval quality and similarity scores as input signals to hallucination risk assessment."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is the purpose of re-ranking in your retrieval pipeline, and how do cross-encoders or BERT-based rerankers improve results?', '{"subcategory": "Two-Stage Retrieval Architecture: Cross-Encoder Rerankers & BERT-Based Relevance Scoring", "key_points": [{"id": "KP1", "description": "Explain the architectural purpose of reranking in two-stage retrieval pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval, candidate generation (first stage) vs precision ranking (second stage), bi-encoder trade-offs, vector search false positives.", "Explains that initial vector/hybrid search is optimized for speed and broad recall across millions of documents, retrieving a candidate pool of 20-50 chunks.", "Explains reranking acts as a precision filter that re-evaluates candidate chunks with high-fidelity deep neural scoring, discarding irrelevant false positives before prompt assembly."]}, {"id": "KP2", "description": "Detail how cross-encoders / BERT-based rerankers score query-document pairs.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder, concatenated sequence `[CLS] query [SEP] chunk [SEP]`, cross-attention across all transformer layers, relevance logit, softmax score.", "Explains cross-encoders feed query and document tokens jointly into the transformer, allowing every word in the query to attend directly to every word in the candidate chunk.", "Contrasts with bi-encoders that map queries and documents into isolated vector embeddings, losing token-to-token contextual interaction."]}, {"id": "KP3", "description": "Analyze selection of top results and the latency-quality trade-off.", "required": true, "acceptable_evidence": ["Technical keywords: top-k selection (filtering top-30 candidates to top-3 to 5), score thresholding, p95 latency overhead (80-250ms), GPU batching.", "Explains sorting candidates by cross-encoder score and selecting top-3 to 5 chunks, applying a score cutoff threshold to drop low-relevance chunks.", "Details trade-off: reranking adds 100-200ms latency but dramatically boosts Context Precision and prevents LLM hallucination."]}], "critical_failures": ["Claims cross-encoders compute cosine similarity between two independently generated embeddings.", "Omits the latency penalty introduced by running cross-encoders on retrieved candidate pools.", "Fails to articulate why a two-stage pipeline is needed rather than running a cross-encoder across the entire corpus."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is the role of indexing in like Milvus, and how do techniques like HNSW or IVF Flat improve retrieval performance?', '{"subcategory": "Vector Indexing Deep Dive: HNSW Graph Indexing vs IVF_FLAT Clustering in Milvus", "key_points": [{"id": "KP1", "description": "Explain the role of vector indexing in Milvus: approximating nearest neighbor search over high-dimensional spaces.", "required": true, "acceptable_evidence": ["Technical keywords: Approximate Nearest Neighbor (ANN), brute-force Flat search ($O(N)$), curse of dimensionality, sub-linear search time ($O(\\log N)$), recall vs latency.", "Explains that indexing pre-structures vector embeddings to avoid scanning millions of vectors sequentially, reducing query latency from seconds to milliseconds.", "Highlights that ANN indices trade a negligible amount of recall (<1-2%) for dramatic 100x query throughput gains."]}, {"id": "KP2", "description": "Detail HNSW (Hierarchical Navigable Small World) graph indexing mechanics and search parameters.", "required": true, "acceptable_evidence": ["Technical keywords: multi-layer proximity graphs, skip-list analogy, parameters $M$ (max links per node), $efConstruction$ (build beam width), $efSearch$ (query beam width), greedy graph routing.", "Explains HNSW constructs a hierarchy of layers: top layers have sparse long-distance connections for rapid coarse routing; bottom layers have dense local clusters for fine-grained nearest neighbor discovery.", "Details tuning `efSearch`: higher values expand search candidate queues, increasing recall at the expense of query latency."]}, {"id": "KP3", "description": "Detail IVF_FLAT (Inverted File Flat) clustering mechanics and contrast with HNSW.", "required": true, "acceptable_evidence": ["Technical keywords: k-means Voronoi cells, clustering centroids ($nlist$), probed cells ($nprobe$), inverted lists, memory footprint vs recall.", "Explains IVF_FLAT partitions vector space into $nlist$ Voronoi cells via k-means clustering; queries search only the $nprobe$ nearest centroids.", "Contrasts HNSW (higher memory consumption, faster query latency, higher recall) with IVF_FLAT (lower memory consumption, faster build times, lower QPS)."]}], "critical_failures": ["Claims HNSW is a tree-based clustering algorithm rather than a multi-layer proximity graph.", "Confuses $efSearch$ (query-time parameter) with $efConstruction$ (index-build-time parameter).", "Fails to mention the substantial RAM memory overhead required to hold HNSW graphs in memory compared to IVF indices."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What is your approach to chunking and metadata design during document ingestion, and how does it impact retrieval quality?', '{"subcategory": "Document Ingestion Architecture: Chunking Strategy & Structured Metadata Schema Design", "key_points": [{"id": "KP1", "description": "Design an optimal document chunking strategy balancing semantic granularity and context preservation.", "required": true, "acceptable_evidence": ["Technical keywords: recursive splitting, layout-aware parsing, token length boundaries (500-800 tokens), sliding window overlap (15%), parent-child chunking.", "Explains splitting documents along structural section boundaries with 10-15% overlap to ensure clauses are not truncated mid-sentence.", "Details using parent-child chunking: creating small 200-token child chunks for high-precision embedding search while retrieving linked 1000-token parent documents for generation context."]}, {"id": "KP2", "description": "Architect a comprehensive structured metadata schema attached to each chunk payload.", "required": true, "acceptable_evidence": ["Technical keywords: metadata schema (`document_id`, `source_url`, `section_hierarchy`, `creation_date`, `department`, `access_role`, `is_active`, `version`).", "Explains designing a strict JSON metadata payload embedded alongside vector vectors to enable deterministic pre-filtering.", "Details storing breadcrumb paths (e.g. `[''Warranty'', ''Battery'', ''Coverage Terms'']`) to provide contextual anchoring."]}, {"id": "KP3", "description": "Analyze how chunking and metadata design directly elevate retrieval quality and access control.", "required": true, "acceptable_evidence": ["Technical keywords: pre-retrieval filtering, multi-tenancy enforcement, elimination of cross-tenant leakage, Context Recall & Precision improvements.", "Explains metadata filtering reduces search space by 90%, speeding up ANN queries and guaranteeing that users only retrieve documents matching their security clearance.", "Demonstrates that clean chunking prevents vector dilution, directly improving top-k Context Precision."]}], "critical_failures": ["Proposes storing raw chunks in vector databases with zero metadata attributes attached.", "Claims chunking strategy has no impact on retrieval relevance or LLM generation quality.", "Ignores data isolation and role-based access control (RBAC) in metadata schema design."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What is your experience extending a basic RAG system into agentic workflows, and how did you leverage tools like LangChain and LangGraph in that process?', '{"subcategory": "Agentic Workflow Evolution: Extending Static RAG Pipelines into Stateful LangGraph Multi-Agent Systems", "key_points": [{"id": "KP1", "description": "Identify architectural limitations of basic RAG driving the transition to agentic workflows.", "required": true, "acceptable_evidence": ["Technical keywords: static linear pipelines, inability to self-correct, lack of multi-step reasoning, brittle single-turn failures, unhandled out-of-domain queries.", "Explains that basic RAG fails when queries require multi-step comparative analysis across multiple documents or when initial retrieval returns zero relevant chunks.", "Highlights the need for autonomous decision loops that evaluate retrieval quality and take corrective action."]}, {"id": "KP2", "description": "Architect stateful cyclic execution graphs using LangGraph nodes, edges, and state schemas.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, TypedDict / Pydantic state, nodes (router, retriever, grade_documents, generator, web_search), conditional edges.", "Explains structuring the RAG pipeline as a computational graph where an agent inspects retrieved documents: if relevant, routes to generator; if irrelevant, routes to query rewriting or web search.", "Details using conditional edges based on model evaluation outputs to create self-corrective retrieval loops (Corrective RAG / Self-RAG)."]}, {"id": "KP3", "description": "Implement state persistence, checkpointing, and Human-in-the-Loop (HITL) approval gates.", "required": true, "acceptable_evidence": ["Technical keywords: SqliteSaver / PostgresSaver checkpointers, thread_id session persistence, HITL interrupt_before, time-travel debugging, rollback.", "Details persisting graph state across multi-turn interactions using PostgreSQL checkpointers, allowing workflows to pause and resume.", "Explains configuring human approval interrupts before the agent executes high-impact transactional tools (e.g. updating customer records or sending emails)."]}], "critical_failures": ["Claims LangChain linear chains provide the exact same cyclic state machine capabilities as LangGraph.", "Fails to explain how conditional edges and state checking create self-correcting retrieval loops.", "Omits persistence and checkpointing mechanisms for state recovery and human-in-the-loop governance."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is your experience with fine-tuning models, and how does it compare to prompt engineering or retrieval-based approaches?', '{"key_points": [{"id": "KP1", "description": "Comparison along task objectives: prompt engineering directs general behavior, RAG injects dynamic external facts, and fine-tuning teaches specialized tone, syntax, or complex formatting.", "required": true, "acceptable_evidence": ["Technical keywords: prompt engineering (in-context), RAG (dynamic factual grounding), fine-tuning (style, syntax, behavioral adaptation)", "Prompt engineering is fastest for zero-shot iteration and framing task constraints without compute costs", "RAG is required for frequently updating knowledge bases and verifiable document citations", "Fine-tuning (e.g. LoRA/QLoRA) adapts models to proprietary output schemas, specialized domain jargon, or custom instruction formats"]}, {"id": "KP2", "description": "Operational trade-offs: compute costs, latency budgets, data preparation overhead, and update agility.", "required": true, "acceptable_evidence": ["Technical keywords: training compute cost, GPU resources, data curation overhead, inference latency, knowledge freshness", "Prompt engineering incurs zero training cost but adds prompt token consumption and latency", "RAG incurs vector search latency (~30-50ms) but updates instantly upon document reindexing", "Fine-tuning requires curated training datasets, GPU compute, and cannot be updated dynamically without retraining cycles"]}, {"id": "KP3", "description": "Synergistic hybrid approaches: combining fine-tuned lightweight models with RAG retrieval to optimize both specialized formatting and factual accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid RAG + fine-tuning, PEFT/LoRA for formatting, RAG for factual retrieval, enterprise architecture", "Fine-tunes a smaller open model (e.g. Llama-3-8B) to reliably output domain-specific JSON schemas, while using RAG to supply dynamic context", "Avoids attempting to memorize facts into fine-tuned weights, which causes ungrounded hallucinations"]}], "critical_failures": ["Failing to compare all three approaches: prompt engineering, fine-tuning, and retrieval-based RAG", "Believing fine-tuning is the optimal approach for frequently updating factual knowledge", "Ignoring the operational trade-offs across training cost, latency, and knowledge freshness"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is your reranking strategy using cross-encoders, and how do you select the final top results?', '{"key_points": [{"id": "KP1", "description": "Role and mechanism of cross-encoder reranking: scoring full query-document pairs simultaneously using full cross-attention to capture deep token-level semantic interactions missed by bi-encoders.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder, BGE-Reranker, Cohere Rerank, full cross-attention, bi-encoder limitations, token interactions", "Explains that bi-encoders produce isolated embedding vectors where query and passage tokens never directly attend to each other", "Details how cross-encoders take [CLS] Query [SEP] Passage [SEP] and output an exact relevance score between 0 and 1"]}, {"id": "KP2", "description": "Two-stage retrieval pipeline: retrieving a broader candidate pool (top-20 to top-50) via fast ANN/vector search and reranking down to the top-3 to top-5 most relevant chunks.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval, candidate pool, top-k reduction, initial recall, top-20/50 to top-3/5", "Explains why cross-encoders cannot be run over millions of vectors directly due to O(N) compute complexity", "Demonstrates balancing high candidate recall at stage 1 with high precision and prompt context economy at stage 2"]}, {"id": "KP3", "description": "Selection logic and latency trade-offs: applying absolute score thresholding or top-K selection, managing added latency budget (15-50ms).", "required": true, "acceptable_evidence": ["Technical keywords: relevance score threshold, cut-off score, latency budget, 15-50ms inference, GPU/ONNX acceleration", "Explains filtering out chunks below a minimum relevance threshold (e.g. score < 0.4) to avoid injecting context noise into the LLM", "Details optimizing reranker inference via quantization (INT8/FP16) or smaller distilled models (e.g. bge-reranker-base)"]}], "critical_failures": ["Failing to explain the architectural difference between bi-encoders and cross-encoders (joint attention vs independent vector cosine)", "Claiming cross-encoders are used to index all documents in the vector database directly", "Ignoring the latency penalty of cross-encoder inference"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What preprocessing, chunking, and embedding strategies did you use for unstructured data, and how did tools like Docling and sentence transformers contribute to the pipeline?', '{"subcategory": "Enterprise Document Processing: Layout-Aware Parsing (Docling) & Sentence Transformer Embeddings", "key_points": [{"id": "KP1", "description": "Explain the role and architecture of Docling for complex unstructured document extraction.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, IBM deep search layout analysis, OCR integration, table structure recognition (TableFormer), multi-column reading order, Markdown output.", "Explains that standard PDF extractors flatten multi-column text and scramble complex tables into disorganized strings, stripping data of its tabular meaning.", "Details Docling using specialized vision-language models (TableFormer) to preserve tabular hierarchy, cell spanning, and reading flow in structured Markdown format."]}, {"id": "KP2", "description": "Detail sentence transformer embedding models: architecture, pooling, and vector generation.", "required": true, "acceptable_evidence": ["Technical keywords: bi-encoder architecture, self-attention, positional encodings, mean pooling, BGE / MiniLM / MPNet, normalized vector representations.", "Explains transformer encoder architecture processing parsed text tokens with multi-head self-attention to capture contextual dependencies.", "Details applying mean pooling over token embeddings to create a single 384/768-dimensional dense vector representing the chunk''s semantic content."]}, {"id": "KP3", "description": "Evaluate end-to-end production performance: parsing throughput, embedding latency, and retrieval quality.", "required": true, "acceptable_evidence": ["Technical keywords: document ingestion throughput (pages/sec), GPU/CPU batch inference, vector search accuracy, table preservation impact on answer accuracy.", "Demonstrates that layout-aware parsing with Docling drastically reduces hallucination on tabular queries compared to raw text extractors.", "Details optimizing batch embedding generation on GPU workers to process thousands of technical enterprise pages per hour."]}], "critical_failures": ["Claims Docling is an LLM generation model rather than a layout-aware document parser.", "Fails to explain how tabular structures are preserved and represented in Markdown/HTML for vectorization.", "Omits the role of pooling layers in transformer embedding models."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What prompting strategies did you find most effective for reducing hallucinations and improving reliability?', '{"key_points": [{"id": "KP1", "description": "Strict grounding instructions and explicit negative constraints: instructing the model to answer solely based on provided context and explicitly decline when information is absent.", "required": true, "acceptable_evidence": ["Technical keywords: strict grounding prompt, negative constraint, out-of-context refusal, ''I do not know'', ungrounded assumptions", "Specifies prompt directives: ''Answer the question strictly using only the provided context snippets. If the context does not contain the answer, state that the information is unavailable.''", "Prohibits extrapolating or using pre-trained external assumptions without source backing"]}, {"id": "KP2", "description": "Citation and verbatim attribution requirements: forcing the LLM to cite chunk IDs, section numbers, or verbatim quotes for every factual assertion made.", "required": true, "acceptable_evidence": ["Technical keywords: citation extraction, source chunk ID, bracketed citations [Doc-1], verbatim evidence, verifiable claims", "Requires the prompt template to mandate referencing the specific chunk metadata for each step or claim", "Enables downstream regex or automated verification of citations against the supplied context"]}, {"id": "KP3", "description": "Chain-of-thought (CoT) and structured intermediate reasoning: directing the model to extract relevant excerpts first before synthesizing the final user response.", "required": true, "acceptable_evidence": ["Technical keywords: Chain-of-Thought (CoT), step-by-step extraction, scratchpad, extract-then-answer, JSON schema output", "Prompts the model: ''Step 1: Identify and quote the relevant sentences from context. Step 2: Formulate the concise answer.''", "Enforces structured JSON output schema containing {answer: str, cited_sources: list, confidence: str}"]}, {"id": "KP4", "description": "Role definition, few-shot demonstration, and defensive framing: positioning the LLM as an enterprise compliance assistant and demonstrating boundary cases.", "required": false, "acceptable_evidence": ["Technical keywords: system prompt persona, few-shot examples, edge cases, partial context demonstration", "Provides few-shot examples of correct refusals when queries ask for out-of-domain proprietary specs", "Defines temperature tuning (e.g. temperature=0.0 or 0.1) for deterministic factual generation"]}], "critical_failures": ["Suggesting generic prompts without concrete grounding constraints or explicit refusal instructions", "Failing to mention citations or verifiable source attribution", "Overlooking deterministic parameter tuning (such as temperature control)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What role did Docklin play in data cleaning, chunking, and ingestion, and why did you choose it?', '{"key_points": [{"id": "KP1", "description": "Docling''s architectural role in layout-aware parsing: utilizing vision and layout analysis models (TableFormer) to parse complex multi-column PDFs, headers, and footers.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, TableFormer, layout-aware parsing, visual document understanding, multi-column reading order, bounding boxes", "Correctly orders reading sequences across complex technical manuals rather than blindly concatenating text columns", "Strips repeating page numbers, running headers, and boilerplate legal disclaimers during cleaning"]}, {"id": "KP2", "description": "Table extraction and structured serialization: extracting complex tables and converting them into clean Markdown or HTML representation to preserve structural semantics.", "required": true, "acceptable_evidence": ["Technical keywords: table extraction, Markdown table format, cell alignment, row-column relationships, tabular data preservation", "Preserves table headers and cell values so embedding models and LLMs can accurately parse diagnostic specs and numerical thresholds", "Prevents table flattening where rows and columns turn into meaningless concatenated strings"]}, {"id": "KP3", "description": "Integration into the chunking and ingestion pipeline: exporting structured document trees (Docling Document representation) for hierarchy-aware chunking.", "required": true, "acceptable_evidence": ["Technical keywords: Docling Document AST, structural chunking, header hierarchy (H1/H2/H3), metadata enrichment, ingestion pipeline", "Splits documents along natural structural boundaries identified by Docling rather than naive character slicing", "Enriches output chunks with section breadcrumbs and metadata before vector embedding generation"]}], "critical_failures": ["Confusing Docling with a vector database or embedding model (it is a document layout parsing and extraction library)", "Failing to mention table extraction (TableFormer) or layout preservation in complex PDFs", "Ignoring how Docling outputs structured formats (Markdown/AST) for downstream chunking"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What role did domain-specific taxonomies and structured metadata play in improving retrieval relevance and system performance?', '{"key_points": [{"id": "KP1", "description": "Structured metadata schema design: attaching rich categorical metadata (model year, vehicle trim, system component, document type, access tier) to every chunk during ingestion.", "required": true, "acceptable_evidence": ["Technical keywords: structured metadata, schema design, payload attributes, document hierarchy, vehicle model, component taxonomy", "Explains enriching raw text with discrete attributes (e.g. system: ''Powertrain'', subcategory: ''Charging'', vehicle_year: ''2024'')", "Distinguishes between unstructured dense content and structured filterable attributes"]}, {"id": "KP2", "description": "Metadata pre-filtering and hybrid search constraints: eliminating irrelevant search partitions before vector similarity calculation to improve precision and eliminate cross-domain noise.", "required": true, "acceptable_evidence": ["Technical keywords: pre-filtering, hard filters, Milvus scalar filtering, boolean expressions, search space pruning", "Shows how applying scalar expressions (e.g. model == ''EV-SUV'' AND year >= 2023) prevents retrieving specs for unrelated models", "Reduces vector candidate search space, dramatically cutting ANN compute and eliminating false positives"]}, {"id": "KP3", "description": "Domain-specific taxonomy alignment: standardizing terminology and synonyms across user colloquial queries and formal enterprise documentation.", "required": true, "acceptable_evidence": ["Technical keywords: domain taxonomy, synonym mapping, ontology, entity normalization, standardized terminology", "Resolves differences between user jargon (e.g. ''fast charging won''t click'', ''juice box'') and engineering manuals (''CCS Combo 1 latch failure'')", "Improves dense embedding alignment by prepending standardized taxonomy breadcrumbs to chunk headers"]}, {"id": "KP4", "description": "Operational impact on latency, recall, and governance: restricting search by tenant/role-based access control (RBAC) and reducing context token waste.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC (Role-Based Access Control), tenant isolation, query latency reduction, index partition pruning", "Ensures proprietary or tier-restricted documentation is filtered out before vector similarity evaluation", "Demonstrates measurable improvements in Hit Rate and reduction in context tokens sent to the LLM"]}], "critical_failures": ["Treating vector search as purely text-based embeddings without recognizing the necessity of scalar metadata filtering", "Failing to explain how taxonomies resolve vocabulary mismatch between user queries and technical manuals", "Ignoring the role of metadata in access control and search space optimization"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What role did the vector database play in your system, and how did you design it to support multi-tenancy and efficient ANN-based retrieval?', '{"key_points": [{"id": "KP1", "description": "Vector database role in the architecture: serving as a low-latency, scalable similarity engine for storing dense document embeddings and performing Approximate Nearest Neighbor (ANN) search.", "required": true, "acceptable_evidence": ["Technical keywords: vector database, Milvus, Pinecone, ANN (Approximate Nearest Neighbor), vector indexing, sub-50ms retrieval", "Explains decoupling vector search from relational DBs to handle millions of 384/1536-dimensional embeddings with high concurrency", "Details role in receiving query vector and returning top-k nearest document chunks"]}, {"id": "KP2", "description": "Multi-tenancy design strategies: implementing partition keys, collections per tenant, or namespace metadata filtering to guarantee strict tenant isolation.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenancy, partition keys, collection-level isolation, partition-level isolation, metadata tenant_id filtering", "Contrasts collection per tenant (high isolation, index overhead) vs partition keys in Milvus (shared collection, physical partition pruning)", "Ensures data leakage across organizations or customer accounts is mathematically impossible at the query layer"]}, {"id": "KP3", "description": "ANN indexing architecture and tuning: selecting and parameterizing graph-based (HNSW) or clustered (IVF_FLAT/IVF_PQ) indexes for optimal recall versus latency.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, M (bi-directional links), efConstruction, efSearch, IVF_FLAT, nlist, nprobe, distance metric", "Details HNSW parameters: tuning M=16..64 and efConstruction=200 for index quality, and efSearch=64..128 at query time", "Balances memory footprint (RAM) and search speed against high recall (>95%)"]}, {"id": "KP4", "description": "Vector database distributed scaling: separating query nodes, data nodes, and index nodes to enable independent horizontal scaling.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed architecture, query nodes, data nodes, index nodes, object storage (S3/MinIO), log broker (Kafka/Pulsar)", "Explains how query nodes scale out horizontally for QPS surges while data nodes handle streaming ingestion independently", "Highlights segment management, compaction, and persistence on cloud object storage"]}], "critical_failures": ["Failing to detail concrete multi-tenancy mechanisms (partition keys vs collections vs scalar filtering)", "Mentioning ANN without knowing specific indexing strategies or tuning parameters (e.g. HNSW M/efSearch)", "Ignoring the distributed system architecture required for enterprise vector database scaling"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What role did you play in deploying the RAG system, and what were the key deployment challenges?', '{"key_points": [{"id": "KP1", "description": "Deployment role and architectural responsibilities: packaging ingestion workers, vector database, and inference orchestration into containerized services deployed on cloud infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: deployment lead, Kubernetes/EKS, Docker, Helm charts, CI/CD pipeline, FastAPI microservices", "Details designing CI/CD workflows (GitHub Actions/GitLab) for automated linting, container builds, and deployment", "Outlines service boundaries between ingestion workers, query API gateway, and vector storage"]}, {"id": "KP2", "description": "Key deployment challenge 1 - Latency budgeting and real-time streaming: overcoming end-to-end response delays across vector search, reranking, and LLM token generation.", "required": true, "acceptable_evidence": ["Technical keywords: latency budget, p95 latency, Server-Sent Events (SSE), token streaming, TTFT (Time to First Token), asynchronous I/O", "Explains breaking down latency: network ingress (20ms) + vector search (30ms) + reranker (40ms) + Bedrock TTFT (400ms)", "Implemented streaming responses to front-end to improve perceived user experience"]}, {"id": "KP3", "description": "Key deployment challenge 2 - Vector store scaling and high-throughput ingestion: managing zero-downtime index updates and memory utilization.", "required": true, "acceptable_evidence": ["Technical keywords: vector index updates, memory footprint, HNSW RAM overhead, zero-downtime reindexing, batch ingestion", "Details challenges with memory exhaustion when building HNSW graphs for large document updates", "Solved by running asynchronous background indexing jobs decoupled from query-serving nodes"]}, {"id": "KP4", "description": "Key deployment challenge 3 - Observability, guardrails, and compliance: integrating tracing, metrics, and secret management in production.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Langfuse, Arize Phoenix, CloudWatch, PII redaction, VPC endpoints", "Instruments distributed traces across LangGraph nodes to pinpoint failure points", "Ensures compliance with enterprise data policies by isolating traffic inside VPC"]}], "critical_failures": ["Describing deployment in vague terms without technical details on container orchestration, CI/CD, or infrastructure", "Failing to identify concrete production challenges (e.g. latency budgets, memory overhead of vector indexes, streaming)", "Neglecting monitoring, tracing, or operational reliability"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What role do agents play compared to traditional retrieval systems, and when would you choose agent-based architectures?', '{"key_points": [{"id": "KP1", "description": "Core differences: traditional retrieval systems are passive, stateless, and single-turn (query -> search -> generate), while agent-based architectures are active, goal-driven, and multi-turn.", "required": true, "acceptable_evidence": ["Technical keywords: passive retrieval vs active agents, stateless vs stateful, single-hop vs iterative reasoning, goal decomposition", "Traditional RAG blindly passes retrieved context to an LLM for immediate answer generation", "Agent-based systems analyze queries, formulate step-by-step plans, decide whether retrieval is necessary, evaluate retrieved evidence, and iterate"]}, {"id": "KP2", "description": "Key capabilities of agent-based architectures: tool invocation, dynamic environment feedback, query self-correction, and multi-source aggregation.", "required": true, "acceptable_evidence": ["Technical keywords: dynamic tool calling, environment feedback, Corrective RAG (CRAG), self-reflection, multi-source orchestration", "Can query multiple disparate databases (vector stores, SQL, external REST APIs) conditionally based on query needs", "Evaluates retrieved candidate quality and automatically reformulates queries if initial results are irrelevant"]}, {"id": "KP3", "description": "Decision criteria for choosing agent architectures: appropriate for complex multi-step workflows, ambiguous intent, transactional task automation, and multi-hop queries.", "required": true, "acceptable_evidence": ["Technical keywords: selection criteria, multi-hop queries, task automation, transactional workflows, latency/cost trade-offs", "Choose traditional RAG when requirements are purely informational, single-turn, low-latency (<500ms), and cost-sensitive", "Choose agent architectures when tasks require calling APIs, updating databases, multi-turn disambiguation, or executing complex diagnostic runbooks"]}], "critical_failures": ["Treating agentic architectures as merely standard RAG with a larger system prompt", "Failing to articulate the decision criteria for when to select traditional RAG vs agent-based systems", "Ignoring the latency, cost, and complexity overhead of multi-turn agent reasoning"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What role do metadata filtering and embedding consistency play in improving retrieval performance?', '{"key_points": [{"id": "KP1", "description": "Role of metadata filtering: pruning the search space with deterministic boolean criteria prior to or during vector search to enforce business rules and precision.", "required": true, "acceptable_evidence": ["Technical keywords: metadata filtering, pre-filtering, iterative filtering, post-filtering, boolean predicates, search space reduction", "Explains pre-filtering restricts vector search only to candidate chunks matching exact tags (e.g. department: ''billing'', year: 2024)", "Prevents semantically similar but structurally invalid chunks from polluting retrieved context"]}, {"id": "KP2", "description": "Role of embedding consistency: ensuring identical embedding models, tokenizers, normalization, and prefix conventions across ingestion and query time.", "required": true, "acceptable_evidence": ["Technical keywords: embedding consistency, identical model checkpoints, symmetric/asymmetric prefixes, query vs passage tokens, L2 normalization", "Explains asymmetric models (e.g. E5, BGE) require specific prefixes like ''query: '' and ''passage: ''; omitting or swapping them degrades similarity", "Highlights danger of embedding drift if documents are embedded with model version A while query uses version B"]}, {"id": "KP3", "description": "Impact on retrieval performance and accuracy: preventing out-of-domain hallucinations, reducing ANN search latency, and improving Top-K precision.", "required": true, "acceptable_evidence": ["Technical keywords: Top-K precision, Hit Rate improvement, ANN search latency reduction, noise reduction, deterministic filtering", "Shows how metadata filtering reduces candidate graph traversal in HNSW, speeding up search while eliminating false positives", "Guarantees that strict constraints (e.g. tenant boundaries or temporal limits) are 100% adhered to"]}], "critical_failures": ["Failing to explain how metadata filtering prunes the vector search space", "Overlooking embedding consistency (such as identical model checkpoints, normalization, and asymmetric query/document prefixes)", "Confusing metadata filtering with post-generation LLM output filtering"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What similarity metrics are used in retrieval systems, and how do they impact search performance?', '{"key_points": [{"id": "KP1", "description": "Cosine similarity: measuring the cosine of the angle between two vectors, invariant to vector magnitude, optimal for text semantics where document length varies.", "required": true, "acceptable_evidence": ["Technical keywords: Cosine Similarity, dot product of normalized vectors, angle between vectors, scale invariance, range [-1, 1]", "Explains formula: (A · B) / (||A|| ||B||)", "Details how cosine similarity isolates directional semantic alignment regardless of chunk length variation"]}, {"id": "KP2", "description": "Dot Product (Inner Product / IP): measuring vector magnitude and direction; computationally identical to cosine similarity when vectors are pre-normalized to unit length (L2 norm).", "required": true, "acceptable_evidence": ["Technical keywords: Dot Product, Inner Product (IP), unit normalization, L2 normalized embeddings, SIMD acceleration", "Explains that normalizing vectors at ingestion allows replacing expensive division with raw dot product (sum of element-wise products)", "Significantly accelerates ANN search using CPU AVX-512 or GPU matrix multiplication"]}, {"id": "KP3", "description": "Euclidean Distance (L2 Distance): measuring straight-line geometric distance in multi-dimensional space, sensitive to vector magnitude.", "required": true, "acceptable_evidence": ["Technical keywords: Euclidean Distance, L2 distance, geometric distance, magnitude sensitivity, sqrt(sum((Ai - Bi)^2))", "Explains smaller L2 distance indicates higher similarity (unlike cosine where higher is better)", "Points out sensitivity to vector norms if embeddings are not normalized"]}, {"id": "KP4", "description": "Impact on search performance and index optimization: metric choice dictates hardware acceleration, index compatibility, and retrieval quality.", "required": false, "acceptable_evidence": ["Technical keywords: index metric alignment, HNSW distance computation, IVF clustering distance, hardware throughput", "Emphasizes using the exact similarity metric that the embedding model was pre-trained on (e.g. BGE/OpenAI trained on cosine/normalized IP)", "Using mismatched distance metrics causes catastrophic recall degradation"]}], "critical_failures": ["Failing to distinguish between Cosine Similarity, Dot Product, and Euclidean (L2) distance", "Not knowing that Cosine Similarity equals Dot Product when vectors are L2-normalized", "Failing to state that the index similarity metric must match the embedding model''s training objective"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What specific optimizations did you apply across preprocessing, chunking, embeddings, retrieval, and prompt engineering in your RAG pipeline?', '{"key_points": [{"id": "KP1", "description": "Preprocessing and chunking optimizations: layout-aware parsing (Docling), boilerplate scrubbing, recursive markdown chunking (512 tokens / 15% overlap), and contextual breadcrumb prepending.", "required": true, "acceptable_evidence": ["Technical keywords: layout parsing (Docling), boilerplate removal, recursive markdown splitting, 512 tokens, 10-20% overlap, header prepending", "Strips headers, footers, and page numbers, converting complex tables to Markdown", "Prepends document title and section hierarchy to each chunk to anchor semantic context"]}, {"id": "KP2", "description": "Embedding and vector indexing optimizations: selecting domain-appropriate models (all-MiniLM-L6-v2 / BGE), L2 normalization, HNSW parameter tuning (M=16, efConstruction=200, efSearch=64), and scalar indexing.", "required": true, "acceptable_evidence": ["Technical keywords: all-MiniLM-L6-v2, L2 normalization, HNSW index tuning (M, efConstruction, efSearch), scalar metadata indexing", "Normalizes vectors for fast dot product similarity computation", "Tunes HNSW search parameters and builds scalar indexes on category/tenant metadata for high-speed pre-filtering"]}, {"id": "KP3", "description": "Retrieval optimizations: implementing hybrid search (dense ANN + sparse BM25) fused via Reciprocal Rank Fusion (RRF), followed by cross-encoder reranking (BGE-Reranker).", "required": true, "acceptable_evidence": ["Technical keywords: hybrid search, BM25 keyword matching, dense vector search, Reciprocal Rank Fusion (RRF), cross-encoder reranker", "Catches exact part codes with BM25 while capturing semantic concepts with dense vectors", "Prunes candidate pool (top-50) down to top-3 to top-5 chunks using cross-attention reranking"]}, {"id": "KP4", "description": "Prompt engineering optimizations: strict negative grounding constraints, mandatory bracketed citations, XML delimiter separation, and low temperature (0.0).", "required": true, "acceptable_evidence": ["Technical keywords: strict grounding prompt, bracketed citations [Doc-1], XML tags (<context>), out-of-context refusal, temperature=0.0", "Wraps context in explicit XML delimiters to prevent prompt injection", "Directs model to strictly decline when facts are missing from retrieved context"]}], "critical_failures": ["Failing to address optimizations across all 5 requested stages (preprocessing, chunking, embeddings, retrieval, prompt engineering)", "Offering generic high-level statements without concrete technical parameters (e.g. chunk size, HNSW parameters, RRF, reranker model)", "Omitting grounding prompt constraints or citation enforcement"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What strategies do you use to prevent hallucinations and enforce guardrails in LLM-based systems?', '{"key_points": [{"id": "KP1", "description": "Input guardrails and query validation: detecting prompt injections, jailbreaks, PII, and out-of-scope domain requests before retrieval or model invocation.", "required": true, "acceptable_evidence": ["Technical keywords: input guardrails, NeMo Guardrails, Llama Guard, Guardrails AI, prompt injection detection, PII masking", "Details sanitizing user queries and rejecting malicious jailbreak patterns (e.g. ''ignore previous instructions'')", "Uses regex and entity recognition (Presidio) to redact sensitive data before vector queries"]}, {"id": "KP2", "description": "Retrieval grounding and strict context constraints: setting minimum relevance thresholds on retrieved chunks and instructing the model to reject ungrounded queries.", "required": true, "acceptable_evidence": ["Technical keywords: grounding constraints, relevance score cutoff, citation enforcement, explicit fallback, context relevance threshold", "Enforces cross-encoder score cutoff (e.g. reranker score < 0.4 triggers polite fallback rather than passing poor context to LLM)", "Prompts model to strictly refuse answering when facts are not entailed by retrieved documents"]}, {"id": "KP3", "description": "Output guardrails and hallucination verification: applying post-generation fact-checking, Natural Language Inference (NLI), and schema validation.", "required": true, "acceptable_evidence": ["Technical keywords: output guardrails, NLI entailment scoring, SelfCheckGPT, citation verification, hallucination detector, JSON schema validation", "Evaluates generated claims against context using lightweight NLI models (entailment vs contradiction)", "Verifies that all bracketed citations accurately map to real chunks provided in prompt"]}, {"id": "KP4", "description": "Human-in-the-Loop (HITL) and graceful fallback mechanisms: routing high-risk, ambiguous, or low-confidence responses to human supervisors or deterministic safe responses.", "required": false, "acceptable_evidence": ["Technical keywords: HITL (Human-in-the-Loop), escalation routing, confidence threshold, fallback template, LangGraph interrupt", "Uses LangGraph checkpoint interrupts to pause stateful execution for human review on destructive or high-liability actions", "Returns standard enterprise disclaimer/fallback when confidence is below SLA"]}], "critical_failures": ["Suggesting only simple system prompt wording without layered programmatic guardrails (input, retrieval, output)", "Ignoring hallucination verification methods like NLI, citation validation, or score thresholds", "Failing to mention fallback or Human-in-the-Loop escalation strategies"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What strategies would you use to evaluate and compare different embedding models, chunking methods, and in a RAG system?', '{"key_points": [{"id": "KP1", "description": "Formulating an empirical evaluation framework: establishing a representative ground-truth golden dataset with query-document-answer triplets.", "required": true, "acceptable_evidence": ["Technical keywords: golden evaluation dataset, query-context-answer triplets, synthetic generation (Ragas testset), domain expert validation", "Explains curating 100-300 representative enterprise queries covering factual, multi-hop, and edge cases", "Maps each test query to exact ground-truth source chunks and reference answers"]}, {"id": "KP2", "description": "Evaluating and comparing embedding models: benchmarking candidate models (e.g. all-MiniLM-L6-v2, BGE-large, text-embedding-3-small) on retrieval accuracy, dimensional latency, and compute cost.", "required": true, "acceptable_evidence": ["Technical keywords: embedding model benchmarking, Hit Rate@K, MRR@K, NDCG@K, MTEB benchmark, inference latency, embedding dimensions", "Measures retrieval recall across candidates while fixing the chunking strategy", "Evaluates trade-off between 384-dim (fast, low RAM) vs 1536-dim (richer semantic capacity, higher memory/storage)"]}, {"id": "KP3", "description": "Evaluating and comparing chunking strategies: testing fixed-size, recursive character, layout-aware, and semantic chunking across varying chunk sizes (256, 512, 1024) and overlap ratios.", "required": true, "acceptable_evidence": ["Technical keywords: chunking evaluation, chunk size (256/512/1024), overlap ratio (10-20%), recursive vs semantic vs layout-aware, context boundary degradation", "Analyzes impact on context fragmentation: small chunks improve vector specificity but lose broad context; large chunks preserve context but dilute vector signal", "Evaluates context relevance and faithfulness scores across different chunking configurations"]}, {"id": "KP4", "description": "Automated pipeline benchmarking: executing parameter grid searches using automated tooling (RAGAS, DeepEval) to identify Pareto-optimal configurations.", "required": false, "acceptable_evidence": ["Technical keywords: grid search, RAGAS, DeepEval, Pareto frontier, latency vs recall trade-off, token cost analysis", "Automates running matrix of [Embedding Model] x [Chunking Strategy] across test dataset", "Selects optimal configuration balancing retrieval accuracy (Hit Rate > 85%) and latency SLA (<100ms)"]}], "critical_failures": ["Proposing subjective manual inspection instead of a structured benchmark on a golden dataset", "Failing to define quantitative retrieval metrics (Hit Rate, MRR, NDCG)", "Ignoring the interaction and trade-offs between chunk size, embedding model dimensionality, and retrieval latency"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What techniques did you implement for query optimization, reranking, and handling conversational context?', '{"key_points": [{"id": "KP1", "description": "Query optimization techniques: applying query expansion, hypothetical document embeddings (HyDE), and multi-query reformulation to enrich user intent.", "required": true, "acceptable_evidence": ["Technical keywords: query expansion, HyDE (Hypothetical Document Embeddings), multi-query generation, sub-query decomposition, query rewriting", "Explains using an LLM to generate 3-5 variations of a brief or ambiguous user query to broaden search coverage", "Generates hypothetical answer passages whose dense vectors are closer to target documents than the raw question"]}, {"id": "KP2", "description": "Two-stage reranking implementation: scoring initial candidate passages with a high-capacity cross-encoder to reorder results based on deep joint token attention.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder reranking, BGE-Reranker, Cohere Rerank, candidate pool (top-25), final top-k (top-3/5), score thresholding", "Explains reranker evaluates query and passage jointly, eliminating bi-encoder semantic compression losses", "Applies relevance cutoff score to discard noisy chunks that passed initial vector search"]}, {"id": "KP3", "description": "Handling conversational context: maintaining multi-turn dialogue memory, resolving coreferences, and reformulating context-dependent follow-up questions.", "required": true, "acceptable_evidence": ["Technical keywords: conversational context, coreference resolution, contextual query rewriting, conversation buffer memory, dialogue state", "Details converting ambiguous follow-ups (''How do I fix it?'', ''What about the 2024 model?'') into standalone search queries using past dialogue turns", "Maintains sliding window of previous Q&A pairs to track active session entities"]}], "critical_failures": ["Failing to explain how conversational follow-ups are rewritten into standalone search queries", "Omitting query optimization techniques such as HyDE, expansion, or decomposition", "Failing to describe cross-encoder reranking and candidate filtering"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What techniques would you use during document preprocessing and chunking to preserve context such as tables, lists, and structured information?', '{"key_points": [{"id": "KP1", "description": "Layout-aware and document structure parsing: utilizing vision/layout parsing models (Docling, TableFormer, PyMuPDF, Unstructured) rather than raw text extraction to preserve headings, tables, and lists.", "required": true, "acceptable_evidence": ["Technical keywords: layout parsing, Docling, TableFormer, unstructured-io, visual document layout, bounding boxes, markdown conversion", "Explains that naive PDF text extraction flattens columns and turns tables into nonsensical concatenated strings", "Extracts structural document hierarchy (H1, H2, H3 headers) and preserves document reading order"]}, {"id": "KP2", "description": "Table handling strategies: converting tables to structured representations (Markdown, HTML, or JSON) and generating table summary embeddings with cell-level metadata.", "required": true, "acceptable_evidence": ["Technical keywords: markdown table format, HTML table tags, JSON key-value pairs, table summary embedding, row-by-row chunking", "Preserves row-column relationships so LLMs and vector search can interpret tabular attributes accurately", "Creates dual representation: a natural language summary for vector retrieval paired with the full structured table in LLM context"]}, {"id": "KP3", "description": "Hierarchical and recursive chunking: splitting on structural boundaries (headers, section markers, bullet lists) rather than arbitrary token cutoffs.", "required": true, "acceptable_evidence": ["Technical keywords: recursive chunking, markdown header splitting, parent-child chunking, list integrity, semantic boundary detection", "Keeps lists and numbered procedures intact within a single chunk or attaches parent header breadcrumbs to child items", "Prevents breaking a procedural troubleshooting step across arbitrary token boundaries"]}, {"id": "KP4", "description": "Metadata enrichment and context injection: prepending section titles, breadcrumbs, and document metadata to chunk content prior to embedding.", "required": false, "acceptable_evidence": ["Technical keywords: breadcrumb injection, contextual chunking, metadata header prefix, document title prepend", "Prepends contextual breadcrumb: ''[Manual: 2024 EV SUV > Section: Charging System > Subsection: Fault Codes]''", "Ensures isolated chunks retain complete semantic context even when read independently by the embedding model"]}], "critical_failures": ["Advocating simple naive token-based chunking that splits tables across arbitrary boundaries", "Failing to mention specialized table parsing formats (Markdown, HTML, JSON) or layout parsers (Docling/TableFormer)", "Ignoring the loss of context when lists and structural headers are severed"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs did you consider when building an MVP for your RAG system, and which features were intentionally excluded?', '{"key_points": [{"id": "KP1", "description": "MVP scope definition: prioritizing a robust, end-to-end baseline RAG pipeline (core ingestion, dense vector search, prompt grounding) over complex, high-overhead features.", "required": true, "acceptable_evidence": ["Technical keywords: MVP (Minimum Viable Product), baseline RAG, core ingestion, dense vector retrieval, single-turn Q&A, rapid validation", "Focuses on proving business value on a clean, high-priority document subset (e.g. top 50 user manuals or standard operating procedures)", "Validates latency, basic factual accuracy, and integration feasibility before adding advanced modules"]}, {"id": "KP2", "description": "Intentionally excluded features: deferring multi-agent orchestration, complex dynamic fine-tuning, automated self-correction loops, and multi-modal parsing to subsequent phases.", "required": true, "acceptable_evidence": ["Technical keywords: excluded features, multi-agent workflows, model fine-tuning, dynamic GraphRAG, multi-modal ingestion, automated agent tool execution", "Avoids non-deterministic autonomous agent loops that inflate latency and failure modes", "Defers complex GraphRAG knowledge graph extraction due to massive ingestion overhead and high LLM extraction costs"]}, {"id": "KP3", "description": "Trade-offs between speed-to-market and architectural perfection: accepting simpler fixed/recursive chunking and managed vector services to accelerate deployment and feedback gathering.", "required": true, "acceptable_evidence": ["Technical keywords: time-to-market, feedback loop, technical debt, managed services, rapid iteration, pragmatic trade-offs", "Chooses managed cloud endpoints and standard embedding models to avoid infrastructure rabbit holes", "Collects real user query distributions and failure logs to inform subsequent reranking and hybrid search enhancements"]}], "critical_failures": ["Failing to specify which features were deliberately cut and why (e.g. multi-agent loops, fine-tuning, graph databases)", "Treating MVP as an excuse for poor retrieval quality rather than disciplined scope management", "Failing to articulate how MVP findings informed production iterations"]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs did you consider when choosing like ChromaDB, PGVector, and MilvusDB across different phases of your project?', '{"key_points": [{"id": "KP1", "description": "ChromaDB evaluation and usage phase: ideal for local prototyping, rapid developer onboarding, and embedded in-memory proof-of-concept testing with zero infrastructure overhead.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB, POC (Proof of Concept), local prototyping, embedded vector store, in-memory/DuckDB backend, zero setup", "Explains using ChromaDB in Phase 1 for fast local iteration without provisioning cloud clusters", "Identifies scaling limitations: lack of distributed multi-node clustering and high-concurrency enterprise support"]}, {"id": "KP2", "description": "PGVector evaluation and usage phase: leveraging existing PostgreSQL relational databases with vector extensions for unified transactional relational data and vector similarity.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector, PostgreSQL extension, ACID compliance, unified relational data, relational joins, HNSW/IVFFlat in Postgres", "Explains benefits: no additional database to operate; can execute SQL JOIN between relational tables and vector embeddings in a single query", "Identifies limitations: indexing performance degrades at high write volumes and scale (>millions of vectors) under concurrent search load"]}, {"id": "KP3", "description": "MilvusDB evaluation and usage phase: deploying for enterprise production scale, distributed high-concurrency ANN retrieval, and billion-scale vector workloads.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, enterprise production, distributed architecture, query/data node separation, high QPS, cloud-native scalability", "Explains selecting Milvus for multi-tenancy partition keys, GPU/SIMD index acceleration, and independent compute/storage scaling", "Justifies operational overhead of Kubernetes/Etcd/MinIO by achieving sub-30ms p95 latency under high concurrent load"]}, {"id": "KP4", "description": "Phase-driven evolution criteria: transitioning across database tiers based on vector volume, concurrency SLA, operational complexity, and team maturity.", "required": false, "acceptable_evidence": ["Technical keywords: migration criteria, concurrency SLAs, volume thresholds, operational complexity, total cost of ownership (TCO)", "Outlines progression: Chroma (dev/POC) -> PGVector (initial production with relational linkage) -> Milvus (scale-out distributed enterprise engine)", "Balances engineering maintenance overhead against performance requirements"]}], "critical_failures": ["Confusing the architectural roles of ChromaDB, PGVector, and Milvus", "Failing to explain the trade-off between unified relational storage (PGVector) and dedicated distributed vector engines (Milvus)", "Ignoring operational complexity and scaling thresholds across project phases"]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs did you consider when deciding not to index all available data in the vector database?', '{"key_points": [{"id": "KP1", "description": "Cost and compute trade-offs: indexing all available enterprise data introduces massive embedding generation costs, bloated vector index RAM requirements, and storage expenses.", "required": true, "acceptable_evidence": ["Technical keywords: embedding API costs, vector RAM footprint, HNSW memory overhead, storage costs, compute budget", "Explains that HNSW graphs require holding raw vectors and graph linkages in memory (RAM), where indexing low-value logs or obsolete docs is cost-prohibitive", "Highlights wasteful spend embedding redundant, ephemeral, or structured tabular data better suited for SQL"]}, {"id": "KP2", "description": "Search precision and noise dilution: indexing unstructured noise, duplicates, legacy policies, and transient chatter pollutes retrieval recall and causes false-positive context injection.", "required": true, "acceptable_evidence": ["Technical keywords: search noise, signal-to-noise ratio, retrieval pollution, false positives, semantic crowding, outdated documentation", "Explains how embedding redundant or superseded versions (e.g. 2018 policy vs 2024 policy) causes vector collisions and model hallucinations", "Curating high-authority knowledge bases dramatically improves Hit Rate and top-k relevance"]}, {"id": "KP3", "description": "Data hygiene and selective ingestion strategies: filtering by document freshness, business authority, access permissions, and content format suitability.", "required": true, "acceptable_evidence": ["Technical keywords: selective ingestion, data curation pipeline, document lifecycle management, authoritative sources, structured vs unstructured split", "Leaves structured operational records (transactions, inventory) in relational databases, indexing only authoritative manuals and knowledge articles", "Applies deduplication, version gating, and quality thresholds before embedding generation"]}], "critical_failures": ["Failing to identify the negative impact of noise and duplicate data on vector search precision (semantic crowding)", "Ignoring the RAM and financial cost implications of indexing massive enterprise datasets", "Failing to articulate selective ingestion criteria (e.g. freshness, authority, structured data separation)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What types of data sources did you use in your RAG system, and how did you preprocess and manage unstructured data?', '{"key_points": [{"id": "KP1", "description": "Enterprise unstructured data sources: ingesting heterogeneous data formats including technical PDF manuals, customer service tickets, Confluence/SharePoint knowledge pages, and transcribed audio logs.", "required": true, "acceptable_evidence": ["Technical keywords: heterogeneous data sources, PDF manuals, customer support transcripts, Confluence/Notion, HTML articles, service bulletins", "Identifies specific document types (e.g. EV service manuals, standard operating procedures, warranty policies, CRM ticket histories)", "Notes distinct formatting challenges inherent in each file format"]}, {"id": "KP2", "description": "Preprocessing and parsing pipeline: extracting clean text, normalizing typography, stripping boilerplate, and applying layout-aware parsers for complex layouts.", "required": true, "acceptable_evidence": ["Technical keywords: text normalization, boilerplate removal, layout-aware parsing, Docling, Unstructured, PDF OCR, table extraction", "Strips repeated headers, footers, legal disclaimers, and navigation bars that pollute vector representations", "Converts structured tables and multi-column layouts into clean Markdown representation"]}, {"id": "KP3", "description": "Chunking, metadata enrichment, and lifecycle management: splitting documents along semantic boundaries, tagging rich metadata, and tracking document versioning in S3.", "required": true, "acceptable_evidence": ["Technical keywords: semantic/recursive chunking, metadata enrichment (document_id, version, category, timestamp), AWS S3 staging, hashing for deduplication", "Computes cryptographic content hashes (SHA-256) to detect modified documents and avoid re-embedding unchanged files", "Attaches structural hierarchy breadcrumbs to maintain semantic coherence in isolated chunks"]}], "critical_failures": ["Listing data sources without detailing concrete preprocessing or parsing steps", "Ignoring layout extraction issues (e.g. tables, headers/footers in PDFs)", "Failing to mention metadata enrichment or deduplication during ingestion management"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What was your approach to transitioning from traditional RAG pipelines to agentic workflows using frameworks like LangGraph?', '{"key_points": [{"id": "KP1", "description": "Limitations of linear RAG pipelines: rigid sequential flow (query -> retrieve -> generate) cannot handle complex multi-step reasoning, ambiguous intent, tool execution, or dynamic self-correction.", "required": true, "acceptable_evidence": ["Technical keywords: linear RAG limitations, sequential execution, lack of self-correction, failure to handle multi-hop queries, static retrieval", "Explains that if initial retrieval fails or returns incomplete context in a standard pipeline, the final answer inevitably hallucinates or fails", "Points out inability of traditional RAG to interact with external transactional APIs"]}, {"id": "KP2", "description": "LangGraph stateful orchestration architecture: modeling workflows as directed cyclic graphs (StateGraph) with typed state, functional nodes, conditional routing edges, and iterative loops.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, agent state schema, nodes, conditional edges, cyclic routing, router/supervisor", "Details defining a centralized state object containing query, retrieved documents, message history, and execution flags", "Implements conditional edges: directing flow to ''retrieve'', ''rewrite_query'', ''execute_tool'', or ''generate_response'' based on runtime evaluations"]}, {"id": "KP3", "description": "Self-reflective agentic patterns: incorporating corrective retrieval (CRAG) and self-RAG mechanisms to dynamically evaluate retrieval quality and rewrite queries.", "required": true, "acceptable_evidence": ["Technical keywords: Corrective RAG (CRAG), Self-RAG, retrieval grader node, hallucination checker, query rewriting loop, recursion limits", "Grader node inspects retrieved chunks; if irrelevant, system loops back to query rewrite node rather than generating", "Enforces max iteration bounds (e.g. recursion_limit=3) to prevent infinite execution cycles"]}, {"id": "KP4", "description": "State persistence and Human-in-the-Loop (HITL): utilizing LangGraph checkpointers for pause/resume capabilities and human escalation for high-stakes tool execution.", "required": false, "acceptable_evidence": ["Technical keywords: checkpointers (MemorySaver/PostgresSaver), HITL interrupt, human review, state rollback, transactional safety", "Freezes agent execution graph before triggering irreversible API actions (e.g. booking service appointments, issuing warranty credits)", "Allows human agents to approve or modify payload before resuming execution"]}], "critical_failures": ["Treating agentic workflows as simple chained prompts rather than stateful cyclic graph architectures", "Failing to explain LangGraph components (StateGraph, nodes, conditional edges, checkpointers)", "Omitting corrective feedback loops (e.g. query rewriting or retrieval evaluation) and recursion safeguards"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'What were the key differences between phase one (RAG-based Q&A;) and phase two (agentic AI) of your project in terms of system design and capabilities?', '{"key_points": [{"id": "KP1", "description": "Phase 1 architecture and capabilities: passive, single-turn informational Q&A system using static retrieval-augmented generation for knowledge search.", "required": true, "acceptable_evidence": ["Technical keywords: Phase 1, informational Q&A, static RAG, passive retrieval, read-only knowledge base, single-turn query", "System retrieves top-k chunks from documentation and generates a conversational answer without performing actions", "Scoped purely to answering user questions based on static manuals and standard operating procedures"]}, {"id": "KP2", "description": "Phase 2 architecture and capabilities: active, multi-turn agentic AI solution capable of intent decomposition, tool execution, external API integration, and automated task execution.", "required": true, "acceptable_evidence": ["Technical keywords: Phase 2, Agentic AI, task automation, tool calling, API integration, multi-turn reasoning, stateful orchestration (LangGraph)", "System moves beyond answering questions to completing end-to-end workflows (e.g. booking appointments, looking up VIN warranty status in CRM, creating support tickets)", "Incorporates multi-agent delegation or supervisory orchestration to coordinate specialized tools"]}, {"id": "KP3", "description": "System design evolution: transitioning from stateless request-response to stateful graph execution, distributed checkpointers, and safety guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: stateful orchestration, conversation memory, session checkpointers, safety guardrails, schema validation, HITL", "Introduced LangGraph StateGraph with persistent checkpoints to track user context across multiple interaction turns", "Implemented deterministic schema validation (Pydantic) and Human-in-the-Loop gates for state-altering transactions"]}, {"id": "KP4", "description": "Business impact and metric progression: scaling from assisting agent information lookup to automating routine customer inquiries.", "required": false, "acceptable_evidence": ["Technical keywords: deflection rate, AHT reduction, FCR improvement, end-to-end resolution, operational ROI", "Phase 1 reduced Average Handling Time (AHT) by 25-35% via instant knowledge retrieval", "Phase 2 enabled autonomous resolution of tier-1 repetitive service tasks, improving First Contact Resolution (FCR) significantly"]}], "critical_failures": ["Failing to highlight the shift from read-only informational Q&A (Phase 1) to actionable API task automation (Phase 2)", "Ignoring the architectural changes required for state management, tool calling, and guardrails in Phase 2", "Presenting Phase 2 merely as a larger prompt or better embedding model rather than a paradigm shift"]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What were the limitations of ChromaDB that led you to migrate to Milvus, and how did this impact scalability and performance?', '{"key_points": [{"id": "KP1", "description": "ChromaDB architectural limitations encountered: embedded in-memory architecture, lack of native distributed clustering, high memory footprint, and concurrency bottlenecks under enterprise load.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB limitations, embedded architecture, lack of distributed scaling, memory exhaustion, SQLite / DuckDB backend bottlenecks", "ChromaDB excels in early POC local development but struggles when concurrent query requests scale up", "Lacked horizontal sharding across multiple nodes and native multi-tenancy partition pruning"]}, {"id": "KP2", "description": "Milvus architectural capabilities and benefits: distributed microservices architecture, separation of query/data/index nodes, horizontal scalability, and multi-tenancy partition keys.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed architecture, query/data/index node separation, horizontal scalability, partition keys, cloud-native storage (S3/MinIO)", "Decouples stateless query nodes from data storage, allowing independent autoscaling during traffic surges", "Provides native multi-tenancy partition keys to enforce strict physical partition pruning"]}, {"id": "KP3", "description": "Impact on system performance and scalability: significant drop in p95 query latency under concurrent load, high QPS throughput, and zero-downtime index building.", "required": true, "acceptable_evidence": ["Technical keywords: p95 latency reduction (<30ms), high QPS throughput, asynchronous indexing, zero query disruption, production stability", "Achieved sub-30ms retrieval latency across millions of vectors while supporting hundreds of concurrent queries", "Index node builds HNSW graphs asynchronously without starving query nodes of CPU or memory"]}], "critical_failures": ["Failing to explain the architectural differences between ChromaDB (embedded/single-node) and Milvus (distributed microservices)", "Failing to mention the specific performance bottlenecks (concurrency, memory scaling, indexing overhead)", "Ignoring Milvus scaling mechanisms (node separation, partition keys, object storage persistence)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What were your main responsibilities as a tech lead in this project across architecture, retrieval, generation, evaluation, and deployment?', '{"key_points": [{"id": "KP1", "description": "Architecture and system design leadership: defining the end-to-end decoupled microservices architecture, technology stack selection, and scalability strategy across ingestion and query serving.", "required": true, "acceptable_evidence": ["Technical keywords: tech lead ownership, system architecture, microservices design, technology stack selection, decoupled ingestion, scalability planning", "Established architectural boundaries: FastAPI query service, asynchronous Celery/SQS ingestion workers, Milvus vector database on EKS", "Defined API contracts, data models (Pydantic), and database schemas for multi-tenancy"]}, {"id": "KP2", "description": "Retrieval and generation engineering: designing the hybrid retrieval strategy (BM25 + dense vector), cross-encoder reranking, and strict prompt grounding architectures.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval design, RRF score fusion, cross-encoder reranker tuning, prompt grounding engineering, hallucination defense", "Architected the two-stage retrieval pipeline: parallel search pruned via RRF and reranked using BGE-Reranker", "Engineered system prompts with XML delimiters, few-shot examples, and citation enforcement"]}, {"id": "KP3", "description": "Evaluation framework and CI/CD quality gates: establishing the golden benchmark dataset and integrating automated Ragas evaluation into deployment pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: golden benchmark dataset curation, Ragas evaluation gate, Faithfulness/Recall thresholds, CI/CD pipeline, regression testing", "Curated 150-200 ground-truth QA triplets with domain experts to benchmark performance", "Configured GitHub Actions CI/CD to block deployments if Faithfulness dropped below 0.90 or Hit Rate@5 below 0.85"]}, {"id": "KP4", "description": "Deployment, observability, and cross-functional leadership: managing Kubernetes container deployments on AWS EKS, OpenTelemetry tracing, and stakeholder alignment.", "required": false, "acceptable_evidence": ["Technical keywords: AWS EKS deployment, OpenTelemetry distributed tracing, CloudWatch monitoring, stakeholder management, mentoring engineers", "Oversaw containerization, Helm chart configuration, and Horizontal Pod Autoscaling (HPA) policies", "Reported business KPIs (AHT reduction, FCR gains) to enterprise executive stakeholders"]}], "critical_failures": ["Giving generic team member responses without articulating technical leadership, architectural decision-making, and system ownership", "Failing to cover the five pillars: architecture, retrieval, generation, evaluation, and deployment", "Omitting quality gates and evaluation methodology leadership"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'When designing the RAG layer for production issue detection, what are the critical components of the data ingestion pipeline, and why is semantic encoding crucial during the embedding and chunking stage?', '{"key_points": [{"id": "KP1", "description": "Critical ingestion pipeline components: log/ticket stream ingestion, telemetry normalization, PII sanitization, structured metadata extraction, and deduplication.", "required": true, "acceptable_evidence": ["Technical keywords: data ingestion pipeline, log parsing, telemetry normalization, PII sanitization, metadata tagging, Kafka/S3 ingestion", "Extracts stack traces, error codes, service names, and severity levels into structured attributes alongside raw textual incident summaries", "Filters out high-frequency noise, repetitive heartbeats, and transient alerts to prevent index pollution"]}, {"id": "KP2", "description": "Why semantic encoding is crucial during chunking: raw error logs and production issues contain idiosyncratic syntax, stack traces, and variable parameters that break naive text chunking.", "required": true, "acceptable_evidence": ["Technical keywords: semantic boundary preservation, stack trace integrity, error log syntax, contextual cohesion, exception block chunking", "Explains that naive token chunking severs stack traces from root-cause error messages, destroying diagnostic meaning", "Chunking must respect logical boundaries (e.g. keeping entire exception blocks, environmental context, and resolution steps intact)"]}, {"id": "KP3", "description": "Semantic encoding during embedding: mapping diverse diagnostic terminology and incident descriptions into a shared semantic latent space.", "required": true, "acceptable_evidence": ["Technical keywords: dense semantic embedding, domain-adapted embeddings, vocabulary mismatch, error code mapping, root-cause correlation", "Enables matching an engineer''s colloquial symptom query (''database timeout during peak checkout'') with a past incident log (''ConnectionPoolExhaustedException: thread pool starved'')", "Captures latent conceptual similarity across disparate error formats and legacy ticketing systems"]}, {"id": "KP4", "description": "Production integration and retrieval for rapid triage: combining vector similarity with temporal/component metadata filtering to locate matching historical post-mortems.", "required": false, "acceptable_evidence": ["Technical keywords: post-mortem retrieval, MTTR reduction, hybrid search, component metadata filtering, runbook recommendation", "Enables on-call engineers to retrieve resolved incident runbooks in seconds, significantly cutting Mean Time to Resolution (MTTR)", "Weights recent incident documentation higher using temporal decay scoring"]}], "critical_failures": ["Treating production log ingestion like simple unstructured web text without considering stack trace and telemetry structures", "Failing to explain why semantic encoding is essential to overcome vocabulary mismatch between symptoms and root-cause logs", "Ignoring the critical need to preserve intact error blocks during chunking"]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'When you''re like trying to retrieve information from a RAG vector database for example, you already have stored information but how do you ensure that you''re getting the most accurate information for your query or for your prompt and how can you basically improve your vector storage in a better way so that your accuracy actually improves during the time of retrieving of the information.', '{"key_points": [{"id": "KP1", "description": "Improving retrieval accuracy at the vector storage and indexing layer: optimizing index parameters (HNSW M, efSearch), partitioning via multi-tenancy keys, and selecting appropriate distance metrics.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW tuning, efSearch increase, M parameter, partition pruning, distance metric alignment (Cosine/IP), scalar indexing", "Explains that increasing efSearch at query time trades a few milliseconds for significantly higher recall (>95%)", "Creates scalar indexes on metadata fields (e.g. vehicle_model, component, doc_type) to enable high-speed pre-filtering"]}, {"id": "KP2", "description": "Enhancing stored chunk representation: implementing parent-child chunking, contextual breadcrumb prepending, and table markdown serialization prior to embedding.", "required": true, "acceptable_evidence": ["Technical keywords: contextual chunking, breadcrumb prepending, parent-child document store, small-to-big retrieval, metadata enrichment", "Stores smaller child chunks for dense semantic embedding while linking to larger parent chunks for LLM synthesis", "Prepends document title and section hierarchy to chunk text so embeddings capture full document context"]}, {"id": "KP3", "description": "Query-time enhancements: implementing hybrid search (BM25 + dense vector) fused with Reciprocal Rank Fusion (RRF) and secondary cross-encoder reranking.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, BM25 keyword search, dense ANN search, Reciprocal Rank Fusion (RRF), cross-encoder reranker", "Catches exact part numbers, acronyms, and error codes that pure vector search often misses", "Reranks combined candidate pool with BGE-Reranker to place the most contextually relevant chunks at the top"]}, {"id": "KP4", "description": "Iterative query reformulation and optimization: utilizing query rewriting, expansion, or HyDE to bridge semantic gaps between user prompts and stored knowledge.", "required": false, "acceptable_evidence": ["Technical keywords: query rewriting, HyDE (Hypothetical Document Embeddings), query expansion, multi-query generation", "Rewrites vague conversational prompts into clear, keyword-rich search queries before executing vector lookup", "Ensures query embedding aligns closely with the semantic distribution of indexed passages"]}], "critical_failures": ["Focusing solely on prompt engineering while completely ignoring vector database and indexing improvements", "Failing to mention hybrid search (BM25 + dense) or cross-encoder reranking as standard accuracy boosters", "Overlooking chunk quality improvements (e.g. contextual prepending, parent-child indexing)"]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose Milvus along with PostgreSQL and SQL databases in the same architecture?', '{"key_points": [{"id": "KP1", "description": "Division of architectural responsibilities: utilizing Milvus for high-dimensional vector similarity search while relying on PostgreSQL for structured transactional data, user state, and relational integrity.", "required": true, "acceptable_evidence": ["Technical keywords: architectural separation of concerns, specialized engines, Milvus for high-dimensional ANN vectors, PostgreSQL for ACID relational data", "Explains that Milvus excels at billion-scale vector indexing, SIMD/GPU acceleration, and horizontal vector search scaling", "PostgreSQL manages relational customer profiles, vehicle telemetry logs, chat session history, auth, and billing transactions"]}, {"id": "KP2", "description": "Limitations of relational databases for massive vector workloads: PGVector can suffer performance degradation under high-concurrency search and massive write ingestion compared to dedicated engines.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector limitations, resource contention, shared buffer pool, WAL bloat during index building, scaling bottlenecks", "Building large HNSW indexes in Postgres consumes substantial CPU/RAM, competing directly with transactional OLTP queries", "Milvus isolates vector search compute entirely from core enterprise database workloads"]}, {"id": "KP3", "description": "Integration and synchronization pattern: linking Milvus vector IDs to primary keys in PostgreSQL and maintaining consistency across systems.", "required": true, "acceptable_evidence": ["Technical keywords: cross-system ID linkage, primary key mapping, payload storage, change data capture (CDC), Debezium/Kafka sync", "Stores vector embedding and minimal chunk metadata in Milvus with a document_id foreign key referencing PostgreSQL", "Uses asynchronous event-driven pipelines (Kafka/SQS) to update vector indexes when relational records or documents are updated"]}], "critical_failures": ["Failing to articulate the clear separation of concerns between dedicated vector search and ACID relational data", "Not understanding the resource contention issues of running massive vector indexes inside an OLTP relational database", "Failing to explain how records are linked and synchronized between Milvus and PostgreSQL"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose Sentence Transformers (MiniLM L6) for embeddings, and how were embeddings stored and utilized within the Milvus vector database?', '{"key_points": [{"id": "KP1", "description": "Rationale for Sentence Transformers (all-MiniLM-L6-v2): high inference throughput, ultra-low latency (<15ms on CPU), small memory footprint (384 dimensions), and zero external API cost.", "required": true, "acceptable_evidence": ["Technical keywords: all-MiniLM-L6-v2, 384 dimensions, CPU inference, sub-15ms latency, lightweight model (80MB), zero API costs, local inference", "Explains selecting MiniLM for high-throughput batch ingestion and fast query-time embedding without network overhead", "384-dimensional vectors reduce RAM requirements by 75% compared to 1536-dimensional OpenAI embeddings"]}, {"id": "KP2", "description": "Storage architecture in Milvus: defining collection schemas with 384-dimensional float vector fields, scalar metadata fields, and HNSW index configuration.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus collection schema, DataType.FLOAT_VECTOR, dim=384, HNSW index, metric_type=COSINE/IP, scalar payload fields", "Defines schema containing doc_id, chunk_id, text_snippet, section_tag, and vector field", "Configures HNSW index parameters (M=16, efConstruction=200) optimized for 384-dim vector space"]}, {"id": "KP3", "description": "Utilization during retrieval: embedding incoming queries with the same MiniLM model, executing ANN similarity search with scalar filtering, and extracting relevant context.", "required": true, "acceptable_evidence": ["Technical keywords: query vector generation, search parameters (efSearch=64), boolean filter expression, Top-K retrieval, cosine similarity score", "Transforms raw user query into a 384-dim vector using the exact same MiniLM checkpoint", "Executes vector similarity search to return top-k candidate chunks with their text payloads for LLM context assembly"]}], "critical_failures": ["Failing to cite the exact dimension of all-MiniLM-L6-v2 (384 dimensions)", "Failing to mention the latency and resource efficiency trade-offs (CPU-friendly, low memory footprint)", "Ignoring the schema definition or query search workflow in Milvus"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose a RAG-based approach instead of fine-tuning an LLM for your use case with internal data?', '{"key_points": [{"id": "KP1", "description": "Dynamic data freshness and frequent updates: internal enterprise data (manuals, policies, specs, ticket histories) updates continuously; RAG updates instantly via ingestion while fine-tuning requires expensive retraining.", "required": true, "acceptable_evidence": ["Technical keywords: data freshness, frequent updates, continuous ingestion, static knowledge cutoff, retraining cost, zero retraining lag", "Explains that adding or revising documentation in RAG takes seconds (chunk, embed, insert into vector DB)", "Fine-tuning to incorporate daily or weekly document changes is financially and computationally prohibitive"]}, {"id": "KP2", "description": "Hallucination mitigation and verifiable citations: RAG grounds responses in explicit retrieved context with direct source attribution, whereas fine-tuning internalizes knowledge into probabilistic weights prone to confabulation.", "required": true, "acceptable_evidence": ["Technical keywords: hallucination mitigation, verifiable citations, source attribution, black-box weights, knowledge grounding, compliance auditability", "Customer-facing and compliance use cases demand verifiable source chunk citations that fine-tuned parametric weights cannot guarantee", "Enables auditing exactly which enterprise manual backed a specific claim"]}, {"id": "KP3", "description": "Access control and security governance: RAG enforces fine-grained Role-Based Access Control (RBAC) and multi-tenancy at the retrieval layer, whereas fine-tuned models expose all training data to any user.", "required": true, "acceptable_evidence": ["Technical keywords: Role-Based Access Control (RBAC), multi-tenancy, data governance, authorization filters, training data leakage", "Fine-tuned models cannot selectively hide confidential information based on user authorization levels", "RAG enforces metadata filters (e.g. user_tier == ''enterprise'' or role == ''internal_mechanic'') at search time"]}, {"id": "KP4", "description": "Complementary nature of fine-tuning: fine-tuning is optimal for tone, task format, and specialized syntax, whereas RAG provides factual retrieval.", "required": false, "acceptable_evidence": ["Technical keywords: fine-tuning for style/syntax, RAG for knowledge retrieval, hybrid approach, domain vocabulary adaptation", "Fine-tuning teaches the model *how* to speak or follow a custom JSON schema; RAG provides *what* facts to speak about", "Avoids attempting to use fine-tuning as a knowledge retrieval database"]}], "critical_failures": ["Believing fine-tuning is the primary way to teach an LLM continuously changing factual internal data", "Failing to mention the inability of fine-tuned models to provide verifiable citations or enforce RBAC access control", "Ignoring the computational cost and time lag of fine-tuning retraining cycles"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose a hybrid retrieval approach (semantic + keyword/BM25), and what limitations of semantic search did it address?', '{"key_points": [{"id": "KP1", "description": "Limitations of pure semantic/dense search: dense embeddings struggle with exact keyword matching, out-of-vocabulary acronyms, part numbers, error codes, and short unique identifiers.", "required": true, "acceptable_evidence": ["Technical keywords: dense search limitations, exact keyword failure, acronyms, part numbers, error codes (e.g. DTC P0A80), out-of-vocabulary terms", "Explains that embedding models map rare alphanumeric strings into blurred semantic neighborhoods, causing them to miss exact part matches", "Dense vectors excel at broad conceptual intent but fail at literal precision"]}, {"id": "KP2", "description": "Role and mechanism of hybrid retrieval: combining dense vector search (semantic similarity) with sparse keyword search (BM25 / inverted index) to achieve high recall across both conceptual and lexical queries.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, BM25, sparse inverted index, dense ANN search, lexical + semantic, high recall", "Executes parallel queries: BM25 catches exact keyword tokens while dense vector search captures synonym and paraphrase concepts", "Provides resilience across varied user query styles (expert part search vs colloquial symptom description)"]}, {"id": "KP3", "description": "Score fusion and ranking: merging dense and sparse candidate lists using Reciprocal Rank Fusion (RRF) or weighted linear score normalization.", "required": true, "acceptable_evidence": ["Technical keywords: Reciprocal Rank Fusion (RRF), score fusion, RRF formula 1/(k + rank), linear weighted score, alpha weighting", "Details RRF: combines rank orders without needing to calibrate incomparable raw score scales (BM25 unbounded vs cosine [-1, 1])", "Produces a unified, robust candidate list for downstream reranking"]}], "critical_failures": ["Failing to identify the failure modes of dense vector search (exact part numbers, error codes, rare acronyms)", "Omitting the mechanism of BM25 keyword search as the lexical component of hybrid retrieval", "Failing to explain how dense and sparse results are merged (e.g. Reciprocal Rank Fusion)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose cosine similarity and cross-encoder re-ranking for retrieval, and what benefits do they provide?', '{"key_points": [{"id": "KP1", "description": "Role of cosine similarity in stage 1 retrieval: provides ultra-fast Approximate Nearest Neighbor (ANN) vector search across massive collections with scale-invariant angle measurement.", "required": true, "acceptable_evidence": ["Technical keywords: stage 1 retrieval, cosine similarity, ANN search, bi-encoder, high recall, scale invariance, sub-30ms search", "Scores pre-computed dense embeddings independently to quickly narrow down millions of chunks to top-20..50 candidates", "Invariant to document chunk length variations"]}, {"id": "KP2", "description": "Role of cross-encoder reranking in stage 2: applies deep full cross-attention between query and candidate text to capture nuanced token-level interactions and syntactic dependencies.", "required": true, "acceptable_evidence": ["Technical keywords: stage 2 reranking, cross-encoder, BGE-Reranker, full cross-attention, token-level interactions, query-document joint modeling", "Eliminates bi-encoder bottleneck where query and passage are compressed into isolated vectors without attending to each other", "Dramatically boosts precision and filters out false-positive chunks before passing context to the LLM"]}, {"id": "KP3", "description": "Synergistic architectural benefits: achieves the optimal Pareto frontier balancing low search latency and high retrieval precision.", "required": true, "acceptable_evidence": ["Technical keywords: Pareto efficiency, latency vs accuracy trade-off, two-stage architecture, candidate pool pruning (50 -> 3/5)", "Running a cross-encoder across millions of chunks is computationally impossible (O(N) full model passes)", "Two-stage pipeline delivers the speed of bi-encoders (30ms) combined with the precision of cross-encoders (+30ms)"]}], "critical_failures": ["Failing to contrast the computational differences between bi-encoders (independent embedding) and cross-encoders (joint attention)", "Claiming cross-encoders are used for the entire database search instead of candidate reranking", "Failing to articulate the latency vs precision trade-off in two-stage retrieval"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose sentence transformers for embeddings, and how does it compare to alternatives like OpenAI embeddings?', '{"key_points": [{"id": "KP1", "description": "Architectural and operational advantages of Sentence Transformers: local on-premise/VPC deployment, complete data privacy, zero external API latency/rate-limits, and zero per-token cost.", "required": true, "acceptable_evidence": ["Technical keywords: Sentence Transformers, HuggingFace, on-premise/VPC execution, data privacy, compliance, zero API cost, no rate limits", "Processes embeddings inside internal infrastructure without transmitting sensitive enterprise IP or PII over external networks", "Eliminates API throttling, network jitter, and vendor lock-in during massive ingestion runs"]}, {"id": "KP2", "description": "Comparison with OpenAI embeddings (text-embedding-3-small/large): OpenAI offers higher zero-shot MTEB benchmarks and larger dimensionality (1536/3072) with managed ease, but incurs recurring API costs and latency.", "required": true, "acceptable_evidence": ["Technical keywords: OpenAI embeddings, text-embedding-3-small, 1536 dimensions, MTEB benchmarks, external SaaS API, per-token pricing", "OpenAI embeddings capture broader general knowledge and nuanced long-context relationships out-of-the-box", "Drawbacks: per-token API billing, network egress latency, potential vendor outages, and strict enterprise privacy barriers"]}, {"id": "KP3", "description": "Hardware and resource trade-offs: Sentence Transformers (e.g. MiniLM, BGE) run efficiently on commodity CPUs or small GPUs with fast 384-dim indexing, whereas larger models require dedicated GPU infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: CPU inference, 384 vs 1536 dimensions, RAM footprint, HNSW index memory, self-hosted GPU cost", "384-dimensional embeddings drastically reduce vector database memory usage and index building time", "Allows fine-tuning open-source models with domain-specific contrastive loss, which is not possible with proprietary closed embedding APIs"]}], "critical_failures": ["Failing to mention data privacy, security, and VPC compliance benefits of self-hosted Sentence Transformers", "Ignoring the difference in dimensionalities (384 vs 1536) and its impact on vector database RAM and indexing speed", "Failing to identify the trade-offs regarding API costs, rate limits, and network latency"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Why was a Retrieval-Augmented Generation (RAG) system chosen over relying solely on a standard LLM, and how does this approach manage domain-specific knowledge, data freshness, and hallucination prevention?', '{"key_points": [{"id": "KP1", "description": "Domain-specific knowledge integration: proprietary enterprise documentation (manuals, policies, warranties) is private, confidential, and absent from public LLM training datasets.", "required": true, "acceptable_evidence": ["Technical keywords: proprietary enterprise data, private manuals, confidential documentation, pre-training data absence, out-of-domain knowledge", "Standard foundation models lack internal corporate knowledge (e.g. proprietary EV diagnostic trouble codes, internal warranty guidelines)", "RAG dynamically injects authoritative proprietary documentation directly into the prompt context at query time"]}, {"id": "KP2", "description": "Data freshness and continuous updates: enterprise documents update continuously; RAG incorporates updates instantaneously via vector reindexing without retraining.", "required": true, "acceptable_evidence": ["Technical keywords: data freshness, knowledge cutoff, continuous updates, real-time ingestion, zero retraining latency", "Standard LLMs are locked to a static pre-training knowledge cutoff date", "RAG updates instantly upon new document uploads in S3 (sub-minute ingestion), ensuring answers always reflect current 2024 policies"]}, {"id": "KP3", "description": "Hallucination mitigation and verifiable citations: grounding generation in retrieved evidence with mandatory source attribution, eliminating speculative black-box fabrications.", "required": true, "acceptable_evidence": ["Technical keywords: hallucination prevention, source attribution, verifiable citations [Doc-1], grounding constraints, compliance auditability", "Standard LLMs generate plausible but factually incorrect assertions when uncertain (confabulation)", "RAG restricts the LLM to synthesized evidence from retrieved chunks and forces explicit chunk citations for compliance auditing"]}], "critical_failures": ["Failing to address all three requested aspects: domain knowledge, data freshness, and hallucination prevention", "Suggesting fine-tuning as the primary solution for data freshness and continuous updates", "Omitting the requirement for verifiable citations and compliance auditability"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'After retrieving SQL query results, should the LLM reprocess the data before responding to the user, and what are the trade-offs?', '{"key_points": [{"id": "KP1", "description": "Architectural decision on LLM post-processing: evaluating direct SQL result passthrough (raw tabular/JSON) versus LLM natural language synthesis and narrative formatting.", "required": true, "acceptable_evidence": ["Technical keywords: post-processing, SQL result passthrough, LLM synthesis, tabular formatting, natural language narration", "Explains that raw SQL output is deterministic, fast, and 100% faithful, but often cryptic for non-technical users", "LLM post-processing translates technical column headers and numbers into intuitive conversational summaries"]}, {"id": "KP2", "description": "Risks of LLM reprocessing: introducing hallucinations, arithmetic miscalculations, truncation of large result sets, and added latency/cost.", "required": true, "acceptable_evidence": ["Technical keywords: arithmetic hallucination, number confabulation, token limit truncation, added latency (TTFT), token cost", "LLMs frequently miscalculate sums, percentages, or alter exact decimal precision when summarizing SQL numbers", "Passing multi-thousand-row query results into context consumes large token budgets and risks truncation or lost-in-the-middle effects"]}, {"id": "KP3", "description": "Best-practice hybrid approach: rendering raw deterministic tables/charts in the UI alongside a lightweight, constrained LLM narrative summary with guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: dual representation, deterministic UI table, lightweight narrative, strict schema guardrail, read-only aggregation", "Present the raw SQL table directly in the UI for factual ground truth, with a 2-sentence LLM synthesis answering the specific user question", "Constrain the prompt: ''Summarize the finding without recalculating or modifying any numeric figures.''"]}], "critical_failures": ["Failing to recognize the risk of LLM arithmetic hallucinations and number confabulation when summarizing SQL results", "Ignoring the latency and context token costs of feeding large SQL result sets back into the LLM", "Failing to propose a hybrid solution separating deterministic tabular display from high-level narrative summary"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe a challenging use case you handled involving MCP server implementation, particularly with graph databases and semantic retrieval?', '{"key_points": [{"id": "KP1", "description": "Model Context Protocol (MCP) server architecture: exposing standardized tools and resources (JSON-RPC over stdio or SSE) to connect agent orchestrators with external databases.", "required": true, "acceptable_evidence": ["Technical keywords: Model Context Protocol (MCP), MCP server, JSON-RPC, stdio / SSE transport, standardized tool schema, resource endpoints", "Explains MCP decouples agent reasoning engines from specific database drivers and API implementations", "Defines explicit tool schemas with Pydantic/JSON Schema validation for incoming arguments"]}, {"id": "KP2", "description": "Graph database integration: querying knowledge graphs (Neo4j / Amazon Neptune) via Cypher templates and graph traversals to extract multi-hop entity relationships.", "required": true, "acceptable_evidence": ["Technical keywords: Neo4j, Cypher query, Amazon Neptune, knowledge graph, multi-hop relationship, entity-relation-entity triples", "Implements MCP tools for executing parameterized Cypher queries to navigate complex entity ontologies (e.g. part -> assembly -> failure code)", "Prevents Cypher injection by enforcing parameterized query templates rather than raw text concatenation"]}, {"id": "KP3", "description": "Semantic retrieval and GraphRAG fusion: unifying vector similarity search with structured graph neighborhood subgraphs in the MCP response payload.", "required": true, "acceptable_evidence": ["Technical keywords: GraphRAG, hybrid retrieval, vector similarity + graph traversal, ego-network subgraph, unified context", "Uses vector search to find initial seed entities, then executes 1-2 hop graph traversals to gather connected relational context", "MCP server serializes combined graph nodes and semantic passages into structured Markdown context for the agent"]}, {"id": "KP4", "description": "Production challenges and error handling: managing connection pools, query timeouts, cycle detection, and security sandboxing within the MCP runtime.", "required": false, "acceptable_evidence": ["Technical keywords: query timeout, connection pooling, recursion limits, read-only transactions, security sandboxing", "Enforces read-only database roles to prevent agents from executing destructive write operations", "Handles graph query timeouts gracefully with fallback to standard vector-only retrieval"]}], "critical_failures": ["Lacking understanding of what Model Context Protocol (MCP) is and how it communicates (standardized JSON-RPC tools/resources)", "Failing to explain how graph queries (Cypher / multi-hop traversals) integrate with semantic retrieval", "Ignoring injection safety or tool parameter validation"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how embeddings work conceptually and how cosine similarity enables semantic search compared to keyword-based approaches?', '{"key_points": [{"id": "KP1", "description": "Conceptual mechanism of embeddings: transforming high-dimensional discrete text tokens into continuous, dense latent vectors that encode semantic meaning and relational geometry.", "required": true, "acceptable_evidence": ["Technical keywords: dense vector embeddings, latent space, transformer encoder, continuous semantic space, dimensionality (e.g. 384/1536)", "Explains transformer self-attention pools token representations into a single fixed-length vector capturing overall contextual semantics", "Semantically similar phrases (e.g. ''battery depleted'' and ''EV won''t charge'') map to proximate points in latent space despite zero overlapping words"]}, {"id": "KP2", "description": "Cosine similarity mechanism: calculating the cosine of the angle between two embedding vectors to evaluate semantic alignment independently of text length or magnitude.", "required": true, "acceptable_evidence": ["Technical keywords: Cosine Similarity, dot product divided by norms, angular distance, vector angle, scale invariance, range [-1, 1]", "Explains formula: cos(θ) = (A · B) / (||A|| ||B||)", "Demonstrates that an angle near 0° (cosine ~ 1.0) indicates high semantic similarity, orthogonal 90° (0.0) means unrelated, and 180° (-1.0) represents diametrical opposites"]}, {"id": "KP3", "description": "Comparison with keyword-based retrieval (TF-IDF / BM25): keyword search requires exact lexical term overlap and fails on synonyms, paraphrases, and polysemy, while semantic search overcomes vocabulary mismatch.", "required": true, "acceptable_evidence": ["Technical keywords: keyword search, BM25, TF-IDF, lexical matching, vocabulary mismatch, synonymy, polysemy", "Details how BM25 fails if a user searches for ''automobile repair'' while the document says ''car servicing''", "Explains how cosine similarity retrieves semantically aligned passages regardless of exact wording"]}], "critical_failures": ["Failing to clearly explain the mathematical and geometric intuition of Cosine Similarity (measuring vector angle invariant to magnitude)", "Treating embeddings as simple word frequency lists rather than dense transformer latent spaces", "Failing to contrast semantic retrieval against keyword matching failure modes (synonymy, paraphrasing)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you implemented a hybrid retrieval strategy combining semantic search, BM25, and cross-encoder re-ranking?', '{"key_points": [{"id": "KP1", "description": "Hybrid first-stage retrieval architecture: executing parallel semantic vector search (ANN via HNSW) and lexical keyword search (BM25 inverted index).", "required": true, "acceptable_evidence": ["Technical keywords: parallel first-stage retrieval, dense vector search, BM25 keyword search, HNSW, inverted index", "Captures conceptual semantic intent via vector embeddings while simultaneously securing exact part numbers, acronyms, and error codes via BM25", "Retrieves top-k candidates (e.g. top-25 to top-50) from both search engines independently"]}, {"id": "KP2", "description": "Score fusion using Reciprocal Rank Fusion (RRF): combining ranked candidate lists without requiring cross-system score calibration.", "required": true, "acceptable_evidence": ["Technical keywords: Reciprocal Rank Fusion (RRF), rank combination, RRF score formula: sum(1 / (k + rank)), rank smoothing constant k=60", "Explains why naive score summation fails due to mismatched score distributions (unbounded BM25 scores vs bounded cosine similarity)", "RRF generates a unified, calibrated candidate list based purely on rank positions"]}, {"id": "KP3", "description": "Second-stage cross-encoder reranking: scoring the top fused candidates with a high-capacity cross-attention model to extract the final top-3 to top-5 chunks.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder reranking, BGE-Reranker-large, Cohere Rerank, joint cross-attention, candidate pool pruning (50 -> 3/5)", "Passes concatenated (query, passage) pairs into the cross-encoder to model full bidirectional token interactions", "Applies a relevance confidence threshold (e.g. score >= 0.45) to discard irrelevant context"]}, {"id": "KP4", "description": "Latency profiling and performance benefits: balancing retrieval accuracy against SLA limits across the multi-stage pipeline.", "required": false, "acceptable_evidence": ["Technical keywords: latency budget, end-to-end SLA, GPU/ONNX runtime, candidate pool sizing, Hit Rate improvement", "Maintains sub-100ms total retrieval latency: 25ms parallel search + 5ms RRF + 35ms cross-encoder inference", "Significantly improves Hit Rate@5 and NDCG compared to standalone dense search"]}], "critical_failures": ["Failing to detail how dense and sparse results are merged (e.g. RRF formula and rationale)", "Omitting the distinction between bi-encoder candidate retrieval and cross-encoder reranking", "Failing to specify candidate pool sizes (e.g. retrieving 50 and pruning to 3-5)"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you performed query optimization in your RAG system and how prompt refinement helped reduce hallucinations?', '{"key_points": [{"id": "KP1", "description": "Query optimization techniques: implementing query expansion, HyDE (Hypothetical Document Embeddings), and multi-turn coreference rewriting to resolve ambiguous user queries.", "required": true, "acceptable_evidence": ["Technical keywords: query optimization, query rewriting, HyDE (Hypothetical Document Embeddings), multi-query expansion, coreference resolution", "Rewrites vague conversational prompts into explicit, standalone search queries before retrieval", "Generates hypothetical answer passages using an LLM to align search vectors closer to target document distributions"]}, {"id": "KP2", "description": "Prompt refinement for hallucination reduction: framing strict grounding boundaries, mandatory source citation tags, and explicit refusal directives.", "required": true, "acceptable_evidence": ["Technical keywords: prompt refinement, strict grounding prompt, explicit refusal directive, bracketed citations [Chunk-ID], out-of-context fallback", "Prompts: ''Answer the question solely using the provided context snippets. If the context does not contain the answer, reply that the information is not available.''", "Requires the LLM to cite verbatim chunk identifiers for each factual claim"]}, {"id": "KP3", "description": "Structured generation and Chain-of-Thought (CoT): forcing the model to cite evidence snippets in a structured scratchpad before synthesizing the final response.", "required": true, "acceptable_evidence": ["Technical keywords: Chain-of-Thought (CoT), extract-then-synthesize, scratchpad, JSON schema constraint, Pydantic validation", "Forces LLM to first output extracted verbatim quotes under an ''evidence'' field before drafting the customer-facing answer", "Significantly reduces ungrounded confabulation and enables programmatic citation validation"]}], "critical_failures": ["Failing to explain concrete query optimization methods (HyDE, coreference rewriting, query expansion)", "Recommending vague prompts without strict grounding boundaries or explicit refusal instructions", "Ignoring structured citation requirements or two-step reasoning (extract-then-synthesize)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you would design a RAG-powered chatbot that decides when to escalate queries to human experts?', '{"key_points": [{"id": "KP1", "description": "Confidence scoring and escalation triggers: establishing multi-factor thresholds across retrieval scores, hallucination detectors, and intent classification to trigger human escalation.", "required": true, "acceptable_evidence": ["Technical keywords: escalation triggers, confidence threshold, cross-encoder score cutoff, NLI entailment score, low-confidence fallback", "Escalates when top reranker score is below threshold (e.g. score < 0.40) or when retrieved context relevance is poor", "Escalates when Natural Language Inference (NLI) flags high contradiction or low faithfulness in the generated response"]}, {"id": "KP2", "description": "Domain-specific and policy risk triggers: identifying high-liability intents (safety hazards, legal disputes, financial refunds, sentiment distress) that mandate immediate agent intervention.", "required": true, "acceptable_evidence": ["Technical keywords: high-liability intents, safety hazards, emergency procedures, negative sentiment spike, policy violations", "Directly routes dangerous queries (e.g. ''high voltage battery smoking'', ''brake failure'') to live tier-2 technicians immediately", "Detects aggressive customer sentiment or repeated unresolved questions in multi-turn dialogues"]}, {"id": "KP3", "description": "Escalation orchestration and handoff protocol: transferring conversation context, summary, retrieved chunks, and customer intent to human CRM platforms (e.g. Salesforce, Zendesk).", "required": true, "acceptable_evidence": ["Technical keywords: agent handoff protocol, conversation summary, CRM integration, Salesforce/Zendesk webhook, state transfer", "Generates an automated handoff packet: structured customer profile, conversation summary, detected failure codes, and attempted bot answers", "Ensures human agent has complete context without asking the customer to repeat their issue"]}, {"id": "KP4", "description": "Human-in-the-Loop feedback loop: capturing human agent resolutions to continuously improve the RAG golden dataset and knowledge base.", "required": false, "acceptable_evidence": ["Technical keywords: HITL feedback loop, golden dataset enrichment, knowledge gap detection, active learning", "Logs escalated queries and human responses to identify missing knowledge articles and update vector embeddings", "Improves automated deflection rate over time"]}], "critical_failures": ["Relying solely on user-initiated escalation without automated quantitative confidence and risk scoring", "Failing to explain how retrieval/faithfulness scores trigger programmatic escalation", "Ignoring the handoff payload and CRM integration needed for seamless human agent takeover"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how your system handled embedding generation, metadata management, and vector database interactions?', '{"key_points": [{"id": "KP1", "description": "Embedding generation pipeline: batching text chunks, managing GPU/CPU inference with Sentence Transformers or Bedrock APIs, and applying normalization.", "required": true, "acceptable_evidence": ["Technical keywords: embedding generation, batch inference, all-MiniLM-L6-v2 / BGE / Bedrock Titan, L2 normalization, embedding cache", "Batches chunks (batch size 32-128) to maximize throughput and GPU utilization during ingestion", "Applies L2 unit normalization to allow dot product similarity to equal cosine similarity"]}, {"id": "KP2", "description": "Structured metadata management: associating granular scalar attributes (doc_id, chunk_id, section, timestamp, access_tier, tenant_id) with vector payloads.", "required": true, "acceptable_evidence": ["Technical keywords: scalar metadata, payload attributes, document hierarchy, tenant isolation, access tier, scalar indexing", "Attaches structured JSON payloads to vector entities to enable hybrid filtering and strict role-based access", "Creates scalar indexes (e.g. Marisa Trie or inverted index on metadata fields) to accelerate pre-filtering"]}, {"id": "KP3", "description": "Vector database interaction patterns: managing collection schemas, HNSW index parameters, connection pooling, and CRUD operations in Milvus/Pinecone.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus connection pooling, collection schema, HNSW index build (M=16, efConstruction=200), search params (efSearch=64), upsert/delete operations", "Uses connection pools and asynchronous clients for high-concurrency query execution", "Executes upsert workflows using document content hashes to prevent duplicate vector entries"]}], "critical_failures": ["Treating vector storage as a raw embedding array without metadata payloads or scalar filtering", "Failing to describe the batching and normalization process in embedding generation", "Overlooking index configuration parameters (e.g. HNSW M and efSearch) or connection pooling"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain the design and purpose of the hallucination detection model you built?', '{"key_points": [{"id": "KP1", "description": "Purpose and architectural role: serving as an automated runtime validation guardrail to evaluate generated responses against retrieved context before presenting them to users.", "required": true, "acceptable_evidence": ["Technical keywords: hallucination detection model, runtime guardrail, post-generation validation, automated fact-checking, context verification", "Explains preventing ungrounded, fabricated, or contradictory statements from reaching enterprise customers", "Acts as a gatekeeper between the LLM output and the API client"]}, {"id": "KP2", "description": "Model design and Natural Language Inference (NLI): utilizing fine-tuned cross-encoder NLI models (e.g. DeBERTa-v3) to score sentence-level entailment, neutrality, and contradiction.", "required": true, "acceptable_evidence": ["Technical keywords: Natural Language Inference (NLI), DeBERTa-v3, premise-hypothesis classification, entailment, contradiction, neutrality", "Segments generated answer into discrete atomic claims/sentences (hypotheses) and evaluates each against retrieved context chunks (premises)", "Computes an aggregate faithfulness score based on the proportion of entailed claims"]}, {"id": "KP3", "description": "Alternative and ensemble detection techniques: combining NLI with LLM-as-a-judge (RAGAS/DeepEval) and token-level citation alignment verification.", "required": true, "acceptable_evidence": ["Technical keywords: LLM-as-a-judge, SelfCheckGPT, citation alignment, claim decomposition, ensemble verification", "Decomposes complex answers into atomic factual statements and prompts an evaluator model to verify if each statement is supported by context", "Verifies that bracketed citations contain the exact textual claim asserted in the response"]}, {"id": "KP4", "description": "Operational latency and mitigation actions: balancing sub-100ms inference overhead, logging hallucination events, and triggering automated fallbacks.", "required": false, "acceptable_evidence": ["Technical keywords: latency budget, ONNX runtime, fallback trigger, regeneration loop, observability logging", "Uses distilled/quantized NLI models on ONNX/TensorRT to keep validation latency under 50ms", "If contradiction score exceeds threshold, the response is discarded and replaced with a polite safe fallback"]}], "critical_failures": ["Failing to explain the core mechanism of hallucination detection (e.g. NLI entailment scoring or claim decomposition)", "Confusing hallucination detection with input prompt moderation", "Ignoring operational latency constraints and fallback handling"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Could you walk me through how you would integrate Retrieval-Augmented Generation (RAG) with a memory management system to handle both short-term and long-term contexts? Specifically, how would you balance retrieval efficiency with ensuring the relevance of retrieved data?', '{"key_points": [{"id": "KP1", "description": "Short-term memory architecture: managing active multi-turn conversation buffer, sliding window of recent messages, and entity state in fast cache (Redis).", "required": true, "acceptable_evidence": ["Technical keywords: short-term memory, conversation buffer, sliding window, Redis cache, session state, recent message history", "Maintains last 5-10 turns of dialogue in low-latency Redis cache for immediate context during follow-up questions", "Tracks active conversation entities (e.g. customer VIN, selected vehicle trim, active error code)"]}, {"id": "KP2", "description": "Long-term memory architecture: storing past user interactions, episodic preferences, and historical resolutions as semantic embeddings in a dedicated vector index.", "required": true, "acceptable_evidence": ["Technical keywords: long-term memory, episodic memory, vector-backed memory, conversation summarization, user profile embeddings", "Summarizes completed sessions asynchronously and embeds the summary into a dedicated user-memory vector collection", "Enables the agent to recall past issues, user preferences, and service history across sessions weeks apart"]}, {"id": "KP3", "description": "Balancing retrieval efficiency and relevance: implementing multi-tier retrieval routing, query contextualization, and token budget management.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tier retrieval, contextual query rewriting, memory relevance threshold, token budget allocation, recency decay", "Rewrites user prompt using short-term memory before retrieving static knowledge and long-term memories", "Allocates strict token budgets in prompt context: e.g. 500 tokens for short-term history, 300 tokens for long-term memory, 2000 tokens for retrieved knowledge", "Applies time-decay weighting to prioritize recent long-term memories over older interactions"]}], "critical_failures": ["Failing to distinguish between short-term conversation state (Redis/buffer) and long-term persistent memory (vector embeddings/summaries)", "Ignoring prompt token budget allocation across memory and retrieved knowledge chunks", "Failing to address retrieval efficiency and relevance balancing mechanisms (e.g. query rewriting, recency decay)"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Discuss the dangers of agent reasoning, and explain how you implement guardrails and validation techniques to manage toxicity, PII, and prevent hallucinations in your LLM and agent systems.', '{"key_points": [{"id": "KP1", "description": "Dangers of unconstrained agent reasoning: infinite recursion loops, tool execution hallucinations, prompt injection hijacking, cascading errors, and unauthorized state changes.", "required": true, "acceptable_evidence": ["Technical keywords: unconstrained reasoning dangers, infinite loops, recursive tool explosion, prompt injection, tool hallucination, cascading failures", "Autonomous agents given tool-calling abilities can execute destructive commands (e.g. deleting database rows or issuing false refunds)", "Vulnerable to indirect prompt injection embedded within retrieved external documents"]}, {"id": "KP2", "description": "Toxicity and PII guardrail implementation: applying automated redaction and classification pipelines (Microsoft Presidio, Llama Guard, AWS Comprehend) across inputs and outputs.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, Microsoft Presidio, Llama Guard, toxicity classification, regex filters, NER anonymization", "Sanitizes customer SSN, credit cards, emails, and phone numbers before storing in vector indexes or logging", "Applies safety classifiers to intercept toxic, biased, or abusive prompts and model generations"]}, {"id": "KP3", "description": "Hallucination mitigation and deterministic validation: enforcing Pydantic schema validation on tool outputs, strict grounding prompts, and Natural Language Inference (NLI) scoring.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic schema validation, deterministic parsing, NLI entailment, strict grounding, citation verification", "Validates agent tool parameters against strict typed schemas before executing API calls", "Verifies generated claims against retrieved context using NLI entailment checks to detect hallucinated facts"]}, {"id": "KP4", "description": "Operational guardrails and circuit breakers: enforcing recursion limits, execution timeouts, read-only permissions, and Human-in-the-Loop approval gates.", "required": false, "acceptable_evidence": ["Technical keywords: circuit breakers, recursion limit (max_iterations=5), timeout limits, HITL approval, principle of least privilege", "Hard-caps agent graph steps to 5-10 iterations to prevent runaway execution costs", "Requires human supervisor confirmation for any high-risk state-altering tool action"]}], "critical_failures": ["Failing to identify concrete dangers of autonomous agent reasoning (infinite loops, prompt injection, tool hallucination)", "Overlooking programmatic PII redaction tools like Microsoft Presidio or Llama Guard", "Failing to include operational safeguards such as recursion limits and Human-in-the-Loop gates"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Explain the retrieval and generation metrics (e.g., F-score, precision@k, recall@k, faithfulness) used for evaluating the RAG system, and describe the evaluation process, including the use of Ragas and an LLM serving as a judge against a ground truth dataset.', '{"key_points": [{"id": "KP1", "description": "Component-level retrieval metrics: Precision@K, Recall@K, F-score, Hit Rate@K, and Mean Reciprocal Rank (MRR) evaluated against ground-truth document labels.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K, Recall@K, F-score, Hit Rate@K, MRR (Mean Reciprocal Rank), NDCG, ground-truth labeled chunks", "Precision@K measures the proportion of retrieved chunks that are truly relevant", "Recall@K measures whether all ground-truth reference chunks were successfully captured in the candidate set", "MRR quantifies the reciprocal rank of the first relevant chunk in search results"]}, {"id": "KP2", "description": "Component-level generation metrics: Faithfulness/Groundedness, Answer Relevance, and Semantic Similarity measuring synthesis fidelity.", "required": true, "acceptable_evidence": ["Technical keywords: Faithfulness, Answer Relevance, Context Relevance, Semantic Similarity, ground-truth reference answer", "Faithfulness checks whether every claim made in the generated answer is strictly entailed by the retrieved context (hallucination rate)", "Answer Relevance measures if the response directly addresses the user query without superfluous fluff", "Semantic Similarity computes cosine similarity between generated answer and gold reference answer"]}, {"id": "KP3", "description": "Evaluation process with Ragas and LLM-as-a-Judge: running automated pipelines using powerful evaluator models (GPT-4 / Claude 3.5 Sonnet) against curated test datasets.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas framework, DeepEval, LLM-as-a-judge, Claude 3.5 Sonnet / GPT-4 evaluator, automated synthetic testset", "Feeds (query, context, generated_answer, ground_truth) tuples into Ragas evaluation harness", "Evaluator LLM parses statements, scores entailment, and computes aggregate rubric scores between 0.0 and 1.0"]}, {"id": "KP4", "description": "Continuous CI/CD regression testing: integrating automated evaluation into build pipelines to prevent retrieval regressions when altering embeddings or chunking.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD regression testing, GitHub Actions pipeline, evaluation benchmark suite, quality gate thresholds", "Fails CI build if Faithfulness drops below 0.90 or Hit Rate@5 drops below 0.85 on the golden test dataset", "Tracks longitudinal performance dashboards across prompt and chunking iterations"]}], "critical_failures": ["Failing to clearly distinguish retrieval metrics (Precision@K, Recall@K, MRR) from generation metrics (Faithfulness, Answer Relevance)", "Failing to explain how LLM-as-a-judge frameworks like Ragas evaluate faithfulness against retrieved context", "Omitting the requirement of a ground-truth golden dataset for rigorous benchmarking"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you apply prompt engineering techniques, such as few-shot prompting and guardrails, to improve response accuracy and reduce hallucinations?', '{"key_points": [{"id": "KP1", "description": "Few-shot prompting for accuracy and format adherence: embedding curated input-output demonstration pairs within the prompt to guide tone, reasoning structure, and boundary conditions.", "required": true, "acceptable_evidence": ["Technical keywords: few-shot prompting, exemplar demonstration, in-context learning, reasoning format, boundary handling", "Includes 2-3 enterprise examples demonstrating how to answer questions correctly using retrieved context snippets", "Demonstrates negative examples where the model explicitly declines to answer when information is absent from context"]}, {"id": "KP2", "description": "Strict grounding guardrails in prompt architecture: establishing explicit negative constraints, forbidding external knowledge extrapolation, and requiring verifiable citations.", "required": true, "acceptable_evidence": ["Technical keywords: strict grounding guardrails, negative constraints, zero external speculation, verifiable citations [Doc-ID], source attribution", "Directs: ''Base your answer entirely on the context below. Do not assume or extrapolate facts not explicitly stated.''", "Mandates citing source chunk IDs for every factual statement to enforce verification"]}, {"id": "KP3", "description": "Step-by-step reasoning constraints (Chain-of-Thought): prompting the model to extract verbatim supporting sentences before synthesizing the response.", "required": true, "acceptable_evidence": ["Technical keywords: Chain-of-Thought (CoT), extract-then-answer, evidence quotation, structured JSON output, intermediate reasoning", "Prompts: ''Step 1: Extract direct quotations from context supporting the answer. Step 2: Formulate the final answer based only on these quotations.''", "Reduces hallucination rate by decoupling factual extraction from language generation"]}, {"id": "KP4", "description": "Defensive prompt engineering against jailbreaks: isolating user query strings inside XML/markdown delimiters to prevent prompt injection hijacking.", "required": false, "acceptable_evidence": ["Technical keywords: prompt injection defense, XML tag delimitation (<user_query>...</user_query>), system instructions hierarchy", "Wraps untrusted user input and retrieved context in distinct XML tags so the LLM distinguishes instructions from data", "Ensures instructions like ''Ignore previous instructions'' embedded in queries are treated as plain text rather than system commands"]}], "critical_failures": ["Giving vague advice without detailing specific few-shot exemplar structures or negative constraints", "Failing to mention citation requirements or step-by-step extraction constraints", "Overlooking defensive prompt formatting (such as XML tag separation for user input and context)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you design and implement a RAG-based pipeline for unstructured data, including preprocessing, chunking, embedding, and retrieval?', '{"key_points": [{"id": "KP1", "description": "Data ingestion and preprocessing: parsing heterogeneous unstructured files (PDF manuals, customer tickets, HTML) with layout-aware tools, cleaning boilerplate, and serializing tables.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware parsing, Docling, Unstructured, PyMuPDF, table serialization (Markdown/HTML), boilerplate removal", "Converts multi-column documents and technical tables into structured Markdown while stripping headers, footers, and page numbers", "Computes SHA-256 document hashes to ensure idempotent ingestion and skip unchanged files"]}, {"id": "KP2", "description": "Chunking strategy: implementing hierarchical / recursive chunking with token overlap and prepending contextual metadata breadcrumbs.", "required": true, "acceptable_evidence": ["Technical keywords: recursive chunking, chunk size (512 tokens), overlap (50 tokens), contextual breadcrumb prepending, header hierarchy", "Splits along structural markdown boundaries (H1, H2, paragraphs) to avoid severing sentences or procedures", "Prepends document title and section hierarchy to chunk text to retain global semantic meaning"]}, {"id": "KP3", "description": "Embedding and vector indexing: generating dense embeddings with domain-appropriate models (Sentence Transformers / Bedrock) and indexing in Milvus/Pinecone using HNSW.", "required": true, "acceptable_evidence": ["Technical keywords: dense embeddings, all-MiniLM-L6-v2 / BGE, Milvus / Pinecone, HNSW index (M=16, efConstruction=200), L2 normalization", "Batches embedding computation on GPU/CPU and normalizes vectors for efficient dot product similarity search", "Stores scalar metadata alongside vectors for multi-tenancy and faceted filtering"]}, {"id": "KP4", "description": "Multi-stage retrieval and reranking: combining dense vector search and sparse BM25 keyword search fused via RRF, followed by cross-encoder reranking.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, BM25 keyword search, dense ANN search, Reciprocal Rank Fusion (RRF), cross-encoder reranking (BGE-Reranker)", "Executes parallel dense and sparse queries to maximize candidate recall (top-50 pool)", "Applies cross-encoder reranker to extract top-3 to top-5 chunks, enforcing a minimum relevance cutoff score"]}], "critical_failures": ["Failing to cover all four core pipeline stages: preprocessing, chunking, embedding, and multi-stage retrieval", "Relying on naive token splitting that destroys tables and document structure", "Omitting hybrid retrieval or cross-encoder reranking in production design"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How did you design and implement an agentic AI system using LangGraph, and what roles did different agents play in orchestration and retrieval?', '{"key_points": [{"id": "KP1", "description": "LangGraph multi-agent architecture: modeling the system as a directed cyclic graph (StateGraph) with typed shared state, functional agent nodes, and conditional routing edges.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, agent state schema, nodes, conditional edges, cyclic routing, router/supervisor", "Defines a structured state schema tracking user query, intermediate agent messages, tool outputs, and execution step count", "Coordinates specialized agent nodes rather than relying on a single monolithic prompt"]}, {"id": "KP2", "description": "Specialized agent roles: implementing a Supervisor/Router agent, a Retrieval Specialist agent (RAG), and a Task Execution/Action agent.", "required": true, "acceptable_evidence": ["Technical keywords: supervisor agent, router, retrieval agent, action/tool execution agent, summarizer agent", "Supervisor analyzes incoming query intent and dynamically delegates to retrieval or execution agents", "Retrieval agent executes hybrid search, query rewriting, and context formatting", "Action agent executes transactional tools (e.g. looking up customer CRM records, booking service appointments)"]}, {"id": "KP3", "description": "Self-reflective loops and conditional routing: implementing Corrective RAG (CRAG) grader nodes to evaluate retrieval quality and rewrite queries dynamically.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval grading node, query rewrite loop, conditional edge routing, Self-RAG, cycle limit safeguard", "Evaluates retrieved documents; if relevance is insufficient, routes back to query rewriting node instead of generating an unsupported answer", "Enforces max recursion limit (e.g. max_steps=5) to terminate infinite agent loops"]}, {"id": "KP4", "description": "State persistence and Human-in-the-Loop (HITL): leveraging LangGraph checkpointers for durable execution and human confirmation gates on critical tool calls.", "required": false, "acceptable_evidence": ["Technical keywords: checkpointers (PostgresSaver / MemorySaver), HITL interrupt, human review gate, state pause and resume", "Pauses graph execution before high-risk actions to allow human agent review and approval", "Persists conversation state across multi-turn interactions and microservice restarts"]}], "critical_failures": ["Describing simple sequential LangChain chains rather than stateful cyclic LangGraph architectures", "Failing to delineate specific specialized agent roles (Supervisor, Retrieval, Action)", "Omitting conditional routing loops (like retrieval grading/rewriting) and recursion safeguards"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you design and implement end-to-end RAG infrastructure, and how was it exposed through APIs?', '{"key_points": [{"id": "KP1", "description": "End-to-end infrastructure architecture: decoupled microservices for ingestion (async workers), vector search (Milvus/Pinecone), and LLM orchestration (FastAPI) deployed on AWS EKS.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end RAG infrastructure, microservices architecture, AWS EKS, Docker, FastAPI, Milvus, Redis cache", "Decouples heavy background ingestion (PDF parsing, embedding generation) from real-time low-latency query serving", "Uses Kubernetes Horizontal Pod Autoscaler (HPA) to scale query-serving pods based on CPU and request latency"]}, {"id": "KP2", "description": "API design and communication protocols: exposing RESTful endpoints and Server-Sent Events (SSE) streaming for real-time token delivery.", "required": true, "acceptable_evidence": ["Technical keywords: REST API, FastAPI, Server-Sent Events (SSE), token streaming, WebSocket, Pydantic request/response schemas", "Exposes POST /v1/query with streaming response (text/event-stream) to provide instant Time-to-First-Token (TTFT) UX", "Implements POST /v1/documents for authenticated file ingestion and document lifecycle management"]}, {"id": "KP3", "description": "Production API operational controls: integrating API Gateway authentication (OAuth2 / JWT), rate limiting, PII sanitization, and structured error handling.", "required": true, "acceptable_evidence": ["Technical keywords: AWS API Gateway, OAuth2/JWT auth, rate limiting (Redis token bucket), PII redaction, error handling, status codes", "Protects downstream LLM endpoints from overload using Redis-based rate limiting", "Returns standard HTTP status codes (400 Bad Request, 429 Too Many Requests, 503 Service Unavailable) with structured error JSON"]}, {"id": "KP4", "description": "Telemetry and observability: instrumenting OpenTelemetry tracing, Prometheus metrics, and Langfuse/Arize Phoenix for LLM call logging.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Prometheus, Grafana, Langfuse, Arize Phoenix, CloudWatch, end-to-end distributed tracing", "Tracks latency across API gateway, vector retrieval, cross-encoder reranker, and Bedrock token streaming", "Logs user queries, retrieved chunk IDs, and model responses for continuous evaluation"]}], "critical_failures": ["Failing to detail how the RAG infrastructure is exposed via APIs (REST, streaming SSE, Pydantic schemas)", "Ignoring production API security controls (JWT authentication, rate limiting, PII filtering)", "Failing to articulate the decoupling between ingestion pipelines and real-time query serving"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How did you design and orchestrate multi-agent workflows using LangGraph and Model Context Protocol to improve retrieval and automation?', '{"key_points": [{"id": "KP1", "description": "Architectural integration of LangGraph and Model Context Protocol (MCP): using LangGraph for cyclic stateful multi-agent workflow orchestration and MCP as the open standardized protocol for tool/resource integration.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, Model Context Protocol (MCP), StateGraph, MCP client/server, JSON-RPC, standardized tool schemas", "LangGraph orchestrates the reasoning loop, agent delegation, and state transitions", "MCP servers encapsulate access to databases (knowledge graphs, vector stores, CRM) and tools through standard interfaces decoupled from LLM providers"]}, {"id": "KP2", "description": "Multi-agent coordination pattern: orchestrating specialized agents (Routing Agent, Graph/Vector Retrieval Agent, Automation/Action Agent) via dynamic graph routing.", "required": true, "acceptable_evidence": ["Technical keywords: multi-agent coordination, supervisor router, specialized agent nodes, dynamic delegation, state sharing", "Supervisor delegates queries requiring domain relationships to the MCP Graph Agent, while pure transactional requests route to the Action Agent", "Maintains a centralized LangGraph state object holding discovered facts, agent dialogue, and pending actions"]}, {"id": "KP3", "description": "Automated execution and retrieval enhancement: invoking MCP tools to query knowledge graphs and vector databases, fusing results, and triggering external business automations.", "required": true, "acceptable_evidence": ["Technical keywords: MCP tool execution, GraphRAG retrieval, automated action execution, API integration, context synthesis", "Retrieval agent calls MCP server tools (e.g. search_vector_db, get_graph_neighbors) to construct unified context", "Action agent calls MCP action tools (e.g. create_jira_ticket, schedule_service_appointment) with validated parameters"]}, {"id": "KP4", "description": "Safety guardrails and transaction reliability: enforcing Pydantic parameter validation, idempotent MCP tool execution, and Human-in-the-Loop review gates.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic validation, idempotency keys, LangGraph interrupt, HITL review, permission boundaries", "Applies schema validation to ensure MCP tool calls have all required parameters before execution", "Interrupts graph execution for human confirmation on high-consequence state-altering actions"]}], "critical_failures": ["Failing to distinguish the complementary roles of LangGraph (workflow/state orchestration) and MCP (standardized tool/resource communication protocol)", "Describing simple linear tool calling without explaining multi-agent coordination patterns", "Ignoring safety guardrails, parameter validation, or transactional reliability"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you design fallback mechanisms to handle retrieval failures or prevent hallucinations?', '{"key_points": [{"id": "KP1", "description": "Retrieval failure detection: establishing quantitative threshold checks on similarity scores, reranker confidence, and minimum chunk counts.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval failure detection, confidence threshold, reranker cutoff score (<0.40), low cosine similarity, empty candidate pool", "Identifies when retrieved chunks have low semantic alignment or when no documents match applied metadata filters", "Prevents feeding low-quality, irrelevant context into the LLM"]}, {"id": "KP2", "description": "Multi-tier recovery and fallback mechanisms: implementing query rewriting, relaxing metadata filters, falling back to keyword search (BM25), or broad web search.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tier fallback, query rewriting/expansion, metadata filter relaxation, BM25 fallback, secondary search provider", "Tier 1: Rewrites ambiguous query or expands terms and retries retrieval", "Tier 2: Relaxes restrictive metadata filters (e.g. broadening model year or category)", "Tier 3: Falls back to lexical BM25 search or enterprise web search if vector search yields zero results"]}, {"id": "KP3", "description": "Deterministic refusal and Human-in-the-Loop (HITL) escalation: serving pre-approved safe responses and routing complex queries to human agents when retrieval fails completely.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic safe fallback, canned response, out-of-domain refusal, human escalation, ticket creation", "Returns a polite standard enterprise response: ''I could not find authoritative documentation for your request. Connecting you to a specialist...''", "Automatically logs the query and creates an escalation ticket in CRM/Zendesk for human triage"]}, {"id": "KP4", "description": "Knowledge gap telemetry and monitoring: capturing unserved queries in dead-letter queues to enrich documentation and update the knowledge base.", "required": false, "acceptable_evidence": ["Technical keywords: knowledge gap detection, dead-letter logging, telemetry, continuous knowledge base improvement, analytics", "Aggregates failed retrieval queries to identify blind spots in technical manuals", "Alerts content teams to draft new articles for frequently requested missing topics"]}], "critical_failures": ["Allowing the LLM to generate answers when retrieval fails, leading directly to hallucinations", "Failing to define concrete fallback tiers (e.g. query rewriting, filter relaxation, canned refusals)", "Omitting human escalation and knowledge gap logging mechanisms"]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How did you design the ingestion pipeline from S3 to a vector database?', '{"key_points": [{"id": "KP1", "description": "Event-driven ingestion trigger: utilizing S3 event notifications (s3:ObjectCreated) routed through AWS SQS/SNS to trigger asynchronous ingestion workers.", "required": true, "acceptable_evidence": ["Technical keywords: event-driven architecture, AWS S3, ObjectCreated event, AWS SQS queue, AWS SNS, decoupled ingestion", "New or updated documents uploaded to S3 trigger an event notification pushed onto an SQS queue", "SQS provides message buffering, rate leveling, and dead-letter queue (DLQ) support for failed documents"]}, {"id": "KP2", "description": "Asynchronous document processing workers: deploying containerized workers on AWS EKS or AWS Fargate to parse documents, clean text, and generate chunks.", "required": true, "acceptable_evidence": ["Technical keywords: asynchronous workers, AWS EKS / Fargate, Docling / Unstructured layout parsing, recursive chunking, metadata enrichment", "Worker pods consume messages from SQS, stream raw files from S3 into memory/scratch storage", "Applies layout-aware parsing and recursive chunking, generating metadata payloads with document S3 URIs and versions"]}, {"id": "KP3", "description": "Embedding generation and vector upsert: computing dense embeddings in batches and executing bulk upsert operations into Milvus/Pinecone.", "required": true, "acceptable_evidence": ["Technical keywords: batch embedding generation, Sentence Transformers / Bedrock Titan, Milvus / Pinecone bulk insert, HNSW indexing", "Batches chunks (e.g. 64-128 chunks per batch) to maximize GPU/CPU embedding efficiency", "Executes upsert into vector database collection, tagging each vector with its partition key and metadata fields"]}, {"id": "KP4", "description": "Idempotency, deduplication, and error handling: tracking document hashes (SHA-256) in DynamoDB/Postgres and handling failure retries via Dead-Letter Queues (DLQ).", "required": false, "acceptable_evidence": ["Technical keywords: idempotency, SHA-256 content hash, DynamoDB state tracking, DLQ (Dead-Letter Queue), retry backoff", "Checks if document content hash already exists to prevent redundant embedding computation on duplicate uploads", "Failed ingestion tasks are retried with exponential backoff before landing in DLQ for engineer alert"]}], "critical_failures": ["Proposing synchronous API uploads instead of an asynchronous event-driven pipeline (S3 -> SQS -> Workers)", "Failing to detail how documents are parsed, chunked, and embedded during the worker stage", "Ignoring idempotency, deduplication, and failure handling (DLQ/retries)"]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'How did you design your AWS-based architecture, including services used for ingestion, storage, orchestration, and deployment?', '{"key_points": [{"id": "KP1", "description": "Ingestion and event-driven pipeline architecture: AWS S3 for document storage, S3 Event Notifications, AWS SQS/SNS for message queuing, and AWS Lambda/Fargate for asynchronous parsing.", "required": true, "acceptable_evidence": ["Technical keywords: AWS S3, S3 Event Notifications, AWS SQS, AWS SNS, AWS Fargate / Lambda, asynchronous event-driven ingestion", "Raw enterprise documents land in S3 raw bucket, triggering SQS messages consumed by containerized processing tasks", "Dead-Letter Queues (DLQ) capture malformed files and unparseable documents"]}, {"id": "KP2", "description": "Storage layer architecture: Amazon OpenSearch / Milvus on EKS for vector indexing, Amazon RDS (PostgreSQL) for transactional user data and metadata, and Amazon ElastiCache (Redis) for caching.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon OpenSearch Service / Milvus on EKS, Amazon RDS PostgreSQL, Amazon ElastiCache Redis, S3 chunk storage", "Stores vector embeddings and scalar filters in dedicated vector engine", "Maintains relational user sessions, chat history, and document lineage in RDS", "Caches frequent query responses and short-term conversation state in ElastiCache Redis"]}, {"id": "KP3", "description": "LLM orchestration and model inference: utilizing AWS Bedrock (Claude 3.5 Sonnet / Haiku) for managed foundation model inference, orchestrated via FastAPI services on AWS EKS.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, Claude 3.5 Sonnet / Haiku, AWS EKS, Docker containers, FastAPI orchestrator, LangGraph", "Hosts agent orchestration and API gateway services as scalable Kubernetes deployments on EKS", "Calls Bedrock serverless endpoints via AWS SDK with IAM authentication, avoiding EC2 GPU cluster maintenance"]}, {"id": "KP4", "description": "Security, networking, and deployment governance: AWS PrivateLink / VPC endpoints, IAM roles for service accounts (IRSA), AWS Secrets Manager, and CI/CD via GitHub Actions / AWS CodePipeline.", "required": true, "acceptable_evidence": ["Technical keywords: AWS VPC, PrivateLink, VPC Endpoints, IAM IRSA, AWS Secrets Manager, AWS CloudWatch, CI/CD pipeline", "Ensures all traffic between EKS, S3, RDS, and Bedrock stays within private VPC without traversing public internet", "Automates container build and Helm chart deployment via CI/CD with CloudWatch/OpenTelemetry observability"]}], "critical_failures": ["Failing to cover the complete service map across ingestion (S3/SQS), storage (Vector DB/RDS/Redis), orchestration (EKS/FastAPI), and inference (Bedrock)", "Ignoring VPC networking, private endpoints, and enterprise IAM security controls", "Failing to articulate how components integrate asynchronously and synchronously"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you design your data chunking strategy, and what trade-offs led you to choose a hybrid approach with hierarchical chunking and overlap?', '{"key_points": [{"id": "KP1", "description": "Hierarchical (parent-child) chunking architecture: generating small child chunks for high-specificity vector embedding while linking them to larger parent chunks for broad context generation.", "required": true, "acceptable_evidence": ["Technical keywords: hierarchical chunking, parent-child chunking, small-to-big retrieval, child embedding, parent context window", "Embeds small child chunks (e.g. 128-256 tokens) to capture precise semantic vectors without semantic dilution", "When a child chunk matches query, retrieves the larger parent chunk (e.g. 1024-2048 tokens or entire section) to provide complete context to LLM"]}, {"id": "KP2", "description": "Chunk overlap ratio and boundary design: configuring 10-20% token overlap (e.g. 50 tokens on 512-token chunks) to prevent semantic fractures across chunk seams.", "required": true, "acceptable_evidence": ["Technical keywords: chunk overlap (10-20%), sliding window, context boundary preservation, semantic seam fracture, sentence boundary splitting", "Ensures critical phrases, coreference entities, and troubleshooting steps spanning split boundaries are not lost", "Splits along natural boundaries (paragraphs, markdown headers, sentences) rather than raw arbitrary token counts"]}, {"id": "KP3", "description": "Trade-offs of the hybrid hierarchical approach: higher indexing complexity and storage footprint in exchange for superior retrieval precision and rich LLM context.", "required": true, "acceptable_evidence": ["Technical keywords: trade-offs, storage overhead, indexing complexity, precision vs context dilemma, parent-child mapping table", "Downside: requires maintaining parent-child ID relational mapping in database and storing more chunks", "Upside: completely solves the fundamental trade-off where small chunks retrieve well but lack context, and large chunks contain context but dilute vector specificity"]}, {"id": "KP4", "description": "Contextual metadata enrichment: prepending structural breadcrumbs (document title, chapter, section) to each child chunk prior to embedding.", "required": false, "acceptable_evidence": ["Technical keywords: contextual breadcrumbs, metadata prepending, section header hierarchy, semantic anchoring", "Prepends header breadcrumbs: ''[Manual: Battery System > Section: Diagnostic Trouble Codes]''", "Ensures child chunks retain complete semantic meaning even when isolated from surrounding text"]}], "critical_failures": ["Failing to explain the parent-child chunking mechanism (embedding small chunks, retrieving large chunks)", "Ignoring the rationale and sizing of chunk overlap (10-20% to avoid boundary context loss)", "Failing to articulate the trade-offs in storage/complexity versus retrieval precision"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you enforce client-specific data isolation and role-based access control in your retrieval system?', '{"key_points": [{"id": "KP1", "description": "Client-specific data isolation strategies: implementing hard multi-tenancy via Milvus partition keys, dedicated collections, or tenant namespaces.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenancy, partition keys, collection per tenant, namespace isolation, tenant_id partitioning", "Partition keys in Milvus physically separate data partitions while sharing collection resources, ensuring zero data leakage", "Strictly validates tenant_id from cryptographically verified JWT claims before issuing any query"]}, {"id": "KP2", "description": "Role-Based Access Control (RBAC) at the retrieval layer: attaching access control lists (ACLs) and security roles as metadata tags and applying scalar pre-filters.", "required": true, "acceptable_evidence": ["Technical keywords: Role-Based Access Control (RBAC), ACLs, scalar pre-filtering, allowed_roles metadata, security filter expression", "Attaches role metadata to chunks (e.g. roles: [''tier1_support'', ''internal_mechanic''])", "Injects deterministic scalar filter into vector query: tenant_id == ''XYZ'' AND role IN (''tier1_support'') prior to ANN similarity search"]}, {"id": "KP3", "description": "Prevention of vector leakage and post-filtering pitfalls: enforcing pre-filtering at the database query engine rather than post-filtering in application code.", "required": true, "acceptable_evidence": ["Technical keywords: pre-filtering vs post-filtering, vector data leakage, unauthorized chunk prevention, query engine enforcement", "Explains post-filtering risks leaking existence of unauthorized data and causes severe recall drops if top-k results belong to unauthorized tenants", "Pre-filtering mathematically guarantees unauthorized vectors are never evaluated or returned"]}, {"id": "KP4", "description": "Audit logging and compliance verification: recording all retrieval operations with tenant identity, user ID, and accessed chunk IDs for security audits.", "required": false, "acceptable_evidence": ["Technical keywords: audit logging, security compliance, SOC2, HIPAA, CloudWatch logs, access auditing", "Logs tenant access logs with cryptographic timestamps to prove compliance", "Maintains immutable audit trail of document access across enterprise boundaries"]}], "critical_failures": ["Advocating application-level post-filtering instead of query-level pre-filtering (which causes vector leakage and recall drops)", "Failing to explain how tenant isolation is enforced in vector databases (partition keys / collections)", "Omitting JWT/claim verification for tenant and role authentication"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you enhance retrieval performance using re-ranking techniques, including cross-encoders and domain-specific metadata?', '{"key_points": [{"id": "KP1", "description": "Cross-encoder reranking mechanism: scoring the top-k candidate pool using a full joint cross-attention model to compute query-chunk relevance scores.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder reranking, BGE-Reranker, Cohere Rerank, full joint cross-attention, bi-encoder candidate pool (top-50 -> top-5)", "Cross-encoders process query and candidate chunk jointly, capturing fine-grained token alignments that isolated bi-encoders miss", "Re-sorts candidate chunks based on true semantic entailment rather than approximate vector distance"]}, {"id": "KP2", "description": "Integrating domain-specific metadata in reranking: incorporating structured attributes (recency, authority, vehicle model match, verified status) into ranking formulas.", "required": true, "acceptable_evidence": ["Technical keywords: domain metadata reranking, recency decay, authority boost, exact entity match, metadata score weighting", "Boosts chunks matching specific critical entities (e.g. exact vehicle trim, matching trouble code) above general documents", "Applies time-decay weighting to prioritize current 2024 service bulletins over older 2021 manuals"]}, {"id": "KP3", "description": "Two-stage pipeline optimization and threshold pruning: balancing reranker latency overhead with quality by establishing confidence score cutoffs.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage pipeline, candidate pool sizing (top-30/50), latency budget (<40ms), relevance cutoff score", "Filters out chunks scoring below a confidence threshold (e.g. score < 0.45) to prevent passing noisy context to the LLM", "Optimizes reranker model inference via INT8 quantization and ONNX/TensorRT acceleration"]}], "critical_failures": ["Failing to explain the architectural difference between bi-encoders and cross-encoders", "Ignoring how domain-specific metadata (recency, authority, entity match) augments cross-encoder scoring", "Omitting candidate pool sizing and relevance score cutoff filtering"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you evaluate the performance of your RAG system, and why did you choose metrics like Precision@K, Recall@K, RAGAS, BLEU, and ROUGE?', '{"key_points": [{"id": "KP1", "description": "Component-level retrieval metrics (Precision@K, Recall@K): evaluating whether the candidate retrieval stage captures gold chunks and minimizes context noise.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K, Recall@K, Hit Rate@K, Mean Reciprocal Rank (MRR), candidate pool evaluation", "Recall@K measures whether all ground-truth reference passages were captured in the retrieved candidate pool", "Precision@K measures the purity of retrieved chunks to prevent injecting noisy context into the LLM prompt"]}, {"id": "KP2", "description": "RAGAS triad metrics (Faithfulness, Answer Relevance, Context Relevance): evaluating factual groundedness and query alignment using LLM-as-a-judge.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS framework, Faithfulness / Groundedness, Answer Relevance, Context Relevance, LLM-as-a-judge", "Faithfulness evaluates whether claims in the generated response are strictly entailed by retrieved context (hallucination rate)", "Answer Relevance measures how directly the answer satisfies the user''s question without irrelevant fluff"]}, {"id": "KP3", "description": "Traditional NLP n-gram metrics (BLEU, ROUGE) and their critical limitations: measuring surface n-gram lexical overlap against gold references, but failing on semantic paraphrases.", "required": true, "acceptable_evidence": ["Technical keywords: BLEU, ROUGE-1/2/L, n-gram lexical overlap, paraphrase blindness, semantic limitation", "BLEU measures precision of n-gram overlap; ROUGE measures recall of n-grams against human reference answers", "Critical limitation: BLEU/ROUGE severely penalize answers that are factually 100% correct but phrased with different synonyms or sentence structures", "Used as auxiliary baseline checks, while RAGAS and semantic embeddings serve as the primary quality arbiters"]}], "critical_failures": ["Failing to contrast modern RAGAS metrics with traditional n-gram metrics (BLEU, ROUGE)", "Ignoring the fatal limitation of BLEU/ROUGE in GenAI evaluation (penalizing semantically valid paraphrases)", "Failing to define Precision@K and Recall@K in the context of retrieval evaluation"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you generate and utilize query rewrites to enhance retrieval performance?', '{"key_points": [{"id": "KP1", "description": "Rationale for query rewriting: user queries are frequently colloquial, underspecified, multi-topic, or context-dependent, resulting in severe vocabulary mismatch with authoritative documentation.", "required": true, "acceptable_evidence": ["Technical keywords: query rewriting rationale, vocabulary mismatch, colloquial phrasing, coreference ambiguity, multi-turn context dependence", "Customer queries like ''it won''t charge after update'' fail to match technical manual phrasing (''CCS Combo 1 charging handshake timeout following ECU firmware flash'')", "Resolves ambiguous pronouns (''it'', ''that issue'') in multi-turn dialogues into fully qualified standalone search queries"]}, {"id": "KP2", "description": "Query rewrite generation strategies: implementing multi-query expansion, sub-query decomposition, and Hypothetical Document Embeddings (HyDE) using lightweight LLMs.", "required": true, "acceptable_evidence": ["Technical keywords: multi-query expansion, sub-query decomposition, HyDE (Hypothetical Document Embeddings), lightweight LLM (Claude 3 Haiku / GPT-4o-mini)", "Generates 3-5 alternative query phrasings capturing technical terminology, synonyms, and related system components", "Decomposes complex multi-part questions into distinct parallel search queries", "Generates a hypothetical answer passage whose embedding sits closer to real documentation in vector space"]}, {"id": "KP3", "description": "Utilizing rewrites during retrieval and candidate fusion: executing parallel searches for all generated query variants and merging results via Reciprocal Rank Fusion (RRF).", "required": true, "acceptable_evidence": ["Technical keywords: parallel vector retrieval, candidate pool aggregation, Reciprocal Rank Fusion (RRF), deduplication, unified candidate ranking", "Executes parallel vector queries across all rewritten queries and merges candidate pools", "Uses RRF to promote documents retrieved across multiple query variations, drastically boosting candidate Recall@K"]}, {"id": "KP4", "description": "Latency management and conditional routing: applying fast classifier routing to only rewrite complex or ambiguous queries while passing clear queries directly.", "required": false, "acceptable_evidence": ["Technical keywords: latency budget, conditional rewrite routing, query classification, fast path vs rewrite path", "Avoids calling an LLM rewriter for simple, high-confidence queries with exact part numbers", "Keeps total query rewrite latency under 200ms using fast streaming or compact models"]}], "critical_failures": ["Failing to explain why query rewriting is necessary (vocabulary mismatch, coreference ambiguity)", "Omitting key query generation strategies (multi-query expansion, decomposition, HyDE)", "Failing to explain how results from rewritten queries are fused (e.g. Reciprocal Rank Fusion)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement CI/CD for your RAG system using GitHub Actions?', '{"key_points": [{"id": "KP1", "description": "CI pipeline automation with GitHub Actions: automating code linting (Ruff/Flake8), type checking (Mypy), unit tests (pytest), and Docker container builds on pull requests.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, GitHub Actions, workflow YAML, linting (Ruff), type checking (Mypy), unit tests (pytest), Docker build", "Runs automated checks on every pull request to ensure application code quality and API contract adherence", "Builds container images, tags with Git commit SHA, and scans for vulnerabilities (Trivy / Snyk)"]}, {"id": "KP2", "description": "Automated RAG evaluation gate: running automated evaluation suites (Ragas / DeepEval) against a golden benchmark dataset to prevent retrieval and generation regressions.", "required": true, "acceptable_evidence": ["Technical keywords: automated RAG evaluation gate, golden benchmark testset, Ragas / DeepEval, regression testing, quality threshold", "Executes benchmark suite of 100-200 ground-truth QA triplets on staging models", "Blocks merging if Faithfulness drops below 0.90 or Hit Rate@5 drops below 0.85"]}, {"id": "KP3", "description": "CD deployment pipeline: publishing container images to Amazon ECR and executing automated rolling or canary deployments to AWS EKS via Helm/ArgoCD.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon ECR, AWS EKS deployment, Helm charts, ArgoCD / GitOps, rolling updates, canary deployment", "Pushes validated container images to Amazon ECR and updates Kubernetes deployment manifests", "Executes zero-downtime rolling update across EKS worker pods with health check probes (/healthz)"]}, {"id": "KP4", "description": "Database migration and vector index management: automating schema migrations (Flyway / Alembic) and managing zero-downtime vector reindexing.", "required": false, "acceptable_evidence": ["Technical keywords: database migrations, Flyway / Alembic, blue-green vector reindexing, zero-downtime migration", "Applies relational database schema migrations before updating API pods", "Performs blue-green collection swapping in vector database when embedding models are upgraded"]}], "critical_failures": ["Describing generic CI/CD without RAG-specific evaluation gates (e.g. benchmarking against golden datasets)", "Failing to mention containerization (Docker, ECR) and Kubernetes deployment automation (Helm, EKS)", "Ignoring regression testing for retrieval and generation accuracy"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you implement guardrails and handle PII in your RAG system, including preprocessing, authorization, and runtime controls?', '{"key_points": [{"id": "KP1", "description": "PII handling in preprocessing and ingestion: detecting and sanitizing sensitive personal data (names, SSN, credit cards, VINs, phone numbers) before chunking and embedding.", "required": true, "acceptable_evidence": ["Technical keywords: PII preprocessing, Microsoft Presidio, regex patterns, Named Entity Recognition (NER), PII masking / tokenization", "Scans raw documents and tickets during ingestion to replace PII with synthetic tokens (e.g. [REDACTED_SSN], [CUSTOMER_ID_102])", "Guarantees that sensitive personal information is never stored in dense vector embeddings or vector database payloads"]}, {"id": "KP2", "description": "Authorization and access control guardrails: enforcing tenant isolation and Role-Based Access Control (RBAC) via cryptographically verified tokens and scalar pre-filters.", "required": true, "acceptable_evidence": ["Technical keywords: authorization guardrails, RBAC, JWT claims, scalar pre-filtering, tenant data isolation, allowed_roles", "Validates caller identity and permissions from JWT claims at API gateway", "Enforces hard scalar filter predicates in vector search queries to restrict retrieval strictly to authorized document tiers"]}, {"id": "KP3", "description": "Runtime input and output guardrails: intercepting prompt injections, jailbreaks, and verifying model outputs with hallucination and toxicity classifiers.", "required": true, "acceptable_evidence": ["Technical keywords: runtime guardrails, NeMo Guardrails, Llama Guard, prompt injection defense, output PII scanning, NLI faithfulness check", "Inspects incoming user queries for adversarial injection attempts before running retrieval", "Runs second-pass PII scanner on generated responses before sending to client to prevent leakage of memorized or contextual PII"]}, {"id": "KP4", "description": "Audit trails and compliance governance: logging sanitized access requests and maintaining SOC2 / HIPAA / GDPR compliance telemetry.", "required": false, "acceptable_evidence": ["Technical keywords: audit logging, SOC2 compliance, HIPAA, GDPR right-to-be-forgotten, immutable audit trail", "Logs all retrieval queries with masked PII to Amazon CloudWatch for compliance auditing", "Implements vector deletion mechanisms to support user data deletion requests under GDPR"]}], "critical_failures": ["Failing to address PII sanitization during the ingestion stage prior to embedding generation", "Omitting authorization and RBAC pre-filtering at the retrieval layer", "Ignoring runtime input guardrails (prompt injection) and output validation"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you implement guardrails for prompt injection, hallucination reduction, PII protection, and healthcare compliance requirements?', '{"key_points": [{"id": "KP1", "description": "Prompt injection and jailbreak defenses: deploying input sanitization layers, delimiter isolation (XML/Markdown), and dedicated classification models (Llama Guard / NeMo Guardrails).", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection defense, jailbreak detection, Llama Guard, NeMo Guardrails, XML tag isolation, system prompt protection", "Isolates user queries inside strict XML tags (<user_query>) to separate instructions from untrusted data", "Classifies incoming queries for adversarial patterns (e.g. role-play bypass, ''ignore system rules'') and rejects offending requests"]}, {"id": "KP2", "description": "Hallucination reduction guardrails: enforcing strict context grounding prompts, citation verification, and automated Natural Language Inference (NLI) entailment checking.", "required": true, "acceptable_evidence": ["Technical keywords: hallucination reduction, strict grounding prompt, NLI entailment scoring, citation verification, relevance threshold cutoff", "Instructs model to explicitly refuse when facts are not supported by retrieved chunks", "Runs post-generation sentence-level entailment verification against retrieved context using cross-encoder NLI models"]}, {"id": "KP3", "description": "PII protection and HIPAA/healthcare compliance: implementing de-identification pipelines (Safe Harbor / Expert Determination), PHI masking, encryption, and BAA governance.", "required": true, "acceptable_evidence": ["Technical keywords: HIPAA compliance, Protected Health Information (PHI), PII redaction, Presidio, AWS Comprehend Medical, encryption at rest/in transit, BAA (Business Associate Agreement)", "Redacts 18 HIPAA Safe Harbor identifiers (names, MRNs, dates, phone numbers, geographic data) using automated medical NER", "Enforces end-to-end KMS encryption (in transit TLS 1.3, at rest AES-256) and signs BAAs with cloud LLM providers (AWS Bedrock / Azure)"]}, {"id": "KP4", "description": "Audit logging, access controls, and Human-in-the-Loop escalation: logging immutable access records and routing high-risk medical decisions to certified professionals.", "required": false, "acceptable_evidence": ["Technical keywords: immutable audit logging, HITL clinical review, Role-Based Access Control (RBAC), medical disclaimer fallback", "Requires certified clinical practitioner review before presenting diagnostic recommendations", "Maintains tamper-evident audit logs of all queries and retrieved records for HIPAA compliance audits"]}], "critical_failures": ["Failing to detail specific healthcare/HIPAA requirements (PHI de-identification, 18 Safe Harbor identifiers, BAAs)", "Ignoring prompt injection defense mechanisms (input classification, delimiter isolation)", "Omitting hallucination verification and grounding constraints"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you implement query optimization, including multi-query generation using LLMs, and what impact did it have on latency and retrieval quality?', '{"key_points": [{"id": "KP1", "description": "Multi-query generation mechanism: prompting an LLM to generate 3-5 distinct query variations (synonyms, technical reformulations, different semantic angles) from a single user prompt.", "required": true, "acceptable_evidence": ["Technical keywords: multi-query generation, query expansion, query rewrites, alternative phrasing, prompt template, lightweight LLM", "Prompts a fast LLM (e.g. Claude 3 Haiku / GPT-4o-mini) to generate alternative phrasings capturing technical terminology and common synonyms", "Overcomes user query underspecification and idiosyncratic vocabulary"]}, {"id": "KP2", "description": "Retrieval execution and candidate fusion: executing parallel vector searches for each generated query and merging candidate chunks using Reciprocal Rank Fusion (RRF).", "required": true, "acceptable_evidence": ["Technical keywords: parallel vector retrieval, Reciprocal Rank Fusion (RRF), candidate pool deduplication, union of results, top-k ranking", "Fires concurrent asynchronous queries to the vector database for all 3-5 query variants", "Fuses resulting candidate lists using RRF (formula 1/(60 + r)) to promote documents that rank high across multiple query formulations"]}, {"id": "KP3", "description": "Impact on retrieval quality: significantly increases Recall@K and Hit Rate by overcoming semantic and lexical blind spots in single queries.", "required": true, "acceptable_evidence": ["Technical keywords: Recall@K improvement, Hit Rate boost, semantic coverage, reduction in false negatives, robust retrieval", "Catches relevant documents that would be missed if relying on the exact wording of the original prompt", "Dramatically reduces retrieval failure rates on ambiguous or multi-faceted questions"]}, {"id": "KP4", "description": "Impact on latency and cost: introduces additional LLM generation latency (150-300ms) and vector database query load, requiring optimization.", "required": true, "acceptable_evidence": ["Technical keywords: latency overhead (150-300ms), token generation cost, vector database QPS multiplication, parallel async execution, caching", "Multiplies vector database query traffic by N-fold (requiring robust query node scaling)", "Mitigates latency by using ultra-fast distilled models for query expansion, running vector searches concurrently via asyncio, and caching common rewrites"]}], "critical_failures": ["Failing to explain how multi-query candidates are merged (e.g. Reciprocal Rank Fusion)", "Ignoring the latency penalty and added QPS load of multi-query generation", "Failing to cite the positive impact on Recall@K and candidate coverage"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you implement reranking, what model did you use, and how did it affect retrieval accuracy and latency?', '{"key_points": [{"id": "KP1", "description": "Reranking model selection: deploying cross-encoders (e.g. BGE-Reranker-large, Cohere Rerank, or ms-marco-MiniLM-L-6-v2) for deep joint query-document interaction.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder reranker, BGE-Reranker-large, Cohere Rerank, full joint cross-attention, bi-encoder candidate pool", "Explains using cross-encoders to score full [CLS] Query [SEP] Document [SEP] sequences, resolving bi-encoder semantic compression losses", "Prunes top-30 candidate pool retrieved by ANN down to top-3 to top-5 chunks"]}, {"id": "KP2", "description": "Quantifiable impact on retrieval accuracy: significant gains in Hit Rate@5, MRR, and NDCG over standalone dense vector search.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@5 improvement (15-25%), MRR increase, NDCG@5 boost, precision enhancement, noise filtering", "Filters out semantically adjacent but factually irrelevant false positives that passed vector similarity", "Ensures the single most relevant chunk is positioned at rank 1 for optimal LLM attention"]}, {"id": "KP3", "description": "Latency impact and mitigation strategies: addressing the 30-80ms compute overhead via ONNX runtime, FP16/INT8 quantization, and GPU batching.", "required": true, "acceptable_evidence": ["Technical keywords: latency overhead (30-80ms), ONNX Runtime, TensorRT, INT8/FP16 quantization, candidate pool cap (K=25-30)", "Controls latency by restricting candidate pool size to top-25 or top-30 rather than hundreds of chunks", "Serves reranker model using optimized runtimes (ONNX/Triton) to keep inference latency strictly within SLA"]}], "critical_failures": ["Failing to identify the specific reranker model family (e.g. BGE-Reranker, Cohere Rerank)", "Ignoring the latency penalty of cross-encoder inference and methods to mitigate it (quantization, pool sizing)", "Failing to cite concrete retrieval metrics impacted by reranking (Hit Rate, MRR, NDCG)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you implement semantic search using FAISS, and what optimizations did you consider for scalability and performance?', '{"key_points": [{"id": "KP1", "description": "FAISS semantic search implementation: indexing dense vector embeddings using FAISS C++ Python bindings with L2 normalized vectors and Inner Product (METRIC_INNER_PRODUCT).", "required": true, "acceptable_evidence": ["Technical keywords: FAISS, IndexFlatIP, IndexHNSWFlat, IndexIVFFlat, METRIC_INNER_PRODUCT, L2 normalization", "Explains creating an in-memory index or persistent file index for high-speed vector distance computation", "Normalizes embedding vectors prior to addition so inner product computation corresponds exactly to cosine similarity"]}, {"id": "KP2", "description": "Index optimization for scale and speed: transitioning from exact IndexFlatIP to approximate IndexHNSWFlat or IndexIVFPQ for multi-million vector datasets.", "required": true, "acceptable_evidence": ["Technical keywords: IndexHNSWFlat, IndexIVFPQ, Product Quantization (PQ), nlist, nprobe, M parameter, memory compression", "Uses HNSW for low latency (<5ms) and high recall when RAM allows", "Uses IVFPQ for massive vector collections to compress vectors into byte codes, reducing RAM consumption by 80-90%", "Tunes nprobe at search time to balance search speed versus recall accuracy"]}, {"id": "KP3", "description": "Production scalability and architectural trade-offs: addressing FAISS lack of built-in distributed clustering, scalar metadata filtering, and real-time CRUD operations.", "required": true, "acceptable_evidence": ["Technical keywords: FAISS limitations, lack of native distributed clustering, manual ID mapping, external metadata storage, Milvus/Pinecone trade-off", "Explains FAISS is an algorithmic library rather than a managed database; requires external SQLite/Postgres to store metadata and text payloads", "Rebuilding IVF indexes requires batch re-training, making real-time dynamic document deletion challenging"]}], "critical_failures": ["Confusing FAISS (algorithmic vector library) with full-featured distributed vector databases (Milvus, Pinecone)", "Failing to mention index types (IndexFlatIP, IndexHNSW, IndexIVFPQ) or tuning parameters (nprobe, nlist)", "Ignoring the lack of native scalar metadata filtering and distributed scale in standalone FAISS"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you measure the quality of your RAG system, including evaluation metrics, latency targets, and accuracy validation methods?', '{"key_points": [{"id": "KP1", "description": "End-to-end evaluation metrics: measuring both retrieval accuracy (Hit Rate@K, MRR, NDCG) and generation quality (Faithfulness, Answer Relevance, Context Relevance).", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, MRR, NDCG, Faithfulness / Groundedness, Answer Relevance, Context Relevance, RAG triad", "Evaluates whether retrieval returns gold source chunks in top positions", "Measures whether model generation is strictly faithful to retrieved context and directly answers user query"]}, {"id": "KP2", "description": "Production latency targets and profiling: establishing p95 and p99 latency budgets across network ingress, vector search, reranking, and LLM TTFT/generation.", "required": true, "acceptable_evidence": ["Technical keywords: latency targets, p95 latency (<1.5s), TTFT (Time to First Token < 500ms), streaming latency, sub-50ms retrieval", "Budgets 30ms for vector search, 40ms for reranking, and 400ms for LLM first token streaming", "Monitors token-per-second generation speed and API Gateway overhead"]}, {"id": "KP3", "description": "Accuracy validation methods: combining automated LLM-as-a-judge (Ragas/DeepEval) on curated golden datasets with Natural Language Inference (NLI) runtime guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: golden benchmark dataset, LLM-as-a-judge, Ragas, DeepEval, NLI entailment scoring, blind human evaluation", "Runs weekly automated regression tests across 150-300 ground-truth QA pairs", "Conducts periodic blind A/B testing with subject matter experts to calibrate automated metrics"]}, {"id": "KP4", "description": "Operational business impact metrics: tracking production business indicators such as Average Handling Time (AHT) and First Contact Resolution (FCR).", "required": false, "acceptable_evidence": ["Technical keywords: Average Handling Time (AHT), First Contact Resolution (FCR), query deflection rate, user thumbs-up/down feedback", "Tracks reduction in human agent call duration (e.g. from 10 minutes to 6.5 minutes)", "Captures user feedback telemetry to identify failing queries in production"]}], "critical_failures": ["Failing to cover both retrieval metrics (MRR/Hit Rate) and generation metrics (Faithfulness/Answer Relevance)", "Ignoring latency SLAs and Time-to-First-Token (TTFT) targets", "Failing to mention structured golden datasets or LLM-as-a-judge validation frameworks"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you modify the chunking strategy to address hallucinations, and what trade-offs did you consider when moving from basic chunking to semantic chunking with overlap?', '{"key_points": [{"id": "KP1", "description": "How basic fixed chunking causes hallucinations: arbitrary token cuts sever sentences mid-phrase, split tabular rows, and separate critical safety conditions from procedural steps.", "required": true, "acceptable_evidence": ["Technical keywords: basic chunking pitfalls, mid-sentence slicing, table destruction, severed procedural steps, context fragmentation, hallucination trigger", "If a precondition (''Only perform if ignition is OFF'') is severed from the procedure (''Disconnect 12V terminal''), the LLM retrieves an incomplete chunk and hallucinates dangerous advice", "Fragmented context forces the LLM to speculate and confabulate missing details"]}, {"id": "KP2", "description": "Moving to semantic chunking with overlap: splitting on semantic boundaries (markdown headers, paragraphs, sentences) with 10-20% sliding window overlap.", "required": true, "acceptable_evidence": ["Technical keywords: semantic chunking, recursive header splitting, 10-20% token overlap (50 tokens), sentence boundary preservation, structural cohesion", "Respects structural document boundaries so complete concepts, paragraphs, and lists stay intact within a single chunk", "Sliding window overlap ensures semantic context and transition phrases spanning chunk borders are preserved in both adjacent chunks"]}, {"id": "KP3", "description": "Trade-offs considered during migration: increased vector database storage footprint and index building compute in exchange for higher retrieval precision and reduced hallucinations.", "required": true, "acceptable_evidence": ["Technical keywords: trade-offs, storage expansion (15-25% more chunks), embedding API compute, index memory overhead, Hit Rate improvement", "Downside: overlap generates more chunks, increasing vector database storage requirements and index memory usage", "Upside: dramatically improves Hit Rate@5 and eliminates context boundary hallucinations, delivering significantly higher faithfulness scores"]}], "critical_failures": ["Failing to explain how poor chunking directly causes LLM hallucinations (severed context, split conditions)", "Failing to explain the mechanism of sliding window token overlap (10-20%)", "Ignoring the storage and compute trade-offs of semantic chunking with overlap"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you monitor and debug retrieval quality issues, and what changes did you implement to improve performance?', '{"key_points": [{"id": "KP1", "description": "Monitoring retrieval quality in production: tracking real-time retrieval metrics (Hit Rate@K, reranker confidence scores, fallback trigger rates) and user feedback telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval monitoring, reranker confidence score tracking, fallback rate, user feedback telemetry (thumbs-up/down), OpenTelemetry logging", "Monitors average cross-encoder score on top-1 retrieved chunk; drops indicate retrieval degradation", "Captures user feedback signals and agent escalation rates to identify underperforming topic clusters"]}, {"id": "KP2", "description": "Debugging retrieval failure modes: analyzing vocabulary mismatch, out-of-vocabulary acronyms, overly restrictive metadata filters, and chunk fragmentation.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval debugging, failure root cause analysis, vocabulary mismatch, missing metadata tags, chunk boundary fracture, search space pruning errors", "Inspects failing queries to see if dense search missed exact codes or if scalar filters filtered out relevant documents", "Renders top retrieved chunks to inspect whether content was corrupted or fragmented during ingestion"]}, {"id": "KP3", "description": "Implemented changes to improve performance: deploying hybrid search (BM25 + vector), adding cross-encoder reranking, tuning HNSW efSearch, and prepending contextual breadcrumbs.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval (BM25 + vector), BGE-Reranker, efSearch tuning (from 16 to 64), contextual breadcrumb prepending, query rewriting", "Added BM25 to catch exact diagnostic codes and part numbers that dense vectors missed", "Added cross-encoder reranker to eliminate semantically adjacent false positives", "Prepended document hierarchy breadcrumbs to chunks, boosting retrieval recall significantly"]}], "critical_failures": ["Failing to describe concrete operational debugging workflows (inspecting reranker scores, logging query-chunk pairs)", "Ignoring specific failure modes (vocabulary mismatch, code lookup failures, metadata filter over-pruning)", "Failing to detail concrete architectural fixes implemented (hybrid search, rerankers, breadcrumbs)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did you structure the deployment and retrieval pipelines, and what responsibilities did each pipeline handle?', '{"key_points": [{"id": "KP1", "description": "Asynchronous ingestion and indexing pipeline: decoupled batch/event-driven workers handling document parsing, layout extraction, chunking, embedding generation, and vector DB upsert.", "required": true, "acceptable_evidence": ["Technical keywords: ingestion pipeline, asynchronous workers, S3 triggers, SQS buffering, layout parsing (Docling), chunking, batch embedding, vector upsert", "Processes heavy unstructured documents offline without impacting real-time user query traffic", "Maintains document versioning, content hashing (SHA-256), and metadata tagging during ingestion"]}, {"id": "KP2", "description": "Online real-time retrieval and orchestration pipeline: low-latency query serving handling query rewriting, hybrid retrieval, cross-encoder reranking, and LLM streaming.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval pipeline, online query serving, FastAPI, query rewriting/expansion, hybrid search (BM25 + vector), RRF fusion, cross-encoder reranking", "Receives user prompt, executes metadata pre-filtering, and queries vector database with sub-50ms latency", "Reranks candidates and formats prompt context for LLM generation"]}, {"id": "KP3", "description": "CI/CD deployment pipeline: automating code quality checks, container builds, automated golden dataset evaluation gates, and blue-green/rolling deployments.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD deployment pipeline, GitHub Actions, Docker, Amazon ECR, AWS EKS, Helm charts, Ragas quality gate", "Executes unit tests and automated RAG regression benchmarks before merging code", "Performs rolling zero-downtime container updates on Kubernetes nodegroups"]}, {"id": "KP4", "description": "Telemetry and monitoring infrastructure: distributed tracing, latency budgeting, and guardrail verification across pipeline boundaries.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Prometheus, Grafana, CloudWatch, Langfuse, distributed tracing", "Monitors ingestion throughput (docs/sec) and online retrieval latency (p95/p99)", "Tracks guardrail violation rates and error status codes across microservices"]}], "critical_failures": ["Failing to decouple the offline ingestion pipeline from the real-time online retrieval pipeline", "Omitting the CI/CD deployment pipeline or quality regression gates", "Failing to delineate specific responsibilities of each pipeline"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How did you use frameworks like LangGraph and RAGAS to orchestrate workflows and evaluate system performance?', '{"key_points": [{"id": "KP1", "description": "LangGraph workflow orchestration: modeling agentic workflows as a directed cyclic graph (StateGraph) with typed state, functional nodes, conditional routing, and checkpointers.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, cyclic orchestration, nodes, conditional edges, supervisor router, checkpointers (PostgresSaver)", "Defines state schema holding query, retrieved passages, execution history, and evaluation flags", "Orchestrates specialized nodes (router, retrieval agent, tool execution, grader node) with cyclic loops for self-correction"]}, {"id": "KP2", "description": "RAGAS evaluation framework integration: utilizing RAGAS to compute automated quantitative scores (Faithfulness, Answer Relevance, Context Relevance) across agent execution paths.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS framework, Faithfulness, Answer Relevance, Context Relevance, LLM-as-a-judge, golden testset benchmarking", "Evaluates whether retrieved context is relevant to the query and whether synthesized answers are faithful to the context", "Automates regression benchmarking across releases to prevent quality degradation"]}, {"id": "KP3", "description": "Synergy between orchestration and evaluation: using RAGAS evaluation insights to tune LangGraph conditional edges, grader thresholds, and query rewriting loops.", "required": true, "acceptable_evidence": ["Technical keywords: closed-loop optimization, grader threshold tuning, Corrective RAG (CRAG) calibration, query rewrite node tuning", "Low Context Relevance scores in RAGAS prompted adding a query rewrite node in LangGraph before retrieval", "Low Faithfulness scores prompted setting strict grader thresholds on conditional edges to reject ungrounded drafts"]}], "critical_failures": ["Failing to explain the distinct roles of LangGraph (workflow orchestration) and RAGAS (system evaluation)", "Failing to explain how evaluation metrics from RAGAS inform orchestration improvements in LangGraph", "Treating LangGraph as a simple linear chain without cyclic state graphs"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How do you design and optimize indexing and retrieval in a vector database such as PGVector?', '{"key_points": [{"id": "KP1", "description": "PGVector indexing strategies: selecting and tuning HNSW or IVFFlat indexes based on dataset scale, write frequency, and memory constraints.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector, HNSW index, IVFFlat index, vector_cosine_ops, m parameter, ef_construction, lists parameter", "Uses HNSW for superior recall and query speed without requiring upfront training, tuning m (e.g. 16) and ef_construction (e.g. 64-128)", "Uses IVFFlat for lower memory consumption on large static datasets, tuning lists (e.g. rows / 1000)"]}, {"id": "KP2", "description": "Query optimization and runtime tuning: tuning runtime parameters (hnsw.ef_search, ivfflat.probes), connection pooling, and leveraging partial/filtered indexes.", "required": true, "acceptable_evidence": ["Technical keywords: hnsw.ef_search, ivfflat.probes, partial indexes, compound indexes, work_mem, maintenance_work_mem", "Increases hnsw.ef_search (e.g. SET hnsw.ef_search = 100) at query time to balance higher recall with latency", "Creates partial vector indexes on specific active tenants or categories (WHERE is_active = true) to shrink index size", "Allocates sufficient maintenance_work_mem to prevent disk spilling during index builds"]}, {"id": "KP3", "description": "Hybrid query design and execution: combining SQL relational filters and metadata with vector similarity in a single unified SQL query.", "required": true, "acceptable_evidence": ["Technical keywords: SQL relational joins, WHERE scalar clauses, ORDER BY embedding <=> query_vector LIMIT k, pre-filtering", "Executes vector search with relational predicates (e.g. WHERE tenant_id = ''XYZ'' AND created_at > NOW() - INTERVAL ''30 days'')", "Avoids application-level post-filtering by allowing Postgres query planner to optimize index scans"]}, {"id": "KP4", "description": "Hardware and resource management trade-offs: managing shared buffer pools, WAL write amplification during indexing, and connection scaling.", "required": false, "acceptable_evidence": ["Technical keywords: shared_buffers, WAL write amplification, PgBouncer, compute contention, dedicated replica", "Deploys dedicated read replicas for vector queries to isolate heavy ANN memory scans from core OLTP transactional writes", "Uses PgBouncer connection pooling to handle high-concurrency client connections without exhausting Postgres processes"]}], "critical_failures": ["Failing to detail PGVector index types (HNSW vs IVFFlat) and their specific tuning parameters (m, ef_construction, lists, probes)", "Ignoring runtime parameter tuning (hnsw.ef_search)", "Failing to explain how SQL relational filters integrate with vector similarity ordering"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you design grounding and hallucination detection mechanisms in LLM-based systems?', '{"key_points": [{"id": "KP1", "description": "Grounding prompt design and context framing: structuring prompts with explicit negative constraints, strict attribution requirements, and delimiter isolation.", "required": true, "acceptable_evidence": ["Technical keywords: grounding prompt, explicit refusal directive, negative constraints, XML delimiters, source citation tags", "Directs the model to answer strictly based on provided context and explicitly decline when facts are missing", "Wraps context in explicit XML tags (<context>...</context>) to distinguish authoritative data from user instructions"]}, {"id": "KP2", "description": "Natural Language Inference (NLI) and factual consistency checks: applying automated sentence-level entailment scoring against retrieved context.", "required": true, "acceptable_evidence": ["Technical keywords: Natural Language Inference (NLI), entailment scoring, DeBERTa, claim decomposition, factual consistency", "Segments LLM response into atomic claims and verifies if each claim is entailed by retrieved chunks", "Flags responses with high contradiction or neutrality scores as potential hallucinations"]}, {"id": "KP3", "description": "Retrieval threshold gating and post-generation fallback: discarding low-relevance retrieval results before generation and substituting deterministic canned fallbacks.", "required": true, "acceptable_evidence": ["Technical keywords: relevance score cutoff, reranker threshold, deterministic fallback, graceful degradation, out-of-context refusal", "Blocks LLM generation if candidate reranker score is below threshold (e.g. < 0.40)", "Serves pre-approved enterprise fallback message instead of letting the model fabricate unsupported answers"]}, {"id": "KP4", "description": "Automated evaluation and monitoring: running continuous Faithfulness scoring via Ragas/DeepEval on production query samples.", "required": false, "acceptable_evidence": ["Technical keywords: Ragas Faithfulness, LLM-as-a-judge, production sampling, hallucination rate dashboard, Langfuse logging", "Logs all generated answers with retrieved contexts and computes daily Faithfulness metrics", "Triggers alerts if production hallucination rates exceed agreed SLA (e.g. > 3%)"]}], "critical_failures": ["Relying solely on basic prompt wording without post-generation validation or retrieval gating", "Failing to explain automated hallucination detection mechanisms (NLI entailment, claim verification)", "Ignoring fallback handling when context is missing or low-confidence"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How do you detect and handle issues such as data drift and hallucinations in production ML systems?', '{"key_points": [{"id": "KP1", "description": "Data drift detection in production RAG: monitoring shifts in user query semantic distributions, vocabulary mismatch, and document updates using statistical distance tests.", "required": true, "acceptable_evidence": ["Technical keywords: data drift, semantic drift, query distribution shift, Kolmogorov-Smirnov test, Population Stability Index (PSI), embedding drift", "Tracks embedding centroids of incoming user queries over time to detect shifts into unindexed topics", "Monitors vector distance changes between user queries and stored knowledge base centroids"]}, {"id": "KP2", "description": "Production hallucination detection: implementing continuous runtime Natural Language Inference (NLI) and automated LLM-as-a-judge sampling (Ragas Faithfulness).", "required": true, "acceptable_evidence": ["Technical keywords: runtime hallucination detection, NLI entailment, Ragas Faithfulness, citation validation, batch evaluation sampling", "Asynchronously evaluates a 5-10% sample of production user sessions for ungrounded claims", "Validates that cited chunk references actually contain the asserted facts"]}, {"id": "KP3", "description": "Handling and remediation strategies for data drift: automated knowledge base reindexing, query rewriter retraining, and active learning curation.", "required": true, "acceptable_evidence": ["Technical keywords: drift remediation, incremental reindexing, knowledge base updates, automated alert routing, active learning", "Triggers automated alerts when out-of-distribution queries spike, indicating missing documentation or new product releases", "Updates document collections and schedules vector re-embedding for modified enterprise manuals"]}, {"id": "KP4", "description": "Handling and remediation strategies for hallucinations: runtime circuit breakers, dynamic prompt adjustment, and automated escalation to human agents.", "required": true, "acceptable_evidence": ["Technical keywords: hallucination remediation, circuit breakers, fallback replacement, temperature adjustment, HITL escalation", "Intercepts unfaithful answers at runtime and serves a deterministic fallback response", "Adjusts prompt grounding constraints and lowers temperature if hallucination rates spike"]}], "critical_failures": ["Failing to distinguish between data drift (distribution shifts) and hallucinations (ungrounded generation)", "Lacking concrete statistical or embedding methods to detect drift (e.g. query centroid tracking, PSI)", "Failing to provide concrete remediation steps for both drift and hallucinations"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate generation quality in RAG systems, particularly in terms of faithfulness and answer relevancy?', '{"key_points": [{"id": "KP1", "description": "Faithfulness (Groundedness) evaluation: measuring the proportion of claims in the generated response that can be directly inferred from the retrieved context.", "required": true, "acceptable_evidence": ["Technical keywords: Faithfulness, Groundedness, claim decomposition, Natural Language Inference (NLI), entailment ratio, hallucination rate", "Deconstructs generated response into atomic factual statements: S = {s1, s2, ..., sn}", "Calculates: Faithfulness = (Number of statements entailed by context) / (Total number of statements)", "A faithfulness score of 1.0 indicates complete grounding with zero hallucinations"]}, {"id": "KP2", "description": "Answer Relevancy evaluation: measuring how directly and completely the generated answer addresses the user query, penalizing redundant or evasive answers.", "required": true, "acceptable_evidence": ["Technical keywords: Answer Relevancy, reverse question generation, cosine similarity of questions, prompt adherence, penalty for fluff", "Prompts an evaluator LLM to generate potential queries based on the generated answer, then measures semantic similarity against original user query", "Penalizes responses that are polite but non-responsive or filled with irrelevant information"]}, {"id": "KP3", "description": "Evaluation methodology with Ragas and LLM-as-a-Judge: running automated pipelines against ground-truth datasets with calibrated prompt rubrics.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas framework, DeepEval, LLM-as-a-judge (GPT-4 / Claude 3.5 Sonnet), golden benchmark dataset, structured prompt scoring", "Automates generation of test triplets (query, retrieved context, answer)", "Uses high-capability LLMs executing deterministic rubric prompts with structured JSON output"]}, {"id": "KP4", "description": "Operational implementation: integrating automated evaluation in CI/CD pipelines and production sample monitoring dashboards.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD quality gate, production telemetry, Langfuse / Arize Phoenix, regression prevention", "Blocks pull requests if Faithfulness drops below 0.90 on benchmark tests", "Tracks daily moving averages of Answer Relevancy across live user traffic"]}], "critical_failures": ["Failing to clearly define the formulas and mechanisms of Faithfulness and Answer Relevancy", "Confusing Answer Relevancy with Context Relevancy (retrieval metric)", "Failing to explain how LLM-as-a-judge frameworks compute these metrics"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate model performance across different tasks, including classification, retrieval, and generation?', '{"key_points": [{"id": "KP1", "description": "Evaluating classification tasks: assessing categorical predictions using Precision, Recall, F1-Score (macro/micro/weighted), ROC-AUC, and Confusion Matrix analysis.", "required": true, "acceptable_evidence": ["Technical keywords: classification metrics, Precision, Recall, F1-Score, Macro/Micro F1, ROC-AUC, Confusion Matrix, class imbalance", "Evaluates intent classifiers or sentiment models against labeled ground truth", "Accounts for class imbalance using PR-AUC and Macro F1 rather than misleading raw accuracy"]}, {"id": "KP2", "description": "Evaluating retrieval tasks: assessing ranked candidate quality using Precision@K, Recall@K, Hit Rate@K, Mean Reciprocal Rank (MRR), and NDCG@K.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval metrics, Precision@K, Recall@K, Hit Rate@K, MRR (Mean Reciprocal Rank), NDCG@K, ranking quality", "Hit Rate@K measures whether the gold relevant passage appears in top-K search results", "NDCG@K evaluates whether highly relevant documents are ranked above marginally relevant ones"]}, {"id": "KP3", "description": "Evaluating generation tasks: assessing natural language outputs using reference-based metrics (ROUGE-L, BLEU, BERTScore) and LLM-as-a-Judge metrics (Faithfulness, Answer Relevance).", "required": true, "acceptable_evidence": ["Technical keywords: generation metrics, ROUGE-L, BLEU, BERTScore, LLM-as-a-Judge, Faithfulness, Answer Relevance, NLI entailment", "Uses ROUGE/BERTScore for lexical and semantic overlap against human gold answers", "Uses LLM-as-a-judge and NLI models to evaluate factual consistency, coherence, and groundedness"]}, {"id": "KP4", "description": "Holistic operational evaluation: tracking latency SLAs, token throughput, computational cost, and human-in-the-loop qualitative auditing.", "required": false, "acceptable_evidence": ["Technical keywords: latency SLAs, cost per inference, throughput, human evaluation, blind A/B testing", "Balances model quality against operational constraints (e.g. latency budget < 500ms, cost per 1k tokens)", "Conducts periodic human expert audits to calibrate automated scoring"]}], "critical_failures": ["Failing to cover all three requested task categories: classification, retrieval, and generation", "Confusing metrics between domains (e.g. using BLEU for retrieval or MRR for classification)", "Ignoring modern LLM-as-a-judge and NLI methods for generation evaluation"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you handle PII data in documents, including scanned PDFs or images, during preprocessing and retrieval?', '{"key_points": [{"id": "KP1", "description": "OCR and document preprocessing for scanned PDFs/images: utilizing OCR engines (Tesseract, AWS Textract, Docling) with bounding-box coordinate tracking to extract text from images.", "required": true, "acceptable_evidence": ["Technical keywords: OCR preprocessing, AWS Textract, Tesseract, Docling, scanned PDFs, bounding-box spatial coordinates", "Extracts raw text, tabular structures, and layout geometry from image-based and scanned PDF documents", "Maintains token spatial coordinates for visual redaction mapping"]}, {"id": "KP2", "description": "PII detection and sanitization pipeline: applying Named Entity Recognition (NER) and regex-based de-identification (Microsoft Presidio) before chunking and embedding.", "required": true, "acceptable_evidence": ["Technical keywords: PII sanitization, Microsoft Presidio, Named Entity Recognition (NER), regex patterns, PII masking / tokenization", "Detects sensitive entities: SSNs, credit cards, driver licenses, phone numbers, addresses, and customer names", "Replaces identified PII with surrogate synthetic tokens (e.g. <PERSON_1>, <SSN_REDACTED>) or visual pixel blackouts on images"]}, {"id": "KP3", "description": "Preventing PII indexing and vector leakage: ensuring sanitized text is embedded so vector databases never store or expose private data.", "required": true, "acceptable_evidence": ["Technical keywords: vector leakage prevention, sanitized embedding, metadata scrub, irreversible redaction", "Guarantees that raw sensitive PII never enters embedding models or vector database payload metadata", "Prevents inadvertent leakage during semantic vector search or nearest neighbor extraction"]}, {"id": "KP4", "description": "Runtime retrieval controls and compliance governance: enforcing Role-Based Access Control (RBAC), re-identification mapping for authorized roles, and HIPAA/GDPR compliance.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC, cryptographic tokenization vault, authorized de-anonymization, HIPAA, GDPR compliance", "Stores original PII mappings in a secure, encrypted key-value vault accessible only by privileged roles with strict audit trails", "Applies runtime output scanning to ensure generated answers do not reconstruct sensitive personal details"]}], "critical_failures": ["Failing to address OCR extraction for scanned documents and images (e.g. AWS Textract, Docling)", "Failing to redact PII prior to embedding generation (allowing PII into vector database)", "Ignoring standard PII detection frameworks such as Microsoft Presidio or NER models"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'HARD', 'SPECIFIC', 120, 'How do you handle embedding generation and deployment, including infrastructure considerations such as cost and scalability?', '{"key_points": [{"id": "KP1", "description": "Embedding generation infrastructure: provisioning scalable GPU/CPU worker pools (AWS EKS / AWS SageMaker / Triton Inference Server) with dynamic batching.", "required": true, "acceptable_evidence": ["Technical keywords: embedding infrastructure, GPU/CPU worker pools, Triton Inference Server, AWS SageMaker, dynamic batching, ONNX Runtime", "Batches embedding requests (e.g. batch size 64-128) to saturate GPU memory and maximize throughput during ingestion", "Deploys lightweight models (e.g. all-MiniLM-L6-v2) on CPU instances to minimize compute costs for low-latency queries"]}, {"id": "KP2", "description": "Cost optimization strategies: comparing self-hosted open-source models versus managed SaaS APIs (Bedrock Titan, OpenAI text-embedding-3).", "required": true, "acceptable_evidence": ["Technical keywords: cost optimization, self-hosted vs managed APIs, spot instances, embedding caching, dimension reduction (Matryoshka)", "Self-hosting open-source models eliminates per-token API costs on large ingestion corpora (>millions of chunks)", "Uses Redis embedding caches to prevent re-embedding identical text snippets or recurring user queries", "Utilizes Matryoshka representation learning to truncate vector dimensions and reduce storage costs"]}, {"id": "KP3", "description": "Scalability and deployment patterns: decoupling asynchronous high-volume ingestion workers from real-time low-latency query embedding services.", "required": true, "acceptable_evidence": ["Technical keywords: decoupled architecture, asynchronous batch ingestion, real-time query serving, horizontal autoscaling (HPA), SQS queue", "Offline ingestion uses auto-scaling spot worker pods consuming from SQS to process document backlogs cost-effectively", "Online query embedding runs on dedicated low-latency microservices with strict p95 SLAs (<15ms)"]}, {"id": "KP4", "description": "Embedding model versioning and migration: implementing blue-green vector reindexing and zero-downtime collection swapping during model upgrades.", "required": false, "acceptable_evidence": ["Technical keywords: blue-green reindexing, collection aliasing, zero-downtime migration, vector versioning", "Upgrades embedding models by creating a new Milvus collection, backfilling vectors in background, and atomically switching collection aliases", "Prevents query downtime or embedding space incompatibility during model transitions"]}], "critical_failures": ["Failing to separate high-throughput asynchronous batch ingestion from low-latency online query embedding", "Ignoring cost considerations (self-hosted vs API pricing, GPU vs CPU, embedding caching)", "Failing to address model versioning or zero-downtime reindexing strategies"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How do you handle issues in Python-based ML pipelines, including preprocessing, chunking, retrieval, and evaluation challenges?', '{"key_points": [{"id": "KP1", "description": "Preprocessing and parsing issues: handling malformed PDFs, corrupted OCR text, table layout fractures, character encoding errors, and boilerplate contamination.", "required": true, "acceptable_evidence": ["Technical keywords: preprocessing challenges, layout fracturing, Docling/Unstructured, OCR errors, table markdown serialization, unicode encoding bugs", "Resolves table destruction in PDFs by using layout-aware vision parsers (Docling/TableFormer) rather than naive text extractors", "Cleans non-ASCII characters, repeated disclaimers, and header/footer boilerplate that pollute embeddings"]}, {"id": "KP2", "description": "Chunking pitfalls: semantic truncation, arbitrary token boundary splits, sentence fragmenting, and loss of section hierarchy.", "required": true, "acceptable_evidence": ["Technical keywords: chunking pitfalls, semantic fragmentation, arbitrary token cuts, context loss, parent-child chunking, metadata breadcrumbs", "Fixes context fragmentation by switching from naive token chunking to recursive Markdown header splitting", "Prepends document hierarchy breadcrumbs to ensure child chunks retain standalone semantic meaning"]}, {"id": "KP3", "description": "Retrieval failures: vocabulary mismatch, out-of-vocabulary acronyms, high ANN latency, vector collisions, and low precision.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval challenges, vocabulary mismatch, ANN parameter tuning, hybrid search (BM25 + vector), RRF fusion, cross-encoder reranking", "Addresses exact keyword/part number retrieval failures by deploying hybrid search (BM25 + dense vectors)", "Eliminates false-positive candidate chunks by adding a cross-encoder reranker stage"]}, {"id": "KP4", "description": "Evaluation bottlenecks: absence of golden test datasets, non-deterministic LLM-as-a-judge scoring, and metric divergence.", "required": true, "acceptable_evidence": ["Technical keywords: evaluation bottlenecks, lack of ground truth, LLM-as-a-judge bias, Ragas calibration, synthetic dataset generation", "Builds representative golden datasets of query-context-answer triplets to establish reliable regression baselines", "Calibrates LLM-as-a-judge prompts with few-shot rubrics and temperature=0.0 to ensure deterministic scoring"]}], "critical_failures": ["Failing to address issues across all four requested pipeline stages (preprocessing, chunking, retrieval, evaluation)", "Offering generic software engineering bugs without RAG-specific ML pipeline failure modes", "Failing to provide concrete technical solutions for each identified issue"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How do you handle long-term memory in agentic systems, and what are the trade-offs between summarization and embedding-based retrieval?', '{"key_points": [{"id": "KP1", "description": "Long-term memory architecture in agentic systems: persisting multi-session user preferences, episodic memories, and historical resolutions across disparate conversations.", "required": true, "acceptable_evidence": ["Technical keywords: long-term memory, episodic memory, persistent user profile, multi-session context, memory consolidation", "Enables an agent to remember recurring issues, user identity attributes, past diagnostic steps, and preferences over weeks or months", "Decouples ephemeral session buffers (Redis) from permanent episodic memory storage"]}, {"id": "KP2", "description": "Summarization-based memory approach: periodically compressing conversation histories into running natural language summaries.", "required": true, "acceptable_evidence": ["Technical keywords: summarization memory, rolling summary, recursive summarization, memory compression, token economy", "Uses an LLM to condense previous dialogue turns into a compact narrative summary injected into the system prompt", "Advantages: simple sequential narrative, retains chronological flow, low retrieval complexity", "Disadvantages: loss of fine-grained granular details, information drift over successive summarizations, token growth over time"]}, {"id": "KP3", "description": "Embedding-based retrieval memory approach: segmenting past interactions into episodic units, embedding them into a dedicated vector store, and retrieving top-k relevant memories at query time.", "required": true, "acceptable_evidence": ["Technical keywords: embedding-based memory, vector retrieval, episodic store, semantic memory lookup, recency decay weighting", "Embeds past user statements and agent actions as searchable vectors in a user-scoped collection", "Advantages: scales to years of interactions, retrieves only contextually relevant past facts, zero prompt token waste on irrelevant memories", "Disadvantages: loses chronological continuity, requires multi-stage retrieval, sensitive to retrieval threshold tuning"]}, {"id": "KP4", "description": "Optimal hybrid memory design: maintaining a running user profile summary alongside an episodic vector index with recency and relevance scoring.", "required": false, "acceptable_evidence": ["Technical keywords: hybrid memory architecture, MemGPT / LangMem pattern, static user profile + dynamic episodic retrieval", "Maintains structured key-value user profile for persistent facts (vehicle model, preferred dealer) while using vector search for historical troubleshooting episodes", "Combines semantic similarity with time-decay scoring: Score = Similarity * exp(-decay * delta_time)"]}], "critical_failures": ["Failing to provide a clear trade-off comparison between summarization and embedding-based retrieval memory", "Ignoring the loss of chronological flow in vector memory and information loss in recursive summarization", "Failing to mention hybrid memory architectures or recency decay weighting"]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How have you designed and implemented RAG-based AI assistants, including data preparation, vectorization, metadata structuring, and prompt engineering to improve task-oriented performance?', '{"key_points": [{"id": "KP1", "description": "Data preparation and vectorization: parsing heterogeneous unstructured documents (PDFs, manuals, tickets), cleaning boilerplate, chunking with overlap, and generating dense embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: data preparation, layout parsing (Docling), recursive chunking (512 tokens / 50 overlap), Sentence Transformers (all-MiniLM-L6-v2), vectorization", "Extracts clean text and Markdown tables while stripping repeated headers and footers", "Generates 384/1536-dimensional embeddings and normalizes vectors for fast dot product similarity"]}, {"id": "KP2", "description": "Metadata structuring and filtering: enriching chunks with domain hierarchies (model, year, component, document_type) and applying scalar pre-filters in vector databases.", "required": true, "acceptable_evidence": ["Technical keywords: metadata structuring, schema design, domain taxonomy, scalar pre-filtering, Milvus partition keys", "Attaches structured attributes (e.g. system: ''Battery'', year: 2024, tier: ''enterprise'') to chunks", "Restricts search space using boolean metadata filters to eliminate false-positive cross-domain context"]}, {"id": "KP3", "description": "Task-oriented prompt engineering: designing structured system prompts with strict grounding rules, citation requirements, persona framing, and deterministic output schemas.", "required": true, "acceptable_evidence": ["Technical keywords: prompt engineering, strict grounding constraints, bracketed citations [Doc-1], few-shot exemplars, JSON output schema", "Directs model to act as a certified diagnostic assistant, answering only from context and refusing ungrounded extrapolation", "Enforces structured JSON or Markdown formatting with explicit troubleshooting steps and safety warnings"]}, {"id": "KP4", "description": "Production performance and guardrail integration: combining hybrid retrieval (BM25 + vector) with hallucination validation (NLI entailment) to ensure operational reliability.", "required": false, "acceptable_evidence": ["Technical keywords: hybrid retrieval, cross-encoder reranking, NLI entailment scoring, latency SLA, production monitoring", "Delivers sub-1.5s p95 response time using streaming tokens and cached embeddings", "Validates generated claims against context before displaying to enterprise users"]}], "critical_failures": ["Failing to cover all four specified areas: data preparation, vectorization, metadata structuring, and prompt engineering", "Treating prompt engineering as generic instructions without grounding constraints or citation enforcement", "Ignoring metadata filtering in retrieval design"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How have you implemented RAG pipelines using LangChain and LangGraph, and what design decisions did you make for multi-agent orchestration?', '{"key_points": [{"id": "KP1", "description": "Evolution from LangChain to LangGraph: transitioning from linear, brittle sequential chains (LLMChain / RetrievalQA) to stateful, cyclic directed graphs with explicit state schemas.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain limitations, LangGraph, StateGraph, cyclic workflows, state schema, functional nodes, conditional edges", "Explains that LangChain chains cannot handle dynamic retries, iterative self-correction, or state persistence across multi-turn interactions", "LangGraph models agent workflows as cyclic graphs where nodes update a typed shared state dictionary"]}, {"id": "KP2", "description": "Multi-agent orchestration architecture: designing a Supervisor / Router pattern delegating to specialized agent nodes (Retrieval Agent, Action/API Agent, Response Grader).", "required": true, "acceptable_evidence": ["Technical keywords: multi-agent orchestration, supervisor pattern, router node, retrieval specialist, tool execution agent, grader node", "Supervisor inspects user intent and dynamically routes execution to RAG search or external API execution nodes", "Decouples knowledge retrieval logic from transactional business logic"]}, {"id": "KP3", "description": "Self-reflective loops and Corrective RAG (CRAG): implementing grader nodes to evaluate retrieval relevance and dynamically trigger query rewriting loops.", "required": true, "acceptable_evidence": ["Technical keywords: Corrective RAG (CRAG), Self-RAG, retrieval grader, query rewrite loop, recursion limit (max_iterations)", "Evaluates retrieved documents; if relevance score is below threshold, routes back to query rewrite node rather than proceeding to LLM generation", "Enforces hard recursion limits (e.g. max_steps=4) to prevent infinite graph loops"]}, {"id": "KP4", "description": "Durable state management and Human-in-the-Loop (HITL): utilizing LangGraph checkpointers (PostgresSaver) for pause-and-resume execution and human review gates.", "required": false, "acceptable_evidence": ["Technical keywords: checkpointers (PostgresSaver / MemorySaver), HITL interrupt, human-in-the-loop, state rollback, transactional safety", "Freezes agent execution before executing irreversible API actions (e.g. booking service appointments or issuing warranty claims)", "Resumes graph execution seamlessly upon receiving human approval"]}], "critical_failures": ["Failing to explain the architectural difference between LangChain (linear chains) and LangGraph (cyclic stateful graphs)", "Ignoring multi-agent orchestration patterns (Supervisor / Router with specialized nodes)", "Omitting self-reflective feedback loops (CRAG / query rewriting) and recursion safeguards"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a class to compute a running average of incoming values, and how would you handle edge cases like division by zero?', '{"key_points": [{"id": "KP1", "description": "Class design and state variables: implementing a Python class maintaining running count and running total (or cumulative sum) with an add_value / get_average interface.", "required": true, "acceptable_evidence": ["Technical keywords: RunningAverage class, __init__, self.count, self.total, add_value(val), get_average()", "Initializes count = 0 and total = 0.0 in __init__ to avoid storing the entire unbounded list of raw values in memory (O(1) space)", "Updates total += val and count += 1 on each incoming value"]}, {"id": "KP2", "description": "Handling edge cases including division by zero: handling empty state when count is 0 by returning None, 0.0, or raising a custom ZeroDivisionError/ValueError.", "required": true, "acceptable_evidence": ["Technical keywords: division by zero handling, if self.count == 0, return None / 0.0 / raise ZeroDivisionError, graceful empty state", "Checks self.count == 0 before performing division total / count", "Explains trade-off: returning None indicates missing data cleanly, while raising an exception enforces strict caller handling"]}, {"id": "KP3", "description": "Numerical stability and additional edge cases: handling non-numeric types, float precision/overflow, NaN/Inf values, and sliding-window variants.", "required": true, "acceptable_evidence": ["Technical keywords: type validation, math.isnan(), math.isinf(), floating-point overflow, Welford''s algorithm, collections.deque for sliding window", "Validates incoming value is an int or float, rejecting or ignoring NaN and Inf values", "Mentions Welford''s algorithm for numerically stable incremental mean and variance computation: mean += (val - mean) / count", "Notes sliding-window variant using collections.deque(maxlen=K) for fixed-window moving average"]}], "critical_failures": ["Failing to handle division by zero when get_average() is called before any values are added", "Storing an unbounded list of all values in memory when an O(1) space running sum/count is required", "Ignoring invalid input types or float NaN/Inf edge cases"]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'How would you design and implement a scalable RAG system using GCP and Python for production use?', '{"key_points": [{"id": "KP1", "description": "GCP infrastructure and ingestion pipeline: Google Cloud Storage (GCS) for document landing, Cloud Pub/Sub for event messaging, and Cloud Run / Cloud Functions for asynchronous document parsing.", "required": true, "acceptable_evidence": ["Technical keywords: Google Cloud Storage (GCS), Cloud Pub/Sub, Cloud Run, Cloud Functions, asynchronous event-driven ingestion", "Uploads to GCS trigger Pub/Sub messages consumed by containerized Cloud Run workers running Docling/Unstructured parsers", "Dead-letter topics in Pub/Sub capture failed or malformed documents for alerting"]}, {"id": "KP2", "description": "Vector storage and search on GCP: utilizing Vertex AI Vector Search (formerly Matching Engine) or self-hosted Milvus on Google Kubernetes Engine (GKE).", "required": true, "acceptable_evidence": ["Technical keywords: Vertex AI Vector Search, Google Kubernetes Engine (GKE), Milvus on GKE, ScaNN algorithm, sub-10ms ANN search", "Vertex AI Vector Search provides managed vector indexing based on Google''s ScaNN algorithm with billion-scale horizontal scaling", "Applies metadata filtering and streaming index updates"]}, {"id": "KP3", "description": "LLM orchestration and model serving: invoking Vertex AI Gemini models (Gemini 1.5 Pro / Flash) orchestrated via Python FastAPI microservices on Cloud Run or GKE.", "required": true, "acceptable_evidence": ["Technical keywords: Vertex AI Gemini, Gemini 1.5 Pro / Flash, Python FastAPI, GKE, Cloud Run, serverless container orchestration", "Serves real-time streaming queries via FastAPI using Server-Sent Events (SSE)", "Vertex AI provides managed IAM authentication, enterprise VPC Service Controls, and regional compliance"]}, {"id": "KP4", "description": "Operational scalability, caching, and observability: Google Cloud Memorystore (Redis) for response caching, Cloud Monitoring/Logging, and Terraform for IaC.", "required": true, "acceptable_evidence": ["Technical keywords: Memorystore Redis, Cloud Monitoring, Cloud Trace, VPC Service Controls, Terraform IaC, latency SLA", "Caches frequent query embeddings and responses in Memorystore Redis to reduce LLM costs and latency", "Instruments distributed tracing via Google Cloud Trace to monitor end-to-end p95 latency (<1.2s)"]}], "critical_failures": ["Failing to detail specific GCP native services (GCS, Pub/Sub, Vertex AI Vector Search / Gemini, Cloud Run / GKE)", "Confusing AWS services with GCP equivalents", "Ignoring asynchronous ingestion decoupling, caching, or security governance (VPC Service Controls)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you scale a RAG system when the number of documents and users increases significantly?', '{"key_points": [{"id": "KP1", "description": "Scaling document ingestion and indexing: decoupling ingestion using distributed message queues (Kafka/SQS) and asynchronous worker pools to handle millions of documents.", "required": true, "acceptable_evidence": ["Technical keywords: distributed ingestion, Kafka, SQS queue, worker autoscale, batch chunking, parallel embedding generation", "Decouples ingestion from user queries so large document backlogs never degrade search latency", "Processes document chunks in parallel batches using GPU/CPU worker pools with content deduplication"]}, {"id": "KP2", "description": "Scaling vector database and search: separating query and data nodes, sharding vector collections, tuning HNSW parameters, and leveraging partition keys.", "required": true, "acceptable_evidence": ["Technical keywords: vector DB sharding, query/data node separation, Milvus distributed cluster, partition keys, HNSW memory optimization, IVFPQ", "Separates stateless query nodes (scale horizontally with QPS) from stateful data nodes (scale with vector volume)", "Uses multi-tenancy partition keys to restrict search traversal to relevant subsets", "Applies Product Quantization (PQ) to reduce index memory footprint when scaling to tens of millions of vectors"]}, {"id": "KP3", "description": "Scaling query throughput and concurrent users: deploying horizontal API autoscaling (HPA), semantic caching (Redis), and connection pooling.", "required": true, "acceptable_evidence": ["Technical keywords: horizontal autoscaling (HPA), semantic cache, Redis, API Gateway rate limiting, connection pooling, read replicas", "Caches frequent queries and embedding results in Redis to bypass vector search and LLM calls for repeated questions", "Scales API gateway and orchestrator pods horizontally on Kubernetes based on incoming request concurrency"]}, {"id": "KP4", "description": "Managing LLM rate limits and inference latency: load balancing across multiple LLM endpoints/regions, utilizing streaming responses, and fallbacks.", "required": false, "acceptable_evidence": ["Technical keywords: multi-region LLM load balancing, token rate limit mitigation, streaming responses (SSE), TTFT optimization", "Distributes LLM calls across multiple cloud regions/providers to bypass provider TPM (Tokens Per Minute) rate limits", "Streams tokens to end users via Server-Sent Events to minimize perceived latency"]}], "critical_failures": ["Addressing only document scaling while ignoring concurrent user scaling (or vice versa)", "Failing to explain how vector databases scale (query/data node separation, sharding, partition keys)", "Ignoring semantic caching (Redis) and LLM rate-limit management under high concurrency"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you troubleshoot a RAG system to determine whether issues arise from retrieval, generation, or preprocessing?', '{"key_points": [{"id": "KP1", "description": "Isolating preprocessing and ingestion issues: inspecting parsed chunks, verifying table structures, checking token histograms, and validating metadata tags.", "required": true, "acceptable_evidence": ["Technical keywords: preprocessing troubleshooting, chunk inspection, table corruption, character encoding errors, missing metadata tags, token length distribution", "Inspects stored chunk records in database to verify whether text was severed, OCR was garbled, or tables were corrupted", "Verifies whether scalar metadata fields (category, model year, tenant_id) were correctly extracted and indexed"]}, {"id": "KP2", "description": "Isolating retrieval issues: decoupling retrieval from generation to measure Hit Rate@K, MRR, and candidate pool relevance scores.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval troubleshooting, isolated retrieval testing, Hit Rate@K, MRR, cross-encoder score cutoff, vector vs keyword evaluation", "Queries the vector database directly without calling the LLM; checks if the gold source document appears in the top-k results", "If gold chunk is absent, checks whether embedding similarity failed or metadata pre-filtering incorrectly excluded it"]}, {"id": "KP3", "description": "Isolating generation issues: evaluating LLM prompt adherence, grounding constraints, context window truncation, and temperature settings using controlled context injection.", "required": true, "acceptable_evidence": ["Technical keywords: generation troubleshooting, controlled context test, Faithfulness scoring, prompt grounding audit, lost-in-the-middle effect, temperature check", "Tests LLM generation by directly injecting the perfect gold chunk into the prompt context", "If the model still hallucinates or fails, isolates the issue to system prompt instructions, model reasoning capacity, or temperature settings"]}], "critical_failures": ["Failing to decouple retrieval testing from generation testing during troubleshooting", "Treating the RAG system as an indivisible black box rather than isolating preprocessing, retrieval, and generation stages", "Lacking concrete verification steps for each stage (chunk inspection, direct vector queries, gold context injection)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Let''s say the latency increased after you did the reranking. How would you tackle that increment in the latency?', '{"key_points": [{"id": "KP1", "description": "Candidate pool size pruning: reducing the number of candidate documents sent to the reranker from 50-100 down to 15-25 to cut cross-attention inference load.", "required": true, "acceptable_evidence": ["Technical keywords: candidate pool reduction, top-k pruning (from 50/100 to 15/25), cross-attention complexity, O(N) compute reduction", "Explains cross-encoder latency scales linearly with candidate count: reranking 20 chunks takes 40% of the time required for 50 chunks", "Most relevant documents are already present in the top-20 after hybrid search"]}, {"id": "KP2", "description": "Model optimization and lightweight architectures: replacing heavy cross-encoders with distilled models, INT8/FP16 quantization, and ONNX Runtime / TensorRT acceleration.", "required": true, "acceptable_evidence": ["Technical keywords: model distillation, bge-reranker-base / ms-marco-MiniLM-L-6-v2, INT8 / FP16 quantization, ONNX Runtime, TensorRT, GPU batching", "Quantizes model weights to INT8 to achieve 2-3x faster CPU/GPU inference with negligible drop in NDCG", "Switches from bge-reranker-large to a distilled lightweight model (e.g. MiniLM cross-encoder) cutting latency from 80ms to 20ms"]}, {"id": "KP3", "description": "Conditional / speculative reranking: bypassing the reranker when first-stage vector similarity or keyword match confidence is exceptionally high.", "required": true, "acceptable_evidence": ["Technical keywords: conditional reranking, fast path, confidence threshold bypass, score margin gating", "If the top vector match has a similarity score > 0.90 and a large margin over the second match, skip reranking and proceed directly to LLM generation", "Only routes ambiguous or dense candidate clusters through the cross-encoder"]}, {"id": "KP4", "description": "Asynchronous pipelining and caching: caching reranker scores for frequent query-document pairs in Redis and overlapping processing stages.", "required": false, "acceptable_evidence": ["Technical keywords: Redis reranker cache, query-chunk pair hashing, parallel processing, async inference", "Caches computed cross-encoder scores for high-frequency queries to achieve 0ms reranker latency on cache hits", "Executes input tokenization concurrently while awaiting remaining vector search results"]}], "critical_failures": ["Suggesting removing the reranker entirely rather than optimizing it", "Failing to mention candidate pool size reduction (the most immediate and effective latency lever)", "Ignoring model optimization techniques (quantization, distillation, ONNX Runtime)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What are common pitfalls when implementing a text chunking function, and how would you debug them?', '{"key_points": [{"id": "KP1", "description": "Common chunking pitfalls: severing sentences or words mid-token, destroying Markdown/HTML tables, splitting numbered procedural lists, and losing section context.", "required": true, "acceptable_evidence": ["Technical keywords: mid-word slicing, sentence fracture, table corruption, broken procedural lists, arbitrary token boundaries, context fragmentation", "Naive fixed-length character slicing cuts words in half (e.g. ''tran- | sportation'') and corrupts embedding tokens", "Slices tabular data across rows, rendering columns unreadable by the LLM", "Splits a 5-step troubleshooting procedure across chunks, leaving step 4-5 without context"]}, {"id": "KP2", "description": "Debugging techniques and inspection tools: logging chunk boundary histograms, token count validation, visual markdown rendering, and verifying semantic overlap.", "required": true, "acceptable_evidence": ["Technical keywords: chunk inspection, token length histogram, visual rendering, boundary logging, overlap verification, assert statements", "Prints chunk start and end snippets to verify splits occur at periods, paragraph breaks, or markdown headers", "Uses tiktoken / HuggingFace tokenizers to verify exact token counts and ensure chunks don''t exceed model context limits", "Renders parsed chunks in a visual UI or diff viewer to inspect table and list preservation"]}, {"id": "KP3", "description": "Architectural fixes: implementing recursive character chunking with natural boundary hierarchies (headers, paragraphs, sentences) and contextual breadcrumb prepending.", "required": true, "acceptable_evidence": ["Technical keywords: RecursiveCharacterTextSplitter, natural separators [''\\n## '', ''\\n\\n'', ''\\n'', ''. '', '' ''], contextual breadcrumb prepend", "Configures separator hierarchy to split on highest-level structural boundaries first before falling back to sentence breaks", "Prepends document metadata and header hierarchy to every chunk to anchor semantic context"]}], "critical_failures": ["Failing to identify concrete chunking failure modes (table destruction, mid-sentence/mid-word splits, severed lists)", "Lacking practical debugging techniques (token histograms, boundary logging, tokenizer validation)", "Failing to recommend recursive hierarchical splitting or metadata prepending"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What are the common issues you troubleshoot, such as tool call failures due to vague user queries, LLM hallucination, or failures in sequenced multi-tool operations due to dependencies?', '{"key_points": [{"id": "KP1", "description": "Troubleshooting tool call failures from vague user queries: implementing clarification prompts, intent classification, and parameter schema validation (Pydantic).", "required": true, "acceptable_evidence": ["Technical keywords: vague query handling, intent disambiguation, interactive clarification, Pydantic schema validation, required argument checking", "When a query lacks essential arguments (e.g. ''check warranty'' without VIN), the agent pauses and asks the user for missing details instead of guessing", "Catches missing or malformed tool arguments at schema validation before firing API requests"]}, {"id": "KP2", "description": "Troubleshooting LLM hallucinations in tool use and answers: enforcing strict grounding constraints, relevance score gating, and Natural Language Inference (NLI) verification.", "required": true, "acceptable_evidence": ["Technical keywords: tool hallucination, fabricated arguments, strict grounding, NLI entailment, relevance score gating, citation check", "Prevents models from fabricating non-existent tool names or dummy parameters by constraining tool definitions in system prompts", "Validates generated answers against retrieved context using NLI entailment scoring to block ungrounded assertions"]}, {"id": "KP3", "description": "Troubleshooting sequenced multi-tool operation failures: managing state persistence, error propagation, dependency graphs (LangGraph DAG), and rollbacks.", "required": true, "acceptable_evidence": ["Technical keywords: sequenced tool dependencies, LangGraph DAG, state persistence, error handling node, retry backoff, transaction rollback", "If Step 1 (lookup customer) fails or returns empty, conditional edge intercepts the error and routes to an error recovery node rather than executing Step 2 (create ticket)", "Implements idempotency keys and compensating transactions to rollback partial actions on failure"]}, {"id": "KP4", "description": "Operational guardrails and human escalation: enforcing circuit breakers, recursion limits, and routing unresolvable tool errors to human supervisors.", "required": false, "acceptable_evidence": ["Technical keywords: circuit breakers, recursion limits (max_iterations=5), graceful fallback, HITL escalation, CRM ticket logging", "Terminates execution if agent gets trapped in a repeated tool retry loop", "Transfers complete execution trace and error state to human support technicians"]}], "critical_failures": ["Failing to address all three specified failure modes: vague query tool failures, hallucinations, and multi-tool dependency sequences", "Ignoring parameter schema validation (Pydantic) and interactive user clarification for missing arguments", "Failing to explain dependency management and error handling in sequenced multi-tool workflows"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What are the key factors affecting latency and throughput in a RAG system, and how would you optimize them?', '{"key_points": [{"id": "KP1", "description": "Key factors affecting latency: network round-trips, embedding generation time, vector database ANN index search time, cross-encoder reranking inference, and LLM Time-to-First-Token (TTFT) / generation speed.", "required": true, "acceptable_evidence": ["Technical keywords: latency factors, network hops, embedding inference, ANN search latency, cross-encoder reranker, LLM TTFT (Time-to-First-Token), token generation speed", "Identifies LLM generation and cross-encoder inference as the primary latency bottlenecks (>80% of total response time)", "Breaks down end-to-end latency budget across pipeline stages"]}, {"id": "KP2", "description": "Key factors affecting throughput: LLM API rate limits (TPM/RPM), GPU compute saturation, vector database query node concurrency, and thread pool starvation.", "required": true, "acceptable_evidence": ["Technical keywords: throughput factors, Tokens Per Minute (TPM), Requests Per Minute (RPM), GPU saturation, vector DB QPS, connection pool exhaustion", "Explains how external LLM provider throttling creates throughput ceilings under concurrent user traffic", "Highlights vector database query node scaling limits under concurrent HNSW graph traversals"]}, {"id": "KP3", "description": "Latency optimization techniques: streaming tokens via SSE, semantic caching (Redis), candidate pool pruning, ONNX runtime quantization for rerankers, and asynchronous parallel retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: Server-Sent Events (SSE) streaming, Redis semantic caching, candidate pool pruning (top-25), INT8 quantization, asyncio parallel search", "Streams tokens to end users immediately to cut perceived latency (TTFT < 500ms)", "Caches frequent query responses and embeddings in Redis to serve instant responses (sub-20ms) for repeated queries", "Fires vector search and BM25 queries concurrently via asyncio.gather()"]}, {"id": "KP4", "description": "Throughput optimization techniques: horizontal pod autoscaling (HPA), multi-region LLM load balancing, batch inference for embeddings, and read replicas.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes HPA, multi-region load balancing, vector DB read replicas, batch embedding inference, connection pooling", "Deploys vector database read replicas to distribute concurrent search load across multiple nodes", "Distributes LLM requests across multiple provider regions to multiply effective TPM limits"]}], "critical_failures": ["Failing to differentiate between latency (duration per single request) and throughput (concurrent requests per second)", "Ignoring TTFT (Time-to-First-Token) and streaming as the core perceived latency optimization", "Failing to provide concrete optimizations across caching, quantization, and autoscaling"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What are the limitations of tools like Ragas, and how would you address gaps such as prompt evaluation?', '{"key_points": [{"id": "KP1", "description": "Limitations of Ragas: reliance on powerful LLM evaluators (cost, non-deterministic scores, evaluator bias), latency overhead, and difficulty evaluating nuanced multi-turn agent trajectories.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas limitations, LLM evaluator bias, non-deterministic scoring, high API evaluation cost, multi-turn trajectory blind spots", "Evaluator models can exhibit self-preference bias and positional bias when scoring context", "Evaluating large test suites using GPT-4 / Claude 3.5 Sonnet is slow and expensive for continuous CI/CD pipelines", "Struggles to evaluate dynamic multi-step agent tool calling and complex conversational state"]}, {"id": "KP2", "description": "Addressing the gap in prompt evaluation: integrating structured prompt benchmarking frameworks (Promptfoo, Langfuse, DeepEval prompt testing).", "required": true, "acceptable_evidence": ["Technical keywords: prompt evaluation gap, Promptfoo, Langfuse, prompt regression testing, prompt versioning, deterministic assertions", "Deploys specialized prompt testing tools to benchmark multiple prompt variants systematically against test matrices", "Combines LLM scoring with deterministic assertions (regex matching, JSON schema validation, latency/token cost tracking)", "Tracks prompt version performance across changes to prevent regressions"]}, {"id": "KP3", "description": "Hybrid evaluation strategy: combining lightweight deterministic rules, fast cross-encoder NLI models, and periodic human-in-the-loop expert calibration.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid evaluation, deterministic assertions, NLI entailment models (DeBERTa), human expert calibration, golden dataset", "Uses fast, cheap local NLI models for CI/CD checks, reserving expensive LLM-as-a-judge runs for release candidates", "Periodically validates automated scores against human expert ratings to compute correlation (Cohen''s Kappa)"]}], "critical_failures": ["Failing to identify the core limitations of Ragas (evaluator bias, API cost, non-determinism, agent trajectory limitations)", "Ignoring prompt evaluation frameworks like Promptfoo or structured assertion testing", "Failing to propose a practical hybrid approach combining deterministic rules with model evaluation"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between different embedding models in terms of performance, cost, and dimensionality?', '{"key_points": [{"id": "KP1", "description": "Performance vs dimensionality trade-offs: higher-dimensional embeddings (e.g. 1536/3072 dims in OpenAI/BGE-large) capture richer semantic nuance but increase memory and latency; smaller embeddings (384 dims in MiniLM) offer high speed and efficiency.", "required": true, "acceptable_evidence": ["Technical keywords: embedding dimensionality (384 vs 768 vs 1536), semantic capacity, MTEB benchmark, retrieval recall, memory footprint", "384-dimensional models (all-MiniLM-L6-v2) reduce RAM and disk storage by 75% compared to 1536-dimensional models", "1536-dimensional models capture complex domain relationships and long-context semantics with higher Hit Rate on MTEB"]}, {"id": "KP2", "description": "Cost and deployment trade-offs: self-hosted open-weight models (Sentence Transformers / BGE / E5) on internal CPU/GPU infrastructure versus managed proprietary SaaS APIs (OpenAI / Bedrock Titan).", "required": true, "acceptable_evidence": ["Technical keywords: self-hosted vs managed APIs, per-token API pricing, fixed infrastructure cost, zero rate limits, data privacy/VPC compliance", "Managed APIs require zero infrastructure management but introduce recurring per-token costs and external network latency", "Self-hosted models provide complete data sovereignty, zero egress to third parties, and predictable fixed compute costs"]}, {"id": "KP3", "description": "Indexing performance and search latency: vector dimensionality directly impacts HNSW graph construction time, RAM usage, and query-time distance calculations.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW memory overhead, distance computation latency, cache line efficiency, AVX-512 SIMD throughput, Matryoshka embeddings", "Calculating dot products for 384 dimensions is ~4x faster per vector comparison than 1536 dimensions", "Matryoshka representation learning allows dynamically truncating embedding dimensions (e.g. 1536 down to 512) to balance recall and RAM footprint"]}], "critical_failures": ["Failing to explain the direct connection between embedding dimensionality, RAM footprint, and search latency", "Ignoring the cost and governance trade-offs between self-hosted open models and managed SaaS APIs", "Failing to cite concrete dimensionality examples (e.g. 384 vs 1536)"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What causes hallucinations in a RAG system, and how do you diagnose and mitigate them using evaluation metrics?', '{"key_points": [{"id": "KP1", "description": "Root causes of hallucinations in RAG systems: retrieval failures (missing or irrelevant chunks), context dilution/noise, conflicting documents, query ambiguity, and weak prompt grounding constraints.", "required": true, "acceptable_evidence": ["Technical keywords: causes of hallucinations, retrieval failure, context dilution, irrelevant chunks, conflicting documentation, query ambiguity, weak prompt constraints", "When retrieval returns irrelevant chunks, the LLM falls back to parametric training memory to fabricate plausible answers", "Retrieving outdated superseded manuals alongside current ones creates conflicting context that confuses the model", "Excessively broad context windows dilute relevant signal with distracting noise (lost-in-the-middle effect)"]}, {"id": "KP2", "description": "Diagnosing hallucinations with evaluation metrics: utilizing the RAG Triad (Context Relevance, Faithfulness, Answer Relevance) and component-level retrieval metrics.", "required": true, "acceptable_evidence": ["Technical keywords: RAG triad, Context Relevance, Faithfulness / Groundedness, Answer Relevance, Hit Rate@K, MRR", "Low Context Relevance identifies the retrieval pipeline as the root cause (retrieving noise)", "High Context Relevance paired with Low Faithfulness isolates the generation prompt or model capability as the root cause (ignoring context)", "Low Answer Relevance indicates model drift or evasive non-answers"]}, {"id": "KP3", "description": "Mitigation strategies: enforcing strict negative prompt grounding, cross-encoder score cutoff thresholds, hybrid search with reranking, and automated NLI verification.", "required": true, "acceptable_evidence": ["Technical keywords: strict negative constraints, relevance score cutoff (<0.40), cross-encoder reranking, NLI entailment scoring, deterministic safe fallback", "Enforces reranker confidence thresholds: if top chunk score is below cutoff, abort generation and serve safe fallback", "Mandates bracketed chunk citations and runs post-generation NLI entailment checks to intercept ungrounded claims"]}], "critical_failures": ["Failing to delineate between retrieval-induced hallucinations and generation-induced hallucinations", "Omitting the diagnostic power of the RAG Triad (Context Relevance vs Faithfulness)", "Lacking concrete mitigation mechanisms (relevance score cutoffs, strict grounding, NLI verification)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What challenges would you expect in scaling such an agent system, and how would you address them at the infrastructure and retrieval levels?', '{"key_points": [{"id": "KP1", "description": "Infrastructure-level scaling challenges and solutions: horizontally scaling API orchestrators on Kubernetes (EKS), managing distributed message queues (SQS/Kafka), and Redis caching.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes HPA, AWS EKS, SQS/Kafka, Redis caching, stateless orchestrators, connection pooling", "Scales agent orchestration pods horizontally based on CPU and request concurrency", "Caches frequent agent query paths, embeddings, and tool responses in Redis to reduce backend load", "Buffers asynchronous tasks in SQS/Kafka to prevent service cascades during traffic spikes"]}, {"id": "KP2", "description": "Retrieval-level scaling challenges and solutions: scaling vector databases via query/data node separation, sharding, partition keys, and index optimization (HNSW/IVFPQ).", "required": true, "acceptable_evidence": ["Technical keywords: vector DB sharding, query/data node decoupling, Milvus cluster, partition keys, HNSW memory footprint, IVFPQ, read replicas", "Decouples stateless query nodes (scale with concurrent QPS) from stateful data nodes (scale with vector volume)", "Uses multi-tenancy partition keys to prune search space to specific customer segments", "Adds vector database read replicas to distribute concurrent ANN search queries"]}, {"id": "KP3", "description": "Agent-specific scaling bottlenecks: managing LLM API provider rate limits (TPM/RPM), multi-region load balancing, recursion guardrails, and state persistence.", "required": true, "acceptable_evidence": ["Technical keywords: LLM rate limits (TPM/RPM), multi-region load balancing, recursion limits, LangGraph checkpointer persistence (Postgres/DynamoDB)", "Distributes LLM requests across multiple cloud regions to prevent hitting provider rate limits", "Enforces strict agent cycle limits (e.g. max_steps=5) to prevent runaway costs and infinite loops", "Persists conversation state in managed distributed databases (RDS/DynamoDB) rather than in-memory storage"]}], "critical_failures": ["Addressing only infrastructure scaling while ignoring retrieval-specific scaling (or vice versa)", "Failing to explain how vector databases scale (query/data separation, partition keys, read replicas)", "Ignoring agent-specific bottlenecks like LLM rate limits and stateful session persistence"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What considerations led you to choose hybrid chunking (semantic + recursive splitting), and how does it impact retrieval performance?', '{"key_points": [{"id": "KP1", "description": "Definition and mechanism of hybrid chunking: combining document structural/semantic boundaries (markdown headers, section splits) with recursive character splitting and token overlap.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid chunking, semantic header splitting, recursive character text splitting, token overlap (10-20%), hierarchical document structure", "First splits documents along high-level semantic boundaries (H1, H2, H3 headers, page sections) to keep logical topics unified", "Recursively applies character/paragraph splitting with sliding window overlap only when a section exceeds target chunk size (e.g. 512 tokens)"]}, {"id": "KP2", "description": "Why hybrid chunking was chosen over naive fixed or pure semantic chunking: avoids arbitrary sentence severance while preventing massive variable-length chunk variance.", "required": true, "acceptable_evidence": ["Technical keywords: naive fixed splitting pitfalls, variable chunk size problem, sentence boundary preservation, predictability", "Fixed-size chunking blindly splits words and sentences, corrupting embeddings and severing procedural instructions", "Pure semantic chunking (embedding distance shifts) produces highly irregular chunk sizes that can exceed context limits or create tiny low-signal chunks", "Hybrid chunking guarantees both semantic integrity and bounded token sizes"]}, {"id": "KP3", "description": "Impact on retrieval performance: significantly improves Hit Rate@K, reduces vector semantic crowding, and preserves complete procedural instructions.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K improvement, dense vector precision, reduced semantic dilution, procedural integrity", "Ensures complete diagnostic procedures and troubleshooting steps remain unified in single chunks", "Produces cleaner vector embeddings that align closely with user search intent, boosting top-k recall"]}], "critical_failures": ["Failing to explain how semantic structure and recursive splitting are combined in hybrid chunking", "Failing to contrast hybrid chunking against pure fixed-size or pure embedding-distance chunking", "Ignoring the impact on retrieval performance and semantic boundary preservation"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What embedding model did you use, and why did you choose not to fine-tune it for your use case?', '{"key_points": [{"id": "KP1", "description": "Selected embedding model and characteristics: deploying Sentence Transformers (all-MiniLM-L6-v2) or BGE-base for dense vector representation.", "required": true, "acceptable_evidence": ["Technical keywords: all-MiniLM-L6-v2 / BGE-base, 384 dimensions, 80MB model size, sub-15ms CPU inference, strong zero-shot retrieval", "Explains choosing MiniLM for high throughput, low CPU/RAM resource requirements, and zero external API dependencies", "Achieves competitive baseline performance on semantic retrieval benchmarks out-of-the-box"]}, {"id": "KP2", "description": "Rationale for not fine-tuning the embedding model: high data collection and annotation costs, risk of catastrophic forgetting, and operational maintenance overhead.", "required": true, "acceptable_evidence": ["Technical keywords: fine-tuning trade-offs, catastrophic forgetting, training data annotation cost, hard negative mining, maintenance overhead", "Fine-tuning embeddings requires thousands of high-quality positive and mined hard-negative (query, passage) pairs, which was cost-prohibitive for initial phases", "Risk of degrading performance on general linguistic queries (catastrophic forgetting)", "Off-the-shelf pre-trained models already provide robust zero-shot generalization across domain text"]}, {"id": "KP3", "description": "Alternative architectural levers prioritized over fine-tuning: hybrid search (BM25 + dense), cross-encoder reranking, and contextual chunking to achieve superior accuracy without model retraining.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval (BM25 + vector), cross-encoder reranking, contextual chunking, metadata pre-filtering", "Achieved higher retrieval gains by adding BM25 for domain-specific acronyms and cross-encoder reranking for precision", "Enriched chunks with structural metadata and breadcrumbs, solving vocabulary mismatch without modifying model weights"]}], "critical_failures": ["Failing to name the specific embedding model used (e.g. all-MiniLM-L6-v2 or BGE)", "Failing to explain the technical and operational reasons against fine-tuning (hard negative mining, annotation cost, catastrophic forgetting)", "Ignoring architectural alternatives that yielded higher ROI than fine-tuning (hybrid search, cross-encoders, contextual chunking)"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What evaluation metrics did you use for retrieval and generation in your RAG system, and how did they help reduce hallucinations?', '{"key_points": [{"id": "KP1", "description": "How retrieval metrics diagnose hallucination risk: low Hit Rate@K and low Context Relevance indicate retrieval is serving irrelevant noise, forcing the LLM to hallucinate.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, Context Relevance, noise injection, retrieval failure diagnostics, hallucination root cause", "If Context Relevance is low, the retrieved passages contain distracting, off-topic tokens that dilute model attention", "Low Hit Rate means the required factual answer is entirely missing from context, making hallucinations almost inevitable without strict refusal prompts"]}, {"id": "KP2", "description": "How generation metrics detect and reduce hallucinations: measuring Faithfulness / Groundedness using sentence-level Natural Language Inference (NLI) entailment.", "required": true, "acceptable_evidence": ["Technical keywords: Faithfulness, Groundedness, NLI entailment scoring, claim decomposition, hallucination rate", "Deconstructs LLM responses into atomic factual claims and verifies whether each claim is entailed by retrieved context", "Tracks the proportion of ungrounded statements; responses scoring below threshold (e.g. < 0.90) are flagged for automated redaction or safe fallback"]}, {"id": "KP3", "description": "Operational closed-loop remediation: using metric feedback to set reranker score cutoffs and enforce explicit out-of-context refusal prompts.", "required": true, "acceptable_evidence": ["Technical keywords: closed-loop remediation, reranker threshold cutoff (<0.40), prompt negative constraints, deterministic safe fallback", "Establishes cross-encoder score thresholds: if top retrieval candidates score below 0.40, abort generation and serve safe canned fallback", "Refines system prompt with negative constraints (''Answer only from context; decline if unavailable'') based on faithfulness test regressions"]}], "critical_failures": ["Failing to explain how retrieval metrics (Context Relevance) directly correlate with hallucination likelihood", "Failing to explain the mechanism of generation Faithfulness metrics (NLI entailment scoring)", "Omitting operational remediation mechanisms (relevance score cutoffs and fallback prompts)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What evaluation metrics would you use to measure the performance of the retriever and overall system, and why?', '{"key_points": [{"id": "KP1", "description": "Retriever performance metrics: evaluating candidate recall and ranking using Hit Rate@K, Mean Reciprocal Rank (MRR), and NDCG@K against gold passage labels.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, MRR (Mean Reciprocal Rank), NDCG@K, Precision@K, Recall@K, gold labeled chunks", "Hit Rate@K verifies whether the ground-truth evidence chunk is captured in the retrieved top-k candidate set", "MRR quantifies the rank position of the first relevant chunk, directly rewarding systems that place correct information first"]}, {"id": "KP2", "description": "Overall end-to-end system metrics: evaluating generation fidelity using Faithfulness / Groundedness, Answer Relevancy, and Context Relevancy (RAG Triad).", "required": true, "acceptable_evidence": ["Technical keywords: Faithfulness / Groundedness, Answer Relevancy, Context Relevancy, RAG Triad, Ragas framework", "Faithfulness checks whether claims in the generated response are strictly entailed by retrieved context (measuring hallucination rate)", "Answer Relevancy evaluates whether the response directly and concisely answers the user query without irrelevant padding"]}, {"id": "KP3", "description": "Operational business and system metrics: tracking Time to First Token (TTFT), p95 latency, cost per interaction, and Average Handling Time (AHT) impact.", "required": true, "acceptable_evidence": ["Technical keywords: TTFT (Time to First Token), p95 latency (<1.5s), cost per query, Average Handling Time (AHT), user satisfaction / CSAT", "Tracks operational performance to ensure the system satisfies real-time production SLAs", "Measures real-world impact on enterprise efficiency (e.g. reducing call handling time or improving first contact resolution)"]}], "critical_failures": ["Failing to separate retriever metrics (MRR, Hit Rate) from end-to-end generation metrics (Faithfulness, Answer Relevancy)", "Ignoring the RAG Triad framework or automated LLM-as-a-judge methodologies", "Failing to explain *why* each metric is chosen and what specific failure mode it detects"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What frameworks did you use for LLM output evaluation (e.g., LLM as a judge, RAGAS, DP well), and how is a ''golden set'' truth data set utilized in this process?', '{"key_points": [{"id": "KP1", "description": "Role of evaluation frameworks: utilizing structured libraries (RAGAS, DeepEval, TruLens) and LLM-as-a-judge to automate scoring across the RAG triad (Faithfulness, Relevance, Recall).", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS, DeepEval, TruLens, LLM-as-a-judge, automated evaluation pipelines, RAG triad", "Orchestrates automated evaluation of (query, context, response, reference) quadruplets using high-capability models (GPT-4 / Claude 3.5 Sonnet)", "Provides standardized scoring formulas bounded between 0.0 and 1.0 for objective comparison"]}, {"id": "KP2", "description": "Construction and curation of the ''Golden Dataset'': creating representative query-context-ground_truth triplets covering common queries, edge cases, and adversarial samples.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset curation, ground-truth reference answers, gold context passages, synthetic testset generation, domain expert review", "Curates 100-300 high-quality test cases with verified human-curated reference answers and source document chunks", "Combines synthetic generation (RAGAS testset generator) with human subject matter expert validation to cover diverse user intents"]}, {"id": "KP3", "description": "Utilization in the evaluation and CI/CD lifecycle: running regression benchmarks against the golden dataset to evaluate prompt changes, embedding models, and chunking parameters.", "required": true, "acceptable_evidence": ["Technical keywords: regression benchmarking, CI/CD quality gate, automated test execution, performance baseline, release criteria", "Executes benchmark test suite before production releases to ensure new prompt or chunking iterations do not regress quality", "Establishes strict pass/fail gates: e.g. Faithfulness >= 0.90 and Context Recall >= 0.85 across the entire golden test suite"]}], "critical_failures": ["Failing to explain what a ''golden dataset'' is and how it is curated (verified reference answers and gold contexts)", "Failing to explain how evaluation frameworks (RAGAS / LLM-as-a-judge) utilize the golden dataset for scoring", "Omitting the role of golden datasets in regression testing and CI/CD quality gates"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What guardrails or validation mechanisms did you implement to reduce hallucinations in agent outputs?', '{"key_points": [{"id": "KP1", "description": "Deterministic input and schema validation guardrails: validating user queries and tool inputs with Pydantic schemas, regex filters, and adversarial jailbreak detection.", "required": true, "acceptable_evidence": ["Technical keywords: input guardrails, Pydantic schema validation, Llama Guard / NeMo Guardrails, regex filters, prompt injection defense", "Validates incoming tool parameters against strict typed schemas to prevent tool invocation hallucinations", "Detects and rejects malicious prompt injections before orchestrator reasoning begins"]}, {"id": "KP2", "description": "Retrieval gating and grounding constraints: enforcing minimum cross-encoder relevance thresholds (<0.40) and explicit out-of-context refusal directives.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval gating, relevance score cutoff, strict grounding constraints, explicit refusal, citation enforcement", "Blocks the generation agent from synthesizing answers when retrieved context is irrelevant or below confidence thresholds", "Mandates verifiable citations for every factual assertion made by the model"]}, {"id": "KP3", "description": "Runtime output verification: implementing Natural Language Inference (NLI) sentence-level entailment scoring and claim verification before displaying responses.", "required": true, "acceptable_evidence": ["Technical keywords: output guardrails, NLI entailment scoring, DeBERTa-v3, claim decomposition, hallucination detector, automated fallback", "Segments agent output into atomic claims and checks entailment against retrieved context", "Replaces ungrounded or contradictory outputs with deterministic, pre-approved safe fallback messages"]}, {"id": "KP4", "description": "Operational agent limits and Human-in-the-Loop (HITL): enforcing recursion caps, execution timeouts, and human approval gates for critical actions.", "required": false, "acceptable_evidence": ["Technical keywords: recursion limit (max_iterations=5), timeout limits, HITL interrupt, human approval gate", "Caps agent graph cycles to prevent runaway execution loops", "Pauses execution to require human supervisor authorization before state-altering actions"]}], "critical_failures": ["Relying solely on system prompt instructions without automated programmatic guardrails", "Failing to explain post-generation verification mechanisms (NLI entailment or claim decomposition)", "Ignoring retrieval score thresholds and fallback mechanisms"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'What is agentic AI, and how did you design and implement multiple agents such as orchestration, RAG-based QA, planner, and policy agents?', '{"key_points": [{"id": "KP1", "description": "Definition of Agentic AI: an autonomous, goal-driven paradigm featuring stateful reasoning, iterative planning, dynamic tool invocation, environment feedback, and self-correction.", "required": true, "acceptable_evidence": ["Technical keywords: Agentic AI definition, autonomous goal execution, stateful reasoning, dynamic tool calling, self-correction, environment feedback", "Contrasts static, linear pipelines (input -> retrieve -> output) with iterative loops that decompose problems, execute tools, evaluate results, and adjust trajectories", "Maintains typed execution state across multi-turn reasoning steps"]}, {"id": "KP2", "description": "Orchestration and Planner agents: analyzing high-level user intent, generating step-by-step execution plans, and dynamically routing tasks to specialized agents.", "required": true, "acceptable_evidence": ["Technical keywords: Orchestration agent, Supervisor, Planner agent, Plan-and-Solve, LangGraph StateGraph, dynamic routing", "Planner decomposes complex requests into an ordered sequence of executable sub-tasks", "Supervisor inspects intermediate outputs and decides whether to proceed, backtrack, or delegate to another agent"]}, {"id": "KP3", "description": "RAG-based QA and Policy/Compliance agents: specialized agents dedicated to knowledge retrieval and enterprise policy enforcement.", "required": true, "acceptable_evidence": ["Technical keywords: RAG QA agent, Policy agent, Guardrail agent, compliance validation, role separation, domain knowledge retrieval", "RAG QA agent executes query rewriting, hybrid search, and synthesized answers grounded strictly in retrieved documentation", "Policy agent verifies outputs against regulatory rules, safety constraints, and enterprise standard operating procedures before user delivery"]}, {"id": "KP4", "description": "Inter-agent communication and state management: utilizing LangGraph shared state schemas, message passing, and recursion limits to ensure stability.", "required": false, "acceptable_evidence": ["Technical keywords: inter-agent communication, shared state schema, message passing, recursion limits (max_steps=5), LangGraph checkpointers", "Agents communicate by reading and updating a centralized state object rather than unconstrained point-to-point text chats", "Enforces hard recursion limits to prevent cyclic ping-pong loops between agents"]}], "critical_failures": ["Failing to define Agentic AI beyond standard prompt engineering or simple chatbots", "Failing to delineate the specific roles and interactions of the requested agent types (Orchestration, Planner, RAG QA, Policy)", "Omitting state management, structured communication, and recursion safeguards"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What is the difference between retrieval and sourcing nodes in your proposed system design, and when would each be used?', '{"key_points": [{"id": "KP1", "description": "Definition and role of Retrieval Nodes: executing low-latency similarity search against pre-indexed static knowledge stores (vector databases, BM25 indices).", "required": true, "acceptable_evidence": ["Technical keywords: retrieval nodes, pre-indexed vector store, Milvus/Pinecone, BM25, semantic similarity, cached embeddings, sub-50ms search", "Retrieves existing, pre-computed document chunks and metadata based on query vector alignment", "Used for fast, deterministic lookup of established enterprise documentation, manuals, and FAQs"]}, {"id": "KP2", "description": "Definition and role of Sourcing Nodes: dynamically fetching live, real-time, or external data directly from live systems (APIs, web scrapers, database queries, ticketing systems).", "required": true, "acceptable_evidence": ["Technical keywords: sourcing nodes, live data fetching, external APIs, transactional SQL queries, web scraping, real-time telemetry", "Executes on-demand external calls to obtain dynamic, ephemeral, or volatile data not present in static vector indexes", "Used for retrieving live vehicle battery telemetry, real-time inventory levels, current order status, or live calendar availability"]}, {"id": "KP3", "description": "Architectural decision criteria and use cases: routing between retrieval and sourcing based on data volatility, latency requirements, and system overhead.", "required": true, "acceptable_evidence": ["Technical keywords: decision criteria, data volatility, static vs dynamic data, latency budget, API rate limits, hybrid integration", "Retrieval nodes are prioritized for high-speed, cost-effective access to static knowledge manuals (<50ms)", "Sourcing nodes are triggered when information must be up-to-the-second accurate or involves user-specific transactional records", "Supervisor agents often combine both: sourcing live customer records and retrieving matching diagnostic manual sections"]}, {"id": "KP4", "description": "Failure modes, caching, and resilience: handling API rate limits, timeouts, and staleness across both node types.", "required": false, "acceptable_evidence": ["Technical keywords: resilience, circuit breakers, timeout fallback, Redis caching, exponential backoff", "Applies circuit breakers and short-lived caching on sourcing nodes to protect downstream enterprise APIs", "Falls back to cached retrieval nodes if live sourcing endpoints experience transient outages"]}], "critical_failures": ["Failing to clearly distinguish between pre-indexed static Retrieval nodes and real-time live Sourcing nodes", "Failing to provide concrete use cases for when each node type is appropriate", "Ignoring data volatility and latency considerations in node selection"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What metrics are used to evaluate retrieval performance, and how do precision, recall, and MRR differ?', '{"key_points": [{"id": "KP1", "description": "Precision@K in retrieval: measuring the proportion of retrieved documents in the top-K results that are relevant to the query.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K, relevant retrieved documents / K, signal-to-noise ratio, top-K purity, context window economy", "Formula: Precision@K = (Number of relevant items in top-K) / K", "Indicates how clean the retrieved context is; low precision means the LLM context is flooded with distracting, irrelevant chunks"]}, {"id": "KP2", "description": "Recall@K in retrieval: measuring the proportion of all relevant documents existing in the corpus that were successfully captured in the top-K results.", "required": true, "acceptable_evidence": ["Technical keywords: Recall@K, relevant retrieved / total relevant in corpus, candidate coverage, false negative minimization", "Formula: Recall@K = (Number of relevant items in top-K) / (Total relevant items in corpus)", "Indicates whether critical information was missed; low recall causes incomplete answers or hallucinations due to missing context"]}, {"id": "KP3", "description": "Mean Reciprocal Rank (MRR): measuring the reciprocal rank of the first relevant document retrieved, averaged across all queries.", "required": true, "acceptable_evidence": ["Technical keywords: Mean Reciprocal Rank (MRR), formula: (1/|Q|) * sum(1 / rank_i), first relevant item, top-1 ranking quality", "Focuses exclusively on how high the single best relevant document is placed (rank 1 = 1.0, rank 2 = 0.5, rank 3 = 0.33)", "Critical for search and Q&A systems where the user or LLM relies heavily on the first result"]}, {"id": "KP4", "description": "Comparative differences and complementary usage: contrasting trade-offs between precision, recall, and rank-aware metrics (MRR / NDCG).", "required": false, "acceptable_evidence": ["Technical keywords: trade-offs, precision-recall curve, rank awareness, NDCG comparison, golden test dataset", "Precision and recall do not penalize order among the top-K, whereas MRR is strictly rank-sensitive", "High Recall@50 is essential for first-stage candidate retrieval, while high Precision@3 and high MRR are essential for the final reranked context"]}], "critical_failures": ["Failing to provide exact definitions or formulas for Precision@K, Recall@K, and MRR", "Confusing Precision (relevance of retrieved items) with Recall (coverage of all relevant items)", "Failing to explain how MRR incorporates ranking order while Precision and Recall treat top-K as an unranked set"]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What specific technical stack did you utilize for the RAG chatbot''s full-stack implementation, covering the front-end (React), back-end (FastAPI), and deployment environment (AWS EKS)?', '{"key_points": [{"id": "KP1", "description": "Front-end architecture with React: modern single-page application using React, TypeScript, TailwindCSS, and Server-Sent Events (SSE) streaming for real-time token rendering.", "required": true, "acceptable_evidence": ["Technical keywords: React, TypeScript, TailwindCSS, Server-Sent Events (SSE), EventSource / fetch stream, real-time token rendering", "Renders streaming token responses to minimize perceived Time-to-First-Token (TTFT)", "Displays interactive source citation popovers, conversation session history, and thumbs-up/down feedback controls"]}, {"id": "KP2", "description": "Back-end architecture with FastAPI: asynchronous Python REST API handling request validation (Pydantic), streaming endpoints, JWT authentication, and orchestration.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, Python, Pydantic v2, async/await, StreamingResponse, JWT authentication, CORS middleware", "Implements POST /v1/chat with StreamingResponse yielding SSE chunks directly from the LLM", "Orchestrates hybrid retrieval, cross-encoder reranking, and Bedrock/OpenAI model invocations asynchronously"]}, {"id": "KP3", "description": "Deployment environment on AWS EKS: containerized microservices managed via Docker, Helm charts, Kubernetes deployments, and ingress controllers.", "required": true, "acceptable_evidence": ["Technical keywords: AWS EKS, Docker containers, Helm charts, Horizontal Pod Autoscaler (HPA), AWS ALB Ingress Controller, IAM Roles for Service Accounts (IRSA)", "Deploys front-end Nginx container and back-end FastAPI containers into distinct Kubernetes pods", "Configures HPA to scale FastAPI pods based on CPU utilization and request concurrency"]}, {"id": "KP4", "description": "Supporting infrastructure and data layer: Milvus/Pinecone for vector search, Amazon RDS PostgreSQL for conversation history, and Amazon ElastiCache Redis for caching.", "required": false, "acceptable_evidence": ["Technical keywords: Milvus, Amazon RDS PostgreSQL, Amazon ElastiCache Redis, AWS PrivateLink, CloudWatch observability", "Maintains sub-50ms vector similarity lookup and stores user chat sessions in RDS", "Caches frequent queries in Redis to bypass vector search and LLM calls"]}], "critical_failures": ["Failing to cover all three specified layers: React front-end, FastAPI back-end, and AWS EKS deployment", "Ignoring streaming communication (SSE / StreamingResponse) between FastAPI and React", "Failing to explain containerization and orchestration details on Kubernetes/EKS"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What techniques did you use for chunking, embedding, and indexing data to optimize retrieval performance?', '{"key_points": [{"id": "KP1", "description": "Optimized chunking techniques: applying layout-aware recursive chunking with 10-20% token overlap and contextual breadcrumb prepending.", "required": true, "acceptable_evidence": ["Technical keywords: recursive chunking, chunk size (512 tokens), overlap (50 tokens), contextual breadcrumb prepending, layout-aware parsing (Docling)", "Splits documents along structural markdown boundaries (headers, paragraphs) to avoid breaking sentences or procedural steps", "Prepends document title and section hierarchy to ensure standalone chunks retain semantic context during embedding"]}, {"id": "KP2", "description": "Optimized embedding techniques: selecting domain-adapted sentence transformer models (e.g. all-MiniLM-L6-v2 or BGE) with L2 normalization.", "required": true, "acceptable_evidence": ["Technical keywords: Sentence Transformers, all-MiniLM-L6-v2 / BGE-base, 384 dimensions, L2 normalization, batch inference", "Normalizes embedding vectors so inner product calculations equal cosine similarity", "Batches embedding generation to saturate CPU/GPU compute during ingestion"]}, {"id": "KP3", "description": "Optimized vector indexing techniques: configuring graph-based (HNSW) indexes with tuned M and efConstruction parameters alongside scalar metadata indexes.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW indexing, M parameter (16-32), efConstruction (100-200), efSearch tuning (64), scalar indexing, Milvus / Pinecone", "Tunes HNSW graph connectivity for optimal balance of search latency (<20ms) and high recall (>95%)", "Creates scalar indexes on metadata fields (e.g. tenant_id, category, year) for high-speed pre-filtering"]}], "critical_failures": ["Failing to cover all three requested stages: chunking, embedding, and indexing", "Relying on naive fixed-token chunking without overlap or context preservation", "Failing to specify concrete indexing parameters (e.g. HNSW M, efConstruction, efSearch)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs did you consider when balancing semantic retrieval accuracy versus system performance and latency?', '{"key_points": [{"id": "KP1", "description": "Core trade-off dimensions: balancing retrieval recall and precision against end-to-end query latency, infrastructure cost, and memory consumption.", "required": true, "acceptable_evidence": ["Technical keywords: accuracy vs latency trade-off, Recall vs QPS, memory footprint (RAM), compute cost, SLA budget (<1.5s total)", "Higher accuracy mechanisms (large embedding models, heavy rerankers, extensive graph traversals) add substantial compute time and financial cost", "Production systems must enforce a strict latency budget across retrieval (sub-100ms) to leave headroom for LLM generation"]}, {"id": "KP2", "description": "Vector indexing trade-offs: exact IndexFlat (100% recall, high latency, O(N) compute) versus Approximate Nearest Neighbor (ANN) HNSW/IVF (sub-10ms, >95% recall, higher RAM overhead).", "required": true, "acceptable_evidence": ["Technical keywords: IndexFlat vs HNSW vs IVF_FLAT, Product Quantization (PQ), memory overhead, efSearch tuning", "Exact search is computationally impossible at scale; ANN trades a slight recall drop (e.g. 2-4%) for a 100x speedup", "Tuning efSearch allows dynamic control over latency versus recall depending on traffic load"]}, {"id": "KP3", "description": "Multi-stage pipeline trade-offs: adding cross-encoder rerankers improves Hit Rate significantly (+15-25%) but adds 30-80ms of inference latency.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval, cross-encoder reranking latency, candidate pool size pruning (50 -> 25), INT8 quantization", "Balancing reranker pool size: sending 100 chunks gives slightly better recall but quadruples reranking latency; capping at 20-30 chunks achieves optimal Pareto efficiency", "Quantizing reranker models to INT8 recovers latency with negligible accuracy loss"]}, {"id": "KP4", "description": "Embedding model dimensionality trade-offs: 384-dim (fast, low memory, CPU-friendly) versus 1536-dim (richer semantics, 4x memory footprint, slower search).", "required": false, "acceptable_evidence": ["Technical keywords: 384 vs 1536 dimensions, Matryoshka embeddings, vector RAM caching, hardware throughput", "Smaller embeddings drastically lower RAM requirements and allow caching larger portions of the index in memory", "Matryoshka embeddings provide flexibility to truncate vector dimensions dynamically"]}], "critical_failures": ["Treating retrieval as a zero-sum problem without articulating specific Pareto-optimal architectural levers", "Failing to explain the latency impact of cross-encoder rerankers and candidate pool sizing", "Ignoring indexing trade-offs (exact vs ANN) and embedding dimensionality"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What types of data sources and formats have you handled in RAG pipelines, and how did you preprocess and extract structured information from them?', '{"key_points": [{"id": "KP1", "description": "Heterogeneous enterprise data sources: ingesting complex PDF technical manuals, scanned documents, customer service tickets/transcripts, HTML articles, and structured CSV/Excel files.", "required": true, "acceptable_evidence": ["Technical keywords: heterogeneous formats, PDF manuals, scanned documents, CRM tickets, HTML/Markdown articles, spreadsheets (CSV/Excel)", "Handles technical manuals with complex diagrams, callouts, and multi-column layouts", "Ingests customer call transcripts and chat logs with conversational noise and slang"]}, {"id": "KP2", "description": "Layout-aware parsing and extraction: utilizing vision/layout parsers (Docling, TableFormer, AWS Textract, Unstructured) to extract text, tables, and document hierarchies.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, TableFormer, AWS Textract, Unstructured, layout-aware parsing, bounding-box detection, OCR", "Reconstructs reading order across multi-column pages rather than concatenating text blindly", "Extracts structural document hierarchy (H1, H2, H3 headers) to preserve contextual section boundaries"]}, {"id": "KP3", "description": "Structured table serialization and extraction: converting complex tabular data into Markdown, HTML tables, or JSON key-value records with summary embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: table serialization, Markdown tables, HTML tables, JSON key-value, table summary embedding, row-level chunking", "Preserves row-column relationships and header associations so LLMs and search engines can parse numerical specifications accurately", "Generates dual representations: textual summary for dense vector retrieval paired with the full structured table for LLM context"]}, {"id": "KP4", "description": "Automated metadata tagging and entity enrichment: extracting structured entities (VIN, model, component, error codes, dates) into metadata payloads.", "required": true, "acceptable_evidence": ["Technical keywords: metadata enrichment, Named Entity Recognition (NER), regex extraction, scalar payload tagging, document versioning", "Extracts diagnostic trouble codes (DTCs), vehicle model years, and system components into discrete filterable metadata fields", "Stores metadata alongside chunks in the vector database to enable precise scalar pre-filtering"]}], "critical_failures": ["Failing to address table extraction and serialization from technical documents", "Relying on naive plain-text extraction that corrupts multi-column layouts and tables", "Omitting metadata enrichment and entity extraction during preprocessing"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'When retrieval performance is poor for certain queries, how would you debug and improve the system?', '{"key_points": [{"id": "KP1", "description": "Query-level retrieval failure analysis: categorizing root causes into vocabulary mismatch, out-of-vocabulary acronyms, overly restrictive metadata filters, and semantic drift.", "required": true, "acceptable_evidence": ["Technical keywords: failure root cause analysis, vocabulary mismatch, out-of-vocabulary acronyms/part numbers, scalar filter over-pruning, semantic distance", "Analyzes failing queries where similarity scores are low or top-k chunks are irrelevant", "Identifies whether user query was too colloquial, contained exact error codes missed by dense embeddings, or was filtered out by metadata rules"]}, {"id": "KP2", "description": "Targeted retrieval-level fixes: deploying query expansion/rewriting, implementing hybrid search (BM25 + vector), and tuning ANN search parameters (HNSW efSearch).", "required": true, "acceptable_evidence": ["Technical keywords: query rewriting / HyDE, hybrid search (BM25), HNSW efSearch tuning, Reciprocal Rank Fusion (RRF)", "Adds LLM query rewriting to expand vague user queries into technical terminology before retrieval", "Activates BM25 keyword search to reliably catch exact diagnostic error codes and part numbers", "Increases efSearch at query time to expand search graph exploration and improve recall on hard queries"]}, {"id": "KP3", "description": "Knowledge base and chunking fixes: repairing fragmented chunks, prepending contextual breadcrumbs, and enriching missing knowledge articles.", "required": true, "acceptable_evidence": ["Technical keywords: chunking boundary fix, contextual breadcrumb prepending, knowledge base enrichment, parent-child indexing", "If chunks were severed across critical procedures, re-chunks with layout-aware markdown splitters and overlap", "Identifies true documentation blind spots and notifies content teams to draft missing technical service bulletins"]}], "critical_failures": ["Suggesting changing LLM prompts when the failure is specifically within the retrieval stage", "Failing to diagnose concrete retrieval failure modes (vocabulary mismatch, exact code lookup failures, filter over-pruning)", "Lacking practical remediation techniques (hybrid BM25, query rewriting, HNSW efSearch tuning, re-chunking)"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Where do you expect bottlenecks in a RAG system, and how would you optimize them?', '{"key_points": [{"id": "KP1", "description": "Bottleneck 1 - LLM generation latency and Time-to-First-Token (TTFT): model autoregression represents 70-80% of total response time; optimize via token streaming (SSE) and smaller distilled models.", "required": true, "acceptable_evidence": ["Technical keywords: LLM generation bottleneck, TTFT (Time-to-First-Token), autoregressive generation, Server-Sent Events (SSE) streaming, model distillation (Claude 3 Haiku / GPT-4o-mini)", "Streams tokens immediately to the UI to drop perceived user wait time from 2.5s down to 400ms", "Uses faster, lighter models for conversational synthesis while reserving frontier models for complex multi-step reasoning"]}, {"id": "KP2", "description": "Bottleneck 2 - Cross-encoder reranking compute: joint cross-attention over large candidate sets adds significant CPU/GPU latency; optimize via pool pruning (top-25) and INT8 quantization.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder bottleneck, candidate pool pruning (50 -> 25), ONNX Runtime, TensorRT, INT8/FP16 quantization, speculative reranking", "Pruning candidate pool size from 50 to 25 cuts reranking latency in half", "Deploys ONNX Runtime with INT8 quantization to accelerate cross-encoder inference to sub-25ms"]}, {"id": "KP3", "description": "Bottleneck 3 - Repeated queries and retrieval overhead: redundant vector searches and LLM calls for popular questions; optimize via Redis semantic caching.", "required": true, "acceptable_evidence": ["Technical keywords: Redis semantic caching, embedding cache, query-response cache, cache hit ratio, sub-20ms response", "Caches high-frequency query embeddings and synthesized answers in Redis", "Returns cached answers instantly (sub-20ms) for identical or semantically identical queries, bypassing retrieval and LLM costs entirely"]}, {"id": "KP4", "description": "Bottleneck 4 - Concurrent vector database throughput: HNSW graph traversal saturation under concurrent load; optimize via read replicas, partition pruning, and async I/O.", "required": false, "acceptable_evidence": ["Technical keywords: vector DB concurrency, HNSW CPU saturation, read replicas, partition key pruning, asyncio.gather()", "Adds stateless query node read replicas to distribute concurrent search requests", "Executes BM25 and vector similarity queries concurrently using asynchronous non-blocking I/O"]}], "critical_failures": ["Failing to identify the primary latency bottleneck (LLM autoregressive generation and TTFT)", "Ignoring reranker latency and candidate pool pruning", "Failing to mention caching (Redis) or token streaming as fundamental latency optimizations"]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose a distilled open-source embedding model over proprietary alternatives, and what trade-offs did you consider?', '{"key_points": [{"id": "KP1", "description": "Data privacy, security, and VPC compliance: open-source distilled models (e.g. all-MiniLM-L6-v2 / BGE) can be deployed fully inside private enterprise VPCs with zero data egress.", "required": true, "acceptable_evidence": ["Technical keywords: data privacy, private VPC deployment, zero data egress, HIPAA / SOC2 compliance, no third-party vendor logging", "Prevents sensitive enterprise intellectual property and confidential customer queries from being transmitted across public APIs", "Eliminates risk of proprietary data exposure to external model providers"]}, {"id": "KP2", "description": "Cost economics and rate-limit immunity: open-source models eliminate per-token API charges during massive ingestion and are immune to API provider throttling (TPM/RPM).", "required": true, "acceptable_evidence": ["Technical keywords: zero per-token cost, high-volume ingestion economics, no API rate limits (TPM/RPM), fixed compute cost, CPU inference", "Embedding millions of document chunks incurs zero incremental API cost when running on existing CPU/GPU compute", "Eliminates 429 Too Many Requests errors and network jitter during peak ingestion pipelines"]}, {"id": "KP3", "description": "Latency, throughput, and hardware efficiency: distilled models feature compact dimensionality (384 dims) and small model weights (<100MB), achieving sub-15ms CPU inference.", "required": true, "acceptable_evidence": ["Technical keywords: distilled model efficiency, 384 dimensions, sub-15ms latency, lightweight RAM footprint, CPU-friendly", "384-dimensional embeddings reduce vector database RAM usage and index construction time by 75% compared to 1536-dimensional models", "Can be served on standard CPU worker pods without requiring expensive dedicated GPU clusters"]}, {"id": "KP4", "description": "Trade-offs and limitations accepted: slightly lower zero-shot MTEB benchmark performance and shorter context window limits compared to frontier commercial models.", "required": false, "acceptable_evidence": ["Technical keywords: trade-offs, MTEB benchmark delta, maximum sequence length (512 tokens), hybrid search compensation", "Accepts shorter token input limits (typically 512 tokens) and slightly lower zero-shot recall on broad open-domain knowledge", "Compensates for the marginal semantic gap by implementing BM25 hybrid search and cross-encoder reranking"]}], "critical_failures": ["Failing to mention data privacy and VPC compliance advantages of self-hosted open-source models", "Ignoring the economic differences (per-token API costs vs fixed infrastructure) and rate-limit immunity", "Failing to explain how compact dimensionality (384 dims) impacts vector DB RAM and search latency"]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'Why did you design your RAG system as stateless, and what are the trade-offs of this decision?', '{"key_points": [{"id": "KP1", "description": "Stateless system design: API servers and orchestrator pods hold no in-memory session state between requests; all necessary state (conversation history, user identity) is passed in the request or stored in external distributed stores.", "required": true, "acceptable_evidence": ["Technical keywords: stateless architecture, shared-nothing architecture, externalized state, Redis / RDS persistence, ephemeral pods", "Any API server instance can handle any incoming user request without requiring sticky sessions", "Session history and conversation context are fetched from Redis or passed in the request payload"]}, {"id": "KP2", "description": "Advantages of statelessness: seamless horizontal scalability, zero-downtime rolling deployments, high fault tolerance, and simplified load balancing.", "required": true, "acceptable_evidence": ["Technical keywords: horizontal autoscaling (HPA), load balancing, fault tolerance, zero-downtime rolling updates, pod restart resilience", "Kubernetes can spin up or terminate API pods dynamically based on traffic spikes without dropping active user sessions", "Pod crashes or rolling updates do not corrupt or lose active conversation state"]}, {"id": "KP3", "description": "Trade-offs and overhead of statelessness: network latency for external state retrieval, serialization/deserialization compute, and distributed cache dependency.", "required": true, "acceptable_evidence": ["Technical keywords: trade-offs, state retrieval latency (5-15ms), Redis roundtrip, JSON serialization overhead, external storage dependency", "Each request incurs a small latency penalty to fetch conversation history from Redis or database", "Introduces operational dependency on distributed caching infrastructure (Redis/Postgres) which requires high availability"]}], "critical_failures": ["Confusing stateless API architecture with a chatbot that has no conversational memory (failing to understand externalized state)", "Failing to articulate the scalability and deployment benefits of statelessness on Kubernetes", "Ignoring the latency and infrastructure trade-offs of external state retrieval"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Are you of the belief that data architecture and AI principles are the same regardless of the industry you''re working in?', '{"key_points": [{"id": "KP1", "description": "Universal core architectural principles: foundational AI and data engineering principles (decoupling compute and storage, idempotent ETL, indexing strategies, evaluation rigor, layered guardrails) are consistent across all industries.", "required": true, "acceptable_evidence": ["Technical keywords: universal principles, decoupling compute/storage, idempotency, vector indexing, evaluation frameworks, layered guardrails", "Core patterns like two-stage retrieval (BM25 + vector + rerank), async ingestion, and microservices apply equally to finance, healthcare, automotive, or retail", "Mathematical properties of embeddings and similarity metrics do not change based on industry"]}, {"id": "KP2", "description": "Industry-specific regulatory, compliance, and governance divergence: distinct industries impose radically different constraints regarding data residency, auditability, PII/PHI handling, and liability.", "required": true, "acceptable_evidence": ["Technical keywords: regulatory compliance, HIPAA (healthcare), FINRA/SEC (finance), automotive safety (ISO 26262), GDPR, data residency, auditability", "Healthcare mandates strict HIPAA de-identification (18 Safe Harbor identifiers) and signed Business Associate Agreements (BAAs)", "Finance requires explainability, deterministic decision audit trails, and strict anti-bias verification", "Consumer tech prioritizes low latency and engagement over strict regulatory certification"]}, {"id": "KP3", "description": "Domain data characteristics and ontology differences: variation in document structures, jargon density, error tolerance, and Human-in-the-Loop thresholds.", "required": true, "acceptable_evidence": ["Technical keywords: domain ontologies, error tolerance, failure consequences, Human-in-the-Loop (HITL) thresholds, jargon density", "In safety-critical or clinical domains, hallucination tolerance is virtually zero, necessitating mandatory human review", "Domain vocabularies (e.g. medical terminology vs automotive wiring schematics) dictate specialized layout parsers and fine-tuned embeddings"]}], "critical_failures": ["Taking an absolute position (claiming everything is identical OR completely different) without nuanced architectural vs regulatory analysis", "Failing to mention specific regulatory frameworks (HIPAA, FINRA, GDPR)", "Ignoring domain-specific error tolerances and Human-in-the-Loop requirements"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe a generative AI application you built end-to-end, including architecture, tools, and evaluation approach?', '{"key_points": [{"id": "KP1", "description": "End-to-end application architecture: designing a production enterprise generative AI assistant (e.g. EV Call Center Diagnostic Assistant) with decoupled ingestion, low-latency API orchestration, and vector search.", "required": true, "acceptable_evidence": ["Technical keywords: enterprise GenAI application, EV customer support assistant, microservices architecture, ingestion worker, FastAPI, AWS EKS", "Articulates the business problem solved (e.g. reducing customer call handling time and improving first contact resolution)", "Decouples offline document processing from online real-time user query serving"]}, {"id": "KP2", "description": "Technical toolchain and infrastructure: integrating Docling for layout parsing, Sentence Transformers (MiniLM) for embeddings, Milvus for vector indexing, LangGraph for orchestration, and Bedrock (Claude 3.5 Sonnet) for generation.", "required": true, "acceptable_evidence": ["Technical keywords: Docling / Unstructured, Sentence Transformers / BGE, Milvus vector database, LangGraph / FastAPI, AWS Bedrock (Claude 3.5 Sonnet), Redis cache", "Uses Docling to parse complex technical PDF manuals and extract Markdown tables cleanly", "Orchestrates hybrid retrieval (BM25 + vector) and cross-encoder reranking (BGE-Reranker) before model synthesis"]}, {"id": "KP3", "description": "Evaluation methodology and production metrics: assessing retrieval (Hit Rate, MRR) and generation (Ragas Faithfulness, Answer Relevancy) against a golden benchmark dataset.", "required": true, "acceptable_evidence": ["Technical keywords: golden benchmark dataset, Ragas framework, Faithfulness (>0.90), Answer Relevancy, Hit Rate@5 (>0.85), p95 latency (<1.5s)", "Curated 150-200 ground-truth QA triplets to run automated regression testing in CI/CD pipelines", "Demonstrates tangible business outcomes: reducing Average Handling Time (AHT) from 10 minutes to 6.5 minutes and boosting FCR to 84%"]}, {"id": "KP4", "description": "Production guardrails and safety controls: implementing PII redaction (Microsoft Presidio), prompt injection filtering, and Natural Language Inference (NLI) entailment validation.", "required": false, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, Llama Guard, NLI entailment scoring, fallback mechanism, human escalation", "Sanitizes customer personal details prior to embedding storage", "Validates generated claims against context to ensure zero ungrounded advice reaches customers"]}], "critical_failures": ["Describing a superficial tutorial project instead of a production-grade enterprise application", "Failing to specify concrete tools across parsing, embedding, vector DB, orchestration, and model inference", "Omitting quantitative evaluation metrics (Faithfulness, Hit Rate) and business impact"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your approach to rapidly building and iterating on AI-driven proof-of-concepts in a fast feedback environment?', '{"key_points": [{"id": "KP1", "description": "Fast-feedback POC methodology: adopting an agile, hypothesis-driven iteration cycle starting with a minimal baseline, synthetic golden datasets, and rapid automated benchmarking.", "required": true, "acceptable_evidence": ["Technical keywords: hypothesis-driven development, minimal viable POC, golden benchmark dataset, rapid iteration cycle, fast feedback loop", "Curates a focused subset of high-priority documents and 50-100 representative queries to establish a day-one quantitative baseline", "Validates feasibility on real enterprise queries before committing to large-scale infrastructure engineering"]}, {"id": "KP2", "description": "Lightweight modular prototyping stack: leveraging managed or embedded tools (ChromaDB / PGVector, Streamlit / Chainlit, lightweight LLM APIs) to eliminate initial DevOps drag.", "required": true, "acceptable_evidence": ["Technical keywords: modular prototyping, ChromaDB / PGVector, Streamlit / Chainlit UI, LangChain / LangGraph, managed LLM APIs", "Builds interactive UI mockups in Streamlit to put live prototypes in front of business stakeholders within days", "Uses modular code structures allowing swapping embedding models or vector databases without refactoring business logic"]}, {"id": "KP3", "description": "Automated evaluation and stakeholder feedback loops: running automated RAG evaluations (Ragas / DeepEval) paired with structured qualitative review sessions.", "required": true, "acceptable_evidence": ["Technical keywords: automated evaluation (Ragas), Faithfulness scoring, stakeholder review, error tagging, iterative refinement", "Tags retrieval and generation failure modes during weekly stakeholder review sessions", "Uses automated test runs to verify that fixes for edge cases do not cause regressions across the broader test suite"]}, {"id": "KP4", "description": "Graduation criteria from POC to production: defining clear quantitative gates (Faithfulness > 0.90, Hit Rate > 0.85, latency < 1.5s) before transitioning to Kubernetes microservices.", "required": false, "acceptable_evidence": ["Technical keywords: graduation criteria, production readiness gates, SLA benchmarks, architectural hardening", "Establishes explicit go/no-go quality and latency thresholds", "Hardens prototype with enterprise security, distributed vector stores, and CI/CD only after the business value is proven"]}], "critical_failures": ["Focusing solely on writing code without establishing feedback loops or golden test datasets", "Failing to balance rapid prototyping tools (Streamlit, Chroma) with modular design for eventual production scaling", "Omitting explicit graduation criteria or quantitative evaluation benchmarks"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain the architecture of Apache Spark, including the roles of the Driver, Executors, and Cluster Manager?', '{"key_points": [{"id": "KP1", "description": "Role of the Driver: the central coordinator that runs the application''s main() method, creates the SparkSession, converts code into a Directed Acyclic Graph (DAG) of stages, and schedules tasks.", "required": true, "acceptable_evidence": ["Technical keywords: Spark Driver, main() method, SparkSession / SparkContext, DAG creation, DAGScheduler, TaskScheduler, central coordinator", "Translates user transformations and actions into an execution plan of stages and tasks", "Coordinates task scheduling across worker nodes and collects final results back to the driver"]}, {"id": "KP2", "description": "Role of the Executors: distributed worker processes running on cluster nodes responsible for executing individual tasks, storing cached RDD/DataFrame partitions in memory/disk, and returning results.", "required": true, "acceptable_evidence": ["Technical keywords: Spark Executors, worker processes, task execution, in-memory computation, partition caching, block manager", "Executes task pipelines assigned by the driver on local data partitions", "Manages in-memory storage and caching for persisted datasets, handling shuffle write and read operations"]}, {"id": "KP3", "description": "Role of the Cluster Manager: external resource allocator (Kubernetes, YARN, Mesos, or Spark Standalone) responsible for acquiring cluster resources, spawning executor processes, and managing hardware node health.", "required": true, "acceptable_evidence": ["Technical keywords: Cluster Manager, Kubernetes, YARN, Standalone, resource allocation, CPU/memory scheduling, executor lifecycle", "Allocates cluster CPU and memory resources to the Spark application", "Provisions executor pods/containers on worker nodes and replaces failed nodes automatically"]}, {"id": "KP4", "description": "End-to-end execution workflow and distributed mechanics: Driver submits job -> Cluster Manager provisions Executors -> Driver schedules DAG tasks -> Executors process partitions and perform shuffles.", "required": false, "acceptable_evidence": ["Technical keywords: DAG execution, stages and tasks, shuffle boundaries, wide vs narrow transformations, fault tolerance", "Explains how narrow transformations (map/filter) execute within tasks while wide transformations (groupBy/join) require shuffles across executors", "Driver reconstructs lost partitions automatically using RDD lineage if an executor crashes"]}], "critical_failures": ["Failing to clearly articulate the distinct responsibilities of Driver, Executors, and Cluster Manager", "Confusing the Driver with the Cluster Manager (Driver coordinates tasks; Cluster Manager allocates compute resources)", "Omitting the concepts of DAG creation, task scheduling, or distributed data partitioning"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain your experience working with graph databases, including how you modeled relationships and structured the data?', '{"key_points": [{"id": "KP1", "description": "Graph data modeling principles: designing Property Graphs consisting of labeled Nodes (entities), directed Relationships (edges), and key-value Properties on both nodes and edges.", "required": true, "acceptable_evidence": ["Technical keywords: Property Graph model, Nodes, Relationships (edges), Labels, Properties, directionality", "Models real-world domain entities as nodes (e.g. (:VehicleModel), (:Component), (:FaultCode), (:Document))", "Models interactions as typed directed relationships (e.g. [:HAS_COMPONENT], [:TRIGGERS], [:REFERENCED_IN]) with properties like confidence or timestamp"]}, {"id": "KP2", "description": "Structuring complex domain ontologies: organizing hierarchical part-assembly structures, symptom-to-cause mappings, and multi-hop relationship traversal.", "required": true, "acceptable_evidence": ["Technical keywords: domain ontology, part-assembly hierarchy, diagnostic ontology, multi-hop traversal, entity resolution", "Structures automotive domain knowledge: (:Model)-[:HAS_SYSTEM]->(:Subsystem)-[:CONTAINS]->(:Part)", "Maps diagnostic error codes directly to historical failure root causes and repair runbooks for multi-hop graph traversal"]}, {"id": "KP3", "description": "Graph database implementation and integration: leveraging Neo4j / Amazon Neptune, executing index-free adjacency traversals, and combining graph queries with vector retrieval (GraphRAG).", "required": true, "acceptable_evidence": ["Technical keywords: Neo4j, Amazon Neptune, index-free adjacency, Cypher query, GraphRAG, hybrid graph + vector retrieval", "Leverages index-free adjacency where traversing relationships is O(1) per step regardless of overall database size", "Fuses graph traversal with vector search: vector search finds candidate seed nodes, and graph traversal extracts connected 1-2 hop neighborhood context"]}], "critical_failures": ["Failing to define property graph fundamentals (Nodes, Relationships, Properties, Labels)", "Lacking concrete domain modeling examples (e.g. vehicle components, error codes, part hierarchies)", "Failing to explain how graph structures enhance retrieval (index-free adjacency, multi-hop traversals, GraphRAG)"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you talk to me about your experience building and integrating REST APIs?', '{"key_points": [{"id": "KP1", "description": "REST API design principles and HTTP standards: designing resource-oriented endpoints, standard HTTP verbs (GET, POST, PUT, DELETE), status codes (200, 201, 400, 401, 404, 500), and JSON payloads.", "required": true, "acceptable_evidence": ["Technical keywords: REST API design, resource-oriented endpoints, HTTP verbs (GET/POST/PUT/DELETE), status codes, idempotent methods, JSON payloads", "Structures intuitive RESTful routes (e.g. GET /v1/documents, POST /v1/chat, DELETE /v1/documents/{doc_id})", "Adheres to HTTP semantics with appropriate status codes and structured error responses"]}, {"id": "KP2", "description": "API implementation with modern frameworks (FastAPI): request validation via Pydantic, asynchronous endpoints (async/await), and real-time streaming responses (Server-Sent Events).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, Pydantic validation, async/await, StreamingResponse, Server-Sent Events (SSE), OpenAPI / Swagger documentation", "Leverages Pydantic schemas for automatic request data validation, serialization, and OpenAPI spec generation", "Implements asynchronous streaming endpoints yielding SSE tokens for real-time generative chat experiences"]}, {"id": "KP3", "description": "Production API security, resilience, and integration: implementing JWT authentication, CORS middleware, rate limiting, connection pooling, and external service integration.", "required": true, "acceptable_evidence": ["Technical keywords: JWT authentication, OAuth2, CORS middleware, rate limiting (Redis token bucket), httpx / aiohttp client, retry backoff", "Secures endpoints using cryptographically signed JWT bearer tokens and role-based access checks", "Integrates with downstream third-party REST APIs using asynchronous HTTP clients (httpx) with timeout handling and exponential backoff"]}], "critical_failures": ["Failing to demonstrate core REST concepts (HTTP methods, status codes, resource path conventions)", "Ignoring input validation (Pydantic) or streaming protocols (SSE) in modern API architectures", "Overlooking API security (JWT/OAuth2 auth) and operational controls (rate limiting, error handling)"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Describe your experience using various REST APIs and graph databases, specifically referencing Neo4j and the Cypher query language.', '{"key_points": [{"id": "KP1", "description": "REST API experience and best practices: designing clean, resource-oriented HTTP APIs with standard methods (GET, POST, PUT, DELETE), JSON payloads, authentication, and status codes.", "required": true, "acceptable_evidence": ["Technical keywords: REST API, HTTP methods (GET/POST/PUT/DELETE), status codes (200, 201, 400, 404, 500), Pydantic validation, OAuth2 / JWT", "Builds production APIs using FastAPI / Flask with OpenAPI documentation", "Implements robust error handling, rate limiting, and structured JSON response schemas"]}, {"id": "KP2", "description": "Neo4j and Cypher query fundamentals: writing declarative Cypher queries utilizing MATCH, WHERE, RETURN, CREATE, and MERGE clauses for graph data manipulation.", "required": true, "acceptable_evidence": ["Technical keywords: Neo4j, Cypher query language, MATCH, WHERE, RETURN, CREATE, MERGE, property graph", "Demonstrates Cypher syntax: MATCH (v:Vehicle {model: ''EV-2024''})-[:HAS_SYSTEM]->(s:System)-[:HAS_CODE]->(c:FaultCode) RETURN c.description", "Uses MERGE for idempotent node and relationship creation to avoid duplicate graph elements"]}, {"id": "KP3", "description": "Advanced Cypher patterns and optimization: multi-hop variable-length path queries, Cypher indexing, APOC procedures, and parameterized query security.", "required": true, "acceptable_evidence": ["Technical keywords: variable-length paths [*1..3], Cypher indexes, PROFILE / EXPLAIN query plans, APOC library, parameterized Cypher", "Performs multi-hop traversals to discover indirect dependencies across components", "Creates node property indexes to eliminate full graph scans on initial MATCH lookups", "Enforces parameterized queries to protect against Cypher injection vulnerabilities"]}, {"id": "KP4", "description": "Architectural integration in AI systems (GraphRAG): exposing Neo4j Cypher queries via REST endpoints or MCP tools to feed structured relationship subgraphs to LLMs.", "required": false, "acceptable_evidence": ["Technical keywords: GraphRAG integration, REST-to-Cypher gateway, MCP tools, ego-network extraction, subgraphs for LLM context", "Wraps Cypher queries in REST endpoints or Model Context Protocol tools called by agent orchestrators", "Serializes extracted graph subgraphs into clean Markdown context for LLM prompt synthesis"]}], "critical_failures": ["Failing to demonstrate concrete Cypher syntax (MATCH, WHERE, RETURN, MERGE)", "Superficial REST API discussion without mentioning HTTP methods, status codes, or parameter validation", "Ignoring query optimization (indexes, EXPLAIN) or injection prevention in Cypher"]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Did you work on any document size restrictions, and how were you processing very large documents?', '{"key_points": [{"id": "KP1", "description": "Document size restrictions and memory management: handling large files (100MB+ PDFs, 1000+ page manuals) by streaming file reads from S3 to disk rather than loading entire binary payloads into RAM.", "required": true, "acceptable_evidence": ["Technical keywords: document size limits, streaming I/O, S3 chunked download, memory limits, OOM (Out Of Memory) prevention, disk spooling", "Enforces upload limits (e.g. 50-100MB per file) at API Gateway while supporting large enterprise service manuals via background S3 ingestion", "Streams large PDF files to temporary scratch storage using chunked reads to avoid worker pod memory exhaustion"]}, {"id": "KP2", "description": "Page-by-page and distributed parallel processing: splitting massive documents into page batches processed concurrently across distributed worker tasks (Celery / EKS workers).", "required": true, "acceptable_evidence": ["Technical keywords: page-level splitting, batch processing, PyMuPDF page iteration, distributed workers, Celery / SQS tasks", "Iterates through PDFs page-by-page or section-by-section using PyMuPDF / Docling rather than parsing entire 500-page books at once", "Distributes batches of pages across multiple Kubernetes worker pods for parallel OCR and layout extraction"]}, {"id": "KP3", "description": "Hierarchical chunking and vector batch upsert: chunking extracted text iteratively and upserting vector embeddings in controlled batches (32-128 chunks) to avoid database request timeouts.", "required": true, "acceptable_evidence": ["Technical keywords: hierarchical chunking, iterative embedding, batch upsert, Milvus bulk insert limits, rate leveling", "Generates chunks and embeddings incrementally as pages are processed, immediately releasing raw page text from memory", "Batches vector insertions into Milvus/Pinecone to stay well within network payload limits and prevent connection timeouts"]}], "critical_failures": ["Suggesting loading multi-hundred-page PDFs entirely into memory at once (causing OOM crashes)", "Failing to explain page-by-page or batch processing techniques for large documents", "Ignoring streaming downloads and batch upsert limitations in vector databases"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'Do you have any experience with API gateways, and how were you routing the traffic for your microservices?', '{"key_points": [{"id": "KP1", "description": "API Gateway architectural role: serving as the single entry point, reverse proxy, and traffic orchestrator for all backend microservices, decoupling public clients from internal service topology.", "required": true, "acceptable_evidence": ["Technical keywords: API Gateway, reverse proxy, AWS API Gateway / Kong / Traefik / ALB Ingress, single entry point, service decoupling", "Terminates external SSL/TLS connections and centralizes cross-cutting concerns (authentication, rate limiting, logging)", "Routes external client requests to internal private microservices running on Kubernetes"]}, {"id": "KP2", "description": "Traffic routing mechanisms: implementing path-based and host-based routing rules, header-based routing, and versioned routing (/v1, /v2).", "required": true, "acceptable_evidence": ["Technical keywords: path-based routing, host-based routing, URL rewrites, canary routing, weighted routing, /api/v1/query -> Query Service", "Routes /v1/chat to Orchestrator service, /v1/documents to Ingestion service, and /v1/auth to Authentication service", "Uses weighted routing (canary deployment) to direct 10% of user traffic to experimental model versions"]}, {"id": "KP3", "description": "Cross-cutting gateway policies and security: centralizing JWT authentication verification, rate limiting (token bucket / Redis), CORS management, and request validation.", "required": true, "acceptable_evidence": ["Technical keywords: JWT token validation, rate limiting, Redis token bucket, CORS headers, DDoS protection, WAF integration", "Validates cryptographically signed JWT bearer tokens before forwarding traffic downstream", "Enforces per-client rate limits (e.g. 100 requests/minute) to protect downstream LLM inference endpoints from denial-of-service"]}], "critical_failures": ["Failing to explain path-based or host-based routing to specific backend microservices", "Ignoring cross-cutting gateway concerns (JWT authentication, rate limiting, CORS)", "Treating API gateways as simple load balancers without routing logic or security policies"]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'Do you have any experience with NoSQL?', '{"key_points": [{"id": "KP1", "description": "NoSQL database paradigms and experience: hands-on work with Document stores (MongoDB, Amazon DocumentDB), Key-Value caches (Redis, DynamoDB), and Wide-Column stores (Cassandra).", "required": true, "acceptable_evidence": ["Technical keywords: NoSQL paradigms, Document stores (MongoDB / DocumentDB), Key-Value stores (Redis / DynamoDB), Wide-Column (Cassandra), flexible schema", "Explains using document databases for semi-structured JSON payloads, chat transcripts, and heterogeneous metadata", "Uses key-value stores (Redis) for ultra-low-latency session caching and rate-limiting counters"]}, {"id": "KP2", "description": "Key differences between NoSQL and Relational (SQL): flexible schema vs rigid schema, horizontal sharding vs vertical scaling, eventual consistency (BASE) vs ACID transactions.", "required": true, "acceptable_evidence": ["Technical keywords: schema flexibility, horizontal scaling, partition keys, eventual consistency, BASE vs ACID, denormalization", "NoSQL supports polymorphic data where documents have differing fields without schema migration locks", "Relational databases enforce strict referential integrity and multi-table ACID transactions, whereas NoSQL favors denormalized reads and horizontal scaling"]}, {"id": "KP3", "description": "Application in AI/RAG architectures: storing unstructured conversation histories, episodic memory snapshots, document metadata payloads, and semantic cache entries.", "required": true, "acceptable_evidence": ["Technical keywords: chat session storage, episodic memory, vector metadata payloads, Redis semantic cache, DynamoDB state checkpoints", "Persists multi-turn LangGraph checkpoints and conversation message history in DynamoDB or MongoDB", "Uses Redis for fast session state lookup (<2ms) and vector DB metadata payload caching"]}], "critical_failures": ["Claiming NoSQL experience without naming specific engines (MongoDB, Redis, DynamoDB) or paradigms", "Failing to contrast NoSQL trade-offs against relational databases (schema flexibility and sharding vs ACID)", "Failing to articulate how NoSQL stores support AI and RAG architectures (caching, session history, metadata)"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Do you have experience working with multi-model architectures?', '{"key_points": [{"id": "KP1", "description": "Definition and rationale of multi-model architectures: orchestrating multiple specialized models across different modalities (text, vision, audio) or specialized model sizes (router, fast draft, heavy reasoner, reranker) rather than relying on a single monolithic LLM.", "required": true, "acceptable_evidence": ["Technical keywords: multi-model architecture, multimodal systems, specialized model routing, fast vs frontier models, model cascading", "Deploys specialized models tailored for distinct tasks: vision model for document layout, lightweight model for routing, and frontier model for synthesis", "Optimizes latency, accuracy, and operational compute cost across the workflow"]}, {"id": "KP2", "description": "Architectural patterns in multi-model systems: cascading/tiered routing, multimodal fusion (text + image embeddings), and multi-agent division of labor.", "required": true, "acceptable_evidence": ["Technical keywords: tiered routing, speculative drafting, multimodal embeddings (CLIP / ColPali), multi-agent specialization, ensemble validation", "Uses compact models (Claude 3 Haiku / GPT-4o-mini) to handle simple queries, escalating complex or high-liability reasoning to Claude 3.5 Sonnet", "Combines vision-language models for extracting schematics with text models for reasoning"]}, {"id": "KP3", "description": "Production trade-offs and engineering challenges: managing heterogeneous model latency budgets, vendor API redundancy, schema compatibility, and cost management.", "required": true, "acceptable_evidence": ["Technical keywords: latency budgeting, schema alignment, fallback providers, rate-limit diversification, cost optimization", "Requires strict Pydantic output schemas to ensure seamless data handoffs between models", "Implements cross-model fallback: falling back to secondary providers if the primary frontier model experiences downtime"]}], "critical_failures": ["Confusing multi-model architectures with basic single-model prompt engineering", "Failing to explain routing patterns (e.g. lightweight router delegating to heavy reasoner)", "Ignoring engineering challenges (latency budgets, schema alignment, cross-model fallbacks)"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did inter-service communication work within your backend, particularly in a VPC environment with secure communication?', '{"key_points": [{"id": "KP1", "description": "Private network topology and VPC design: isolating all backend microservices, databases, and worker pods within private subnets without public internet exposure.", "required": true, "acceptable_evidence": ["Technical keywords: AWS VPC, private subnets, NAT Gateway, security groups, Network Access Control Lists (NACLs), zero public egress", "Only the Application Load Balancer / API Gateway resides in public subnets; all API pods, vector DBs, and worker nodes reside in private subnets", "Outbound internet access for external updates is restricted through managed NAT Gateways"]}, {"id": "KP2", "description": "Secure inter-service communication protocols: enforcing mutual TLS (mTLS) with service mesh (Istio / AWS App Mesh), gRPC, or internal HTTPS with private DNS.", "required": true, "acceptable_evidence": ["Technical keywords: mutual TLS (mTLS), service mesh (Istio / Linkerd), gRPC, private DNS (Route 53 Private Hosted Zones), Kubernetes CoreDNS", "Encrypts all pod-to-pod and service-to-service traffic in transit using mTLS with automated certificate rotation", "Resolves internal service hostnames securely via private DNS zones without leaving the VPC"]}, {"id": "KP3", "description": "Secure cloud service access and VPC Endpoints: utilizing AWS PrivateLink and VPC Endpoints to connect to AWS services (S3, Bedrock, Secrets Manager) privately.", "required": true, "acceptable_evidence": ["Technical keywords: AWS PrivateLink, VPC Endpoints, Interface Endpoints, Gateway Endpoints (S3), zero public transit", "Routes traffic to Amazon S3 and AWS Bedrock over dedicated AWS internal network backbones rather than the public internet", "Guarantees that sensitive enterprise data and model prompts never traverse public IP space"]}, {"id": "KP4", "description": "Authentication and authorization controls: enforcing IAM Roles for Service Accounts (IRSA), Kubernetes NetworkPolicies, and internal JWT verification.", "required": false, "acceptable_evidence": ["Technical keywords: IAM Roles for Service Accounts (IRSA), Kubernetes NetworkPolicies, least privilege, internal JWT authentication", "Applies Kubernetes NetworkPolicies to block unauthorized network egress between unrelated pods", "Grants granular AWS permissions directly to Kubernetes service accounts without hardcoding static credentials"]}], "critical_failures": ["Failing to mention private VPC subnets and network isolation", "Ignoring encryption in transit (mTLS / internal HTTPS) between microservices", "Failing to explain AWS PrivateLink or VPC Endpoints for private AWS service communication"]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did you ensure reliability, scalability, and cost efficiency while productionizing the system?', '{"key_points": [{"id": "KP1", "description": "Ensuring system reliability: implementing multi-AZ deployments, health check probes (/healthz), automated pod restarts, circuit breakers, and dead-letter queues (DLQ).", "required": true, "acceptable_evidence": ["Technical keywords: multi-AZ redundancy, Kubernetes liveness/readiness probes, circuit breakers, dead-letter queues (DLQ), retry backoff, graceful degradation", "Distributes EKS pods and RDS database instances across multiple Availability Zones to withstand data center failures", "Uses circuit breakers to stop cascading failures when downstream services experience latency spikes"]}, {"id": "KP2", "description": "Ensuring scalability: deploying Horizontal Pod Autoscaling (HPA) on EKS, asynchronous decoupled ingestion (SQS/Kafka), vector DB sharding, and Redis caching.", "required": true, "acceptable_evidence": ["Technical keywords: Horizontal Pod Autoscaler (HPA), asynchronous SQS queues, vector DB read replicas / sharding, Redis semantic caching", "Autoscales API pods dynamically based on CPU utilization and request rate", "Buffers high-volume document ingestion through message queues, preventing spikes from impacting query serving"]}, {"id": "KP3", "description": "Ensuring cost efficiency: utilizing Spot instances for background ingestion, model right-sizing (Claude 3 Haiku for simple tasks), embedding caches, and index quantization.", "required": true, "acceptable_evidence": ["Technical keywords: EC2 Spot instances, model right-sizing, prompt token caching, Redis semantic cache, vector quantization (PQ/INT8)", "Runs offline ingestion worker pools on AWS Spot instances, cutting compute costs by up to 70%", "Uses semantic caching to serve repeat queries with 0 LLM token cost", "Applies Product Quantization to reduce vector index memory footprint and hardware requirements"]}, {"id": "KP4", "description": "Observability and proactive alerting: instrumenting OpenTelemetry distributed tracing, CloudWatch alarms, and Prometheus/Grafana dashboards.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Prometheus, Grafana, CloudWatch alarms, p95 latency tracking, error rate alerting", "Monitors p95 latency, error rates, and GPU/CPU utilization in real time", "Triggers automated alerts before resource exhaustion affects production users"]}], "critical_failures": ["Failing to cover all three required pillars: reliability, scalability, and cost efficiency", "Offering generic high-level advice without concrete cloud/Kubernetes mechanisms (HPA, DLQ, Spot instances, Redis caching)", "Ignoring cost optimization levers in LLM and vector infrastructure (Spot instances, caching, model right-sizing)"]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How did you ensure the correctness of SQL queries generated by the system?', '{"key_points": [{"id": "KP1", "description": "Syntactic validation and AST parsing: parsing generated SQL strings using SQL parsers (sqlglot / sqlparse) to verify syntax, dialect validity, and structural correctness before execution.", "required": true, "acceptable_evidence": ["Technical keywords: SQL syntax validation, AST parsing, sqlglot, sqlparse, PostgreSQL dialect validation, token parsing", "Catches unclosed quotes, malformed JOIN syntax, and dialect-specific keyword errors before hitting the database engine", "Prevents invalid SQL queries from causing database driver execution errors"]}, {"id": "KP2", "description": "Schema alignment and semantic validation: inspecting the parsed AST against real database metadata catalogs to verify tables, columns, data types, and join keys exist.", "required": true, "acceptable_evidence": ["Technical keywords: schema catalog validation, information_schema, column existence check, foreign key relationship check, type compatibility", "Verifies that all referenced tables and columns actually exist in the database schema catalog", "Validates that JOIN clauses connect valid foreign key and primary key pairs with compatible data types"]}, {"id": "KP3", "description": "Security guardrails and safe execution sandboxing: enforcing read-only permissions, parameterized execution, statement timeouts, and forbidding destructive DDL/DML.", "required": true, "acceptable_evidence": ["Technical keywords: read-only database user, SELECT-only whitelist, forbidding DROP/DELETE/UPDATE/ALTER, statement_timeout, LIMIT enforcement", "Connects via a dedicated PostgreSQL user with SELECT-only grants, preventing accidental or malicious data modification", "Injects LIMIT clauses (e.g. LIMIT 100) and enforces statement timeouts (e.g. 5 seconds) to prevent runaway resource exhaustion"]}, {"id": "KP4", "description": "Self-correction and execution feedback loop: capturing database execution errors and feeding compiler error logs back to the LLM for automated retry.", "required": false, "acceptable_evidence": ["Technical keywords: self-correction loop, execution error feedback, retry mechanism, LangGraph cyclic recovery", "If a query fails with a database syntax or column error, passes the error message back into the model context to generate an immediate fix", "Caps self-correction loops at 2-3 retries before escalating to fallback"]}], "critical_failures": ["Executing generated SQL directly against the database without syntax validation or security checks", "Failing to enforce read-only execution permissions or destructive query whitelisting (SELECT only)", "Ignoring schema metadata verification (validating table and column names before execution)"]}', 1),
('TECHNICAL', 'Software Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'How did you integrate structured (SQL) and unstructured data sources within your AI system using techniques like text-to-SQL?', '{"key_points": [{"id": "KP1", "description": "Hybrid query decomposition and intent classification: analyzing user prompts to determine whether the information requires structured relational SQL data, unstructured RAG knowledge, or both.", "required": true, "acceptable_evidence": ["Technical keywords: query routing, intent classification, hybrid query decomposition, structured vs unstructured data split, supervisor agent", "Identifies whether a question is factual documentation (unstructured), operational database records (structured), or a composite request", "Decomposes composite questions (e.g. ''How many EV battery repairs occurred this month, and what is the troubleshooting procedure for code P0A80?'') into distinct sub-tasks"]}, {"id": "KP2", "description": "Structured data retrieval with Text-to-SQL: utilizing schema-linked prompts, semantic catalogs, and AST validation to generate and execute verified SQL queries against relational databases.", "required": true, "acceptable_evidence": ["Technical keywords: Text-to-SQL, database schema linking, few-shot examples, read-only connection, sqlglot AST validation, PostgreSQL", "Provides the LLM with relevant table schemas, foreign key relationships, and sample values", "Executes validated read-only SQL queries to extract exact numerical metrics, counts, and customer transaction records"]}, {"id": "KP3", "description": "Unstructured data retrieval with RAG: executing hybrid search (BM25 + dense vector) across technical documentation, manuals, and service bulletins in Milvus.", "required": true, "acceptable_evidence": ["Technical keywords: unstructured RAG, Milvus vector search, BM25 keyword search, cross-encoder reranking, procedural manuals, knowledge articles", "Retrieves relevant semantic chunks explaining diagnostic procedures, policies, or technical specifications", "Filters results using metadata attributes matching entities extracted during query analysis"]}, {"id": "KP4", "description": "Context fusion and unified synthesis: merging deterministic SQL tabular results with retrieved semantic text passages in the final synthesis prompt.", "required": true, "acceptable_evidence": ["Technical keywords: context fusion, unified prompt synthesis, deterministic tabular display + narrative explanation, multi-source grounding", "Constructs a structured prompt containing both the exact SQL query results and the retrieved procedural context", "Generates a cohesive response presenting exact numbers alongside contextual qualitative explanations and verifiable citations"]}], "critical_failures": ["Failing to explain how structured Text-to-SQL and unstructured RAG are coordinated and merged", "Ignoring query decomposition and intent routing across structured and unstructured data sources", "Failing to address Text-to-SQL safety guardrails (read-only execution, schema validation)"]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'Can you explain the high-level architecture of your multi-agent system and how different agents are orchestrated?', '{"subcategory": "Multi-Agent System High-Level Architecture & Orchestration", "key_points": [{"id": "KP1", "description": "Orchestration pattern and supervisory topology: implementing hierarchical supervisor routing (LangGraph StateGraph) with dynamic task decomposition across specialized worker agents.", "required": true, "acceptable_evidence": ["Technical keywords: supervisor agent, orchestrator-worker topology, LangGraph StateGraph, hierarchical routing, conditional edges, task decomposition.", "Explains using a centralized supervisor or conversation manager that inspects query intent and delegates execution to domain-specific worker nodes.", "Details how dynamic edge transitions return control to the supervisor after sub-agent tool execution."]}, {"id": "KP2", "description": "Inter-agent communication and state schema: maintaining a shared typed state dictionary across execution nodes.", "required": true, "acceptable_evidence": ["Technical keywords: shared state schema, TypedDict, message history buffer, agent scratchpad, state reducer, context propagation.", "Explains how state preserves user goals, intermediate tool outputs, and execution history across agent transitions without loss.", "Highlights isolation of worker-specific sub-states to prevent context window bloat."]}, {"id": "KP3", "description": "Execution failure handling and tool coordination: implementing retry policies, fallback boundaries, and termination conditions.", "required": true, "acceptable_evidence": ["Technical keywords: fallback edges, retry thresholds, max execution cycles, circuit breaker, human escalation.", "Details how the system catches worker tool exceptions and loops back to the supervisor or escalates to a human operator.", "Enforces strict cycle limits to avoid infinite looping in cyclic graph execution."]}], "critical_failures": ["Describing simple sequential pipeline chains without explaining multi-agent orchestration or supervisor routing.", "Failing to detail how inter-agent state is structured or propagated across nodes.", "Omitting loop limits or failure recovery mechanisms in cyclic agent execution."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you provide an overview of your background and experience in AI/ML, particularly in generative and agentic AI?', '{"subcategory": "AI/ML Engineering Background & Generative/Agentic AI Experience", "key_points": [{"id": "KP1", "description": "Technical career evolution: articulating a structured transition from classical software/ML engineering to production Generative and Agentic AI systems.", "required": true, "acceptable_evidence": ["Technical keywords: software engineering foundation, MLOps lifecycle, Generative AI adoption, agentic systems engineering, production impact.", "Articulates progression from backend APIs and deterministic data pipelines to building LLM applications and autonomous multi-agent workflows.", "Mentions hands-on ownership of architectural components from model evaluation to deployment."]}, {"id": "KP2", "description": "Core competencies in RAG and agent orchestration: demonstrating real-world experience with retrieval pipelines, vector stores, and graph-based frameworks.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, LangChain, hybrid search (BM25 + dense vector), Milvus/Pinecone, tool calling, Model Context Protocol (MCP).", "Explains building end-to-end RAG systems with document parsing, chunking, and cross-encoder reranking.", "Highlights designing multi-agent workflows with state persistence, tool execution, and guardrails."]}, {"id": "KP3", "description": "Production engineering and reliability rigor: emphasizing guardrails, observability, and business metric impact.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS evaluation, Presidio PII masking, latency SLAs, token economics, AHT reduction, production observability.", "Details operational focus on system reliability, cost efficiency, and response latency rather than prototype hype.", "Quantifies operational impact such as deflection rates or processing time improvements."]}], "critical_failures": ["Providing a generic non-technical summary without mentioning specific generative AI architectures or agentic frameworks.", "Failing to discuss production deployment considerations such as latency, evaluation, or reliability.", "Focusing exclusively on toy prompt engineering without backend system integration experience."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'Can you take a deep dive in multi-agent architecture and explain a little bit more on that front?', '{"subcategory": "Deep-Dive Multi-Agent Architecture & Coordination Mechanics", "key_points": [{"id": "KP1", "description": "Specialized worker agent roles and boundary definition: isolating domain responsibilities across distinct agent nodes.", "required": true, "acceptable_evidence": ["Technical keywords: domain-specific agents, customer support agent, diagnostic agent, booking agent, specialized tools, bounded context.", "Explains how each sub-agent is scoped to a precise domain with restricted system prompts and curated toolkits.", "Prevents tool contamination by ensuring agents only access APIs relevant to their specific role."]}, {"id": "KP2", "description": "Graph topology and dynamic transition edges: configuring conditional routing and deterministic fallback pathways in LangGraph.", "required": true, "acceptable_evidence": ["Technical keywords: conditional edges, StateGraph, router node, intent classification, dynamic dispatch, END node criteria.", "Details how routing decisions are computed based on agent output payload, structured routing tags, or intent classifiers.", "Describes termination criteria and returning synthesized responses back to the user."]}, {"id": "KP3", "description": "Concurrency, shared memory, and conflict resolution: managing state reconciliation during collaborative multi-agent execution.", "required": true, "acceptable_evidence": ["Technical keywords: state checkpointing, memory persistence, message history deduplication, lock management, conflict resolution.", "Explains how agent trace logs and tool artifacts are recorded into persistent memory (e.g. Redis or Postgres checkpointer).", "Addresses how conflicting outputs between agents are arbitrated by the orchestrator."]}], "critical_failures": ["Treating multi-agent systems as a single monolithic prompt with tool calling rather than coordinated independent nodes.", "Failing to explain routing criteria or state transitions between agents.", "Omitting state checkpointing or concurrency considerations in graph execution."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you walk me through your career progression from software engineering to MLOps and then to generative and agentic AI systems?', '{"subcategory": "Career Progression: Software Engineering to MLOps to Generative & Agentic AI", "key_points": [{"id": "KP1", "description": "Foundational software engineering base: demonstrating strong fundamentals in API design, microservices, and distributed backend systems.", "required": true, "acceptable_evidence": ["Technical keywords: software engineering foundation, REST/gRPC APIs, backend microservices, system architecture, data modeling, clean code.", "Highlights how core software practices (error handling, CI/CD, modularity) serve as the foundation for building robust AI platforms.", "Explains experience in scalable service implementation prior to specializing in ML."]}, {"id": "KP2", "description": "Evolution into MLOps: mastering reproducible pipelines, model deployment, tracking, and serving infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: MLOps lifecycle, MLflow, Docker containerization, Kubernetes/EKS, model registries, feature stores, drift monitoring.", "Describes managing end-to-end training and inference pipelines, automated retraining, and artifact versioning.", "Emphasizes bridging the gap between data science experimentation and production reliability."]}, {"id": "KP3", "description": "Pivoting to Generative & Agentic AI: architecting RAG pipelines, graph-based workflows, and autonomous agent systems.", "required": true, "acceptable_evidence": ["Technical keywords: LLM orchestration, RAG architectures, LangGraph, vector databases, tool invocation, production guardrails.", "Explains leveraging both backend and MLOps strengths to solve generative AI challenges: latency, non-determinism, and observability.", "Highlights driving end-to-end enterprise implementations with measurable business outcomes."]}], "critical_failures": ["Claiming an abrupt jump into GenAI without demonstrating how software engineering and MLOps foundations enabled the transition.", "Failing to highlight real architectural challenges solved across each career stage.", "Omitting production engineering principles when discussing recent GenAI/Agentic work."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'How did your career progress from software engineering to leading multi-agent AI systems at an architect level?', '{"subcategory": "Career Progression: SWE to Architect-Level Multi-Agent Systems Leadership", "key_points": [{"id": "KP1", "description": "Architectural mindset evolution: shifting from component-level feature coding to system-wide decomposition, contracts, and scalability.", "required": true, "acceptable_evidence": ["Technical keywords: systems architecture, interface contracts, trade-off analysis, non-functional requirements, technical leadership.", "Explains taking ownership of end-to-end system topologies, API contracts, and cross-team integration standards.", "Emphasizes designing for reliability, maintainability, and organizational scalability."]}, {"id": "KP2", "description": "Leading multi-agent system design: establishing orchestration patterns, protocol standards, and governance.", "required": true, "acceptable_evidence": ["Technical keywords: multi-agent architecture, LangGraph StateGraph, MCP standardization, tool isolation, guardrail enforcement.", "Details establishing architectural standards for agent routing, shared memory schemas, and Human-in-the-Loop policies.", "Describes balancing autonomy with deterministic control across multi-agent workflows."]}, {"id": "KP3", "description": "Technical mentoring and stakeholder alignment: driving engineering best practices and translating business requirements into AI capabilities.", "required": true, "acceptable_evidence": ["Technical keywords: technical roadmap, cross-functional leadership, design reviews, production readiness reviews, business KPI alignment.", "Articulates guiding junior engineers through debugging non-deterministic agent trajectories.", "Demonstrates aligning executive stakeholders on AI capabilities, cost projections, and risk mitigation."]}], "critical_failures": ["Describing individual contributor coding tasks without demonstrating architect-level system design or leadership.", "Failing to articulate how multi-agent architectural standards were established and enforced across a team.", "Omitting trade-off evaluation and governance in autonomous AI systems."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'How did your career transition from software engineering to machine learning and then to generative AI and agent-based architectures?', '{"subcategory": "Career Transition: SWE to ML to Generative AI & Agent Architectures", "key_points": [{"id": "KP1", "description": "Progression trajectory and technical milestones: detailing the journey across deterministic software, statistical machine learning, and generative agents.", "required": true, "acceptable_evidence": ["Technical keywords: career transition, software engineering, predictive ML models, generative AI, agentic architectures, skill compounding.", "Explains initial focus on web/backend services, progressing into statistical data modeling, and culminating in LLM-driven autonomous workflows.", "Highlights how each phase informed and reinforced subsequent architectural capabilities."]}, {"id": "KP2", "description": "Overcoming paradigm shifts: adapting engineering practices from deterministic code to probabilistic LLM outputs.", "required": true, "acceptable_evidence": ["Technical keywords: probabilistic systems, non-deterministic outputs, evaluation benchmarks, semantic validation, guardrails.", "Discusses transitioning from unit testing static logic to probabilistic evaluation (RAGAS, LLM-as-a-judge).", "Details implementing guardrails and schema validation to enforce deterministic bounds on probabilistic components."]}, {"id": "KP3", "description": "Practical application in agent-based systems: applying combined discipline to real-world multi-agent production use cases.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, tool calling, state management, enterprise APIs, production deployment.", "Connects software patterns (state machines, retry logic) directly to agentic graph orchestration.", "Demonstrates clear understanding of why agentic workflows represent the current frontier of AI engineering."]}], "critical_failures": ["Describing a superficial career overview without addressing the conceptual shift from deterministic to probabilistic systems.", "Failing to explain how software and ML skills directly contributed to building agent-based systems.", "Omitting practical production examples or technical frameworks used in modern GenAI."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you balance system scalability and maintainability when building agentic AI systems with multiple dependencies?', '{"subcategory": "Agentic AI System Scalability vs. Maintainability Trade-offs", "key_points": [{"id": "KP1", "description": "Decoupled agent microservices and interface contracts: architecting modular agent components with standardized communication protocols.", "required": true, "acceptable_evidence": ["Technical keywords: decoupled microservices, interface contracts, Model Context Protocol (MCP), gRPC/REST, loose coupling, modularity.", "Explains isolating agents and tools as independent services so updates do not break dependent workflow nodes.", "Adopts standardized protocols (like MCP) to prevent custom point-to-point integration sprawl."]}, {"id": "KP2", "description": "State management and horizontal scaling: separating stateless compute nodes from distributed state storage.", "required": true, "acceptable_evidence": ["Technical keywords: stateless agent workers, externalized state, Redis checkpointer, PostgreSQL, horizontal pod autoscaling (HPA), Kubernetes.", "Ensures agent execution nodes remain stateless, delegating state persistence to centralized checkpointers.", "Enables horizontal scaling of high-throughput worker nodes under variable query loads."]}, {"id": "KP3", "description": "Maintainability via automated testing and trajectory tracing: implementing comprehensive telemetry and replay capabilities.", "required": true, "acceptable_evidence": ["Technical keywords: LangSmith/OpenTelemetry, execution tracing, mock tool environments, golden dataset regression, deterministic replay.", "Captures full agent decision graphs, tool invocations, and token usage for rapid debugging of failing trajectories.", "Uses synthetic tool mocks to unit test agent logic without calling production third-party APIs."]}], "critical_failures": ["Suggesting tightly coupled monolithic agent graphs where all tools and agents live in a single unmaintainable process.", "Failing to explain how state is persisted externally to support horizontal scalability.", "Ignoring observability, tracing, or regression testing in multi-agent maintenance."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'Were you building and steering the agentic machine learning architecture for the platform, or was that done by someone else on the team?', '{"subcategory": "Ownership & Technical Leadership in Agentic ML Architecture", "key_points": [{"id": "KP1", "description": "Architectural steering and decision ownership: defining core system topology, framework selection, and technical vision.", "required": true, "acceptable_evidence": ["Technical keywords: architectural ownership, technical steering, framework evaluation (LangGraph vs Autogen/CrewAI), design docs (RFCs).", "Articulates direct responsibility for selecting orchestration frameworks, state schemas, and deployment topologies.", "Describes authoring architectural blueprints and driving technical alignment across cross-functional teams."]}, {"id": "KP2", "description": "Boundary setting and governance: establishing tool permissions, security sandboxes, and Human-in-the-Loop thresholds.", "required": true, "acceptable_evidence": ["Technical keywords: tool governance, security guardrails, HITL approval policies, PII filtering (Presidio), RBAC authorization.", "Defines which actions agents can execute autonomously versus actions requiring human operator sign-off.", "Enforces credential isolation and least-privilege access across all integrated tool nodes."]}, {"id": "KP3", "description": "Delivery execution and operational accountability: overseeing production deployment, evaluation benchmarks, and SLA compliance.", "required": true, "acceptable_evidence": ["Technical keywords: production rollout, latency budget, cost monitoring, regression testing, SLA adherence, incident management.", "Owns post-deployment telemetry, latency optimization, and ongoing prompt/routing tuning.", "Demonstrates accountability for both functional correctness and system uptime."]}], "critical_failures": ["Claiming passive participation or treating ownership as simple prompt modification without system-level accountability.", "Failing to describe specific architectural choices or governance rules established for the team.", "Omitting production readiness and operational monitoring responsibilities."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'What is MCP, and why is standardization important for tool calling in distributed systems?', '{"subcategory": "Model Context Protocol (MCP) Standardization in Distributed Systems", "key_points": [{"id": "KP1", "description": "Core concepts and architecture of MCP: standardizing client-host-server communication for tool discovery and resource access.", "required": true, "acceptable_evidence": ["Technical keywords: Model Context Protocol (MCP), client-host-server architecture, JSON-RPC 2.0, standardized tool discovery, resources, prompts.", "Explains how MCP decouples LLM applications from specific tool implementations via an open standard.", "Details how hosts query MCP servers to dynamically discover available tools and schemas at runtime."]}, {"id": "KP2", "description": "Solving N*M integration complexity in distributed environments: replacing ad-hoc tool integrations with uniform contracts.", "required": true, "acceptable_evidence": ["Technical keywords: N*M integration problem, point-to-point sprawl, unified protocol, interoperability, plug-and-play tools.", "Contrasts proprietary, bespoke SDK integrations with a single universal interface across heterogeneous databases and enterprise APIs.", "Enables sharing tool servers across multiple different agent frameworks without rewriting integration logic."]}, {"id": "KP3", "description": "Security boundaries, sandboxing, and enterprise governance: enforcing centralized authorization and audit logging via MCP servers.", "required": true, "acceptable_evidence": ["Technical keywords: security sandboxing, permission negotiation, token-scoped access, audit logging, transport security (stdio, SSE).", "Explains how MCP servers isolate execution environments and enforce parameter verification before invoking sensitive operations.", "Enables granular enterprise auditing of every agent-initiated tool invocation."]}], "critical_failures": ["Confusing MCP with basic LangChain tool calling without explaining the standardized client-server protocol.", "Failing to explain how MCP solves the N*M integration problem across distributed systems.", "Omitting security, transport mechanisms, or tool discovery capabilities in MCP."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and coordinate multiple agents in an agentic AI system, and what tasks were distributed across them?', '{"subcategory": "Multi-Agent System Coordination & Task Distribution Design", "key_points": [{"id": "KP1", "description": "Task decomposition and role specialization: partitioning user intent into bounded sub-tasks handled by specialized agents.", "required": true, "acceptable_evidence": ["Technical keywords: task decomposition, specialized agents, domain separation, single responsibility principle, customer care vs billing vs technical support.", "Explains how complex multi-intent queries are broken down into discrete operational steps.", "Assigns distinct sub-agents specific domain knowledge, tools, and system prompt constraints."]}, {"id": "KP2", "description": "Orchestration mechanics and control flow: using supervisor routing or collaborative peer handoffs in LangGraph.", "required": true, "acceptable_evidence": ["Technical keywords: supervisor orchestration, dynamic handoffs, conditional branching, router agent, LangGraph edges.", "Details how the supervisor analyzes intermediate findings and decides whether to invoke another agent or synthesize the final answer.", "Implements structured handoff schemas allowing agents to transfer execution context seamlessly."]}, {"id": "KP3", "description": "State consistency and execution boundaries: synchronizing global conversation state while isolating local scratchpads.", "required": true, "acceptable_evidence": ["Technical keywords: global state buffer, local agent state, context pruning, state synchronization, recursion limits.", "Prevents context pollution by passing only relevant sub-task results back to the global state.", "Enforces strict timeouts and depth limits to prevent deadlock or circular task delegation."]}], "critical_failures": ["Describing multiple agents performing identical unspecialized tasks without role boundaries.", "Failing to explain the orchestration mechanism that routes tasks and aggregates results.", "Omitting how state is synchronized across agents during complex task execution."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement human-in-the-loop mechanisms in your agent-based system, and when are they triggered?', '{"subcategory": "Human-in-the-Loop (HITL) Implementation & Trigger Conditions", "key_points": [{"id": "KP1", "description": "Trigger criteria and risk classification: establishing deterministic thresholds for pausing autonomous execution.", "required": true, "acceptable_evidence": ["Technical keywords: HITL triggers, high-consequence actions, financial transactions, PII modification, confidence threshold, intent ambiguity.", "Triggers human intervention when an action involves irreversible writes, financial transactions, or critical database mutations.", "Pauses execution when model confidence scores fall below defined safety thresholds or ambiguous intents are detected."]}, {"id": "KP2", "description": "Technical implementation in graph orchestration: using LangGraph interrupt and persistent state checkpointing.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph interrupt(), breakpoint, state checkpointer, execution suspension, asynchronous resume.", "Explains using interrupt() nodes to halt graph execution, serializing state to a persistent checkpointer (e.g. Postgres/Redis).", "Leaves execution paused until an external webhook or operator UI submits an approval or payload update."]}, {"id": "KP3", "description": "Operator review interface and state mutation: enabling review, parameter editing, approval, or graceful rejection.", "required": true, "acceptable_evidence": ["Technical keywords: human review UI, parameter override, approval payload, state update, audit trail.", "Allows human operators to inspect pending tool calls, modify parameters, approve, or cancel the action.", "Logs all human decisions into an immutable audit trail for compliance and model fine-tuning feedback."]}], "critical_failures": ["Describing simple print-and-wait console prompts rather than production asynchronous graph suspension (interrupt/checkpointers).", "Failing to define clear, risk-based trigger criteria for human intervention.", "Omitting how the agent resumes execution once human input or approval is received."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you manage and track state and context in an agent over time, particularly in graph-based frameworks like LangGraph?', '{"subcategory": "Agent State & Context Management Over Time in LangGraph", "key_points": [{"id": "KP1", "description": "State schema architecture and reducers: designing strongly-typed StateGraph schemas with custom message reducers.", "required": true, "acceptable_evidence": ["Technical keywords: StateGraph, TypedDict schema, add_messages reducer, message state, state immutability, delta updates.", "Explains structuring graph state using typed dictionaries containing dialogue messages, active user metadata, and tool execution flags.", "Uses operator reducers (like add_messages) to append new turn events without overwriting historical context."]}, {"id": "KP2", "description": "State checkpointing and persistence: utilizing persistent checkpointers for session continuity and time-travel debugging.", "required": true, "acceptable_evidence": ["Technical keywords: checkpointer (MemorySaver, PostgresSaver, RedisSaver), thread_id, session resumption, time-travel debugging.", "Details using thread_id keys to partition and persist conversations across multi-turn user sessions.", "Enables rewinding graph state to prior checkpoints to replay or correct faulty execution branches."]}, {"id": "KP3", "description": "Context window pruning and memory compression: managing token limits through selective summarization and buffer truncation.", "required": true, "acceptable_evidence": ["Technical keywords: context window management, conversation summarization, sliding window buffer, token pruning, long-term memory store.", "Implements background summarization nodes that condense historical turns into concise summaries when token limits near thresholds.", "Persists key user facts into external key-value or vector stores for long-term semantic retrieval across sessions."]}], "critical_failures": ["Relying solely on in-memory Python variables that lose state upon server restart or process crash.", "Failing to explain how LangGraph checkpointers bind state to thread_id sessions.", "Ignoring context window limitations and token growth over multi-turn interactions."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How would you design a scalable ML system architecture for handling multiple AI agents and high query volumes?', '{"subcategory": "Scalable ML System Architecture for Multi-Agent Workflows & High QPS", "key_points": [{"id": "KP1", "description": "Stateless worker scaling and asynchronous message queuing: decoupling request ingress from agent execution via distributed queues.", "required": true, "acceptable_evidence": ["Technical keywords: asynchronous task queue, Celery, RabbitMQ, Apache Kafka, AWS SQS, horizontal pod autoscaling (HPA), Kubernetes.", "Buffers high-volume user queries into message queues to prevent overwhelming backend LLM endpoints.", "Scales stateless agent worker containers horizontally based on queue depth metrics."]}, {"id": "KP2", "description": "Distributed state externalization and caching: offloading session state and LLM responses to fast caching layers.", "required": true, "acceptable_evidence": ["Technical keywords: Redis cluster, ElastiCache, distributed caching, semantic cache (GPTCache), state checkpointing, connection pooling.", "Stores active conversation states and graph checkpoints in Redis to allow any worker node to handle incoming turns.", "Implements semantic caching for frequent queries to bypass expensive LLM calls and reduce latency."]}, {"id": "KP3", "description": "LLM gateway, rate limiting, and circuit breakers: managing model provider quotas and failover routes.", "required": true, "acceptable_evidence": ["Technical keywords: LLM gateway (LiteLLM, Kong), rate limiting, token bucket, fallback models, circuit breaker pattern, load balancing.", "Distributes query traffic across multiple model deployments or providers (e.g. Bedrock Claude, Azure OpenAI) to avoid rate limits.", "Trips circuit breakers upon downstream provider degradation, falling back to cached responses or lightweight models."]}], "critical_failures": ["Proposing synchronous blocking architectures where each HTTP request directly holds an agent loop until completion.", "Failing to externalize agent state, preventing horizontal scaling across multiple container instances.", "Omitting rate limiting, queuing, or LLM gateway failover mechanisms under high query loads."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you design an ingestion agent that processes multiple document formats and inserts data into a database without manual SQL queries?', '{"subcategory": "Autonomous Multi-Format Document Ingestion Agent Architecture", "key_points": [{"id": "KP1", "description": "Multi-format document parsing and layout understanding: routing diverse file formats (PDF, DOCX, CSV, HTML) through specialized parsers.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, unstructured.io, PyPDF, pdfplumber, layout-aware parsing, TableFormer, OCR (Tesseract).", "Automatically detects file MIME types and dispatches to appropriate parsers capable of extracting complex tables and multi-column text.", "Preserves document hierarchy, headers, and metadata tags during extraction."]}, {"id": "KP2", "description": "Automated data transformation, validation, and schema mapping: transforming raw unstructured content into structured records.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic schema validation, LLM-based entity extraction, structured JSON serialization, data cleaning, deduplication.", "Uses structured extraction (Instructor/Pydantic) to normalize parsed document attributes into consistent relational/vector schemas.", "Validates data types and rejects malformed records before database persistence."]}, {"id": "KP3", "description": "Automated database insertion via ORM/vector loaders: storing structured metadata and chunk embeddings without manual SQL.", "required": true, "acceptable_evidence": ["Technical keywords: SQLAlchemy ORM, vector database loader (Milvus, PGVector), bulk ingestion, batch embedding, transaction management.", "Executes programmatic ORM inserts into relational tables and dispatches chunk vectors into vector collections within transactional blocks.", "Employs idempotent upsert keys to prevent duplicate document insertion during reprocessing."]}], "critical_failures": ["Suggesting manual SQL string concatenation or requiring human intervention to format records.", "Failing to address table and layout preservation in unstructured document parsing.", "Omitting schema validation or idempotent database insertion mechanisms."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What architectural design patterns are commonly used in agentic solutions, such as router agents, orchestration agents, and graph-based agents?', '{"subcategory": "Architectural Design Patterns in Agentic AI Solutions", "key_points": [{"id": "KP1", "description": "Router and dispatcher pattern: classifying intent to route queries to specialized deterministic handlers or domain agents.", "required": true, "acceptable_evidence": ["Technical keywords: router pattern, semantic router, intent classifier, single-turn dispatch, rule-based vs LLM router.", "Explains using an upfront lightweight classifier to route queries directly to single-purpose tools, bypassing expensive full-agent loops.", "Minimizes latency and token cost for straightforward retrieval or transactional tasks."]}, {"id": "KP2", "description": "Orchestrator-worker and hierarchical supervisory pattern: coordinating multi-step planning and dynamic sub-task delegation.", "required": true, "acceptable_evidence": ["Technical keywords: orchestrator-worker, supervisor pattern, plan-and-solve, task decomposition, agent delegation, aggregation.", "Details how a central planning agent formulates an execution plan, invokes specialized workers, and synthesizes intermediate outputs.", "Provides centralized oversight and prevents workers from taking uncontrolled execution branches."]}, {"id": "KP3", "description": "Stateful graph-based agents (LangGraph): supporting cyclic iteration, reflection, self-correction, and state persistence.", "required": true, "acceptable_evidence": ["Technical keywords: cyclic state graphs, StateGraph, reflection pattern, self-correction loop, checkpointing, conditional edges.", "Contrasts directed acyclic graphs (chains) with cyclic graphs capable of re-evaluating tool outputs and retrying upon errors.", "Enables persistent Human-in-the-Loop workflows and structured state evolution across multi-step execution."]}], "critical_failures": ["Failing to distinguish between linear chains, router dispatchers, hierarchical supervisors, and cyclic state graphs.", "Describing agent design patterns purely in terms of prompt wording rather than architectural control flow.", "Omitting cyclic feedback and self-correction capabilities in graph-based agent patterns."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'What evaluation strategy did you follow specifically for LangGraph-based workflows?', '{"subcategory": "Evaluation Strategy for LangGraph-Based Workflows", "key_points": [{"id": "KP1", "description": "Graph trajectory and path correctness evaluation: assessing whether the agent navigated the correct node sequence and conditional branches.", "required": true, "acceptable_evidence": ["Technical keywords: trajectory evaluation, execution path accuracy, transition correctness, golden paths, cycle count, step efficiency.", "Compares observed node transitions against benchmark golden execution paths to verify correct supervisory routing.", "Measures step efficiency and flags unnecessary intermediate node traversals."]}, {"id": "KP2", "description": "Tool-calling precision and argument fidelity: evaluating the accuracy of selected tools and structured input parameters.", "required": true, "acceptable_evidence": ["Technical keywords: tool selection accuracy, argument parsing precision, Pydantic schema validation, hallucinated tool calls, parameter match.", "Scores whether the correct tool was chosen for a given state and whether arguments matched expected schemas exactly.", "Flags invalid tool invocations and tracks rate of tool execution failures."]}, {"id": "KP3", "description": "Cycle termination, token cost, and latency metrics: tracking infinite loop prevention and non-functional execution constraints.", "required": true, "acceptable_evidence": ["Technical keywords: recursion limit violations, infinite loop detection, end-to-end latency, cumulative token spend, cost per execution.", "Tracks the frequency of hitting maximum recursion limits (circuit breakers) due to unresolvable agent loops.", "Monitors token consumption and latency across each graph node to identify bottleneck agents."]}], "critical_failures": ["Evaluating only the final text output (e.g. BLEU/ROUGE) without inspecting intermediate graph node transitions or tool calls.", "Failing to track trajectory correctness or loop termination in cyclic graph execution.", "Omitting tool parameter validation and execution efficiency metrics."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and implement a multi-agent AI system using LangGraph, and how did you define roles and coordination between different agents?', '{"subcategory": "Multi-Agent System Design & Role Coordination in LangGraph", "key_points": [{"id": "KP1", "description": "Node role definition and system prompt scoping: isolating worker capabilities within modular graph nodes.", "required": true, "acceptable_evidence": ["Technical keywords: node definition, domain-specific worker, scoped system prompt, tool binding, LangGraph node function.", "Explains defining separate functions for each agent role (e.g. triage agent, retrieval agent, booking agent) with dedicated prompts.", "Binds only relevant domain tools to each node to prevent parameter confusion and tool hallucination."]}, {"id": "KP2", "description": "Coordination topology and routing edges: configuring supervisor or router nodes with conditional transition logic.", "required": true, "acceptable_evidence": ["Technical keywords: supervisor node, conditional edge, Command/Router pattern, next-node dispatch, END criteria.", "Details implementing a supervisor node that returns the name of the next worker node to execute based on state evaluation.", "Configures conditional edges that route execution dynamically and return to the supervisor upon sub-task completion."]}, {"id": "KP3", "description": "Shared state management and message passing: maintaining a central StateGraph schema with structured reducers.", "required": true, "acceptable_evidence": ["Technical keywords: TypedDict State, add_messages reducer, conversation history, shared state context, message passing.", "Ensures all worker nodes read from and write to a standardized state schema, allowing seamless context handover.", "Appends tool outputs and agent reasoning steps cleanly to the conversation history."]}], "critical_failures": ["Implementing multi-agent logic as loose sequential functions without formal LangGraph nodes and conditional edges.", "Failing to define how the supervisor coordinates and delegates tasks across worker nodes.", "Omitting shared state definition or message passing mechanics in graph coordination."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'How did you design and implement a multi-agent architecture using frameworks like LangGraph for handling complex user queries?', '{"subcategory": "Multi-Agent Architecture for Complex User Query Fulfillment", "key_points": [{"id": "KP1", "description": "Complex query decomposition and multi-intent handling: breaking compound user requests into parallel or sequential sub-intents.", "required": true, "acceptable_evidence": ["Technical keywords: query decomposition, multi-intent classification, plan generation, sub-task graph, compound query handling.", "Explains analyzing queries that require multiple distinct capabilities (e.g. checking warranty status AND booking a technician appointment).", "Generates an actionable execution plan directing sub-intents to appropriate domain nodes."]}, {"id": "KP2", "description": "Inter-agent dependency resolution and intermediate synthesis: passing context between agents to resolve interdependent steps.", "required": true, "acceptable_evidence": ["Technical keywords: dependency resolution, state handoff, intermediate synthesis, context chaining, worker-to-worker context.", "Details how output from an upstream agent (e.g. vehicle diagnostic code lookup) is passed as structured input to a downstream scheduling agent.", "Synthesizes intermediate outputs into the global state before final customer response generation."]}, {"id": "KP3", "description": "Error recovery, fallback routing, and graceful degradation: handling sub-agent failures during complex query resolution.", "required": true, "acceptable_evidence": ["Technical keywords: fallback edges, error recovery, partial fulfillment, graceful degradation, human escalation.", "Explains how the system handles a failure in one sub-task without aborting the entire multi-turn workflow.", "Communicates partial results to the user while gracefully escalating the failed sub-action to a human representative."]}], "critical_failures": ["Treating complex multi-intent queries as simple single-shot RAG retrieval without query decomposition.", "Failing to explain how dependencies between distinct sub-tasks are managed across agent nodes.", "Omitting error handling and partial fulfillment strategies in multi-agent query execution."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and implement agentic workflows using LangChain and LangGraph, and what role did autonomous agents play in your system?', '{"subcategory": "Agentic Workflows using LangChain and LangGraph: Autonomous Agent Roles", "key_points": [{"id": "KP1", "description": "Evolution from LangChain linear chains to LangGraph cyclic graphs: moving beyond DAG limitations to support autonomous loops.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain chains (DAG), LangGraph StateGraph, cyclic graphs, autonomous loops, iterative reasoning, stateful workflows.", "Explains that LangChain chains execute deterministically in one direction (DAG), making retries, reflection, and loops difficult.", "Details how LangGraph introduces cyclic execution graphs where agents autonomously decide whether to continue looping or exit."]}, {"id": "KP2", "description": "Role of autonomous agents in tool selection and execution: empowering agents to formulate action plans and invoke external APIs.", "required": true, "acceptable_evidence": ["Technical keywords: autonomous tool calling, ReAct pattern (Reason + Act), dynamic parameter extraction, external APIs, tool schema.", "Describes how the LLM evaluates current state, selects appropriate tools from its schema, and executes actions autonomously.", "Analyzes tool responses and decides subsequent actions without hardcoded decision trees."]}, {"id": "KP3", "description": "Balancing autonomy with deterministic boundary control: combining autonomous node decisions with structural graph constraints.", "required": true, "acceptable_evidence": ["Technical keywords: bounded autonomy, structural guardrails, max iteration limits, validation nodes, deterministic fallback.", "Emphasizes that production systems require bounded autonomy: allowing the LLM freedom within a node while the graph enforces valid exit edges.", "Ensures autonomous agents cannot drift outside designated operational boundaries."]}], "critical_failures": ["Failing to explain the architectural difference between LangChain linear chains and LangGraph cyclic state graphs.", "Advocating for unbounded, unrestricted agent autonomy without structural graph guardrails.", "Omitting how autonomous agents evaluate tool outputs to plan subsequent execution steps."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and implement multi-agent workflows using LangGraph, including graph nodes, tool usage, and API/database interactions?', '{"subcategory": "Multi-Agent Workflows in LangGraph: Nodes, Tool Execution & API/DB Integration", "key_points": [{"id": "KP1", "description": "Graph node design and tool integration: binding structured tools to specific nodes using Pydantic schemas and ToolNode.", "required": true, "acceptable_evidence": ["Technical keywords: ToolNode, @tool decorator, Pydantic schema validation, tool binding, LangGraph node execution.", "Details defining reusable tools with explicit input validation schemas using Pydantic.", "Integrates prebuilt ToolNode components that execute tool calls emitted by LLM nodes and route results back into the state graph."]}, {"id": "KP2", "description": "Enterprise API and database connectivity: establishing reliable external connections (REST, SQL, vector stores) with connection management.", "required": true, "acceptable_evidence": ["Technical keywords: external API integration, database connection pooling, SQLAlchemy/Psycopg2, vector store client (Milvus), async I/O.", "Explains implementing database queries and third-party REST API calls within dedicated tool execution functions.", "Employs asynchronous execution and connection pools to maintain low latency during heavy I/O operations."]}, {"id": "KP3", "description": "State transition logic and conditional edge handling: routing execution between agent nodes and tool nodes based on tool call presence.", "required": true, "acceptable_evidence": ["Technical keywords: tools_condition, conditional edge, should_continue function, AIMessage.tool_calls, StateGraph routing.", "Details using standard conditional functions (e.g. tools_condition) that route to ToolNode if tool_calls exist, or to END/supervisor if complete.", "Updates graph state with tool output messages to inform the next agent reasoning step."]}], "critical_failures": ["Describing API and database calls as direct unvalidated prompt injections rather than structured tool execution nodes.", "Failing to explain conditional edge logic (e.g. checking AIMessage.tool_calls) that directs control flow to tool nodes.", "Omitting input validation or connection management for external database/API interactions."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How do you design and implement agentic workflows using LangGraph, and how do multiple agents communicate and coordinate to fulfill a user query?', '{"subcategory": "Agentic Workflows in LangGraph: Multi-Agent Communication & Coordination", "key_points": [{"id": "KP1", "description": "Communication protocols between agents: exchanging information via standardized message objects in a shared state graph.", "required": true, "acceptable_evidence": ["Technical keywords: inter-agent communication, BaseMessage, HumanMessage, AIMessage, ToolMessage, shared state context.", "Explains how agents communicate by reading and writing standardized message objects to the shared conversation history.", "Ensures downstream agents receive clear contextual summaries of upstream decisions without message loss."]}, {"id": "KP2", "description": "Coordination mechanisms: implementing supervisor arbitration or direct agent-to-agent peer handoffs.", "required": true, "acceptable_evidence": ["Technical keywords: supervisor coordinator, agent handoffs, Command(goto=...), router dispatch, delegation protocol.", "Details how a central supervisor inspects worker outputs and coordinates next actions, or how agents pass control directly via Command objects.", "Maintains clear execution ownership so only one agent operates on the state at any given step."]}, {"id": "KP3", "description": "Synthesis and final response delivery: consolidating findings from multiple agents into a unified, coherent user response.", "required": true, "acceptable_evidence": ["Technical keywords: response synthesizer node, context aggregation, final response generation, hallucination check, END transition.", "Passes accumulated findings from various domain agents to a final synthesizer node that formats an authoritative response.", "Ensures tone, branding, and compliance guidelines are consistently applied before exiting the graph."]}], "critical_failures": ["Describing agent communication as uncoordinated external API calls without graph state synchronization.", "Failing to explain how control is transferred between agents (supervisor or handoffs).", "Omitting the final synthesis step required to produce a unified response from multi-agent outputs."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How was the MCP client implemented as a node within LangGraph, and how did it interact with other agents?', '{"subcategory": "MCP Client Implementation as a LangGraph Node & Agent Interactions", "key_points": [{"id": "KP1", "description": "MCP Client initialization and lifecycle management: establishing client connections to remote MCP servers within the host process.", "required": true, "acceptable_evidence": ["Technical keywords: MCP Client session, stdio/SSE transport, ClientSession, server initialization, tool discovery lifecycle.", "Details configuring client connections over stdio or Server-Sent Events (SSE) to interact with remote MCP tool servers.", "Initializes sessions and retrieves available tool definitions, schemas, and resource templates dynamically."]}, {"id": "KP2", "description": "Wrapping MCP tools into LangGraph compatible tool nodes: converting MCP tool schemas into callable graph functions.", "required": true, "acceptable_evidence": ["Technical keywords: MCP tool wrapper, StructuredTool, dynamic tool schema, ToolNode, LangGraph integration.", "Explains converting MCP JSON-RPC tool schemas into LangChain/LangGraph compatible tool objects with input validation.", "Registers wrapped tools into the graph''s ToolNode for seamless agent invocation."]}, {"id": "KP3", "description": "Runtime interaction flow and security sandboxing: executing tools via MCP protocol and feeding results back to agent state.", "required": true, "acceptable_evidence": ["Technical keywords: JSON-RPC call_tool, payload serialization, state update, security isolation, error propagation.", "When an agent emits a tool call, the MCP node serializes arguments, executes call_tool over the transport, and handles responses.", "Appends ToolMessage results to the graph state while maintaining strict process isolation from sensitive backend servers."]}], "critical_failures": ["Confusing the MCP protocol client with a basic local Python function import.", "Failing to explain how MCP tool definitions are translated into LangGraph tool schemas.", "Omitting how MCP client execution connects to and updates the graph''s shared state."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you build an agentic AI system without using orchestration frameworks like LangGraph or LangChain, and what trade-offs would you face?', '{"subcategory": "Building Agentic AI Systems Without Frameworks: Architecture & Trade-offs", "key_points": [{"id": "KP1", "description": "Custom state machine and event loop design: implementing native Python loops with explicit state models and dispatch logic.", "required": true, "acceptable_evidence": ["Technical keywords: custom state machine, while loop event loop, native Python dataclasses/Pydantic, transition table, dispatch function.", "Explains implementing an explicit while-loop that tracks execution state, formats prompt messages, and dispatches tool calls.", "Constructs deterministic state transitions using standard dictionary dispatch or state pattern classes."]}, {"id": "KP2", "description": "Direct provider API tool calling and serialization: calling OpenAI/Anthropic SDKs natively and handling tool payloads manually.", "required": true, "acceptable_evidence": ["Technical keywords: native provider SDK (openai.chat.completions, anthropic.messages), tool schema definition, manual JSON parsing, function dispatch.", "Directly defines tool schemas in JSON Schema format and inspects raw API response objects (e.g. tool_calls).", "Executes corresponding local functions and appends role=''tool''/''user'' messages back to the request array."]}, {"id": "KP3", "description": "Architectural trade-offs: total control and minimal dependency overhead vs. rebuilding complex orchestration plumbing.", "required": true, "acceptable_evidence": ["Technical keywords: zero framework overhead, debuggability, dependency reduction vs. manual checkpointer, lack of ecosystem tools, maintenance cost.", "Benefits: removes bloated abstractions, simplifies stack traces, eliminates breaking library changes, and optimizes execution speed.", "Drawbacks: requires writing custom state persistence, memory pruning, time-travel debugging, and multi-agent coordination from scratch."]}], "critical_failures": ["Failing to detail how an agent loop, state tracking, and tool execution are implemented natively in code.", "Presenting an unbalanced view that ignores either the major benefits (control, lightweight) or drawbacks (boilerplate, maintenance).", "Failing to address state persistence and recursion limits in custom agent loops."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'So what is the difference between this LangChain and LangGraph?', '{"subcategory": "Architectural Distinctions: LangChain vs. LangGraph", "key_points": [{"id": "KP1", "description": "Execution topology: LangChain''s linear DAG chains vs. LangGraph''s cyclic state graphs.", "required": true, "acceptable_evidence": ["Technical keywords: Directed Acyclic Graph (DAG), linear chains (LCEL), cyclic graphs, StateGraph, iterative loops, branching.", "LangChain is fundamentally built around DAG pipelines where steps execute sequentially in one direction without easy loops.", "LangGraph is specifically designed for cyclic workflows where execution can loop back, evaluate results, self-correct, and branch dynamically."]}, {"id": "KP2", "description": "State management: transient chain memory vs. first-class persistent state checkpointing.", "required": true, "acceptable_evidence": ["Technical keywords: centralized state schema, TypedDict, checkpointer (Postgres/Redis), thread_id, state persistence, time-travel debugging.", "LangChain treats memory as conversational buffers passed into prompts, primarily scoped to single-pass chains.", "LangGraph treats state as a centralized, typed object that updates via reducers and persists across turns using durable checkpointers."]}, {"id": "KP3", "description": "Agentic control and Human-in-the-Loop: rigid abstractions vs. granular graph interrupts and multi-agent coordination.", "required": true, "acceptable_evidence": ["Technical keywords: interrupt(), breakpoint, Human-in-the-Loop (HITL), multi-agent coordination, supervisor topology, fine-grained control.", "LangChain''s legacy agent executors act as black boxes with limited control over intermediate decisions and pauses.", "LangGraph provides first-class interrupt() primitives to pause execution for human approval and orchestrates complex multi-agent topologies."]}], "critical_failures": ["Claiming LangGraph is merely an updated version of LangChain with identical architecture.", "Failing to articulate the fundamental DAG vs. cyclic graph topological difference.", "Omitting state checkpointing and Human-in-the-Loop interrupt capabilities in LangGraph."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'How do you evaluate whether a startup environment is the right fit for your next career move?', '{"subcategory": "Candidate Career Strategy: Startup Fit Evaluation & Impact Alignment", "key_points": [{"id": "KP1", "description": "Assessing product-market fit, technical problem space, and market opportunity: evaluating whether the startup''s core mission aligns with career goals.", "required": true, "acceptable_evidence": ["Technical keywords: product-market fit (PMF), problem space, GenAI market validation, competitive moat, business runway, technical traction.", "Evaluates the uniqueness and sustainability of the startup''s AI product compared to foundation model commodities.", "Examines runway, funding tier, and growth velocity to ensure stability and impact opportunity."]}, {"id": "KP2", "description": "Engineering autonomy, high-velocity culture, and ownership scope: seeking environments with wide technical scope and rapid iteration.", "required": true, "acceptable_evidence": ["Technical keywords: ownership culture, end-to-end execution, rapid prototyping, cross-functional agility, minimal bureaucracy, wear multiple hats.", "Values the ability to architect systems from zero to production without layers of bureaucratic red tape.", "Thrives in environments requiring rapid experimentation, customer feedback loops, and broad technical ownership."]}, {"id": "KP3", "description": "Leadership alignment and engineering standards: evaluating executive vision, engineering rigor, and technical debt management.", "required": true, "acceptable_evidence": ["Technical keywords: technical leadership vision, architectural standards, pragmatism vs technical debt, transparent communication.", "Assesses whether founders understand the realities and limitations of AI systems (latency, evaluation, cost).", "Ensures leadership balances fast time-to-market with sound architectural foundations and psychological safety."]}], "critical_failures": ["Giving a vague or passive response that focuses solely on compensation or equity without discussing technical alignment or culture.", "Failing to evaluate product-market fit or technical challenges unique to startup environments.", "Ignoring the realities of startup execution: autonomy, velocity, ambiguity, and risk tolerance."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'How would your colleagues describe your strengths in a team environment, particularly regarding communication and collaboration?', '{"subcategory": "Team Strengths: Communication, Collaboration & Cross-Functional Alignment", "key_points": [{"id": "KP1", "description": "Transparent, proactive technical communication: articulating complex architectural concepts clearly to both technical and non-technical peers.", "required": true, "acceptable_evidence": ["Technical keywords: proactive communication, technical clarity, cross-functional translation, design documentation (RFCs), stakeholder alignment.", "Explains translating probabilistic AI behavior and latency constraints into understandable business impacts for product managers.", "Authors detailed architectural decision records (ADRs) to establish clarity before writing code."]}, {"id": "KP2", "description": "Constructive code reviews, pair programming, and peer mentorship: elevating team quality through collaborative feedback.", "required": true, "acceptable_evidence": ["Technical keywords: constructive code review, empathetic feedback, mentorship, knowledge sharing, pair programming, blameless culture.", "Focuses code reviews on system architecture, maintainability, and edge cases while fostering psychological safety.", "Actively mentors junior engineers on debugging LLM workflows, evaluation frameworks, and MLOps best practices."]}, {"id": "KP3", "description": "Cross-functional collaboration and delivering shared outcomes: partnering across data engineering, frontend, and product teams.", "required": true, "acceptable_evidence": ["Technical keywords: cross-functional collaboration, shared ownership, unblocking teammates, blameless post-mortems, alignment.", "Works closely with frontend teams to define clean API schemas and streaming protocols (SSE) for AI interfaces.", "Participates in blameless post-mortems after production incidents to strengthen team resilience and processes."]}], "critical_failures": ["Portraying oneself as an isolated individual contributor who avoids team communication and documentation.", "Failing to provide concrete examples of how communication improved team outcomes or unblocked teammates.", "Omitting cross-functional collaboration with product, data, or frontend stakeholders."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'How is role-based access control (RBAC) implemented to manage authentication credentials and control data visibility for different user roles in your system?', '{"subcategory": "Role-Based Access Control (RBAC) & Metadata Visibility Architecture", "key_points": [{"id": "KP1", "description": "Authentication credential management and identity propagation: validating user identity tokens (JWT) and claims.", "required": true, "acceptable_evidence": ["Technical keywords: JSON Web Tokens (JWT), OAuth2 / OIDC, identity provider (Keycloak, Cognito, Okta), claims validation, token propagation.", "Validates cryptographically signed JWT tokens at the API gateway, extracting role claims and tenant IDs.", "Propagates validated identity context across internal microservices and downstream retrieval nodes."]}, {"id": "KP2", "description": "Enforcing RBAC at the retrieval layer via metadata pre-filtering: restricting vector search to authorized document partitions.", "required": true, "acceptable_evidence": ["Technical keywords: metadata pre-filtering, vector database filter (Milvus, Pinecone), department_id, security_clearance, partition keys, access control list (ACL).", "Injects user permissions directly into vector query filter expressions: e.g. expr=''department in [\"HR\", \"Public\"] && clearance <= 2''.", "Guarantees that vector similarity search never computes proximity over or returns unauthorized document chunks."]}, {"id": "KP3", "description": "Multi-tenant data isolation and defense-in-depth: combining transport encryption, database multi-tenancy, and audit logging.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenant isolation, collection-level partitioning, least-privilege access, immutable audit logging, defense-in-depth.", "Isolates tenant data using dedicated partitions or collections to prevent cross-tenant data leakage.", "Logs all retrieval queries with requesting user IDs and retrieved document IDs for enterprise compliance auditing."]}], "critical_failures": ["Suggesting post-retrieval filtering in the LLM prompt (asking the LLM not to read unauthorized text), which causes severe data leakage.", "Failing to explain how user roles and tokens are validated before executing retrieval queries.", "Omitting metadata pre-filtering in the vector database to enforce access boundaries."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'How did you utilize AWS Lambda in your architecture, and what strategies did you consider for handling cold start issues?', '{"subcategory": "AWS Lambda in AI Architectures: Cold Start Mitigation & Workload Suitability", "key_points": [{"id": "KP1", "description": "Role of AWS Lambda in event-driven AI pipelines: executing lightweight preprocessing, API orchestration, and trigger automation.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Lambda, serverless architecture, event-driven triggers (S3 PutObject, SQS, EventBridge), lightweight preprocessing, API Gateway.", "Uses Lambda functions to respond to document upload events in S3, triggering initial validation, text extraction, and queue dispatch.", "Acts as lightweight serverless glue between API Gateway, queuing systems, and backend model services."]}, {"id": "KP2", "description": "Root causes of cold start latency in ML workloads: heavy runtime dependencies and container image initialization overhead.", "required": true, "acceptable_evidence": ["Technical keywords: cold start latency, package initialization (PyTorch, Transformers), container image size, memory allocation, execution environment boot.", "Explains that loading large ML libraries (e.g. PyTorch, tokenizers) into Lambda memory adds seconds of cold start initialization.", "Identifies VPC attachment and container image extraction as contributing factors to initial invocation latency."]}, {"id": "KP3", "description": "Cold start mitigation strategies and architectural boundaries: applying provisioned concurrency, lightweight runtimes, and external inference offloading.", "required": true, "acceptable_evidence": ["Technical keywords: Provisioned Concurrency, Lambda SnapStart, ONNX Runtime, external inference endpoints (SageMaker, Bedrock), memory overprovisioning.", "Configures Provisioned Concurrency to keep pre-warmed execution environments ready for latency-critical API paths.", "Offloads heavy model inference to dedicated endpoints (SageMaker/Bedrock), keeping Lambda strictly for lightweight orchestration using ONNX or API calls."]}], "critical_failures": ["Attempting to run full heavy LLM model weights directly inside AWS Lambda execution environments.", "Failing to provide concrete technical solutions for cold start mitigation (Provisioned Concurrency, offloading inference).", "Ignoring dependency bloat and initialization overhead in serverless Python runtimes."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'How have you applied AWS and ML frameworks together to build scalable AI solutions?', '{"subcategory": "Synergistic AWS Services & ML Frameworks for Scalable AI Solutions", "key_points": [{"id": "KP1", "description": "AWS cloud infrastructure backbone: orchestrating storage, managed compute, and container clusters for AI workloads.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3 (data lake), Amazon EKS / ECS (container orchestration), AWS Batch, AWS Lambda, IAM role-based security.", "Utilizes S3 for raw document storage and processed parquet feature datasets with lifecycle policies.", "Deploys containerized model serving microservices across Amazon EKS with auto-scaling GPU/CPU node groups."]}, {"id": "KP2", "description": "Managed AI/ML platforms and foundation model services: leveraging SageMaker and Bedrock for training, hosting, and inference.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon SageMaker (endpoints, pipelines, feature store), AWS Bedrock (Claude, Titan), managed endpoints, auto-scaling inference.", "Uses SageMaker for scalable distributed model training, hyperparameter tuning, and real-time inference endpoints.", "Leverages AWS Bedrock for managed foundation model access with enterprise VPC security and pay-per-token pricing."]}, {"id": "KP3", "description": "Integration with open-source ML frameworks: deploying PyTorch, Hugging Face, LangGraph, and vector databases within AWS environments.", "required": true, "acceptable_evidence": ["Technical keywords: PyTorch, Hugging Face Transformers, LangGraph, Milvus on EKS, OpenSearch Service, hybrid architecture.", "Packages custom ML pipelines built with PyTorch and Transformers into Docker containers running on AWS infrastructure.", "Integrates LangGraph orchestration microservices with Amazon OpenSearch Service or self-hosted Milvus clusters for vector search."]}], "critical_failures": ["Listing cloud service names without explaining how they integrate with ML frameworks to solve end-to-end problems.", "Failing to address scalability, auto-scaling, or GPU resource provisioning.", "Omitting foundation model managed services (Bedrock/SageMaker) or open-source framework deployment patterns."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How would you design your system to be vendor-agnostic across cloud providers like AWS, GCP, and Azure?', '{"subcategory": "Vendor-Agnostic AI System Design Across Cloud Providers (AWS, GCP, Azure)", "key_points": [{"id": "KP1", "description": "Containerized microservices and standard orchestration: adopting Kubernetes and Docker to decouple compute from proprietary runtimes.", "required": true, "acceptable_evidence": ["Technical keywords: Docker containerization, Kubernetes (Kube-native), Helm charts, Terraform (Infrastructure as Code), cloud-agnostic compute.", "Packages all application logic, model serving (FastAPI/Triton), and agent workflows into standardized OCI containers.", "Deploys workloads onto vanilla Kubernetes abstractions, allowing migration between EKS, GKE, and AKS with identical manifests."]}, {"id": "KP2", "description": "Abstracted storage and vector database layers: utilizing open-source data stores and standard storage abstractions.", "required": true, "acceptable_evidence": ["Technical keywords: S3-compatible object storage (MinIO, Ceph), open-source vector databases (Milvus, Qdrant, Chroma), PostgreSQL, abstraction interfaces.", "Uses S3-compatible API abstractions rather than proprietary cloud blob SDKs, allowing seamless switching across storage backends.", "Deploys open-source vector databases (e.g. Milvus distributed) on Kubernetes rather than binding to proprietary cloud vector services."]}, {"id": "KP3", "description": "Model gateway abstractions and multi-provider SDKs: shielding applications from proprietary foundation model APIs.", "required": true, "acceptable_evidence": ["Technical keywords: LLM gateway (LiteLLM, Portkey), OpenAI-compatible API format, provider-agnostic interface, fallback routing.", "Routes all model calls through a unified gateway (e.g. LiteLLM) exposing standard OpenAI-compatible endpoints.", "Allows swapping underlying LLM providers (AWS Bedrock, Azure OpenAI, GCP Vertex AI, self-hosted vLLM) via environment variables without code changes."]}], "critical_failures": ["Tightly coupling application code to proprietary, cloud-specific APIs (e.g. native AWS Bedrock SDK, DynamoDB-only APIs).", "Failing to explain how Kubernetes and Infrastructure as Code enable multi-cloud portability.", "Omitting model gateway abstractions for foundation model provider interoperability."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you approach learning and adopting new technologies or architectural changes in a fast-evolving environment?', '{"subcategory": "Continuous Learning & Rapid Technology Adoption Strategy in AI", "key_points": [{"id": "KP1", "description": "Systematic evaluation framework for emerging tools: establishing proof-of-concept benchmarks before adopting new libraries or models.", "required": true, "acceptable_evidence": ["Technical keywords: technology evaluation framework, POC benchmarking, evaluation criteria, architectural trade-offs, developer velocity vs stability.", "Evaluates new tools against strict production criteria: latency, community health, license, maintainability, and regression safety.", "Avoids blindly adopting trending hype tools without validating measurable performance gains on internal datasets."]}, {"id": "KP2", "description": "Continuous information filtering and community engagement: tracking research papers, open-source repositories, and technical RFCs.", "required": true, "acceptable_evidence": ["Technical keywords: arXiv preprints, GitHub release notes, engineering blogs, RFC reviews, open-source contributions, technical spikes.", "Monitors key foundational releases (e.g. Hugging Face, LangChain/LangGraph, vLLM, DeepSeek, Anthropic research).", "Conducts rapid time-boxed technical spikes to prototype and pressure-test new capabilities."]}, {"id": "KP3", "description": "Knowledge sharing and architectural governance: disseminating learnings to cross-functional teams through design docs and brown-bag sessions.", "required": true, "acceptable_evidence": ["Technical keywords: architectural decision records (ADRs), tech talks, internal wikis, brown-bag sessions, engineering enablement.", "Documents architectural patterns and migration recipes in team RFCs to prevent knowledge silos.", "Mentors team members on adopting new paradigms (e.g. moving from chain scripts to stateful graph agents)."]}], "critical_failures": ["Advocating for rewriting production systems whenever a new trending library is released.", "Describing passive, ad-hoc browsing without a structured technical evaluation or benchmarking methodology.", "Omitting knowledge sharing and documentation practices for team enablement."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'EASY', 'SPECIFIC', 60, 'How would you design state to maintain conversation history across multiple user interactions?', '{"subcategory": "Conversation History & Multi-Turn State Management Architecture", "key_points": [{"id": "KP1", "description": "State schema and message session persistence: binding multi-turn interactions to durable session keys in distributed storage.", "required": true, "acceptable_evidence": ["Technical keywords: session_id / thread_id, Redis cache, PostgreSQL, message buffer, serialized BaseMessage, TTL expiration.", "Partitions conversation states by unique session/thread identifiers stored in low-latency key-value or relational stores.", "Stores structured message tuples (user, assistant, tool calls) with timestamps and role metadata."]}, {"id": "KP2", "description": "Context window management and history pruning: balancing semantic recall with token budget limits.", "required": true, "acceptable_evidence": ["Technical keywords: sliding window buffer, token counter (tiktoken), conversational summary buffer, semantic compression, prune.", "Maintains recent turns verbatims while summarizing older turns to prevent context window overflow and quadratic attention latency.", "Applies token estimation to truncate excess message history before model inference."]}, {"id": "KP3", "description": "Multi-agent and branch state isolation: preserving distinct sub-dialogue contexts during task handoffs.", "required": true, "acceptable_evidence": ["Technical keywords: state branching, LangGraph StateGraph, child thread checkpoints, context isolation, state reconciliation.", "Isolates worker agent scratchpads from the user-facing dialogue history to keep prompts clean.", "Reconciles finalized task outcomes back into the primary conversation memory."]}], "critical_failures": ["Relying on in-memory global Python variables that lose state across concurrent requests or container restarts.", "Appending unbounded raw message history without context window limits or summarization.", "Failing to explain how user sessions are uniquely partitioned and retrieved."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'How does BERTScore work, and why did you use it for evaluating generated outputs?', '{"subcategory": "BERTScore Evaluation Methodology for Generated Text Fidelity", "key_points": [{"id": "KP1", "description": "Core mechanics of BERTScore: computing token-level contextual embedding cosine similarity using pretrained transformers.", "required": true, "acceptable_evidence": ["Technical keywords: BERTScore, contextual embeddings (RoBERTa, DeBERTa), cosine similarity matrix, greedy matching, token alignment.", "Generates contextual vector embeddings for each token in candidate and reference sentences.", "Computes pairwise cosine similarities between all token representations, reflecting contextual meaning rather than surface string forms."]}, {"id": "KP2", "description": "Precision, Recall, and F1 formulation with importance weighting: calculating soft semantic overlap.", "required": true, "acceptable_evidence": ["Technical keywords: Precision_BERT, Recall_BERT, F1_BERT, maximum similarity matching, inverse document frequency (IDF) weighting.", "Recall matches each reference token to the most similar candidate token; Precision matches each candidate token to reference tokens.", "Applies IDF weighting to give higher significance to rare content words over common stopwords."]}, {"id": "KP3", "description": "Advantages over n-gram metrics (BLEU/ROUGE): robust handling of paraphrasing, synonyms, and word order variations.", "required": true, "acceptable_evidence": ["Technical keywords: n-gram limitations, synonym capture, paraphrase robustness, lexical vs semantic matching, evaluation correlation.", "Unlike BLEU or ROUGE which require exact lexical n-gram matches, BERTScore credits valid synonyms and alternative phrasing.", "Correlates much higher with human judgment on factual and semantic text evaluation."]}], "critical_failures": ["Confusing BERTScore with basic n-gram overlap metrics like ROUGE or BLEU.", "Claiming BERTScore requires training a new classification model from scratch.", "Failing to explain that BERTScore uses token-level contextual embedding cosine similarities."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How have you integrated LLMs into applications, particularly using AWS services like Bedrock or SageMaker?', '{"subcategory": "LLM Integration in Production via AWS Bedrock & SageMaker", "key_points": [{"id": "KP1", "description": "AWS Bedrock managed foundation model integration: serverless invocation, streaming responses, and prompt management.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock, boto3 client (bedrock-runtime), invoke_model / invoke_model_with_response_stream, Anthropic Claude, serverless API.", "Invokes enterprise foundation models (e.g. Claude 3.5 Sonnet) via Bedrock without managing underlying GPU clusters.", "Implements response streaming via Server-Sent Events (SSE) to achieve sub-second perceived latency for end users."]}, {"id": "KP2", "description": "AWS SageMaker dedicated model hosting: deploying custom open-weights models and specialized embeddings.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon SageMaker real-time endpoints, Hugging Face Deep Learning Containers (DLC), Triton Inference Server, custom embeddings, GPU instances.", "Hosts custom fine-tuned models (e.g. Llama-3-8B) or dense bi-encoders on SageMaker multi-model or dedicated GPU endpoints.", "Configures endpoint autoscaling policies based on InvocationPerInstance metrics."]}, {"id": "KP3", "description": "Security, IAM authentication, and enterprise VPC isolation: securing model communication in compliance boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: AWS IAM roles, VPC private endpoints (PrivateLink), Bedrock Guardrails, KMS encryption, zero data retention policies.", "Secures model API access using IAM role delegation without hardcoded API keys.", "Applies Bedrock Guardrails to filter PII, toxicity, and unauthorized topics before model response dispatch."]}], "critical_failures": ["Hardcoding raw third-party API keys in client-side code instead of using AWS IAM role-based authentication.", "Failing to differentiate between serverless managed APIs (Bedrock) and dedicated hosted containers (SageMaker).", "Omitting response streaming or enterprise VPC security considerations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What advantages do transformer architectures offer over traditional sequence models like RNNs?', '{"subcategory": "Transformer Architectures vs. Traditional Sequence Models (RNNs/LSTMs)", "key_points": [{"id": "KP1", "description": "Parallel processing vs. sequential recurrence: replacing O(n) recurrent dependencies with O(1) sequential training depth.", "required": true, "acceptable_evidence": ["Technical keywords: non-recurrent parallelization, sequential bottleneck, O(n) recurrent time complexity, GPU matrix parallelization, training throughput.", "RNNs and LSTMs must process tokens sequentially step-by-step (hidden state h_t depends on h_{t-1}), preventing GPU parallelization during training.", "Transformers process all tokens simultaneously in parallel matrix operations, dramatically reducing training wall-clock time."]}, {"id": "KP2", "description": "Self-attention mechanism and constant path length: mitigating vanishing gradients across long contexts.", "required": true, "acceptable_evidence": ["Technical keywords: scaled dot-product self-attention, maximum path length O(1), long-range dependencies, vanishing gradients, catastrophic forgetting.", "In RNNs, signals degrade over long sequences due to gradient decay over sequential backpropagation through time (BPTT).", "Self-attention connects any token directly to every other token with an O(1) path length, capturing long-distance context without degradation."]}, {"id": "KP3", "description": "Positional encodings and scalability: enabling pretraining on massive web-scale corpora.", "required": true, "acceptable_evidence": ["Technical keywords: positional encodings (sinusoidal, RoPE), compute scaling laws, foundation model pretraining, transfer learning.", "Since transformers lack inherent sequential ordering, positional encodings inject token order into representations.", "Massive scalability allowed transformers to obey empirical scaling laws, enabling modern foundation models."]}], "critical_failures": ["Claiming that Transformers require sequential step-by-step recurrent execution during training.", "Failing to explain how self-attention eliminates vanishing gradient bottlenecks over long sequences.", "Omitting the role of parallel GPU matrix multiplication in Transformer training efficiency."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What experience do you have with cloud platforms, and how have you used services like AWS Bedrock or SageMaker in your workflows?', '{"subcategory": "Cloud Platform Experience: AWS Bedrock & SageMaker in MLOps Workflows", "key_points": [{"id": "KP1", "description": "Operationalizing AWS Bedrock: prompt templating, knowledge base integration, and serverless foundation model scaling.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Bedrock runtime, Bedrock Knowledge Bases, Claude 3/3.5, prompt management, pay-as-you-go economics, token limits.", "Configures Bedrock integrations for real-time customer assistant synthesis, managing system prompts and temperature hyperparameters.", "Leverages managed model endpoints to eliminate GPU provisioning overhead for generative workflows."]}, {"id": "KP2", "description": "SageMaker lifecycle automation: managed model training, processing jobs, and real-time inference hosting.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Training Jobs, Processing Jobs, Model Registry, Real-Time Endpoints, Spot Instances, Deep Learning Containers.", "Executes data preparation using SageMaker Processing jobs and trains embedding/predictive models on GPU-backed training jobs.", "Registers versioned model artifacts into SageMaker Model Registry for automated staging-to-production promotion."]}, {"id": "KP3", "description": "End-to-end cloud infrastructure integration: connecting S3, EKS/ECS, CloudWatch, and IAM security boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3, Amazon CloudWatch (latency/error alarms), IAM execution roles, EKS container cluster, VPC private subnets.", "Stores training datasets and vector indexes in S3 buckets configured with server-side KMS encryption.", "Monitors model invocation latency, throttling exceptions, and 5xx errors via CloudWatch dashboards and automated alerts."]}], "critical_failures": ["Listing AWS service acronyms without demonstrating practical implementation experience in training or inference.", "Failing to explain how SageMaker and Bedrock serve distinct use cases in an enterprise AI portfolio.", "Omitting security, monitoring, or cost governance considerations in cloud ML workflows."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What is the most important component of a Transformer architecture?', '{"subcategory": "Critical Core Component of Transformer Architecture: Multi-Head Self-Attention", "key_points": [{"id": "KP1", "description": "Multi-Head Self-Attention as the primary engine: dynamically routing information across token representations based on pairwise affinity.", "required": true, "acceptable_evidence": ["Technical keywords: Multi-Head Attention (MHA), Scaled Dot-Product Attention, Queries (Q), Keys (K), Values (V), representation subspaces.", "Identifies multi-head self-attention as the central breakthrough enabling transformers to model context without recurrence.", "Explains projecting input vectors into multiple distinct Q, K, V subspaces to attend to information from different representation aspects simultaneously."]}, {"id": "KP2", "description": "Mathematical formulation and scaling factor: softmax(QK^T / sqrt(d_k)) * V mechanics.", "required": true, "acceptable_evidence": ["Technical keywords: QK^T matrix multiplication, sqrt(d_k) scaling factor, softmax normalization, attention weights, weighted sum of Values.", "Details how query-key dot products compute unnormalized attention logits.", "Explains dividing by sqrt(d_k) to prevent dot products from growing excessively large, avoiding vanishing gradients in the softmax region."]}, {"id": "KP3", "description": "Supporting foundational components: layer normalization, residual connections, and feed-forward networks (FFN).", "required": true, "acceptable_evidence": ["Technical keywords: residual connections (Add & Norm), LayerNorm / RMSNorm, position-wise Feed-Forward Network (FFN), non-linear projection.", "Explains that residual skip connections allow stable gradient flow through hundreds of transformer layers.", "Details the point-wise FFN applying non-linear transformations (e.g. SwiGLU, GeLU) to process attended representations."]}], "critical_failures": ["Claiming recurrent hidden state updates are the core component of Transformers.", "Failing to explain the Query, Key, Value attention formulation or the purpose of the sqrt(d_k) scaling factor.", "Omitting the function of Multi-Head projections in capturing diverse contextual relationships."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What is your level of familiarity with deep learning models, particularly in NLP and transformer-based architectures?', '{"subcategory": "Deep Learning & Transformer-Based Architecture Proficiency in NLP", "key_points": [{"id": "KP1", "description": "Encoder-only, Decoder-only, and Encoder-Decoder paradigms: distinguishing structural topologies and their optimal tasks.", "required": true, "acceptable_evidence": ["Technical keywords: Encoder-only (BERT, RoBERTa), Decoder-only (GPT, Llama, Claude), Encoder-Decoder (T5, BART), causal masking, bidirectional context.", "Encoder-only models utilize bidirectional attention for classification, NER, and dense feature embedding extraction.", "Decoder-only models use causal (autoregressive) attention masks for left-to-right text generation and conversational reasoning.", "Encoder-Decoder models excel at sequence-to-sequence translation and abstractive document summarization."]}, {"id": "KP2", "description": "Pretraining objectives and tokenization: understanding masked language modeling, causal prediction, and subword algorithms.", "required": true, "acceptable_evidence": ["Technical keywords: Byte-Pair Encoding (BPE), WordPiece, Masked Language Modeling (MLM), Next-Token Prediction (NTP), cross-entropy loss.", "Explains subword tokenization handling out-of-vocabulary terms efficiently without vocabulary explosion.", "Details pretraining loss functions driving model weight convergence across massive text corpora."]}, {"id": "KP3", "description": "Hands-on implementation and fine-tuning frameworks: utilizing PyTorch and Hugging Face in production pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: PyTorch, Hugging Face Transformers, Accelerate, PEFT/LoRA, flash-attention, tensor parallelism, vLLM serving.", "Details practical experience loading, quantizing (bitsandbytes), and fine-tuning transformer checkpoints.", "Applies modern inference accelerators (FlashAttention-2, vLLM) to optimize throughput and memory footprint."]}], "critical_failures": ["Confusing bidirectional encoders (BERT) with autoregressive causal decoders (GPT/Llama).", "Failing to articulate the operational trade-offs between different transformer architectural families.", "Lacking hands-on familiarity with modern NLP tooling (Hugging Face, PyTorch, vLLM)."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What motivated your transition from your previous company to a role focused on newer technologies like LLMs and advanced machine learning?', '{"subcategory": "Career Transition Motivation: Traditional Engineering to LLMs & Advanced ML", "key_points": [{"id": "KP1", "description": "Strategic technical inflection point: recognizing the paradigm shift from rule-based and predictive models to Generative AI.", "required": true, "acceptable_evidence": ["Technical keywords: paradigm shift, Generative AI breakthrough, in-context learning, foundation models, cognitive automation, career pivot.", "Identifies how LLMs unlocked solutions to previously intractable natural language and workflow orchestration problems.", "Recognized an opportunity to combine backend systems engineering with cutting-edge probabilistic AI."]}, {"id": "KP2", "description": "Proactive upskilling and hands-on project execution: demonstrating deliberate initiative in mastering modern GenAI stacks.", "required": true, "acceptable_evidence": ["Technical keywords: deliberate practice, open-source experimentation, RAG development, prompt engineering, LangChain/LangGraph, research papers.", "Articulates building functional prototypes, studying attention mechanisms, and mastering vector search architectures.", "Demonstrates practical problem-solving rather than theoretical curiosity alone."]}, {"id": "KP3", "description": "Focus on high-leverage production impact: translating modern AI capabilities into measurable business value.", "required": true, "acceptable_evidence": ["Technical keywords: business ROI, automation leverage, customer experience impact, production-grade AI, pragmatic engineering.", "Emphasizes moving to a role where AI models directly automate complex enterprise workflows and reduce operational costs.", "Aligns technical passion with delivering durable, scalable business products."]}], "critical_failures": ["Giving a purely superficial or trend-chasing answer (''everyone is doing AI now'') without technical substance.", "Failing to demonstrate concrete learning initiatives or technical projects undertaken during the transition.", "Ignoring business impact and practical enterprise engineering considerations."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Tell me about your use of LoRA for fine tuning. Was it LoRA or QLoRA? And why choose that method over full fine tuning?', '{"subcategory": "LoRA vs. QLoRA Parameter-Efficient Fine-Tuning Methodology", "key_points": [{"id": "KP1", "description": "Mathematical mechanics of Low-Rank Adaptation (LoRA): freezing base weights and injecting low-rank decomposition matrices.", "required": true, "acceptable_evidence": ["Technical keywords: Low-Rank Adaptation (LoRA), rank r, scaling factor alpha, Delta W = B * A, rank decomposition, frozen base weights.", "Freezes the pre-trained model parameter matrix W_0 and decomposes weight updates into two low-rank matrices A and B (where r << d).", "Reduces trainable parameters by over 99%, dramatically cutting optimizer memory and storage overhead."]}, {"id": "KP2", "description": "QLoRA innovations: enabling fine-tuning on consumer hardware via 4-bit NormalFloat quantization and double quantization.", "required": true, "acceptable_evidence": ["Technical keywords: QLoRA, NF4 (4-bit NormalFloat), Double Quantization (DQ), Paged Optimizers, bitsandbytes, VRAM reduction.", "Quantizes frozen base weights to 4-bit NormalFloat (information-theoretically optimal for normal distributions).", "Applies double quantization to quantize quantization constants, and uses paged optimizers to manage memory spikes during gradient checkpoints."]}, {"id": "KP3", "description": "Decision rationale over Full Fine-Tuning: compute constraints, catastrophic forgetting, and modular adapter deployment.", "required": true, "acceptable_evidence": ["Technical keywords: VRAM budget, catastrophic forgetting mitigation, modular adapters, multi-tenant serving, adapter merging.", "Full fine-tuning requires 16-bit optimizer states (AdamW) requiring 4-6x base model VRAM, demanding expensive multi-GPU clusters.", "LoRA prevents catastrophic forgetting of general reasoning while producing tiny (~50MB-200MB) adapter files that can be hot-swapped per task."]}], "critical_failures": ["Failing to explain how low-rank matrix decomposition (A and B matrices) works mathematically in LoRA.", "Confusing LoRA with full fine-tuning or basic prompt engineering.", "Omitting the memory-saving innovations of QLoRA (NF4 quantization, paged optimizers)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'What is your experience with neural network architectures, including transformers and their components?', '{"subcategory": "Neural Network & Transformer Architectural Components", "key_points": [{"id": "KP1", "description": "Foundational feedforward and deep learning layers: linear projections, non-linear activation functions, and normalization.", "required": true, "acceptable_evidence": ["Technical keywords: dense linear layers, activation functions (ReLU, GELU, SwiGLU), LayerNorm / RMSNorm, residual connections, backpropagation.", "Explains how linear transformations and non-linear activations allow networks to learn complex non-linear decision boundaries.", "Highlights residual connections preserving gradient flow across deep network backbones."]}, {"id": "KP2", "description": "Transformer self-attention and attention variants: multi-head, grouped-query, and cross-attention.", "required": true, "acceptable_evidence": ["Technical keywords: Multi-Head Attention (MHA), Grouped-Query Attention (GQA), Multi-Query Attention (MQA), cross-attention, KV cache.", "Details how self-attention computes dynamic weights across input tokens.", "Explains modern optimizations like Grouped-Query Attention (GQA) sharing key-value heads to reduce KV cache memory during inference."]}, {"id": "KP3", "description": "Positional representations and generation mechanisms: encoding sequence order and decoding next tokens.", "required": true, "acceptable_evidence": ["Technical keywords: Rotary Position Embeddings (RoPE), ALiBi, causal attention mask, autoregressive generation, temperature, top-p sampling.", "Details how RoPE applies rotation matrices to queries and keys to naturally capture relative distance between tokens.", "Describes causal masking enforcing triangular attention masks during autoregressive token generation."]}], "critical_failures": ["Confusing basic feedforward neural networks with Transformer architectures.", "Failing to explain how positional information (e.g. RoPE) is incorporated into non-recurrent transformers.", "Omitting modern attention optimizations like Grouped-Query Attention (GQA) or KV cache."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'How do you design scalable AI systems that integrate LLMs, APIs, and cloud infrastructure?', '{"subcategory": "Scalable AI System Design Integrating LLMs, APIs & Cloud Infrastructure", "key_points": [{"id": "KP1", "description": "Asynchronous API layer and streaming architecture: handling long-running model inference without blocking client connections.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, asynchronous event loop (async/await), Server-Sent Events (SSE), WebSockets, non-blocking I/O, worker pools (Uvicorn/Gunicorn).", "Builds non-blocking API gateways that stream token chunks back to clients as they are generated by the model.", "Prevents thread pool exhaustion by properly utilizing asynchronous I/O for all downstream network calls."]}, {"id": "KP2", "description": "Queue-based task decoupling and rate management: buffering requests and managing provider rate limits.", "required": true, "acceptable_evidence": ["Technical keywords: task queue (Celery, SQS), Redis broker, rate limiting (token bucket), backpressure, concurrency limits.", "Decouples heavy background agent tasks from user HTTP request cycles using distributed message queues.", "Implements rate limiters to respect third-party LLM provider TPM (tokens per minute) and RPM quotas."]}, {"id": "KP3", "description": "Cloud infrastructure auto-scaling and observability: orchestrating containers and monitoring system health.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes (EKS), Horizontal Pod Autoscaler (HPA), Prometheus, Grafana, OpenTelemetry, token cost monitoring.", "Scales API pods horizontally based on CPU, memory, and queue backlog metrics.", "Monitors P95/P99 latency, token consumption costs, model error rates, and cache hit ratios via centralized telemetry."]}], "critical_failures": ["Designing a synchronous blocking architecture where client connections hang during multi-second LLM calls.", "Failing to address token-per-minute rate limits and provider throttling in high-throughput environments.", "Omitting container auto-scaling and infrastructure observability."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your experience building and deploying AI or machine learning solutions, including any projects you have taken to production?', '{"subcategory": "End-to-End Production AI/ML Deployment Experience & Project Delivery", "key_points": [{"id": "KP1", "description": "Production project scope and problem statement: articulating a real-world enterprise problem solved with deployed AI.", "required": true, "acceptable_evidence": ["Technical keywords: production deployment, enterprise problem framing, business metrics, customer support automation / fraud detection / recommendations.", "Describes delivering a tangible system (e.g. EV customer call center assistant, real-time fraud scoring) with measurable business targets.", "Explains identifying why traditional heuristic solutions were insufficient and required machine learning."]}, {"id": "KP2", "description": "End-to-end engineering ownership: architecting ingestion, model inference, API serving, and user integration.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end architecture, data ingestion, feature engineering / chunking, model serving (FastAPI/SageMaker), CI/CD.", "Details personal ownership across data preparation, model selection/fine-tuning, backend service creation, and deployment pipelines.", "Demonstrates practical hands-on execution across all stages of the delivery lifecycle."]}, {"id": "KP3", "description": "Production validation, monitoring, and measurable business impact: ensuring reliability and tracking production outcomes.", "required": true, "acceptable_evidence": ["Technical keywords: production metrics, latency SLA (<2s), AHT reduction, deflection rate, accuracy/recall benchmarks, drift monitoring.", "Quantifies system performance (e.g. reduced average handle time by 35%, processed 100k queries/day with 99.9% uptime).", "Monitors model drift, hallucination rates, and customer satisfaction scores in live traffic."]}], "critical_failures": ["Discussing academic exercises or local Jupyter notebook experiments without production deployment experience.", "Failing to cite measurable operational or business metrics from the deployed project.", "Omitting production engineering concerns such as latency, monitoring, and error handling."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your experience building and deploying full-stack AI applications, including backend APIs and frontend interfaces?', '{"subcategory": "Full-Stack AI Application Development: Backend APIs & Frontend Interfaces", "key_points": [{"id": "KP1", "description": "Backend API architecture and streaming protocols: building robust endpoints with FastAPI and async streaming.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, async/await, Server-Sent Events (SSE), WebSockets, Pydantic request validation, CORS, token streaming.", "Implements asynchronous API routes that stream LLM tokens to the client using SSE event-stream formats.", "Validates incoming payloads and sanitizes user input using Pydantic models before triggering agent execution."]}, {"id": "KP2", "description": "Interactive frontend interface integration: building responsive UI components that consume streamed AI responses.", "required": true, "acceptable_evidence": ["Technical keywords: React.js, Next.js, TypeScript, state management, EventSource API, markdown rendering, citation pills.", "Consumes backend SSE streams using the EventSource API, rendering text progressively to minimize perceived latency.", "Renders interactive citation chips, source document previews, and Human-in-the-Loop approval modal controls."]}, {"id": "KP3", "description": "Session state synchronization and end-to-end security: managing conversation threads and user authentication.", "required": true, "acceptable_evidence": ["Technical keywords: JWT authentication, session state management, thread_id persistence, secure cookies, error handling UI.", "Maintains active thread IDs across frontend and backend sessions, allowing users to resume historical conversations seamlessly.", "Gracefully displays timeout warnings and recovery prompts when backend services encounter rate limits or network disconnections."]}], "critical_failures": ["Focusing solely on the backend without explaining frontend streaming consumption or UI state management.", "Describing blocking HTTP requests that wait for full LLM generation instead of streaming token-by-token.", "Omitting authentication, session management, or error recovery across the full stack."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your experience building and deploying recommendation systems, including the data and models used?', '{"subcategory": "Recommendation System Architecture: Data Pipelines & Deep Learning Models", "key_points": [{"id": "KP1", "description": "Data collection, feature engineering, and interaction matrices: processing explicit ratings and implicit behavioral logs.", "required": true, "acceptable_evidence": ["Technical keywords: implicit feedback (clicks, dwell time, purchases), explicit feedback (ratings), user/item features, sparse interaction matrix, negative sampling.", "Processes clickstream events and user purchase histories into interaction matrices and dense feature vectors.", "Performs negative sampling to balance unobserved interactions during training."]}, {"id": "KP2", "description": "Two-stage recommendation architecture: candidate generation (retrieval) and precision ranking.", "required": true, "acceptable_evidence": ["Technical keywords: two-tower neural network, candidate generation, ANN vector search (HNSW), deep ranking model (DLRM / Wide & Deep), collaborative filtering.", "Uses dual-encoder two-tower networks to embed user and item features into a shared vector space, retrieving top-100 candidates in sub-10ms via ANN search.", "Passes retrieved candidates into a complex ranking model that predicts click-through rate (CTR) and conversion probability."]}, {"id": "KP3", "description": "Cold-start mitigation, diversity, and business evaluation metrics: balancing relevance, novelty, and business KPIs.", "required": true, "acceptable_evidence": ["Technical keywords: cold-start handling, content-based fallback, exploration vs exploitation (multi-armed bandits), NDCG@K, Hit Rate@K, business conversion.", "Mitigates cold-start problems for new users/items using content-based metadata embeddings until interaction history accumulates.", "Evaluates offline performance with NDCG and Precision@K, and online performance via A/B testing on revenue and retention metrics."]}], "critical_failures": ["Describing simple rule-based sorting or naive collaborative filtering without the modern two-stage (retrieval + ranking) architecture.", "Failing to explain how candidate generation is scaled using vector search or two-tower models.", "Omitting cold-start mitigation strategies and offline/online evaluation metrics."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your experience transitioning from full-stack development to MLOps and GenAI, and the types of systems you have built in this space?', '{"subcategory": "Career Transition: Full-Stack Development to MLOps and Generative AI", "key_points": [{"id": "KP1", "description": "Leveraging full-stack foundations: applying API design, database modeling, and distributed systems to AI platforms.", "required": true, "acceptable_evidence": ["Technical keywords: full-stack foundation, API contracts, async streaming, distributed databases, systems thinking, production reliability.", "Explains how frontend and backend experience enabled building user-centric AI interfaces (streaming, citations) and resilient API gateways.", "Transfers strong software disciplines (testing, containerization, CI/CD) into machine learning deployment."]}, {"id": "KP2", "description": "Transition into MLOps: mastering model serving, containerization, pipeline automation, and tracking.", "required": true, "acceptable_evidence": ["Technical keywords: Docker containerization, Kubernetes, MLflow, model registries, GPU resource allocation, drift monitoring.", "Upskilled in managing the machine learning operational lifecycle: packaging models into Triton/FastAPI containers and automating deployments.", "Tackled ML-specific production hurdles: non-deterministic latency, GPU cost optimization, and model version tracking."]}, {"id": "KP3", "description": "Specialization in Generative AI: architecting production RAG systems, graph-based agents, and guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: RAG pipelines, LangGraph, vector databases (Milvus, Pinecone), evaluation frameworks (RAGAS), guardrails, business value.", "Advanced into building enterprise retrieval and multi-agent workflows, combining full-stack API integration with cognitive LLM reasoning.", "Demonstrates practical delivery of production assistants that drive measurable workflow automation."]}], "critical_failures": ["Failing to articulate how full-stack experience directly strengthened your ability to build MLOps and GenAI systems.", "Describing the transition without concrete technical milestones or tools mastered across each discipline.", "Omitting production engineering challenges encountered when moving from static web software to probabilistic AI."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your experience transitioning from software engineering to machine learning, MLOps, and Gen AI, and the types of systems you have built along the way?', '{"subcategory": "Career Transition: SWE to Machine Learning, MLOps, and Generative AI", "key_points": [{"id": "KP1", "description": "Continuous technical evolution: building from core backend software engineering to predictive ML and generative agents.", "required": true, "acceptable_evidence": ["Technical keywords: progressive evolution, software engineering rigor, classical ML modeling, MLOps automation, Generative AI engineering.", "Chronicles growth from building core services and data pipelines to implementing machine learning models and deploying generative AI systems.", "Emphasizes combining software reliability with machine learning innovation."]}, {"id": "KP2", "description": "Key milestone systems delivered across the progression: highlighting tangible architectures built at each phase.", "required": true, "acceptable_evidence": ["Technical keywords: predictive scoring services, automated CI/CD pipelines, containerized model microservices, enterprise RAG systems, multi-agent platforms.", "Details specific deliverables: e.g. scalable REST microservices $\\rightarrow$ MLflow automated training pipelines $\\rightarrow$ LangGraph multi-agent customer care assistants.", "Shows increasing architectural scope and business ownership across career milestones."]}, {"id": "KP3", "description": "Philosophical and operational mindset shift: mastering the management of probabilistic systems in production.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic vs probabilistic, evaluation frameworks, guardrail boundaries, regression testing, feedback loops.", "Articulates adopting statistical evaluation and semantic validation to tame non-deterministic model outputs.", "Demonstrates deep appreciation for testing, observability, and defensive system design in modern AI."]}], "critical_failures": ["Presenting an unfocused resume summary without technical depth across the three career phases (SWE, ML/MLOps, GenAI).", "Failing to discuss concrete projects and architectures delivered along the way.", "Ignoring the operational differences between traditional deterministic software and probabilistic AI systems."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'Can you explain your experience deploying AI systems on AWS, including the architecture and any scalability considerations?', '{"subcategory": "AWS Production AI Deployment Architecture & Scalability Considerations", "key_points": [{"id": "KP1", "description": "Compute and container orchestration layer: hosting services on Amazon EKS or SageMaker endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Kubernetes, SageMaker Real-Time Endpoints, GPU node groups (g5/p4 instances), Horizontal Pod Autoscaler (HPA).", "Deploys containerized FastAPI applications and agent orchestrators on Amazon EKS with auto-scaling node groups.", "Hosts heavy model inference on managed SageMaker endpoints with dynamic instance autoscaling."]}, {"id": "KP2", "description": "Storage, vector search, and data pipeline tier: managing high-throughput data access on S3 and distributed databases.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3 (data lake), Milvus on EKS / Amazon OpenSearch, Amazon ElastiCache (Redis), AWS KMS.", "Stores raw document corpora and parquet artifacts in S3 buckets with lifecycle management.", "Connects retrieval pipelines to low-latency distributed vector databases and Redis caches deployed in high-availability VPC subnets."]}, {"id": "KP3", "description": "Scalability, traffic routing, and cost governance: optimizing P99 latency and infrastructure spend.", "required": true, "acceptable_evidence": ["Technical keywords: Application Load Balancer (ALB), AWS CloudWatch, cost optimization, Spot instances, auto-scaling cooldown, P95/P99 latency.", "Distributes incoming traffic across container replicas using ALBs configured with health checks.", "Employs AWS Spot instances for asynchronous batch tasks and auto-scaling cooldown periods to prevent rapid provisioning thrash."]}], "critical_failures": ["Describing manual EC2 single-instance deployments without container orchestration or autoscaling.", "Failing to address GPU resource management and latency SLAs in production serving.", "Omitting network security, VPC private subnets, and load balancing across AWS services."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'How did you use MLflow and SageMaker in your workflow?', '{"subcategory": "MLflow & AWS SageMaker Integration in Machine Learning Workflows", "key_points": [{"id": "KP1", "description": "Experiment tracking and model registry using MLflow: recording hyperparameters, metrics, and versioned artifacts.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking, MLflow Model Registry, autologging, run metrics (loss, validation accuracy), model artifacts, versioning.", "Logs experiment runs, hyperparameters, code commits, and metric curves to a centralized MLflow tracking server.", "Registers candidate models into the MLflow Model Registry and transitions stages from Staging to Production."]}, {"id": "KP2", "description": "SageMaker scalable compute integration: training jobs and containerized production endpoint hosting.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon SageMaker Training Jobs, Estimator, SageMaker Model Hosting, S3 artifact syncing, IAM execution roles.", "Uses SageMaker Estimators to spin up transient, multi-GPU training instances that read data from S3.", "Exports validated model artifacts to Amazon S3 and provisions real-time SageMaker inference endpoints."]}, {"id": "KP3", "description": "End-to-end synergy: coupling MLflow governance with SageMaker scalable infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow-SageMaker deployment integration, automated CI/CD triggers, model promotion, auditability.", "Leverages MLflow as the unified governance and experiment comparison UI while using SageMaker as the heavy elastic compute engine.", "Automates deployments by invoking SageMaker endpoint updates directly upon approving an MLflow registry model version."]}], "critical_failures": ["Treating MLflow and SageMaker as identical competing tools without recognizing their complementary roles (tracking/governance vs elastic compute).", "Failing to explain how model artifacts and metrics move between MLflow and SageMaker/S3.", "Omitting model versioning and staged promotion workflows."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What experience do you have building ML pipelines with tools such as MLflow, Databricks, SageMaker, or DVC?', '{"subcategory": "ML Pipeline Automation with MLflow, Databricks, SageMaker & DVC", "key_points": [{"id": "KP1", "description": "Data versioning and pipeline reproducibility: tracking raw datasets and intermediate features with DVC or Delta Lake.", "required": true, "acceptable_evidence": ["Technical keywords: Data Version Control (DVC), Databricks Delta Lake, data lineage, Git-backed data pointers, reproducible pipelines.", "Tracks dataset versions alongside code commits using DVC metadata pointers to prevent data drift discrepancies.", "Leverages Databricks Delta Lake for ACID transactions and time-travel querying on large-scale feature stores."]}, {"id": "KP2", "description": "Distributed data processing and model training: orchestrating scalable compute across Databricks and SageMaker.", "required": true, "acceptable_evidence": ["Technical keywords: Apache Spark on Databricks, distributed feature engineering, SageMaker Training Jobs, GPU clusters, spot pricing.", "Executes large-scale distributed ETL and feature extraction across Apache Spark clusters on Databricks.", "Dispatches model training jobs to SageMaker on-demand or spot GPU instances with automated checkpointing."]}, {"id": "KP3", "description": "Experiment governance and continuous delivery: logging runs and automating deployments with MLflow and CI/CD.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking & Registry, CI/CD pipeline (GitHub Actions/GitLab), automated model evaluation, blue-green deployment.", "Logs all training metrics and artifacts to MLflow, establishing complete lineage from raw data version to production endpoint.", "Triggers automated regression tests and blue-green deployment updates upon successful model registration."]}], "critical_failures": ["Describing manual ad-hoc model training without automated pipeline tools or data versioning.", "Failing to explain how tools like DVC/Delta Lake establish dataset reproducibility.", "Omitting experiment tracking and automated deployment stages in the pipeline."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What is your experience building and deploying AI assistants or conversational systems for real users?', '{"subcategory": "Production Conversational AI Assistants & Real-User Deployment Experience", "key_points": [{"id": "KP1", "description": "End-to-end conversational system architecture: designing dialogue flows, retrieval augmentation, and intent handling.", "required": true, "acceptable_evidence": ["Technical keywords: conversational AI assistant, RAG architecture, intent classification, multi-turn context buffer, fallback mechanisms.", "Architects conversational assistants (e.g. EV customer call center agent, internal IT helpdesk) with dynamic retrieval and state tracking.", "Implements intent classification to route between informational retrieval, transactional tool calling, and human escalation."]}, {"id": "KP2", "description": "User experience, streaming latency, and hallucination guardrails: ensuring engaging and accurate user interactions.", "required": true, "acceptable_evidence": ["Technical keywords: token streaming (SSE), low first-token latency, hallucination mitigation, source citation pills, Presidio PII masking.", "Optimizes time-to-first-token (<800ms) via streaming APIs to maintain responsive conversational rhythm.", "Grounds answers strictly in retrieved context and attaches clickable source citations to build user trust."]}, {"id": "KP3", "description": "Real-user feedback loops, production telemetry, and operational outcomes: measuring live business impact.", "required": true, "acceptable_evidence": ["Technical keywords: CSAT / user feedback thumbs up/down, query deflection rate, average handling time (AHT), LangSmith telemetry, continuous fine-tuning.", "Captures user feedback signals (thumbs up/down, query rewrites) to identify knowledge gaps and fine-tuning candidates.", "Demonstrates quantifiable production impact (e.g. 40% automated deflection of tier-1 support tickets)."]}], "critical_failures": ["Discussing basic rule-based FAQ bots or offline chatbot toys without real-user production exposure.", "Failing to detail how hallucinations and PII were controlled in live user conversations.", "Omitting user experience considerations like token streaming latency and real-world business metrics."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What is your experience building and serving ML models using FastAPI and containerization tools like Docker and Kubernetes?', '{"subcategory": "Model Serving with FastAPI, Docker & Kubernetes: Low Latency & High Availability", "key_points": [{"id": "KP1", "description": "FastAPI service architecture: building asynchronous inference endpoints with Pydantic schema validation.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, async def endpoints, Pydantic BaseModel, background tasks, Uvicorn ASGI server, lifespan context manager.", "Constructs high-performance inference APIs using FastAPI with strict request/response data validation via Pydantic.", "Loads model weights once during application startup using lifespan context managers, avoiding per-request reloading overhead."]}, {"id": "KP2", "description": "Docker containerization and optimization: crafting lightweight multi-stage Dockerfiles.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage build, slim Python base image, CUDA runtime, non-root user, minimal image footprint, dependency pinning.", "Utilizes multi-stage Docker builds to separate compilation dependencies from the lean production runtime image.", "Enforces non-root execution and security scanning to comply with enterprise container standards."]}, {"id": "KP3", "description": "Kubernetes deployment and high-availability configuration: managing auto-scaling, liveness probes, and resource quotas.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes Deployment, Horizontal Pod Autoscaler (HPA), liveness/readiness probes, resource limits (CPU/memory/GPU), zero-downtime rolling update.", "Configures readiness probes that only accept traffic after model weights are fully loaded into memory.", "Sets CPU/GPU resource requests and limits, enabling HPA to autoscale pods during traffic surges with rolling updates."]}], "critical_failures": ["Loading model weights inside the request handler on every incoming HTTP call.", "Failing to explain how readiness/liveness probes prevent routing traffic to uninitialized model containers.", "Omitting multi-stage Docker optimization or Kubernetes auto-scaling configurations."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you briefly walk through your professional background and current work, particularly your experience with ML, MLOps, and generative AI applications?', '{"subcategory": "Professional Background Overview: ML, MLOps & Generative AI Applications", "key_points": [{"id": "KP1", "description": "Comprehensive engineering identity: presenting a coherent career narrative spanning classical ML to modern GenAI.", "required": true, "acceptable_evidence": ["Technical keywords: machine learning engineer, MLOps practitioner, generative AI systems, production architecture, career evolution.", "Articulates a clear technical profile focused on designing, deploying, and maintaining reliable AI systems in enterprise settings.", "Highlights an engineering philosophy rooted in production reliability, cost efficiency, and business metric impact."]}, {"id": "KP2", "description": "Current core technical focus: building production RAG pipelines, agentic orchestration, and MLOps platforms.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph agent workflows, hybrid RAG (dense + BM25), vector databases (Milvus), model evaluation (RAGAS), AWS infrastructure.", "Details active work building stateful multi-agent systems with tool integration, guardrails, and persistent memory.", "Describes architecting automated retrieval pipelines with cross-encoder rerankers and layout-aware parsing."]}, {"id": "KP3", "description": "Engineering standards and organizational impact: driving best practices, documentation, and operational excellence.", "required": true, "acceptable_evidence": ["Technical keywords: technical leadership, CI/CD automation, observability (OpenTelemetry), cross-functional collaboration, measurable outcomes.", "Emphasizes establishing robust testing suites, automated regression benchmarks, and infrastructure as code across teams.", "Demonstrates clear alignment between technical architecture and business value delivery."]}], "critical_failures": ["Giving a rambling or disjointed resume walkthrough without highlighting core strengths in ML, MLOps, or GenAI.", "Failing to mention current production technologies or technical frameworks.", "Omitting practical engineering standards and business impact."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your approach to building production-ready AI systems, including testing, deployment, and monitoring?', '{"subcategory": "Building Production-Ready AI Systems: Testing, Deployment & Continuous Monitoring", "key_points": [{"id": "KP1", "description": "Multi-tier testing strategy: unit testing logic, regression testing with golden datasets, and semantic evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: unit testing (pytest), golden evaluation datasets, semantic evaluation (RAGAS / DeepEval), tool mocking, deterministic replay.", "Implements unit tests with mocked tool calls to verify deterministic business logic and edge-case handling.", "Executes automated regression benchmarks against curated golden Q&A datasets to catch performance degradation before release."]}, {"id": "KP2", "description": "Production deployment strategies: blue-green deployments, canary rollouts, and infrastructure automation.", "required": true, "acceptable_evidence": ["Technical keywords: blue-green deployment, canary releases, ArgoCD / GitHub Actions, Terraform (IaC), zero-downtime rollout.", "Automates deployments using CI/CD pipelines that spin up staging environments, run integration tests, and promote to production.", "Applies canary routing to expose new model versions to a small percentage of traffic while monitoring error rates."]}, {"id": "KP3", "description": "Production telemetry, drift detection, and observability: tracking latency, cost, and output quality in real time.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, OpenTelemetry, LangSmith, data drift / concept drift, token spend tracking, P99 latency alerts.", "Monitors token consumption, P95/P99 latency, and downstream API error rates through centralized dashboards.", "Tracks embedding and feature drift over time, alerting engineers when input distributions diverge from training distributions."]}], "critical_failures": ["Relying solely on informal manual testing without automated regression suites or golden datasets.", "Failing to explain canary or blue-green zero-downtime deployment strategies.", "Omitting real-time monitoring of data drift, token costs, and model latency."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How did you use tools like MLflow, Databricks, or SageMaker in your machine learning lifecycle and deployment workflows?', '{"subcategory": "MLflow, Databricks & SageMaker in ML Lifecycle & Deployment Workflows", "key_points": [{"id": "KP1", "description": "Databricks for scalable data processing and feature engineering: executing distributed Spark pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: Databricks, Apache Spark, Delta Lake, distributed feature engineering, parquet data tables, ETL orchestration.", "Leverages Databricks compute clusters to process terabyte-scale raw datasets and compute complex feature transformations.", "Saves cleansed features into Delta Lake tables ensuring schema enforcement and time-travel reproducibility."]}, {"id": "KP2", "description": "MLflow for unified experiment tracking and model governance: versioning models and managing promotion stages.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking, autologging, Model Registry, versioned model artifacts, Staging/Production transition.", "Tracks experiment runs, hyperparameters, and evaluation curves across distributed model training sessions.", "Manages model lifecycle governance within the MLflow Model Registry, enforcing approval workflows prior to deployment."]}, {"id": "KP3", "description": "SageMaker for scalable model training and production hosting: utilizing managed GPU instances and endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon SageMaker Training Jobs, Real-Time Endpoints, Multi-Model Endpoints, auto-scaling, VPC integration.", "Submits high-compute training jobs to transient SageMaker GPU instances, syncing model checkpoints directly to S3.", "Hosts registered models on auto-scaling SageMaker endpoints, integrating with API gateways under secure VPC configurations."]}], "critical_failures": ["Conflating Databricks, MLflow, and SageMaker without clarifying their distinct roles (Spark compute vs tracking vs managed hosting).", "Failing to explain how data and models flow between the three systems across the lifecycle.", "Omitting model governance and registry staging controls."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you design data pipelines and full-stack systems that integrate AI models with real-world applications?', '{"subcategory": "Designing Data Pipelines & Full-Stack Systems Integrating AI with Real Applications", "key_points": [{"id": "KP1", "description": "Robust data pipeline architecture: designing reliable batch and streaming ETL workflows to feed AI models.", "required": true, "acceptable_evidence": ["Technical keywords: Apache Kafka, AWS Kinesis, Airflow, batch vs streaming ETL, schema validation (Pydantic), data cleansing.", "Ingests live application events and operational logs via streaming queues or scheduled batch pipelines.", "Enforces strict schema validation and deduplication to ensure incoming data meets model input requirements."]}, {"id": "KP2", "description": "Decoupled full-stack system architecture: integrating backend microservices, caching, and frontend clients.", "required": true, "acceptable_evidence": ["Technical keywords: microservices architecture, FastAPI backend, Redis cache, React frontend, REST / gRPC, asynchronous task queue.", "Connects frontend user interfaces to AI services via asynchronous FastAPI endpoints, offloading long-running jobs to worker queues.", "Caches repeated model inferences and intermediate query results in Redis to minimize system latency."]}, {"id": "KP3", "description": "Operational resilience and feedback integration: handling downstream failures and capturing user feedback.", "required": true, "acceptable_evidence": ["Technical keywords: circuit breakers, graceful degradation, fallback responses, feedback telemetry (thumbs up/down), error logging.", "Implements circuit breakers to return sensible heuristic fallbacks if model endpoints experience downtime or latency spikes.", "Feeds explicit user interaction outcomes back into data stores for continuous model evaluation and retraining."]}], "critical_failures": ["Proposing tight coupling where frontend clients directly query raw database tables or long-running synchronous model functions.", "Failing to include data validation and cleaning steps in pipeline design.", "Omitting fallback mechanisms and error handling when AI services degrade."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'How do you design flexible, observable, and production-ready AI systems, and what best practices do you follow?', '{"subcategory": "Designing Flexible, Observable & Production-Ready AI Systems", "key_points": [{"id": "KP1", "description": "Modular, pluggable architecture design: isolating model providers, retrieval engines, and business rules via interfaces.", "required": true, "acceptable_evidence": ["Technical keywords: modular architecture, dependency injection, provider abstraction (LiteLLM), adapter pattern, loose coupling.", "Abstracts model providers behind consistent interfaces, allowing seamless swapping of models (e.g. GPT-4 to Claude 3.5 Sonnet) with zero code changes.", "Decouples retrieval indexing from generation logic, enabling independent scaling and component updates."]}, {"id": "KP2", "description": "Comprehensive telemetry and distributed observability: implementing end-to-end tracing and custom AI metrics.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Prometheus, Grafana, LangSmith, distributed tracing, trace_id, token cost tracking, P95 latency.", "Injects unique trace_ids across request lifecycles to trace execution across API gateways, vector databases, and LLM nodes.", "Monitors key operational metrics: first-token latency, tokens per second, cache hit rates, and error rate distributions."]}, {"id": "KP3", "description": "Production guardrails and defensive engineering: enforcing input validation, output verification, and rate controls.", "required": true, "acceptable_evidence": ["Technical keywords: input guardrails (Presidio, NeMo), output schema validation (Pydantic), hallucination checks, rate limiting, circuit breakers.", "Intercepts prompt injections and sensitive PII before queries reach foundational models.", "Validates model JSON outputs against strict schemas, falling back to deterministic recovery responses upon validation failure."]}], "critical_failures": ["Building monolithic, rigid systems hardcoded to a single LLM provider or vector database.", "Lacking distributed tracing and granular metrics for intermediate AI pipeline stages.", "Omitting guardrails and schema validation for production safety."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How do you design reusable and scalable MLOps components using platforms like SageMaker or Kubeflow?', '{"subcategory": "Designing Reusable & Scalable MLOps Components with SageMaker or Kubeflow", "key_points": [{"id": "KP1", "description": "Component containerization and interface standardization: building modular, parameterized pipeline steps.", "required": true, "acceptable_evidence": ["Technical keywords: Kubeflow Pipelines (KFP), SageMaker Pipelines, containerized components, reusable pipeline steps, YAML component specs.", "Packages each pipeline stage (data extraction, preprocessing, training, evaluation) into independent, versioned Docker containers.", "Defines standardized input/output parameter contracts using component specifications to enable cross-team reuse."]}, {"id": "KP2", "description": "Pipeline orchestration and dynamic DAG execution: managing task dependencies, caching, and elastic scaling.", "required": true, "acceptable_evidence": ["Technical keywords: pipeline DAG, step caching, task dependencies, dynamic parameter passing, GPU node scaling.", "Orchestrates execution sequences using Kubeflow/SageMaker DAG workflows with automated artifact passing between steps.", "Enables step-level execution caching to skip unchanged upstream tasks during pipeline reruns, cutting compute costs."]}, {"id": "KP3", "description": "Model evaluation gates and automated deployment triggers: enforcing production promotion criteria.", "required": true, "acceptable_evidence": ["Technical keywords: evaluation step, threshold condition, SageMaker Model Registry, automated model approval, CI/CD webhook.", "Incorporates an automated evaluation step that compares newly trained model metrics against active production baseline models.", "Automatically gates model registration, approving models only if accuracy and latency thresholds are met."]}], "critical_failures": ["Writing monolithic pipeline scripts where preprocessing, training, and evaluation are tightly coupled in a single container.", "Failing to explain how components pass versioned data and parameters between steps.", "Omitting automated evaluation gates before model registration and deployment."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How have you designed and deployed ML systems using tools like FastAPI, AWS, and Databricks in production environments?', '{"subcategory": "Designing & Deploying Production ML Systems with FastAPI, AWS & Databricks", "key_points": [{"id": "KP1", "description": "Large-scale data engineering and model training on Databricks: running distributed Spark ETL and model development.", "required": true, "acceptable_evidence": ["Technical keywords: Databricks, Apache Spark, Delta Lake tables, distributed training, MLflow tracking, feature store.", "Prepares large-scale training datasets using distributed Spark transformations on Databricks clusters.", "Tracks training iterations, hyperparameters, and model evaluation curves in Databricks-hosted MLflow."]}, {"id": "KP2", "description": "Asynchronous microservice design with FastAPI: building high-throughput low-latency inference APIs.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, async def, Uvicorn, Pydantic input validation, connection pooling, Redis caching.", "Exposes model predictions through lightweight FastAPI microservices supporting concurrent async request handling.", "Validates incoming features using Pydantic and caches frequent queries in Redis for sub-10ms response times."]}, {"id": "KP3", "description": "Production hosting and infrastructure on AWS: container orchestration, autoscaling, and secure VPC routing.", "required": true, "acceptable_evidence": ["Technical keywords: AWS (EKS / ECS / SageMaker), Application Load Balancer (ALB), Horizontal Pod Autoscaler (HPA), IAM roles, CloudWatch.", "Deploys containerized FastAPI services to Amazon EKS with auto-scaling policies based on traffic volume.", "Implements robust health checks, IAM role-based authentication, and CloudWatch alarm monitoring."]}], "critical_failures": ["Failing to describe how Databricks (training/data), FastAPI (serving), and AWS (hosting) fit together architecturally.", "Proposing synchronous blocking architectures that fail under concurrent production traffic.", "Omitting autoscaling, containerization, and monitoring in the AWS deployment setup."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How have you integrated AWS services such as SageMaker, S3, and MLflow into an MLOps pipeline?', '{"subcategory": "Integrating AWS SageMaker, Amazon S3 & MLflow into an MLOps Pipeline", "key_points": [{"id": "KP1", "description": "S3 as the central artifact and data lake storage: housing raw data, processed features, and serialized models.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3, data lake, versioned S3 buckets, model artifact storage, KMS encryption, lifecycle rules.", "Stores versioned training datasets, validation splits, and serialized model checkpoints in secure S3 buckets.", "Acts as the shared storage substrate accessed by both training and tracking frameworks."]}, {"id": "KP2", "description": "SageMaker for scalable compute execution: running managed training jobs and auto-scaling real-time endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Training Jobs, Estimator, Real-Time Endpoints, GPU instances, Spot Instances, Deep Learning Containers.", "Launches distributed GPU training jobs on SageMaker pulling datasets directly from S3.", "Provisions managed real-time inference endpoints from validated model artifacts stored in S3."]}, {"id": "KP3", "description": "MLflow as the governance and experiment tracking layer: logging metadata and managing lifecycle stage promotion.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking Server, MLflow Model Registry, S3 artifact backend, experiment comparisons, Staging to Production.", "Configures the MLflow tracking server with S3 as its artifact store, logging metrics, parameters, and model signatures.", "Promotes model versions through governance stages in the registry, triggering automated deployments to SageMaker endpoints."]}], "critical_failures": ["Confusing S3''s role as raw storage with MLflow''s role as metadata tracking and registry governance.", "Failing to explain how SageMaker reads data from S3 and registers artifacts to MLflow.", "Omitting the operational flow that connects experiment logging to production deployment."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How have you used AWS services like S3, SageMaker, DynamoDB, and Redis in building scalable ML systems?', '{"subcategory": "AWS Services Synergy (S3, SageMaker, DynamoDB, Redis) for Scalable ML", "key_points": [{"id": "KP1", "description": "Amazon S3 & SageMaker roles: persistent data lake storage and elastic distributed compute.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3 (raw/processed data, model artifacts), SageMaker Training & Real-Time Endpoints, KMS encryption, Spot instances.", "Stores multi-terabyte training corpora, raw audit logs, and serialized model weights in S3 with lifecycle management.", "Provisions managed SageMaker instances for distributed model training and zero-downtime inference endpoints."]}, {"id": "KP2", "description": "Amazon DynamoDB & Redis roles: persistent operational metadata and sub-millisecond feature caching.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon DynamoDB (NoSQL metadata, audit history), Redis / ElastiCache (online feature store, low-latency cache), TTL.", "Uses DynamoDB for durable storage of user metadata, prompt templates, and execution audit trails.", "Leverages in-memory Redis clusters for sub-millisecond retrieval of precomputed online features and semantic query caching."]}, {"id": "KP3", "description": "Architectural data flow and integration: connecting components into an end-to-end low-latency inference path.", "required": true, "acceptable_evidence": ["Technical keywords: inference path, low latency SLA (<50ms), online vs offline sync, VPC peering, IAM role boundaries.", "During real-time scoring, the service fetches fast online features from Redis, falls back to DynamoDB for state, and invokes SageMaker endpoints.", "Batch pipelines asynchronously update S3 and sync precomputed aggregates into Redis/DynamoDB."]}], "critical_failures": ["Failing to differentiate between in-memory caching (Redis), NoSQL document storage (DynamoDB), and blob storage (S3).", "Omitting the interaction pattern between online inference serving and offline feature stores.", "Listing AWS service names without explaining their role in a cohesive ML architecture."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a Dockerfile to deploy a PyTorch model with a FastAPI endpoint?', '{"subcategory": "Production Dockerfile Design for PyTorch Model with FastAPI Endpoint", "key_points": [{"id": "KP1", "description": "Multi-stage build and base image selection: utilizing official CUDA/Python runtimes and minimizing attack surface.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage build, base image (python:3.11-slim / nvidia/cuda runtime), builder pattern, minimal image size.", "Separates compiler tools (gcc, build-essential) into a builder stage, copying only wheels/binaries into the final runtime container.", "Selects minimal official base images to minimize image footprint and patchable CVE vulnerabilities."]}, {"id": "KP2", "description": "Dependency installation and layer caching: optimizing Docker build cache and managing heavy PyTorch wheels.", "required": true, "acceptable_evidence": ["Technical keywords: layer caching, requirements.txt, --no-cache-dir, PyTorch CPU/CUDA index-url, pinned versions.", "Copies requirements.txt independently before application code to leverage Docker layer caching during rebuilds.", "Specifies explicit PyTorch wheel URLs (e.g. download.pytorch.org/whl/cu121) to prevent pulling unneeded cached binaries."]}, {"id": "KP3", "description": "Container execution and security hardening: non-root user, health checks, and production ASGI command.", "required": true, "acceptable_evidence": ["Technical keywords: non-root user (USER appuser), HEALTHCHECK, EXPOSE, CMD / ENTRYPOINT, Uvicorn/Gunicorn worker configuration.", "Creates and switches to a dedicated non-root user (`useradd -m appuser`) to enforce least-privilege security.", "Configures an explicit HEALTHCHECK against `/health` and runs Uvicorn with appropriate worker and timeout flags."]}], "critical_failures": ["Running the container as the default `root` user in a production deployment.", "Copying application source code before `pip install`, destroying Docker build layer caching.", "Omitting container health checks or creating massive unoptimized images (>10GB) with build compilers left in runtime."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a data pipeline that validates, cleans, and transforms data before storing it in a feature store?', '{"subcategory": "Data Validation, Cleaning & Transformation Pipeline for Feature Stores", "key_points": [{"id": "KP1", "description": "Data ingestion and automated validation: enforcing schema integrity and statistical boundaries before processing.", "required": true, "acceptable_evidence": ["Technical keywords: Great Expectations, Pydantic, schema validation, anomaly detection, null-check constraints, statistical distribution checks.", "Applies deterministic schema validation checking field types, null value thresholds, and range constraints on raw input feeds.", "Quarantines malformed records into dead-letter sinks to prevent dirty data from poisoning the feature store."]}, {"id": "KP2", "description": "Feature cleaning, transformation, and point-in-time correctness: computing deterministic features with temporal integrity.", "required": true, "acceptable_evidence": ["Technical keywords: point-in-time correctness, event timestamp, time-travel joins, feature transformations, outlier clipping, imputation.", "Imputes missing values and applies standardized feature scalers or categorical encodings.", "Attaches event timestamps to each record to prevent data leakage during historical training dataset generation."]}, {"id": "KP3", "description": "Dual-store ingestion into Feature Store: synchronizing offline batch tables with low-latency online stores.", "required": true, "acceptable_evidence": ["Technical keywords: Feast / SageMaker Feature Store, online store (Redis / DynamoDB), offline store (S3 / Parquet / Snowflake), entity keys.", "Persists transformed feature records to the offline parquet data lake for historical training dataset generation.", "Synchronizes latest feature values into the online key-value store keyed by entity ID for sub-10ms real-time model inference."]}], "critical_failures": ["Omitting point-in-time correctness or event timestamps, causing catastrophic data leakage during model training.", "Failing to explain the dual storage mechanism (offline data lake for training vs online store for inference).", "Allowing unvalidated, dirty data into feature storage without schema validation or automated anomaly checks."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What experience do you have with cloud ML platforms like AWS SageMaker, and how have you used them for training or deployment?', '{"subcategory": "Cloud ML Platforms: AWS SageMaker for Distributed Training & Deployment", "key_points": [{"id": "KP1", "description": "SageMaker training orchestration: managing distributed training jobs, Spot instances, and hyperparameter tuning.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Estimator, Distributed Training (DDP), Managed Spot Training, Hyperparameter Tuning (HPO), S3 checkpointing.", "Configures SageMaker PyTorch estimators to spin up transient multi-GPU clusters (e.g. ml.g5.12xlarge).", "Leverages Managed Spot Training with S3 checkpointing to reduce compute costs by up to 70%."]}, {"id": "KP2", "description": "SageMaker model hosting and inference endpoints: real-time, asynchronous, and serverless deployment options.", "required": true, "acceptable_evidence": ["Technical keywords: Real-Time Endpoints, Asynchronous Inference, Multi-Model Endpoints (MME), Triton Inference Server, auto-scaling.", "Deploys models to real-time endpoints configured with auto-scaling policies based on CloudWatch invocation metrics.", "Utilizes Asynchronous Inference for payloads with long execution times, writing outputs directly to S3."]}, {"id": "KP3", "description": "Model registry, governance, and VPC security: managing staging promotion and private network isolation.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Model Registry, model versioning, VPC PrivateLink, IAM execution roles, KMS encryption.", "Registers model artifacts into the Model Registry with performance metrics, gating approval prior to production deployment.", "Enforces private network traffic via VPC endpoints without exposing training data or model APIs to public internet."]}], "critical_failures": ["Treating SageMaker simply as an expensive hosted Jupyter notebook without mentioning training jobs or real-time endpoints.", "Failing to address cost optimization techniques such as Spot instances or autoscaling.", "Omitting model registry governance or VPC security controls."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'What is the difference between a Dockerfile, Docker image, and Docker container?', '{"subcategory": "Docker Fundamentals: Dockerfile vs. Docker Image vs. Docker Container", "key_points": [{"id": "KP1", "description": "Dockerfile: declarative text recipe defining build instructions and dependencies.", "required": true, "acceptable_evidence": ["Technical keywords: Dockerfile, declarative script, build instructions (FROM, RUN, COPY, CMD), source code, version controlled.", "Explains that a Dockerfile is the human-readable configuration text file that outlines step-by-step instructions to assemble an environment.", "Lives in source control alongside application code as the foundation of reproducible environments."]}, {"id": "KP2", "description": "Docker Image: immutable, read-only template composed of stacked layered filesystems.", "required": true, "acceptable_evidence": ["Technical keywords: Docker image, immutable snapshot, read-only layers, container registry (ECR/DockerHub), artifact.", "Explains that building a Dockerfile (`docker build`) produces an immutable, portable binary image consisting of read-only layers.", "Stored in container registries and serves as the deployable artifact across staging and production environments."]}, {"id": "KP3", "description": "Docker Container: isolated, runnable live instance of an image with a writable filesystem layer.", "required": true, "acceptable_evidence": ["Technical keywords: Docker container, running process, isolated execution, writable container layer, cgroups, namespaces, runtime.", "Explains that a container is a live running execution of an image (`docker run`), adding a thin read-write layer on top of image layers.", "Leverages Linux kernel namespaces and cgroups to isolate CPU, memory, and network resources from the host OS."]}], "critical_failures": ["Confusing images (static templates) with containers (live running runtime processes).", "Failing to describe Dockerfile as the source code build recipe.", "Omitting the concept of read-only layered filesystems in images vs the writable layer in containers."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'What role did React, FastAPI, and Amazon EKS play in your production deployment?', '{"subcategory": "Production Stack Roles: React Frontend, FastAPI Gateway & Amazon EKS Hosting", "key_points": [{"id": "KP1", "description": "React frontend role: delivering responsive, streaming user interfaces and interactive citation inspection.", "required": true, "acceptable_evidence": ["Technical keywords: React.js, single-page application (SPA), Server-Sent Events (SSE) consumer, token streaming UI, citation rendering.", "Consumes backend SSE streams to progressively display generated LLM answers in real-time.", "Renders interactive citation chips, document source popups, and user feedback buttons (thumbs up/down)."]}, {"id": "KP2", "description": "FastAPI backend role: high-throughput asynchronous API orchestration and business logic validation.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, async request handling, Pydantic validation, agent orchestration (LangGraph), vector store client.", "Acts as the core orchestration middleware: validating requests, managing dialogue sessions, and querying vector databases.", "Yields token chunks asynchronously to stream responses back to the React client without blocking workers."]}, {"id": "KP3", "description": "Amazon EKS deployment role: resilient container orchestration, auto-scaling, and production isolation.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Kubernetes cluster, Horizontal Pod Autoscaler (HPA), Application Load Balancer (ALB), zero-downtime rolling updates.", "Manages container deployments for both frontend and backend services across multi-AZ worker nodes.", "Automatically scales pod replicas under fluctuating user traffic and executes zero-downtime rolling deployments."]}], "critical_failures": ["Failing to articulate the division of responsibility between the presentation (React), API orchestration (FastAPI), and infrastructure (EKS) layers.", "Describing synchronous polling instead of event streaming between React and FastAPI.", "Omitting container orchestration and auto-scaling capabilities provided by Amazon EKS."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What role does FastAPI play in your ML deployment workflow, and how do you ensure reliability and scalability?', '{"subcategory": "FastAPI in ML Deployment: Reliability, Low Latency & High Concurrency", "key_points": [{"id": "KP1", "description": "Asynchronous event-driven I/O: preventing thread blocking during external model and database network calls.", "required": true, "acceptable_evidence": ["Technical keywords: async / await, non-blocking I/O, event loop, Uvicorn ASGI server, concurrency vs parallelism.", "Leverages native asynchronous Python syntax to handle thousands of concurrent client connections waiting on LLM or vector database network I/O.", "Prevents thread pool starvation common in legacy synchronous frameworks (e.g. Flask/Django)."]}, {"id": "KP2", "description": "Strict schema validation and error handling via Pydantic: ensuring data contract integrity.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic BaseModel, type hints, request validation, automated 422 error responses, OpenAPI / Swagger documentation.", "Validates incoming feature payloads and JSON queries against strict schemas before hitting downstream pipelines.", "Automatically returns detailed validation error messages, preventing malformed requests from causing silent pipeline failures."]}, {"id": "KP3", "description": "Production reliability patterns: startup lifespans, connection pooling, and health check probes.", "required": true, "acceptable_evidence": ["Technical keywords: lifespan context manager, connection pooling (HTTPX/asyncpg), liveness/readiness probes, graceful shutdown.", "Initializes model clients and connection pools once during application startup via lifespan managers rather than per request.", "Provides dedicated `/health/live` and `/health/ready` endpoints to enable Kubernetes traffic management and zero-downtime restarts."]}], "critical_failures": ["Using blocking synchronous operations inside `async def` endpoints, stalling the single-threaded asyncio event loop.", "Re-instantiating heavy database connections or model clients on every incoming HTTP request.", "Failing to explain how Pydantic enforces data contracts and prevents corrupted model inputs."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What steps do you take to evaluate whether to reuse existing data pipelines versus building new ones?', '{"subcategory": "Data Pipeline Decision Strategy: Reusing Existing Pipelines vs. Building New Ones", "key_points": [{"id": "KP1", "description": "Technical evaluation criteria: assessing schema compatibility, update latency, data quality, and volume capacity.", "required": true, "acceptable_evidence": ["Technical keywords: schema alignment, update SLA (streaming vs batch), data quality, throughput capacity, upstream dependencies.", "Evaluates whether existing pipelines supply required features with necessary freshness (e.g. real-time sub-second vs 24h batch).", "Audits existing pipeline reliability, data lineage, and failure rate before introducing critical new dependencies."]}, {"id": "KP2", "description": "Organizational and operational trade-offs: developer velocity vs technical debt and maintenance burden.", "required": true, "acceptable_evidence": ["Technical keywords: technical debt, time-to-market, dual maintenance overhead, cross-team coupling, blast radius.", "Reusing existing pipelines accelerates time-to-market and prevents duplicate infrastructure compute spend.", "However, tight coupling to another team''s pipeline introduces blast-radius risk if schema changes are made without warning."]}, {"id": "KP3", "description": "Hybrid and wrapper approaches: extending existing pipelines via modular transformation layers.", "required": true, "acceptable_evidence": ["Technical keywords: pipeline extension, intermediate view, downstream micro-batch, decoupled consumer, feature store ingestion.", "Consumes outputs from existing upstream pipelines as an unmutated source, appending downstream transformation logic in a decoupled job.", "Publishes resulting features to an enterprise feature store for shared reuse across multiple downstream AI products."]}], "critical_failures": ["Advocating for always building new pipelines from scratch (''Not Invented Here'' syndrome), causing duplicate compute and fragmented data silos.", "Blindly coupling new production AI systems to unvetted experimental pipelines without checking update frequency or schemas.", "Ignoring downstream maintenance costs and cross-team dependencies in pipeline architecture decisions."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What steps would you take to validate a model and ensure it is production-ready before deployment?', '{"subcategory": "Production Model Validation & Readiness Verification Gates", "key_points": [{"id": "KP1", "description": "Offline metric benchmarking against golden test sets: evaluating predictive and semantic accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: golden evaluation dataset, held-out test split, classification metrics (F1, Precision-Recall AUC), RAGAS (Faithfulness, Relevance).", "Evaluates candidate models against an immutable, human-verified golden benchmark dataset.", "Ensures performance strictly exceeds current production baselines and SLA error thresholds before release."]}, {"id": "KP2", "description": "Non-functional performance and stress testing: validating latency, memory footprint, and concurrency limits.", "required": true, "acceptable_evidence": ["Technical keywords: load testing (Locust), P95/P99 latency SLA, peak QPS throughput, memory leakage, GPU VRAM headroom.", "Executes synthetic stress tests simulating peak concurrent traffic to ensure response latency remains within SLA budgets.", "Verifies container memory stability under sustained load to catch memory leaks and unexpected OOM crashes."]}, {"id": "KP3", "description": "Safety, fairness, and adversarial robustness testing: stress-testing edge cases and malicious inputs.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection / jailbreak testing, out-of-distribution robustness, bias/fairness auditing, boundary testing.", "Subjects model to red-teaming adversarial prompts to verify guardrail intercept rates.", "Audits prediction outputs across demographic or sensitive subgroups to detect and prevent disparate impact."]}], "critical_failures": ["Declaring a model production-ready based solely on training loss without testing on held-out golden datasets.", "Failing to conduct load testing or latency SLA validation under concurrent traffic conditions.", "Omitting adversarial robustness, safety, or bias checks before public deployment."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What trade-offs do you consider when choosing tools and frameworks for deploying scalable ML systems?', '{"subcategory": "Tool & Framework Selection Trade-offs for Deploying Scalable ML Systems", "key_points": [{"id": "KP1", "description": "Managed cloud services vs. self-hosted open-source infrastructure: operational overhead vs flexibility and cost.", "required": true, "acceptable_evidence": ["Technical keywords: managed services (SageMaker, Bedrock, Vertex AI) vs self-hosted (Kubernetes, Ray Serve, vLLM), operational overhead, vendor lock-in.", "Managed platforms offer zero infrastructure maintenance and rapid startup, but incur high markup costs and limited low-level customization.", "Self-hosted Kubernetes clusters reduce long-term compute spend and avoid vendor lock-in, but require dedicated platform engineering overhead."]}, {"id": "KP2", "description": "Serving framework selection: lightweight APIs (FastAPI) vs high-throughput inference engines (Triton, vLLM, TorchServe).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI vs Triton Inference Server / vLLM, continuous batching, dynamic tensor batching, paged attention, GPU utilization.", "FastAPI is ideal for flexible agent orchestration and I/O-bound routing logic.", "Specialized inference engines (vLLM, Triton) are essential for high-throughput model execution, providing continuous batching and optimal GPU saturation."]}, {"id": "KP3", "description": "Monitoring and observability tools: lightweight APM vs specialized ML monitoring platforms.", "required": true, "acceptable_evidence": ["Technical keywords: standard APM (Datadog, Prometheus) vs ML-specific (Evidently AI, Arize, LangSmith), drift detection, trace logging.", "Standard APM monitors infrastructure health (CPU, RAM, HTTP errors) but lacks visibility into model degradation.", "ML observability tools track data drift, embedding shifts, token spend, and factual grounding over time."]}], "critical_failures": ["Suggesting FastAPI as an optimized engine for heavy LLM GPU matrix batching instead of using specialized runtimes like vLLM or Triton.", "Failing to articulate the cost vs maintenance trade-off between managed cloud services and self-hosted infrastructure.", "Ignoring the distinction between standard infrastructure APM and machine learning drift/observability tools."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'What was your deployment architecture using AWS services, and how did components interact?', '{"subcategory": "Production ML Deployment Architecture on AWS & Component Interactions", "key_points": [{"id": "KP1", "description": "Ingress and API orchestration layer: routing client traffic through ALB and containerized services.", "required": true, "acceptable_evidence": ["Technical keywords: Application Load Balancer (ALB), Amazon EKS / ECS, FastAPI microservices, VPC public/private subnets, Route 53.", "Routes external user traffic through an ALB to containerized FastAPI pods running in private EKS subnets.", "Handles authentication token validation and rate limiting before initiating downstream pipeline tasks."]}, {"id": "KP2", "description": "Compute and model execution layer: delegating inference to SageMaker endpoints or GPU node pools.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon SageMaker endpoints, GPU worker nodes, asynchronous task queue (SQS), decoupled processing.", "Directs real-time scoring requests to SageMaker real-time endpoints or dedicated GPU pods on EKS.", "Offloads asynchronous heavy tasks via Amazon SQS to backend worker pods."]}, {"id": "KP3", "description": "Storage, caching, and observability tier: managing state in S3, ElastiCache, DynamoDB, and CloudWatch.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3, ElastiCache (Redis), Amazon DynamoDB, CloudWatch logs & metrics, IAM role policies.", "Retrieves cached features from Redis and logs conversation history/metadata into DynamoDB.", "Streams logs and execution metrics to Amazon CloudWatch for automated alarming and dashboard visualization."]}], "critical_failures": ["Describing components as disconnected silos without showing the end-to-end request flow.", "Placing sensitive databases and model instances in public subnets without VPC network isolation.", "Omitting the caching layer or asynchronous queuing mechanisms for high-throughput traffic."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'What would be your approach to delivering a production-ready AI solution within a 90-day roadmap, from ideation to deployment?', '{"subcategory": "90-Day Production AI Delivery Roadmap: Ideation to Scalable Deployment", "key_points": [{"id": "KP1", "description": "Days 1–30 (Discovery, Data Foundation & POC Benchmark): defining problem scope, data access, and baseline validation.", "required": true, "acceptable_evidence": ["Technical keywords: discovery phase, business KPI definition, data auditing, rapid POC, baseline evaluation, golden dataset.", "Aligns with stakeholders on target metrics (e.g. 30% handle time reduction, <2s latency SLA).", "Audits raw data sources, establishes a curated golden test dataset, and validates a working prototype."]}, {"id": "KP2", "description": "Days 31–60 (MVP Architecture, Evaluation & Security Hardening): building the production pipeline and guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: production MVP, RAG/Agent pipeline, evaluation suite (RAGAS), PII masking (Presidio), CI/CD setup, Dockerization.", "Refactors POC into containerized microservices with structured chunking, vector indexing, and reranking.", "Integrates automated evaluation regression gates, PII sanitization, and security guardrails."]}, {"id": "KP3", "description": "Days 61–90 (Pilot Deployment, Observability & Full Rollout): canary release, monitoring, and operational handover.", "required": true, "acceptable_evidence": ["Technical keywords: canary deployment, pilot user group, telemetry (OpenTelemetry/LangSmith), feedback loops, production scale-out.", "Deploys to a restricted 10% pilot user group on Kubernetes/EKS, monitoring real-time latency and user feedback.", "Tunes prompts and indexing based on pilot telemetry before executing full 100% production rollout with automated documentation."]}], "critical_failures": ["Spending the entire 90 days on model experimentation without planning for deployment, infrastructure, or testing.", "Failing to establish golden evaluation datasets or measurable business KPIs early in the timeline.", "Omitting canary rollout, security compliance, or telemetry monitoring in the final production phase."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain your experience with MLOps, including model deployment, CI/CD, and tools like MLflow, Databricks, and SageMaker?', '{"subcategory": "MLOps Lifecycle Experience: Model Deployment, CI/CD & Toolchain Integration", "key_points": [{"id": "KP1", "description": "Automated training and tracking with MLflow & Databricks: managing experiment lineage and model registration.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking, MLflow Model Registry, Databricks Spark ETL, artifact lineage, hyperparameter logging.", "Tracks training metrics, hyperparameters, and dataset versions across distributed Databricks compute clusters.", "Maintains governance and staged approvals within the MLflow Model Registry."]}, {"id": "KP2", "description": "Continuous Integration & Continuous Deployment (CI/CD) pipelines: automating testing, container builds, and deployment.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD (GitHub Actions / GitLab CI), automated testing (pytest), Docker build, Amazon ECR, ArgoCD GitOps.", "Triggers automated unit tests, model validation checks, and Docker container builds upon pull request merges.", "Uses GitOps or CI/CD pipelines to deploy container manifests to staging and production Kubernetes environments."]}, {"id": "KP3", "description": "Production model serving and monitoring with SageMaker: managing endpoints and tracking performance drift.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker endpoints, blue-green deployment, Model Monitor, data drift detection, CloudWatch alarms.", "Hosts validated model artifacts on auto-scaling SageMaker endpoints with zero-downtime blue-green updates.", "Monitors live inference payloads for data drift and latency spikes, triggering automated retrain notifications."]}], "critical_failures": ["Describing manual model handoffs via email or manual file copying instead of automated CI/CD pipelines.", "Failing to explain how MLflow tracks model lineage from code commit to registry.", "Omitting production drift monitoring and containerized deployment mechanisms."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 120, 'Can you walk through the end-to-end architecture of your Generative AI system, including backend, APIs, frontend, and deployment infrastructure?', '{"subcategory": "End-to-End Generative AI System Architecture: Frontend, Backend, APIs & Infrastructure", "key_points": [{"id": "KP1", "description": "Presentation layer (Frontend): delivering responsive user interactions and real-time streaming displays.", "required": true, "acceptable_evidence": ["Technical keywords: React / Next.js frontend, Server-Sent Events (SSE) streaming, interactive citations, conversation history UI.", "Renders clean chat interfaces that consume streaming token responses progressive to minimize perceived latency.", "Displays interactive citation pills linked to source documents, along with thumbs up/down feedback mechanisms."]}, {"id": "KP2", "description": "Backend API & orchestration layer: managing user sessions, state graphs, and retrieval augmentation.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservices, LangGraph StateGraph, hybrid search (Milvus/Pinecone + BM25), cross-encoder reranker, Presidio PII.", "Validates incoming user queries with Pydantic, applies PII sanitization, and queries vector databases for relevant context.", "Orchestrates multi-agent reasoning, invokes domain tools, and streams synthesized responses back to the client."]}, {"id": "KP3", "description": "Cloud hosting and deployment infrastructure: running scalable containers with enterprise observability.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, AWS Bedrock / self-hosted vLLM, ElastiCache (Redis), Application Load Balancer, OpenTelemetry / LangSmith.", "Deploys containerized frontend and backend services to Amazon EKS with auto-scaling pod policies.", "Integrates with AWS Bedrock for foundation model access, caches state in Redis, and monitors execution telemetry with OpenTelemetry."]}], "critical_failures": ["Focusing solely on prompt text while ignoring frontend streaming, API gateways, and cloud deployment infrastructure.", "Failing to explain how retrieval context and tool execution fit into the backend orchestration flow.", "Omitting security, state management, and production observability across the stack."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'EASY', 'SPECIFIC', 60, 'How did you productionize your ML/AI systems, including CI/CD integration, model deployment, and monitoring?', '{"subcategory": "Productionizing ML/AI Systems: CI/CD, Deployment & Monitoring Strategies", "key_points": [{"id": "KP1", "description": "Automated testing and continuous delivery pipeline: verifying code quality, schema contracts, and model benchmarks.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions / GitLab CI, automated unit/integration tests, semantic regression gates, Docker containerization, Amazon ECR.", "Executes pytest suites, linting checks, and golden dataset regression benchmarks on every code commit.", "Builds and publishes security-scanned Docker container images to container registries upon passing validation."]}, {"id": "KP2", "description": "Zero-downtime deployment patterns: managing rolling updates, canary testing, and blue-green environments.", "required": true, "acceptable_evidence": ["Technical keywords: blue-green deployment, canary rollout, Kubernetes Deployment, ArgoCD, health probes, automated rollback.", "Routes a small percentage of production traffic to canary pods to verify stability before promoting to full traffic.", "Configures automated rollbacks triggered by elevated 5xx error rates or P99 latency regressions."]}, {"id": "KP3", "description": "Continuous production telemetry and quality tracking: monitoring system health, cost, and output drift.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, OpenTelemetry, Evidently AI, token cost monitoring, data drift, hallucination detection.", "Monitors infrastructure metrics (CPU, memory, request throughput) alongside AI-specific metrics (tokens per minute, latency per token).", "Tracks output hallucination rates and data distribution drift to trigger scheduled retraining pipelines."]}], "critical_failures": ["Describing manual deployments directly to production servers without CI/CD automation or regression testing.", "Lacking rollback strategies or health checks in the deployment configuration.", "Omitting post-deployment monitoring of model drift, output quality, and operational costs."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'EASY', 'SPECIFIC', 60, 'How do you handle infrastructure as code and automate deployments for scalable ML systems?', '{"subcategory": "Infrastructure as Code (IaC) & Deployment Automation for Scalable ML Systems", "key_points": [{"id": "KP1", "description": "Declarative cloud provisioning with Terraform / CloudFormation: codifying compute, storage, and networking.", "required": true, "acceptable_evidence": ["Technical keywords: Terraform (HCL), Infrastructure as Code (IaC), AWS provider, state file management, modular architecture, VPC subnets.", "Provisions all required cloud resources (EKS clusters, S3 buckets, RDS/DynamoDB databases, IAM roles) using declarative Terraform modules.", "Maintains environment consistency across Development, Staging, and Production through parameter-driven configurations."]}, {"id": "KP2", "description": "Kubernetes manifest and GitOps automation: managing application deployments via Helm and ArgoCD.", "required": true, "acceptable_evidence": ["Technical keywords: Helm charts, ArgoCD, GitOps, declarative manifests, ConfigMaps, Secrets management (AWS Secrets Manager).", "Packages application services into parameterized Helm charts specifying resource limits, replicas, and ingress rules.", "Uses ArgoCD to continuously reconcile live Kubernetes cluster state against the Git repository configuration."]}, {"id": "KP3", "description": "Automated CI/CD orchestration: executing IaC validation, plan reviews, and automated infrastructure deployment.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD automation, terraform plan / apply, tflint / checkov security scanning, automated promotion, audit trail.", "Runs automated security scanning (Checkov/tfsec) and `terraform plan` checks on pull requests before infrastructure merges.", "Executes automated applies within isolated CI/CD runner pipelines, recording an immutable audit trail of changes."]}], "critical_failures": ["Relying on manual AWS Management Console clicking to configure production infrastructure.", "Storing sensitive credentials directly inside unencrypted Git repositories or plain text templates.", "Omitting GitOps or CI/CD automation for infrastructure and application deployment reconciliation."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What engineering responsibilities did you handle in your ML role, including API development, CI/CD pipelines, and deployment using Kubernetes and AWS SageMaker?', '{"subcategory": "ML Engineering Core Responsibilities: APIs, CI/CD & Kubernetes/SageMaker Deployment", "key_points": [{"id": "KP1", "description": "Robust API design and serving layer implementation: building performant asynchronous prediction services.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI development, async/await, Pydantic schemas, REST/gRPC endpoints, request serialization, error handling.", "Architects clean API contracts with strict input validation, translating incoming client payloads into optimized model feature tensors.", "Implements asynchronous concurrency and response streaming to maintain sub-second response times under load."]}, {"id": "KP2", "description": "Continuous Integration and delivery automation: managing testing pipelines and container lifecycle.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD pipelines (GitHub Actions/GitLab), unit/integration testing (pytest), Docker build, image vulnerability scanning, Amazon ECR.", "Maintains automated testing suites that validate model inference accuracy, API contracts, and edge cases prior to merging.", "Builds, tags, and pushes optimized Docker containers to Amazon ECR as deployable immutable artifacts."]}, {"id": "KP3", "description": "Cloud deployment execution on Kubernetes (EKS) and AWS SageMaker: managing compute scaling and reliability.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Kubernetes manifests, HPA, AWS SageMaker endpoints, GPU resource management, CloudWatch monitoring.", "Deploys containerized services to Amazon EKS clusters configured with autoscaling and health probes.", "Deploys model endpoints to SageMaker, managing instance types, memory quotas, and production monitoring alarms."]}], "critical_failures": ["Portraying engineering responsibilities as purely running offline notebooks without API development or deployment duties.", "Failing to detail practical experience with CI/CD automation or containerization.", "Omitting hands-on orchestration using Kubernetes or AWS SageMaker."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'EASY', 'SPECIFIC', 60, 'What is your experience with deploying scalable AI systems on cloud-native infrastructure?', '{"subcategory": "Deploying Scalable AI Systems on Cloud-Native Infrastructure", "key_points": [{"id": "KP1", "description": "Microservices decomposition and container orchestration: architecting decoupled components on Kubernetes.", "required": true, "acceptable_evidence": ["Technical keywords: cloud-native architecture, Kubernetes (Kube-native), Docker containers, microservices, service mesh (Istio), gRPC/REST.", "Deconstructs AI applications into modular containerized microservices (ingestion, retrieval, ranking, LLM generation) running on Kubernetes.", "Leverages Kubernetes service networking and service mesh for secure, low-latency inter-service communication."]}, {"id": "KP2", "description": "Elastic autoscaling and hardware resource optimization: scaling heterogeneous CPU and GPU workloads.", "required": true, "acceptable_evidence": ["Technical keywords: Horizontal Pod Autoscaler (HPA), Cluster Autoscaler / Karpenter, GPU node pools, resource requests/limits, Spot instances.", "Configures intelligent autoscalers (e.g. Karpenter) to provision specialized GPU instances dynamically during peak inference traffic.", "Sets strict CPU and memory resource requests/limits to prevent runaway processes from destabilizing cluster nodes."]}, {"id": "KP3", "description": "Cloud-native storage, caching, and observability: integrating distributed databases and unified telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: distributed storage (S3), distributed vector database (Milvus distributed), Redis cluster, Prometheus, Grafana, OpenTelemetry.", "Connects services to distributed cloud-native vector databases and in-memory caches designed for horizontal scaling.", "Collects system metrics, trace logs, and model performance indicators into centralized Prometheus/Grafana stacks."]}], "critical_failures": ["Proposing monolithic single-server architectures that fail cloud-native resilience and scaling requirements.", "Failing to explain how GPU resources are allocated, monitored, and scaled in Kubernetes.", "Omitting cloud-native observability or distributed storage integrations."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'What role did AWS services such as SageMaker, EKS, and MLFlow play in your ML infrastructure and deployment workflows?', '{"subcategory": "AWS SageMaker, EKS & MLflow Synergy in Production ML Infrastructure", "key_points": [{"id": "KP1", "description": "Amazon SageMaker role: managed training jobs and elastic model inference endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon SageMaker Training Jobs, Real-Time Endpoints, Managed Spot Training, Deep Learning Containers, GPU instances.", "Provides heavy elastic compute infrastructure for running multi-GPU distributed model training jobs.", "Hosts managed real-time inference endpoints with built-in instance autoscaling and blue-green updates."]}, {"id": "KP2", "description": "Amazon EKS role: microservice orchestration, API routing, and agent graph workflows.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Kubernetes cluster, FastAPI microservices, LangGraph orchestration, Horizontal Pod Autoscaler, ALB ingress.", "Runs the customer-facing API gateway, application business logic, and multi-agent coordination graphs.", "Provides granular control over container networking, ingress load balancing, and horizontal pod scaling."]}, {"id": "KP3", "description": "MLflow role: unified experiment tracking, artifact lineage, and model governance.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking Server, MLflow Model Registry, S3 backend, experiment comparison, model stage governance.", "Acts as the central control plane tracking hyperparameters, code commits, and evaluation metrics across training runs.", "Governs model promotion from Staging to Production, triggering automated deployment workflows to SageMaker or EKS."]}], "critical_failures": ["Treating EKS and SageMaker as identical competing tools without distinguishing between microservice orchestration and managed ML endpoints.", "Failing to explain how MLflow provides governance and metadata tracking across the pipeline.", "Omitting the interaction flow that links experiment tracking to production deployment across AWS services."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your background, including your education and your transition from data analytics to machine learning engineering?', '{"subcategory": "Career Transition: Data Analytics to Machine Learning Engineering", "key_points": [{"id": "KP1", "description": "Foundational data fluency: leveraging exploratory analysis, SQL mastery, and statistical rigor.", "required": true, "acceptable_evidence": ["Technical keywords: data analytics background, complex SQL, exploratory data analysis (EDA), hypothesis testing, statistical distributions, data intuition.", "Explains how deep experience with data anomalies, aggregations, and business metrics created a strong foundation for ML feature engineering.", "Understands that model performance is fundamentally bounded by underlying data quality."]}, {"id": "KP2", "description": "Deliberate upskilling into software engineering & machine learning: mastering algorithms, PyTorch, and clean code.", "required": true, "acceptable_evidence": ["Technical keywords: software engineering rigor, Python OOP, algorithms and data structures, scikit-learn, PyTorch, model training, cross-validation.", "Invested deliberate effort transitioning from static BI dashboards to writing modular, testable Python code and training predictive models.", "Mastered machine learning fundamentals: loss optimization, regularization, overfitting prevention, and cross-validation."]}, {"id": "KP3", "description": "Embracing production systems and MLOps: building end-to-end pipelines, APIs, and model serving infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: MLOps transition, Docker containerization, FastAPI serving, CI/CD automation, cloud deployment (AWS), production impact.", "Evolved beyond offline model development to own production deployments, latency optimization, and automated retraining pipelines.", "Demonstrates practical delivery of production ML services that automate core business decisions."]}], "critical_failures": ["Describing data analytics solely as simple dashboard creation without highlighting statistical or data modeling depth.", "Failing to explain the technical steps taken to master software engineering and machine learning principles.", "Omitting production engineering and MLOps capabilities acquired during the transition."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you summarize your overall machine learning experience and how it has evolved over your career?', '{"subcategory": "Comprehensive Machine Learning Career Experience & Evolution Narrative", "key_points": [{"id": "KP1", "description": "Broad progression overview: evolving across traditional predictive ML, MLOps automation, and modern Generative AI.", "required": true, "acceptable_evidence": ["Technical keywords: career evolution, predictive modeling (tabular/NLP), MLOps lifecycle, Generative AI / LLMs, agentic systems engineering.", "Presents a structured narrative of career milestones: from early predictive models (gradient boosting, scikit-learn) to modern foundation model applications.", "Emphasizes continuous expansion from mathematical modeling to full systems architecture and production ownership."]}, {"id": "KP2", "description": "Core technical specializations: building robust retrieval pipelines, vector search, and agentic workflows.", "required": true, "acceptable_evidence": ["Technical keywords: RAG architectures, vector databases (Milvus/Pinecone), LangGraph, hybrid retrieval, cross-encoders, model evaluation (RAGAS).", "Details active specialization in building production RAG systems with layout-aware document chunking and cross-encoder reranking.", "Highlights hands-on experience designing stateful multi-agent workflows with tool integration and safety guardrails."]}, {"id": "KP3", "description": "Production engineering philosophy: prioritizing business impact, reliability, latency SLAs, and cost management.", "required": true, "acceptable_evidence": ["Technical keywords: business ROI, latency budgets, token economics, regression testing, observability, customer outcome alignment.", "Frames technical accomplishments around measurable business value (e.g. ticket deflection, latency reduction, fraud loss prevention).", "Demonstrates pragmatic engineering maturity by focusing on maintainable, battle-tested solutions over fleeting trends."]}], "critical_failures": ["Delivering a disjointed list of past jobs without a clear technical narrative or progressive growth story.", "Failing to mention specific modern ML/GenAI tools and architectures mastered.", "Ignoring production reliability, business metrics, and engineering principles."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you walk me through your professional background and how you transitioned from full stack development to data science, data engineering, and machine learning?', '{"subcategory": "Career Transition: Full-Stack to Data Science, Data Engineering & Machine Learning", "key_points": [{"id": "KP1", "description": "Full-stack software engineering foundation: leveraging systems design, API architecture, and database modeling.", "required": true, "acceptable_evidence": ["Technical keywords: full-stack background, backend microservices, SQL/NoSQL databases, distributed systems, clean code, CI/CD.", "Explains how deep experience with scalable web architectures provided the systems engineering foundation needed for data platforms.", "Brought rigorous testing, containerization, and modular software design into data and ML workflows."]}, {"id": "KP2", "description": "Evolution through Data Science & Data Engineering: mastering distributed data pipelines, ETL, and feature stores.", "required": true, "acceptable_evidence": ["Technical keywords: data engineering, Apache Spark, Airflow, feature stores (Feast), statistical modeling, predictive algorithms.", "Transitioned into building robust data ingestion pipelines, handling large-scale streaming and batch processing.", "Developed statistical modeling and feature engineering expertise to support predictive analytics use cases."]}, {"id": "KP3", "description": "Culmination in Machine Learning & GenAI Engineering: deploying models, RAG pipelines, and agent systems.", "required": true, "acceptable_evidence": ["Technical keywords: ML engineering, model deployment (FastAPI/Kubernetes), MLOps (MLflow), RAG systems, LangGraph, business impact.", "Combined data pipeline expertise and software engineering rigor to deploy production machine learning models and generative AI systems.", "Demonstrates unique versatility: capable of owning the entire lifecycle from raw data ingestion to frontend streaming user interfaces."]}], "critical_failures": ["Failing to connect how full-stack software experience directly enhanced data engineering and ML engineering capabilities.", "Describing the transition without concrete examples of tools or projects completed across each discipline.", "Omitting the distinction between data engineering (pipelines/storage) and machine learning (modeling/serving)."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you walk through your professional experience, including your transition from software engineering to machine learning and generative AI, and describe the projects you have worked on?', '{"subcategory": "Professional Experience: Software Engineering to ML/GenAI Transition & Key Projects", "key_points": [{"id": "KP1", "description": "Career milestone narrative: detailing progressive technical stages from software engineering to machine learning and GenAI.", "required": true, "acceptable_evidence": ["Technical keywords: software engineering, predictive ML modeling, MLOps automation, generative AI systems, architectural progression.", "Articulates a clear technical journey: starting in core software development, advancing into predictive ML pipelines, and expanding into GenAI architectures.", "Emphasizes how strong software design principles underpin reliable, deterministic wrappers around probabilistic AI models."]}, {"id": "KP2", "description": "Key production projects: detailing concrete architectures built and deployed for real users.", "required": true, "acceptable_evidence": ["Technical keywords: production RAG assistant (EV call center / helpdesk), fraud detection service, multi-agent orchestration (LangGraph), vector search.", "Describes architecting an enterprise RAG assistant with layout-aware document chunking (Docling), hybrid retrieval, and reranking.", "Details implementing multi-agent workflows with state checkpointing, domain tools, and Human-in-the-Loop approval gates."]}, {"id": "KP3", "description": "Production outcomes and business metric impact: quantifying performance and operational success.", "required": true, "acceptable_evidence": ["Technical keywords: average handle time (AHT) reduction, inquiry deflection rate, sub-second latency SLA, cost optimization, RAGAS evaluation.", "Quantifies tangible results: e.g. reducing customer call resolution time by 35% and achieving 92% answer faithfulness.", "Demonstrates operational ownership: managing token economics, monitoring drift, and ensuring system uptime."]}], "critical_failures": ["Speaking in broad generalities without describing specific production projects or system architectures.", "Failing to highlight technical transition milestones from traditional software to GenAI.", "Omitting quantitative operational metrics and business outcomes achieved by delivered projects."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Have you built or worked with a feature store, and how did it integrate into your ML workflows?', '{"subcategory": "Feature Store Implementation & Integration into Production ML Workflows", "key_points": [{"id": "KP1", "description": "Core purpose and dual-store architecture of a Feature Store: centralizing feature definitions across offline and online stores.", "required": true, "acceptable_evidence": ["Technical keywords: Feature Store (Feast / SageMaker Feature Store), offline store (S3 / Delta Lake), online store (Redis / DynamoDB), entity keys, feature views.", "Explains how a feature store serves as a single source of truth for curated features, preventing feature duplication across teams.", "Employs dual storage: an offline store for high-throughput batch training and an online key-value store for sub-10ms real-time inference lookup."]}, {"id": "KP2", "description": "Solving training-serving skew: maintaining identical feature transformations across batch and real-time paths.", "required": true, "acceptable_evidence": ["Technical keywords: training-serving skew, code reuse, unified transformation logic, feature drift, point-in-time correctness.", "Ensures that feature transformation logic is defined once and executed consistently during both offline training and online serving.", "Eliminates subtle bugs caused by divergent feature calculation code between data science pipelines and production API microservices."]}, {"id": "KP3", "description": "Point-in-time correctness and historical feature retrieval: preventing data leakage during training dataset construction.", "required": true, "acceptable_evidence": ["Technical keywords: point-in-time joins (as-of joins), event timestamps, time-travel queries, data leakage prevention, entity dataframe.", "Performs time-travel joins matching label timestamps with feature values as they existed precisely at event time.", "Prevents catastrophic future data leakage that inflates offline evaluation metrics while causing production model failure."]}], "critical_failures": ["Treating a feature store as just a standard relational database table without understanding offline vs online store requirements.", "Failing to explain training-serving skew and how feature stores solve it.", "Omitting point-in-time joins (as-of joins) and how they prevent data leakage during training set creation."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'How did you ensure consistency between the feature store and model serving layers?', '{"subcategory": "Consistency Enforcement Between Feature Store & Model Serving Layers", "key_points": [{"id": "KP1", "description": "Synchronized ingestion and automated dual-write synchronization: keeping online key-value stores in sync with offline storage.", "required": true, "acceptable_evidence": ["Technical keywords: Feast materialize / sync job, streaming ingestion (Kafka/Kinesis), dual-write, change data capture (CDC), TTL management.", "Executes automated materialization jobs that continuously sync precomputed batch features from offline tables into the online Redis/DynamoDB store.", "Leverages streaming pipelines (e.g. Kafka into Feast) to push real-time feature updates directly into the online store with minimal lag."]}, {"id": "KP2", "description": "Shared transformation libraries and schema validation: eliminating code divergence between training and serving.", "required": true, "acceptable_evidence": ["Technical keywords: shared transformation logic, packaged feature engineering library, Pydantic / protobuf schema validation, versioned feature views.", "Packages feature calculation functions into a single shared Python library imported by both offline batch pipelines and real-time APIs.", "Validates feature names, data types, and null constraints against versioned feature store definitions before model scoring."]}, {"id": "KP3", "description": "Continuous monitoring and drift detection: validating consistency and catching feature divergence in production.", "required": true, "acceptable_evidence": ["Technical keywords: feature distribution monitoring, Evidently AI / Great Expectations, Kolmogorov-Smirnov (KS) test, population stability index (PSI), drift alerts.", "Logs real-time feature vectors served to models and periodically compares their statistical distributions against offline baseline features.", "Triggers automated alerts when divergence metrics (e.g. PSI > 0.2) indicate potential upstream data corruption or pipeline delays."]}], "critical_failures": ["Maintaining separate, duplicated feature calculation codebases for training (Python) and serving (Java/C++ or raw SQL).", "Failing to explain how offline and online stores are synchronized (materialization/streaming).", "Omitting monitoring for training-serving skew or statistical feature distribution drift."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What are your career interests within machine learning, and what types of problems or domains are you most interested in working on?', '{"subcategory": "Machine Learning Career Interests & Target Problem Domains", "key_points": [{"id": "KP1", "description": "Target problem domains and business challenges: articulating a passion for enterprise automation, retrieval, and decision systems.", "required": true, "acceptable_evidence": ["Technical keywords: target domains, enterprise conversational AI, intelligent retrieval (RAG), agentic workflow automation, high-throughput recommendation systems.", "Expresses strong motivation to solve complex operational challenges: reducing customer support friction, automating diagnostic workflows, and knowledge discovery.", "Focuses on domains where machine learning directly interfaces with users or mission-critical backend processes."]}, {"id": "KP2", "description": "Technical focus areas: deepening mastery in multi-agent orchestration, evaluation rigor, and low-latency systems.", "required": true, "acceptable_evidence": ["Technical keywords: technical specialization, stateful multi-agent systems (LangGraph), Model Context Protocol (MCP), LLM evaluation frameworks (RAGAS), latency optimization.", "Excited by emerging frontiers in agent coordination: combining deterministic graph boundaries with autonomous cognitive tool execution.", "Committed to rigorous evaluation methodologies and building transparent, grounded AI systems."]}, {"id": "KP3", "description": "Engineering philosophy and long-term career impact: building scalable, durable software rather than short-lived prototypes.", "required": true, "acceptable_evidence": ["Technical keywords: production engineering mindset, scalable architecture, reliable systems, long-term impact, continuous learning, business ROI.", "Emphasizes delivering durable production value, optimizing infrastructure cost-per-query, and maintaining high uptime standards.", "Seeks opportunities to collaborate with high-caliber engineering teams solving challenging real-world scaling problems."]}], "critical_failures": ["Expressing vague, generic interests (''I just want to do AI'') without identifying specific technical areas or business domains.", "Focusing purely on academic research without interest in production engineering, systems architecture, or business impact.", "Lacking clarity on what makes agentic AI or retrieval systems compelling from an engineering perspective."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What is your educational background, and how has your degree in Electronics and Communication influenced your career in machine learning?', '{"subcategory": "Educational Background Influence on Machine Learning Engineering", "key_points": [{"id": "KP1", "description": "Mathematical and analytical foundation: leveraging signal processing, linear algebra, and probability theory.", "required": true, "acceptable_evidence": ["Technical keywords: engineering foundation (ECE/CS/EE), linear algebra, matrix operations, probability & statistics, signal processing, Fourier transforms.", "Explains how engineering coursework in linear algebra and vector calculus provided the exact mathematical framework needed for neural networks and embeddings.", "Draws direct parallels between digital signal processing (filtering, convolutions, feature extraction) and modern deep learning representations."]}, {"id": "KP2", "description": "Hardware intuition and low-level computing: understanding memory hierarchies, latency budgets, and resource constraints.", "required": true, "acceptable_evidence": ["Technical keywords: hardware architecture, memory bandwidth, compute constraints, embedded systems, low-level optimization, GPU parallelism.", "Highlights how an understanding of computer architecture informs practical MLOps decisions: cache locality, GPU memory bandwidth bottlenecks, and quantization.", "Instills a deep appreciation for latency budgets, computational efficiency, and resource optimization in production."]}, {"id": "KP3", "description": "Systems thinking and root-cause problem solving: applying first-principles debugging to complex AI systems.", "required": true, "acceptable_evidence": ["Technical keywords: first-principles thinking, systems engineering, modular decomposition, feedback control loops, root-cause debugging.", "Connects classical control systems and feedback loop theory directly to iterative agent reflection and Human-in-the-Loop workflows.", "Applies rigorous engineering discipline to isolate issues across complex distributed architectures."]}], "critical_failures": ["Dismissing educational background as completely irrelevant to software or machine learning.", "Failing to connect mathematical concepts (linear algebra, probability) or systems fundamentals to AI engineering.", "Lacking concrete examples of how engineering principles inform daily technical decision-making."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What does human-in-the-loop mean in the context of AI systems, and when would you incorporate it into a workflow?', '{"subcategory": "Human-in-the-Loop (HITL) Architecture & Workflow Integration Criteria", "key_points": [{"id": "KP1", "description": "Definition and core objectives of Human-in-the-Loop (HITL): introducing human oversight to augment model accuracy and ensure safety.", "required": true, "acceptable_evidence": ["Technical keywords: Human-in-the-Loop (HITL), hybrid intelligence, safety boundary, human oversight, model confidence, edge-case triage.", "Defines HITL as an architectural pattern where automated model execution is strategically paused to request human validation or decision-making.", "Balances the speed and cost efficiency of automated AI with the safety, accountability, and nuance of human judgment."]}, {"id": "KP2", "description": "Trigger criteria for human intervention: irreversible actions, financial impact, low confidence, and safety violations.", "required": true, "acceptable_evidence": ["Technical keywords: irreversible side effects, financial mutations, threshold confidence score (<0.75), safety guardrail trips, high-stakes decisions.", "Triggers HITL when an action cannot be automatically rolled back (e.g. canceling an insurance policy, issuing a large refund, executing a major DB migration).", "Halts execution when the model''s confidence or intent classification score falls below defined risk thresholds."]}, {"id": "KP3", "description": "Technical integration mechanisms: asynchronous interrupts, state persistence, and continuous feedback loops.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph interrupt(), state checkpointer, human approval UI, review payload, fine-tuning feedback dataset.", "Uses graph interruption primitives to persist workflow state to a database and notify an operator review portal via webhooks.", "Stores human corrections and approval logs to build high-quality golden evaluation datasets and DPO/RLHF fine-tuning corpora."]}], "critical_failures": ["Treating HITL as a manual bottleneck where humans must review every trivial, low-risk query.", "Failing to define clear, deterministic trigger criteria for when human review is required.", "Omitting how modern workflows suspend and resume execution asynchronously (e.g. LangGraph interrupt and checkpointers)."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What role does human-in-the-loop (HITL) play in your system, and when is it triggered?', '{"subcategory": "Human-in-the-Loop (HITL) Role & Trigger Conditions in Production Agent Systems", "key_points": [{"id": "KP1", "description": "Role of HITL in production safety and governance: acting as an approval firewall for high-consequence operations.", "required": true, "acceptable_evidence": ["Technical keywords: safety firewall, high-consequence operations, regulatory compliance, risk mitigation, Human-in-the-Loop.", "Serves as an authoritative safety barrier preventing autonomous agents from triggering unintended external API side effects.", "Ensures compliance with enterprise policies and legal mandates requiring human accountability for consequential decisions."]}, {"id": "KP2", "description": "Specific trigger scenarios: database mutations, external communications, and policy ambiguity.", "required": true, "acceptable_evidence": ["Technical keywords: database writes/updates, customer-facing emails/SMS, financial transactions, ambiguous intent, low confidence.", "Triggers whenever an agent attempts to execute external database writes, schedule customer appointments, or debit accounts.", "Activates when customer queries contain conflicting instructions or ambiguous policy edge cases."]}, {"id": "KP3", "description": "Implementation architecture: checkpointing, operator interface, and resume protocol.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph interrupt(), thread checkpointing, human review dashboard, approval token, execution resume.", "Pauses agent graph execution and persists state to a durable checkpointer, surfacing the pending action on a reviewer dashboard.", "Resumes graph execution seamlessly upon receiving the operator''s signed approval payload or modified input parameters."]}], "critical_failures": ["Describing simple print statements or CLI inputs as the production mechanism for human intervention.", "Failing to specify the concrete operations that trigger human review.", "Omitting how state is preserved while waiting for asynchronous human approval."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement human-in-the-loop workflows, and when is human intervention necessary in AI systems?', '{"subcategory": "Implementing HITL Workflows & Determining Human Intervention Necessity", "key_points": [{"id": "KP1", "description": "Criteria determining when human intervention is necessary: risk classification, compliance, and ethical boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: risk matrix, high-stakes decisioning, compliance mandates (HIPAA/GDPR), ethical boundaries, customer escalation.", "Applies a risk matrix: low-risk informational queries are fully automated, while high-risk transactional actions require human sign-off.", "Intervenes immediately when safety guardrails detect prompt injection attempts, toxic sentiment, or explicit customer requests for an agent."]}, {"id": "KP2", "description": "Architectural implementation: stateful graph interrupts, webhook dispatch, and operator authorization.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph interrupt(), webhook notification, persistent checkpointer, RBAC review portal, state mutation.", "Configures dedicated interrupt nodes in the agent graph that serialize current state and emit event notifications to operator queues.", "Allows authenticated operators to inspect context, edit proposed tool parameters, and submit an authorization payload."]}, {"id": "KP3", "description": "Closing the continuous learning loop: turning human intervention data into model improvements.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop data flywheels, active learning, correction logging, golden test case generation, DPO/RLHF tuning.", "Logs human modifications and overrides into structured datasets to identify recurring model failure modes.", "Feeds corrected trajectories back into prompt engineering iterations and fine-tuning datasets to reduce future human intervention rates."]}], "critical_failures": ["Failing to establish a risk-based threshold for when human intervention is required versus optional.", "Treating human intervention as an ad-hoc manual process without workflow suspension and resumption mechanics.", "Ignoring the feedback loop that utilizes human correction data to improve future autonomous accuracy."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Can you describe the architecture of the RAG-based AI assistant you built, including the tools and technologies used?', '{"subcategory": "RAG-Based AI Assistant System Architecture & Technology Stack", "key_points": [{"id": "KP1", "description": "Document ingestion and preprocessing pipeline: layout-aware parsing, chunking, and embedding generation.", "required": true, "acceptable_evidence": ["Technical keywords: Docling / Unstructured, layout-aware parsing, structure-aware chunking, Sentence Transformers (bge-large / MiniLM), metadata extraction.", "Parses unstructured enterprise documents (PDF manuals, customer logs) preserving tables, section headers, and reading order.", "Applies hierarchical chunking (512 tokens, 10-20% overlap) and generates dense vector embeddings stored with rich document metadata."]}, {"id": "KP2", "description": "Hybrid retrieval and reranking layer: combining dense similarity with lexical matching and cross-encoders.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, dense vector search (Milvus/Pinecone), sparse BM25, Reciprocal Rank Fusion (RRF), Cross-Encoder reranker (bge-reranker).", "Queries Milvus for semantic similarity and BM25 for exact keyword/part-number matching, fusing top-50 results with RRF.", "Re-scores fused candidate chunks using a cross-encoder to select the top-5 highest-relevance passages for context injection."]}, {"id": "KP3", "description": "Generation, guardrails, and serving infrastructure: orchestrating prompts with foundation models under security controls.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI backend, AWS Bedrock (Claude 3.5 Sonnet), Presidio PII masking, citation grounding, token streaming (SSE).", "Passes reranked chunks into strict prompt templates instructing the LLM to ground answers exclusively in retrieved evidence.", "Streams answers via FastAPI SSE endpoints with clickable citations while masking sensitive PII with Microsoft Presidio."]}], "critical_failures": ["Describing simple naive RAG (fixed-size chunking + basic vector search) without hybrid search or cross-encoder reranking.", "Failing to explain how tables and document structure were preserved during parsing.", "Omitting security guardrails (PII masking), citations, or response streaming."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Can you describe your experience building RAG architectures, including the models, embedding techniques, and orchestration frameworks you have used?', '{"subcategory": "RAG Architectures: Model Selection, Embedding Strategies & Orchestration Frameworks", "key_points": [{"id": "KP1", "description": "Embedding model evaluation and indexing strategy: selecting bi-encoders and index structures for domain data.", "required": true, "acceptable_evidence": ["Technical keywords: embedding models (BGE, text-embedding-3, MiniLM), HNSW index (M, efConstruction, efSearch), cosine similarity, vector dimensionality.", "Evaluates embedding models on MTEB benchmarks and internal domain data, choosing dense bi-encoders optimized for semantic retrieval.", "Configures HNSW indexing in vector databases with tuned parameters to achieve sub-15ms recall@50 under high QPS."]}, {"id": "KP2", "description": "Generation model selection and prompting strategies: balancing reasoning capacity, context window, and inference latency.", "required": true, "acceptable_evidence": ["Technical keywords: LLM selection (Claude 3.5 Sonnet, Llama-3-70B, GPT-4o), system prompt constraints, few-shot exemplars, structured output JSON.", "Selects models based on instruction-following fidelity, low hallucination rates, and cost-per-token economics.", "Constrains prompts with negative fallback instructions (''If context is insufficient, state you do not know'') to prevent hallucinations."]}, {"id": "KP3", "description": "Orchestration frameworks and pipeline control: managing retrieval augmentation and stateful dialogue.", "required": true, "acceptable_evidence": ["Technical keywords: orchestration (LangChain, LangGraph, LlamaIndex), cyclic workflows, state persistence, query transformation, fallback routes.", "Leverages LangGraph to orchestrate multi-step retrieval flows: query rewriting, routing between technical manuals and policy documents, and synthesis.", "Maintains multi-turn conversational context buffers to enable natural follow-up troubleshooting."]}], "critical_failures": ["Failing to explain the technical criteria used to select specific embedding or generation models.", "Describing fixed naive embeddings without discussing vector index configuration (HNSW parameters).", "Omitting orchestration frameworks and prompt constraint strategies."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your professional background and experience, particularly your work in AI/ML and RAG-based systems?', '{"subcategory": "Professional Background Overview: AI/ML Engineering & Enterprise RAG Systems", "key_points": [{"id": "KP1", "description": "Core technical identity: presenting a comprehensive track record building enterprise AI and retrieval architectures.", "required": true, "acceptable_evidence": ["Technical keywords: AI/ML systems engineer, enterprise RAG architectures, full-stack ML delivery, production deployments, career narrative.", "Introduces a proven track record architecting and productionizing high-throughput AI platforms and conversational assistants.", "Emphasizes combining deep machine learning foundations with rigorous software engineering and MLOps practices."]}, {"id": "KP2", "description": "Flagship RAG system implementation: detailing end-to-end delivery of an enterprise retrieval platform.", "required": true, "acceptable_evidence": ["Technical keywords: customer support RAG assistant, hybrid retrieval (Milvus + BM25), cross-encoder reranking, layout-aware parsing (Docling), AWS infrastructure.", "Walks through architecting an enterprise knowledge assistant that ingested thousands of technical PDF manuals and resolved complex customer inquiries.", "Highlights solving key production challenges: table extraction, hybrid search fusion, and strict citation grounding."]}, {"id": "KP3", "description": "Leadership, evaluation standards, and business outcomes: demonstrating technical excellence and measurable impact.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS evaluation framework, AHT reduction, ticket deflection rate, CI/CD automation, technical mentoring.", "Established automated evaluation suites measuring Faithfulness and Context Recall before deploying updates to production.", "Delivered measurable business outcomes (e.g. 35% reduction in support handling time and 40% automated deflection)."]}], "critical_failures": ["Providing a generic summary without discussing specific enterprise RAG projects or system architectures.", "Failing to mention evaluation frameworks or production engineering challenges.", "Omitting quantitative operational metrics and business impact."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'Can you explain the architecture and evolution of your RAG-based AI assistant, including how you incorporated agentic AI features?', '{"subcategory": "RAG Assistant Architecture Evolution: Integrating Agentic AI Features", "key_points": [{"id": "KP1", "description": "Phase 1 Baseline (Static RAG): linear pipeline limitations and inability to perform multi-step execution.", "required": true, "acceptable_evidence": ["Technical keywords: Phase 1 static RAG, linear pipeline (retrieval -> generation), passive question answering, single-turn limitation, lack of tool invocation.", "Explains the initial system was a read-only informational pipeline that retrieved static text and generated answers.", "Identifies limitations: could not handle multi-part queries, verify missing information, or take actions in external software."]}, {"id": "KP2", "description": "Phase 2 Evolution (Agentic RAG): introducing LangGraph cyclic graphs, supervisory routing, and tool integration.", "required": true, "acceptable_evidence": ["Technical keywords: Phase 2 Agentic AI, LangGraph StateGraph, supervisor router, autonomous tool calling, API integration (CRM, ticketing), cyclic iteration.", "Evolved the architecture into a cyclic state graph where an orchestrator delegates tasks to specialized worker nodes.", "Equipped agents with active transactional tools: querying customer databases, verifying warranty records, and booking service dispatches."]}, {"id": "KP3", "description": "Operational and governance enhancements: state persistence, Human-in-the-Loop gates, and measurable UX improvements.", "required": true, "acceptable_evidence": ["Technical keywords: thread checkpointing, Human-in-the-Loop (HITL) interrupt, Pydantic validation, Presidio PII masking, end-to-end task fulfillment.", "Added durable checkpointing to maintain state across multi-turn diagnostic workflows and enabled HITL approval gates for sensitive actions.", "Transformed user experience from passive advice to automated end-to-end resolution, significantly boosting operational efficiency."]}], "critical_failures": ["Describing simple prompt adjustments rather than architectural shifts from linear pipelines to cyclic agent graphs.", "Failing to explain how the system gained the ability to execute transactional actions and call external APIs.", "Omitting state management, Human-in-the-Loop controls, or business impact differences between Phase 1 and Phase 2."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you explain your transition from a RAG-only system to a multi-agent agentic AI solution, and what improvements it brought?', '{"subcategory": "Transition from RAG-Only to Multi-Agent Agentic AI Architecture: Key Improvements", "key_points": [{"id": "KP1", "description": "Catalyst for architectural transition: identifying failure modes of monolithic RAG in complex enterprise workflows.", "required": true, "acceptable_evidence": ["Technical keywords: RAG limitations, multi-intent failure, context stuffing, lack of execution autonomy, passive lookup vs active workflow.", "Monolithic RAG failed on multi-step inquiries requiring data from multiple systems (e.g. checking manual specs AND scheduling a repair).", "Stuffing diverse retrieved contexts into a single prompt caused distraction, hallucination, and inability to perform write actions."]}, {"id": "KP2", "description": "Multi-agent architecture implementation: decoupling capabilities into specialized supervisor and worker nodes.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, supervisor orchestrator, specialized worker agents (diagnostic, booking, policy), domain tools, conditional routing.", "Decomposed the system into an orchestrator that routes tasks to dedicated domain agents equipped with specialized tools and scoped prompts.", "Each agent focuses on a single responsibility, preventing tool confusion and context window bloat."]}, {"id": "KP3", "description": "Measurable business and operational improvements: end-to-end task resolution, error recovery, and deflection.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end task automation, self-correction loops, deflection rate increase, AHT reduction, auditability.", "Agents autonomously retry failed tool calls and self-correct based on intermediate tool outputs without user re-prompting.", "Enabled complete autonomous fulfillment of tier-1 support requests, increasing inquiry deflection from 15% to over 40%."]}], "critical_failures": ["Failing to explain why standard RAG was insufficient for complex multi-step enterprise workflows.", "Describing multi-agent systems without clear role decomposition or supervisory coordination.", "Omitting the concrete operational improvements (self-correction, API action execution, deflection gains) achieved by the transition."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Can you please explain end to end architecture or your thought process for a production based RAG system?', '{"subcategory": "Production RAG End-to-End Architecture & Design Philosophy", "key_points": [{"id": "KP1", "description": "Ingestion and preprocessing foundation: layout-aware document extraction, semantic chunking, and dual-index generation.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware parsing (Docling), structure-aware chunking, dense embeddings (BGE-large), sparse lexical index (BM25), metadata enrichment.", "Extracts clean text and complex tables from enterprise PDFs while preserving reading order and section headers.", "Generates 512-token semantic chunks with 15% overlap and attaches rich metadata (document_id, section, department, access_tier)."]}, {"id": "KP2", "description": "Hybrid retrieval and cross-encoder precision ranking: multi-channel candidate generation and cross-attention scoring.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid search, dense vector ANN (Milvus HNSW), sparse BM25, Reciprocal Rank Fusion (RRF), cross-encoder reranker (bge-reranker-large).", "Executes parallel dense semantic search and sparse keyword matching to capture both conceptual intent and exact part numbers/acronyms.", "Fuses candidates via RRF and scores top-50 passages with a cross-encoder, selecting the top-5 most relevant chunks for prompt assembly."]}, {"id": "KP3", "description": "Generation controls, guardrails, and telemetry: constrained prompt synthesis and real-time observability.", "required": true, "acceptable_evidence": ["Technical keywords: strict negative constraints, Presidio PII masking, token streaming (SSE), RAGAS evaluation, OpenTelemetry.", "Injects retrieved context into prompts with strict negative fallbacks: ''Answer strictly using provided context; state if information is missing.''", "Streams generated responses with verifiable citations while monitoring P95 latency and factual grounding in production."]}], "critical_failures": ["Describing naive RAG without layout-aware parsing, hybrid search, or cross-encoder reranking.", "Failing to enforce prompt negative fallback instructions or PII guardrails.", "Omitting production considerations like latency budgets and evaluation telemetry."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'How did the transition from a basic RAG system to an agentic workflow improve user experience and operational efficiency?', '{"subcategory": "Operational & UX Gains: Transitioning from Static RAG to Agentic Workflows", "key_points": [{"id": "KP1", "description": "User experience transformation: moving from passive text lookup to interactive, multi-step problem resolution.", "required": true, "acceptable_evidence": ["Technical keywords: user experience (UX), conversational continuity, interactive troubleshooting, passive lookup vs active resolution.", "Eliminates user frustration caused by single-turn dead ends where the user must copy-paste model advice into separate tools.", "Guides users through dynamic, multi-turn diagnostic trees, proactively requesting missing details to reach resolution."]}, {"id": "KP2", "description": "Automated action execution and system integration: empowering the assistant to fulfill tasks via enterprise APIs.", "required": true, "acceptable_evidence": ["Technical keywords: API task fulfillment, CRM record updates, dispatch ticket booking, transactional tools, end-to-end automation.", "Integrates with backend systems (e.g. Salesforce, SAP, Jira) allowing the agent to check warranty claims, update records, and schedule technicians.", "Transforms the assistant from a read-only knowledge base into an autonomous operations worker."]}, {"id": "KP3", "description": "Operational metric impact: quantifying deflection improvements and average handling time reduction.", "required": true, "acceptable_evidence": ["Technical keywords: Average Handling Time (AHT) reduction, first-contact resolution (FCR), inquiry deflection rate, cost per contact.", "Reduces support call handle time by over 35% by automating routine repetitive diagnostic and booking steps.", "Increases self-service deflection from 15% to 42%, freeing human agents to focus on complex escalated cases."]}], "critical_failures": ["Failing to contrast the user experience differences between static text answers and interactive task completion.", "Omitting the capability to call transactional enterprise APIs for end-to-end task fulfillment.", "Failing to provide concrete operational metrics (AHT, deflection rate) resulting from the transition."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How did your RAG system evolve from a proof-of-concept to a scalable architecture, and what role did different play in that transition?', '{"subcategory": "RAG System Evolution: From Streamlit POC to Scalable Production Architecture", "key_points": [{"id": "KP1", "description": "POC architecture limitations: single-node bottlenecks, in-memory vector stores, and naive chunking.", "required": true, "acceptable_evidence": ["Technical keywords: POC limitations, Streamlit monolithic script, ChromaDB in-memory, LangChain basic chain, naive character chunking.", "The proof-of-concept ran as a local monolithic Streamlit app using local ChromaDB storage and fixed character splitting.", "Suffered from table corruption in PDFs, lack of concurrency, high query latency, and inability to scale past a few documents."]}, {"id": "KP2", "description": "Production architecture overhaul: distributed vector databases, asynchronous APIs, and advanced indexing.", "required": true, "acceptable_evidence": ["Technical keywords: distributed vector database (Milvus cluster), FastAPI async microservices, Docling parsing, hybrid retrieval (BM25 + HNSW), EKS.", "Replaced local ChromaDB with a distributed Milvus cluster on Kubernetes with sharded HNSW collections.", "Separated frontend into React and backend into scalable FastAPI microservices running on Amazon EKS behind load balancers."]}, {"id": "KP3", "description": "Enterprise reliability, security, and governance: introducing rerankers, guardrails, and automated evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder reranker, Presidio PII masking, RBAC metadata filtering, RAGAS automated evaluation CI/CD, CloudWatch.", "Integrated cross-encoder rerankers to improve precision@5 from 62% to 89% and added metadata pre-filtering for access control.", "Established automated CI/CD evaluation pipelines running RAGAS benchmarks against golden datasets on every deployment."]}], "critical_failures": ["Claiming that a local Streamlit prototype with embedded ChromaDB is suitable for enterprise production.", "Failing to explain how vector storage, backend compute, and document parsing were scaled.", "Omitting security, evaluation benchmarking, and access control additions made during productionization."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'EASY', 'SPECIFIC', 60, 'How does metadata filtering work in a vector database, and why is it important?', '{"subcategory": "Metadata Filtering Mechanics in Vector Databases: Importance & Execution Modes", "key_points": [{"id": "KP1", "description": "Core purpose of metadata filtering: enforcing access control, temporal relevance, and scoped domain retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: metadata filtering, payload filtering, tenant isolation, role-based access control (RBAC), document versioning, date ranges.", "Ensures similarity search is constrained to documents matching user permissions, specific vehicle models, or current date ranges.", "Prevents returning unauthorized confidential records or obsolete deprecated technical guidelines."]}, {"id": "KP2", "description": "Pre-filtering vs. Post-filtering execution mechanics and algorithmic trade-offs.", "required": true, "acceptable_evidence": ["Technical keywords: pre-filtering, post-filtering, single-stage filtered HNSW, candidate exhaustion, recall degradation.", "Post-filtering performs ANN search first and then drops non-matching chunks, risking severe recall drop if top-k lacks valid metadata matches.", "Pre-filtering restricts the search graph to matching metadata nodes before traversing similarity edges, guaranteeing valid results but requiring indexed scalar fields."]}, {"id": "KP3", "description": "Implementation in production vector engines (Milvus / Pinecone): boolean expression filters on scalar indexes.", "required": true, "acceptable_evidence": ["Technical keywords: boolean expression (expr), scalar inverted index, Milvus scalar field indexing, hybrid query execution.", "Builds inverted scalar indexes on categorical fields (e.g. `department_id`, `product_tier`) alongside HNSW vector indexes.", "Executes combined queries: e.g. `client.search(collection, vectors, filter=''department == \"Engineering\" and version >= 2.0'')`."]}], "critical_failures": ["Confusing database metadata filtering with prompting the LLM to ignore retrieved text it shouldn''t read.", "Failing to explain the critical difference and recall trade-offs between pre-filtering and post-filtering.", "Omitting how scalar indexes work alongside vector indexes in modern vector databases."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'What are the fundamental differences between RAG systems and agentic architectures, and when would you prefer one over the other?', '{"subcategory": "Fundamental Distinctions: RAG Systems vs. Agentic Architectures & Selection Criteria", "key_points": [{"id": "KP1", "description": "Control flow topology: static linear retrieval chains (DAG) vs dynamic cyclic graph reasoning (StateGraph).", "required": true, "acceptable_evidence": ["Technical keywords: static linear chain (RAG), cyclic execution (Agentic), Directed Acyclic Graph (DAG), autonomous loops, reflection, branching.", "Traditional RAG follows a fixed deterministic pipeline: Query $\\rightarrow$ Retrieve $\\rightarrow$ Context $\\rightarrow$ Generate.", "Agentic architectures operate as dynamic cyclic state machines that can iteratively query tools, inspect outputs, self-correct, and branch dynamically."]}, {"id": "KP2", "description": "Execution capability: passive read-only information retrieval vs active task automation and tool calling.", "required": true, "acceptable_evidence": ["Technical keywords: read-only knowledge lookup, action execution, API mutations, tool calling, multi-step task completion.", "RAG is strictly an informational lookup mechanism that synthesizes text based on static reference material.", "Agents possess execution capability: querying databases, triggering third-party APIs, creating tickets, and modifying external system state."]}, {"id": "KP3", "description": "Selection criteria and operational trade-offs: latency, cost, determinism, and complexity.", "required": true, "acceptable_evidence": ["Technical keywords: selection criteria, low latency SLA (<1s), deterministic predictability, non-deterministic branching, token cost budget.", "Prefer standard RAG when queries are purely informational, low-latency (<1s) is required, and token cost must remain predictable and bounded.", "Prefer Agentic AI when problems require multi-step planning, tool interaction, query decomposition, or autonomous end-to-end task fulfillment."]}], "critical_failures": ["Treating Agentic AI simply as ''RAG with a longer prompt'' without recognizing tool calling and cyclic control flow.", "Failing to identify when traditional RAG is preferable (lower latency, lower cost, deterministic predictable execution).", "Omitting the distinction between read-only text synthesis and active API task execution."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'What are the limitations of a RAG system, and when would you transition to an agentic architecture?', '{"subcategory": "Limitations of Standard RAG & Architectural Triggers for Transitioning to Agents", "key_points": [{"id": "KP1", "description": "Inherent limitations of standard RAG: single-pass failures on complex, multi-intent, or ambiguous queries.", "required": true, "acceptable_evidence": ["Technical keywords: single-pass retrieval failure, multi-intent queries, context stuffing, semantic distraction, lack of query reformulation.", "Standard RAG cannot resolve compound questions requiring information from multiple disparate documents across several steps.", "If the initial retrieval retrieves irrelevant context, the generator has no mechanism to critique the retrieved chunks or reformulate its search."]}, {"id": "KP2", "description": "Inability to interact with external systems or perform mutations: read-only boundary constraints.", "required": true, "acceptable_evidence": ["Technical keywords: read-only boundary, absence of tool integration, inability to execute writes, transactional gap, passive recommendations.", "RAG cannot query live customer account balances, update appointment schedules, or trigger webhook workflows.", "Leaves the operational burden on the human user to manually act on the synthesized advice."]}, {"id": "KP3", "description": "Transition criteria: adopting agentic architectures when workflows require planning, verification, and action execution.", "required": true, "acceptable_evidence": ["Technical keywords: transition threshold, multi-step planning, iterative self-correction, dynamic tool calling, Human-in-the-Loop gates.", "Transition to an agentic architecture when the use case demands autonomous task execution, cyclic tool exploration, and self-validation.", "Introduces LangGraph cyclic state graphs to allow agents to assess retrieval sufficiency before deciding to respond or perform actions."]}], "critical_failures": ["Failing to explain the technical root causes of RAG failure modes (single-pass retrieval limits, lack of self-correction).", "Omitting the operational necessity of tool calling and transactional action execution.", "Failing to define clear criteria for when an engineering team should transition from RAG to an agentic architecture."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What changes did you introduce when transitioning from a RAG-based system to a multi-agent architecture?', '{"subcategory": "Architectural Changes Introduced When Transitioning to Multi-Agent Systems", "key_points": [{"id": "KP1", "description": "Decomposing monolithic prompt pipelines into specialized worker agents: scoping tools and prompts per domain.", "required": true, "acceptable_evidence": ["Technical keywords: domain decomposition, specialized worker agents, scoped system prompts, tool isolation, triage agent, booking agent.", "Replaced a single bloated prompt with dedicated agent nodes (e.g. diagnostics agent, scheduling agent, warranty agent).", "Bound specific tool subsets to each agent to eliminate parameter hallucination and tool confusion."]}, {"id": "KP2", "description": "Introducing supervisory orchestration and cyclic state graphs: managing routing and handoffs via LangGraph.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, supervisor orchestrator node, conditional edges, dynamic dispatch, shared state schema.", "Implemented an orchestrator node that evaluates user intent, delegates execution to worker nodes, and routes responses dynamically.", "Replaced static DAG pipelines with cyclic state graphs capable of looping back for additional information."]}, {"id": "KP3", "description": "Adding state persistence, safety guardrails, and Human-in-the-Loop controls: ensuring durable and secure execution.", "required": true, "acceptable_evidence": ["Technical keywords: persistent checkpointer (Postgres/Redis), thread checkpointing, Human-in-the-Loop (HITL) interrupt, Pydantic validation.", "Integrated durable checkpointers allowing multi-turn conversations and long-running workflows to pause and resume without state loss.", "Inserted interrupt approval gates before high-risk external API actions to enforce human operator governance."]}], "critical_failures": ["Describing the change as simply writing longer prompts with more instructions.", "Failing to explain how multi-agent coordination, routing, and shared state were architected in code.", "Omitting tool isolation, state checkpointing, or Human-in-the-Loop safety additions."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What considerations influenced your choice of like FAISS or Pinecone, and how did you ensure scalability?', '{"subcategory": "Vector Database Selection: FAISS vs. Pinecone & Scalability Considerations", "key_points": [{"id": "KP1", "description": "FAISS architectural profile: high-performance local library for embedding search without distributed database management.", "required": true, "acceptable_evidence": ["Technical keywords: FAISS (Facebook AI Similarity Search), C++ library with Python bindings, in-memory index, GPU acceleration, lack of persistence/CRUD.", "FAISS provides ultra-fast vector similarity search algorithms (IVF, HNSW, PQ) with raw GPU acceleration.", "However, it is an algorithm library, not a distributed database: lacks native multi-tenancy, real-time CRUD mutations, and horizontal replication out of the box."]}, {"id": "KP2", "description": "Pinecone architectural profile: managed serverless cloud vector database with real-time indexing and metadata filtering.", "required": true, "acceptable_evidence": ["Technical keywords: Pinecone, fully managed serverless vector database, real-time index updates, native metadata filtering, high availability.", "Provides a cloud-native managed service with automated scaling, replication, zero infrastructure maintenance, and instant CRUD updates.", "Native support for expressive metadata filtering during vector search."]}, {"id": "KP3", "description": "Scalability considerations and decision criteria: dataset size, latency SLA, operational budget, and compliance boundaries.", "required": true, "acceptable_evidence": ["Technical keywords: scalability trade-offs, dataset scale (billions of vectors), operational overhead, enterprise VPC compliance, cost-per-query.", "Choose FAISS for local batch jobs, air-gapped on-premise environments, or embedded high-throughput microservices where operational teams can manage memory.", "Choose Pinecone (or Milvus) for enterprise production RAG requiring multi-tenant metadata filtering, high availability SLAs, and zero operational management."]}], "critical_failures": ["Treating FAISS as a managed distributed database server with built-in networking, replication, and persistence.", "Failing to contrast the operational maintenance burden of self-managed libraries (FAISS) with cloud-managed databases (Pinecone).", "Omitting real-time CRUD mutations and metadata filtering capabilities."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What experience do you have with transitioning from RAG systems to agentic workflows, and what motivated that shift?', '{"subcategory": "Experience Transitioning RAG Systems to Agentic Workflows & Motivation Rationale", "key_points": [{"id": "KP1", "description": "Real-world friction driving the transition: identifying business and workflow failure points in passive RAG.", "required": true, "acceptable_evidence": ["Technical keywords: transition motivation, business friction, customer support bottlenecks, manual agent overhead, passive Q&A vs active fulfillment.", "Observes that customers did not just want answers—they wanted actions completed (e.g. appointment scheduling, claim filing).", "Static RAG required human customer service reps to take the model''s text answer and manually re-enter data into ERP/CRM systems."]}, {"id": "KP2", "description": "Architectural refactoring: introducing LangGraph cyclic state orchestration, domain tools, and stateful tracking.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph refactoring, StateGraph, autonomous tool invocation, external REST APIs, state checkpointing, error recovery.", "Refactored the linear pipeline into a stateful multi-agent system where agents query diagnostic tools and trigger booking APIs.", "Enabled the system to inspect intermediate tool errors, self-correct parameter arguments, and retry autonomously."]}, {"id": "KP3", "description": "Delivering measurable business outcomes: tracking deflection, accuracy, and operational efficiency gains.", "required": true, "acceptable_evidence": ["Technical keywords: quantifiable impact, deflection rate improvement, average handle time reduction, customer satisfaction (CSAT), auditability.", "Increased end-to-end automated resolution from 18% to over 45%, eliminating manual agent re-keying.", "Maintained complete audit trails of all tool actions, establishing trust with business operations stakeholders."]}], "critical_failures": ["Describing the motivation as chasing technical trends rather than solving concrete operational and business bottlenecks.", "Failing to explain the technical architecture implemented during the transition (LangGraph, tool calling, state).", "Omitting quantitative operational metrics and business impact resulting from the shift."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'BROAD', 120, 'What have you been working on recently, and can you describe the end-to-end architecture of the RAG-based AI assistant you built?', '{"subcategory": "Recent Project Deep Dive: End-to-End RAG-Based AI Assistant Architecture", "key_points": [{"id": "KP1", "description": "Project overview and problem domain: building an enterprise retrieval assistant for high-consequence customer operations.", "required": true, "acceptable_evidence": ["Technical keywords: recent AI project, EV customer call center assistant / TalentScreen, domain problem framing, technical manuals, knowledge fragmentation.", "Architected an end-to-end RAG assistant ingesting thousands of multi-page technical vehicle manuals, warranty guides, and dealer logs.", "Solved acute operational challenges: long customer hold times, inaccurate repair diagnostic guidance, and compliance risks."]}, {"id": "KP2", "description": "Technical architecture across the pipeline: ingestion, hybrid retrieval, reranking, and generation.", "required": true, "acceptable_evidence": ["Technical keywords: Docling layout-aware parsing, Milvus distributed vector DB, BM25 sparse search, cross-encoder (bge-reranker-large), Claude 3.5 Sonnet on Bedrock.", "Employed Docling to extract multi-column text and tables into structured Markdown chunks, indexed into Milvus and BM25.", "Fused candidate matches with RRF, scored top-50 passages with a cross-encoder, and generated grounded answers with strict citation grounding."]}, {"id": "KP3", "description": "Production engineering rigor, safety guardrails, and business outcomes: ensuring reliability and measurable ROI.", "required": true, "acceptable_evidence": ["Technical keywords: Presidio PII masking, token streaming via SSE, RAGAS evaluation suite, average handling time (AHT) reduced by 35%, deflection rate.", "Integrated automated PII masking on queries and responses, and established CI/CD evaluation pipelines monitoring Faithfulness and Answer Relevance.", "Deployed containerized FastAPI microservices on Amazon EKS, achieving sub-1.5s P95 time-to-first-token with 35% reduction in support AHT."]}], "critical_failures": ["Describing a basic tutorial or toy project without enterprise scale, complex document parsing, or production infrastructure.", "Failing to detail the technical components across all pipeline stages (ingestion, retrieval, ranking, generation).", "Omitting quantitative business metrics, latency SLAs, or safety guardrails."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What interests you about working in RAG and generative AI systems, and how have you applied these concepts in your recent work?', '{"subcategory": "Technical Passion & Practical Application in RAG & Generative AI Systems", "key_points": [{"id": "KP1", "description": "Core technical fascination: solving the grounding and hallucination challenge in non-deterministic systems.", "required": true, "acceptable_evidence": ["Technical keywords: grounding problem, deterministic bounds on probabilistic models, information retrieval, knowledge fidelity, semantic search.", "Fascinated by bridging the gap between vast unstructured enterprise knowledge and precise autoregressive language model reasoning.", "Passionate about designing architectures that eliminate hallucinations and provide verifiable, deterministic source provenance."]}, {"id": "KP2", "description": "Hands-on application in recent systems: building sophisticated multi-stage retrieval and evaluation pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid search (dense + sparse), cross-encoder reranking, layout-aware parsing (Docling), RAGAS evaluation, LangGraph.", "Applied these principles by building production systems featuring table extraction, hybrid search fusion, and cross-encoder precision ranking.", "Instituted rigorous offline evaluation benchmarks measuring Context Recall and Answer Relevance before production rollouts."]}, {"id": "KP3", "description": "Engineering philosophy and future vision: evolving retrieval systems into autonomous operational platforms.", "required": true, "acceptable_evidence": ["Technical keywords: enterprise impact, autonomous task execution, agentic workflows, Model Context Protocol (MCP), continuous learning.", "Views RAG not as a static question-answering tool, but as the foundational perception and memory substrate for agentic decision systems.", "Focuses on delivering durable, high-ROI software that measurably transforms enterprise productivity."]}], "critical_failures": ["Giving vague, superficial answers about ''AI being the future'' without technical depth.", "Failing to connect theoretical interest to concrete production implementations and architectures built.", "Omitting evaluation rigor, grounding mechanisms, or practical engineering challenges."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What interests you most about future work in agentic AI, RAG systems, or emerging technologies such as MCP?', '{"subcategory": "Future Horizons in Agentic AI, RAG & Emerging Protocols (MCP)", "key_points": [{"id": "KP1", "description": "Standardization via Model Context Protocol (MCP): breaking down monolithic tool silos in distributed systems.", "required": true, "acceptable_evidence": ["Technical keywords: Model Context Protocol (MCP), open protocol standard, client-host-server, tool discovery, dynamic context injection.", "Excited by MCP''s ability to decouple LLM applications from proprietary tool integrations via an open JSON-RPC standard.", "Envisions enterprise ecosystems where agents seamlessly connect to diverse internal databases, ERPs, and APIs with standardized security."]}, {"id": "KP2", "description": "Evolution of RAG into Agentic Knowledge Graphs & Long-Term Memory: combining graph traversal with vector proximity.", "required": true, "acceptable_evidence": ["Technical keywords: GraphRAG, knowledge graphs, entity-relationship traversal, long-term episodic memory, stateful checkpointing.", "Anticipates moving beyond flat vector embeddings toward hybrid knowledge graphs that capture multi-hop entity relationships.", "Focuses on designing hierarchical agent memory architectures that maintain user context across months of interactions."]}, {"id": "KP3", "description": "Autonomous multi-agent collaboration with bounded governance: balancing agent autonomy with strict determinism.", "required": true, "acceptable_evidence": ["Technical keywords: multi-agent collaboration, supervisor arbitration, bounded autonomy, Human-in-the-Loop (HITL), self-healing workflows.", "Interested in developing distributed multi-agent swarms capable of collaborative task execution while operating within strict policy guardrails.", "Emphasizes that future advancements must prioritize transparency, auditability, and robust failure recovery in enterprise environments."]}], "critical_failures": ["Speaking in sci-fi generalities (AGI hype) without grounding future interests in concrete software engineering concepts (MCP, GraphRAG).", "Failing to explain what MCP is or why standardized protocols are critical for distributed agent systems.", "Ignoring enterprise governance, safety boundaries, and reliability in future agentic vision."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'What is your experience building and deploying RAG-based applications using large language models like GPT-3 or GPT-4?', '{"subcategory": "Building & Deploying RAG Applications with Foundation Models (GPT-4 / Claude)", "key_points": [{"id": "KP1", "description": "Foundation model selection and prompt orchestration: leveraging high-reasoning models under strict context constraints.", "required": true, "acceptable_evidence": ["Technical keywords: GPT-4 / Claude 3.5 Sonnet, prompt templating, system instructions, negative constraints, in-context learning.", "Selects foundation models based on instruction-following fidelity, low hallucination rates, and long-context reasoning capabilities.", "Structures prompts with explicit boundary instructions: ''Answer strictly using provided context; state if information is missing.''", "Formats retrieved passages with clear chunk identifiers for verifiable source attribution."]}, {"id": "KP2", "description": "Retrieval engineering and context optimization: managing context windows, token budgets, and relevance density.", "required": true, "acceptable_evidence": ["Technical keywords: context window optimization, token budget management, cross-encoder reranking, lost-in-the-middle mitigation.", "Prunes candidate passages using cross-encoders to ensure only high-density, relevant context enters the model prompt.", "Strategically positions the most critical evidence at the beginning and end of the context to counteract ''lost-in-the-middle'' attention decay."]}, {"id": "KP3", "description": "Production deployment, streaming, and cost governance: optimizing latency, spend, and user experience.", "required": true, "acceptable_evidence": ["Technical keywords: token streaming (Server-Sent Events), time-to-first-token (<800ms), token cost optimization, semantic caching, rate limiting.", "Implements streaming APIs via FastAPI and SSE to deliver real-time token rendering for end users.", "Deploys semantic caching (e.g. GPTCache/Redis) for frequent queries to bypass redundant foundation model calls and control API spend."]}], "critical_failures": ["Describing simple direct model prompting without retrieval augmentation or external context injection.", "Failing to address token economics, cost optimization, or latency SLAs in foundation model deployments.", "Omitting prompt negative fallback instructions or context placement strategies to prevent hallucinations."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What or ranking systems have you used, and how do ChromaDB, PGVector, and Milvus differ in terms of scalability and use cases?', '{"subcategory": "Vector Database Comparison: ChromaDB vs. PGVector vs. Milvus Across Scalability & Use Cases", "key_points": [{"id": "KP1", "description": "ChromaDB architectural profile: lightweight, embedded vector store optimized for rapid prototyping and local development.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB, embedded database, DuckDB/ClickHouse backend, local prototyping, single-node, zero-configuration.", "Best suited for rapid proof-of-concept development and local testing with minimal setup overhead.", "Limitations: lacks enterprise horizontal scaling, distributed sharding, high-availability replication, and advanced multi-tenancy."]}, {"id": "KP2", "description": "PGVector architectural profile: relational extension adding vector similarity search directly into PostgreSQL.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector, PostgreSQL extension, IVFFlat, HNSW indexing, relational joins, ACID transactions, operational simplicity.", "Best suited for small-to-medium vector collections (<5M vectors) where teams already rely heavily on PostgreSQL.", "Allows joining vector similarity directly with relational tables in a single SQL query, simplifying operational footprint but consuming high DB CPU/RAM."]}, {"id": "KP3", "description": "Milvus architectural profile: purpose-built, cloud-native distributed vector database for massive scale and low latency.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed, cloud-native, disaggregated compute and storage, MinIO/S3, Kafka log broker, billions of vectors, multi-tenancy.", "Best suited for enterprise-scale vector collections (>10M to billions of vectors) with high concurrent QPS and sub-20ms latency SLAs.", "Features disaggregated compute/storage architecture, partition keys for strict multi-tenant isolation, and specialized hardware acceleration."]}], "critical_failures": ["Recommending ChromaDB for high-throughput distributed enterprise production serving.", "Failing to explain how PGVector enables relational SQL joins with vector embeddings in PostgreSQL.", "Omitting Milvus''s distributed compute-storage disaggregation and multi-tenant scaling capabilities."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What role did cross-encoder re-ranking play in your retrieval pipeline, and how did it affect overall system accuracy?', '{"subcategory": "Role of Cross-Encoder Re-Ranking in Retrieval Pipelines & Overall System Accuracy", "key_points": [{"id": "KP1", "description": "Algorithmic mechanism of Cross-Encoders: joint cross-attention over concatenated query-document token pairs.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder (bge-reranker-large, ms-marco-MiniLM), joint cross-attention, concatenated input [CLS] query [SEP] doc [SEP], full token interaction.", "Unlike bi-encoders which embed query and document independently, cross-encoders feed query and passage together through all transformer layers.", "Computes full pairwise cross-attention between every query token and document token, capturing nuanced syntactic and semantic relationships."]}, {"id": "KP2", "description": "Two-stage retrieval funnel architecture: balancing bi-encoder recall with cross-encoder precision.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval, first-stage high recall (top-50/top-100), second-stage precision ranking (top-5), latency-accuracy trade-off.", "First-stage vector/BM25 search retrieves a broad candidate pool (top-50) in sub-15ms using precomputed embeddings.", "Second-stage cross-encoder scores the 50 candidates in ~30-50ms, pruning irrelevant candidates down to the top-5 highest-quality passages."]}, {"id": "KP3", "description": "Measurable impact on system accuracy and hallucination reduction: boosting precision and filtering noise.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K improvements, NDCG@K, noise filtration, hallucination suppression, context window optimization.", "Significantly boosts Precision@5 (e.g. from 62% to 88%), ensuring that only factual, highly relevant passages reach the LLM prompt.", "Filters out semantically adjacent but factually irrelevant distractor chunks, directly reducing generator hallucination rates."]}], "critical_failures": ["Confusing Cross-Encoders with Bi-Encoders and claiming cross-encoders precompute standalone document vectors for vector database indexing.", "Failing to explain the two-stage retrieval funnel (high-recall first stage + high-precision reranking).", "Omitting the computational cost trade-off (cross-attention latency vs accuracy gains)."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What role did tools like LangChain, Sentence Transformers, and Milvus play in your system, and how did they integrate together?', '{"subcategory": "Integration Synergy: LangChain, Sentence Transformers & Milvus in Production RAG", "key_points": [{"id": "KP1", "description": "Sentence Transformers role: generating dense contextual semantic embeddings for documents and queries.", "required": true, "acceptable_evidence": ["Technical keywords: Sentence Transformers (Hugging Face), bi-encoder models (bge-large-en, all-MiniLM-L6-v2), mean pooling, dense vector generation.", "Converts parsed text chunks into high-dimensional dense vector embeddings (e.g. 768 or 1024 dimensions) capturing semantic meaning.", "Encodes live user queries at runtime into the identical embedding space for similarity matching."]}, {"id": "KP2", "description": "Milvus role: distributed high-speed vector indexing, similarity search, and metadata management.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed, HNSW indexing, cosine similarity / inner product, scalar metadata filtering, collection schema.", "Indexes millions of chunk vectors using HNSW graphs for sub-15ms approximate nearest neighbor (ANN) retrieval.", "Stores document metadata (file name, section, department) and enforces access control via scalar filter expressions."]}, {"id": "KP3", "description": "LangChain role: pipeline orchestration, document loaders, prompt templating, and model chaining.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain LCEL, Document loaders, RecursiveCharacterTextSplitter, Milvus vectorstore integration, prompt templates.", "Acts as the glue connecting ingestion, vector retrieval, and foundation model generation into a cohesive pipeline.", "Formats retrieved passages into parameterized prompt templates and handles streaming communication with the LLM."]}], "critical_failures": ["Conflating the roles of the three tools (e.g. claiming LangChain computes embeddings or Milvus handles prompt templating).", "Failing to explain how vector representations flow from Sentence Transformers to Milvus and then into LangChain prompts.", "Omitting the interaction between query encoding, vector search, and final LLM synthesis."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What steps did you take to productionize and deploy your RAG system on AWS, and how did you ensure scalability and reliability?', '{"subcategory": "Productionizing & Deploying Enterprise RAG on AWS: Scalability & Reliability", "key_points": [{"id": "KP1", "description": "Compute and container orchestration architecture on Amazon EKS: deploying scalable microservices.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Kubernetes cluster, Horizontal Pod Autoscaler (HPA), Application Load Balancer (ALB), multi-AZ deployment.", "Packages ingestion, retrieval, and API gateway services into Docker containers deployed across multi-Availability Zone EKS worker nodes.", "Configures HPA to scale service pods automatically based on CPU utilization and incoming HTTP request volume."]}, {"id": "KP2", "description": "Storage, vector database, and foundation model infrastructure: integrating S3, Milvus, and Bedrock.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3 (raw documents/data lake), Milvus cluster on EKS / OpenSearch, AWS Bedrock (Claude 3.5 Sonnet), VPC PrivateLink.", "Stores original PDF manuals and parsed parquet artifacts in encrypted S3 buckets with automated lifecycle rules.", "Leverages AWS Bedrock for managed foundation model inference, routing traffic through VPC endpoints without traversing the public internet."]}, {"id": "KP3", "description": "Production security, telemetry, and automated CI/CD: ensuring enterprise compliance and uptime.", "required": true, "acceptable_evidence": ["Technical keywords: AWS IAM roles, KMS encryption, CloudWatch alarms, Prometheus/Grafana, GitHub Actions CI/CD, blue-green deployment.", "Enforces least-privilege IAM roles for service accounts (IRSA), preventing hardcoded credentials in application containers.", "Monitors P95 latency and error rates via CloudWatch and Prometheus, rolling out updates with zero downtime via automated CI/CD."]}], "critical_failures": ["Proposing single-instance EC2 deployments without container orchestration, high availability, or load balancing.", "Failing to address security and private network isolation (IAM roles, VPC PrivateLink).", "Omitting cloud monitoring, autoscaling, and automated deployment pipelines."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What steps would you take to transition a prototype RAG system into a scalable production system?', '{"subcategory": "Strategic Roadmap: Transitioning a Prototype RAG System into Scalable Production", "key_points": [{"id": "KP1", "description": "Refactoring data pipelines and storage: moving from local embedded databases to distributed cloud-native stores.", "required": true, "acceptable_evidence": ["Technical keywords: architectural refactoring, replacing ChromaDB with Milvus/Pinecone, Docling layout-aware parsing, Amazon S3 storage, batch ingestion.", "Replaces in-memory or embedded vector stores with a distributed vector database supporting sharding, replication, and backup.", "Upgrades basic text splitting to layout-aware document parsing to properly preserve tables, headers, and metadata."]}, {"id": "KP2", "description": "Implementing advanced retrieval and evaluation gates: adding hybrid search, rerankers, and automated benchmarks.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval (BM25 + dense), cross-encoder reranking, golden evaluation dataset, RAGAS metrics (Faithfulness, Relevance).", "Enhances basic vector search with hybrid BM25 retrieval and a cross-encoder reranking stage to eliminate irrelevant context.", "Establishes automated regression testing using golden Q&A datasets to verify accuracy before each release."]}, {"id": "KP3", "description": "Hardening production infrastructure, security, and observability: scaling microservices and monitoring health.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservices, Docker containerization, Kubernetes (EKS), PII masking (Presidio), token streaming (SSE), OpenTelemetry.", "Containerizes services and deploys to Kubernetes with autoscaling policies and health check probes.", "Integrates PII sanitization guardrails, response streaming, and telemetry dashboards tracking latency and token expenditure."]}], "critical_failures": ["Attempting to scale an in-memory prototype by simply putting it on a larger virtual machine without distributed storage.", "Failing to replace naive text chunking or introduce hybrid search and reranking.", "Omitting security guardrails, evaluation benchmarks, and container autoscaling."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What strategies did you use to ensure data privacy and enforce access controls during retrieval and generation?', '{"subcategory": "Data Privacy & Access Control Enforcement During Retrieval & Generation", "key_points": [{"id": "KP1", "description": "Metadata pre-filtering in vector databases for Role-Based Access Control (RBAC): enforcing security before retrieval.", "required": true, "acceptable_evidence": ["Technical keywords: metadata pre-filtering, vector database filter (Milvus/Pinecone), user authorization token, department_id, security clearance.", "Extracts user roles and access permissions from verified identity tokens (JWT) at the API gateway.", "Injects permission filters directly into vector search queries (`filter=''clearance_level <= user_clearance and tenant_id == current_tenant''`), preventing unauthorized chunks from ever being retrieved."]}, {"id": "KP2", "description": "Automated Personally Identifiable Information (PII) masking and token sanitization: protecting privacy at input and output.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, PII detection and anonymization, regex entities (SSN, credit card, email, phone), zero data retention.", "Scans incoming user prompts with Presidio, masking sensitive PII entities before transmitting prompts to foundation model providers.", "Scans generated responses before returning to users to ensure internal sensitive records are redacted."]}, {"id": "KP3", "description": "Multi-tenant data isolation and immutable audit logging: preventing cross-tenant leakage and enabling compliance.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenant isolation, collection/partition keys, KMS encryption at rest, TLS in transit, audit logging.", "Isolates tenant data using dedicated partitions or collections to cryptographically and logically separate customer data.", "Maintains immutable audit logs recording every query, requesting user identity, and accessed document IDs for regulatory compliance."]}], "critical_failures": ["Relying on LLM system prompt instructions to ''please do not read confidential text'', which leads to prompt injection and data leaks.", "Failing to use metadata pre-filtering to enforce access control in the vector database.", "Omitting PII masking or multi-tenant partition isolation."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What strategies have you applied to productionize RAG systems and integrate them into scalable workflows?', '{"subcategory": "Productionizing RAG Systems & Integrating into Scalable Enterprise Workflows", "key_points": [{"id": "KP1", "description": "Decoupled asynchronous workflow integration: integrating RAG into enterprise business systems via queues and event buses.", "required": true, "acceptable_evidence": ["Technical keywords: event-driven architecture, message queues (AWS SQS, Kafka), asynchronous workers, webhook integration, CRM/ERP integration.", "Decouples document ingestion and heavy processing from user-facing services using distributed message queues.", "Connects retrieval outputs directly to operational workflows (e.g. populating CRM tickets, triggering email drafts, updating billing systems)."]}, {"id": "KP2", "description": "Horizontal scaling, caching, and rate management: maintaining throughput and controlling API costs.", "required": true, "acceptable_evidence": ["Technical keywords: Horizontal Pod Autoscaler (HPA), semantic caching (Redis / GPTCache), rate limiting (token bucket), connection pooling.", "Implements semantic caching to serve answers to repeated customer inquiries instantly without invoking expensive LLMs.", "Scales API containers horizontally based on queue lag and protects external LLM endpoints with token bucket rate limiters."]}, {"id": "KP3", "description": "Continuous telemetry, evaluation gates, and feedback loops: ensuring ongoing production fidelity.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Prometheus/Grafana, RAGAS regression benchmarks, user feedback telemetry (thumbs up/down), continuous fine-tuning.", "Tracks operational metrics (P95 latency, cost-per-query, error rates) and semantic metrics (Faithfulness, Context Precision) in real-time.", "Captures user feedback to flag low-quality retrievals and update knowledge base documentation automatically."]}], "critical_failures": ["Building synchronous point-to-point connections that lock up when downstream enterprise systems experience latency.", "Failing to implement caching or rate limiting to manage external LLM API costs.", "Omitting real-time observability and continuous automated evaluation."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What was the role of a knowledge graph in your RAG architecture, and how did it enhance contextual retrieval?', '{"subcategory": "Role of Knowledge Graphs in RAG Architecture: Enhancing Contextual Retrieval", "key_points": [{"id": "KP1", "description": "Overcoming vector similarity limitations: capturing multi-hop relationships and explicit entity connectivity.", "required": true, "acceptable_evidence": ["Technical keywords: Knowledge Graph, GraphRAG, multi-hop reasoning, entity-relationship extraction, structured relationships, vector limitations.", "Standard vector embeddings struggle with complex queries requiring multi-hop reasoning across indirectly related documents.", "Knowledge graphs explicitly model entities (e.g. Vehicle Model $\\rightarrow$ Battery System $\\rightarrow$ Inverter Module $\\rightarrow$ Diagnostic Code) and their typed relationships."]}, {"id": "KP2", "description": "Graph extraction and storage architecture: building and querying knowledge graphs with Neo4j or Amazon Neptune.", "required": true, "acceptable_evidence": ["Technical keywords: Neo4j / Amazon Neptune, Cypher query language, LLM-based entity extraction, triplet extraction (subject-predicate-object), graph database.", "Extracts entity triplets during document ingestion using structured LLM extraction and populates a graph database (Neo4j).", "Executes Cypher graph traversals to retrieve connected subgraphs relevant to identified query entities."]}, {"id": "KP3", "description": "Hybrid Graph-Vector retrieval fusion: synthesizing graph context with unstructured vector chunks.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid GraphRAG, subgraph extraction, context enrichment, vector search + graph traversal, hallucination reduction.", "Combines unstructured vector chunks from Milvus with structured relational context from Neo4j in the prompt.", "Enables the generator to understand high-level structural dependencies alongside detailed technical textual explanations."]}], "critical_failures": ["Treating knowledge graphs as simple flat metadata tags rather than connected entity-relationship networks.", "Failing to explain how multi-hop reasoning is achieved through graph traversal.", "Omitting how graph context and vector search chunks are fused into the final generation prompt."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What were the key scalability improvements made when moving from the initial POC (Streamlit + ChromaDB) to a production-grade system?', '{"subcategory": "Scalability Overhaul: Moving from Streamlit + ChromaDB POC to Production System", "key_points": [{"id": "KP1", "description": "Frontend and presentation decoupling: replacing Streamlit with React and asynchronous streaming.", "required": true, "acceptable_evidence": ["Technical keywords: Streamlit limitations (script reruns, websocket bottleneck), React.js SPA, Server-Sent Events (SSE), asynchronous streaming UI.", "Streamlit reruns the entire Python script on every user interaction, making it unsuitable for multi-user concurrent sessions.", "Replaced with a lightweight React single-page app consuming backend Server-Sent Events (SSE) for smooth token streaming and citation rendering."]}, {"id": "KP2", "description": "Vector storage and indexing upgrade: transitioning from local ChromaDB to distributed Milvus cluster.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB single-node limitations, distributed Milvus, HNSW indexing, sharded collections, MinIO/S3 object storage, multi-tenancy.", "Replaced embedded ChromaDB (which suffered from memory limits and lack of distributed replication) with a distributed Milvus cluster.", "Enabled horizontal sharding across millions of chunks with sub-15ms ANN query latencies and partition-level access control."]}, {"id": "KP3", "description": "API serving and infrastructure scalability: containerized FastAPI microservices on Amazon EKS with auto-scaling.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservices, Docker containerization, Amazon EKS, Horizontal Pod Autoscaler (HPA), ALB load balancing.", "Migrated backend logic into decoupled FastAPI microservices running in Docker containers on Amazon EKS.", "Configured load balancers and horizontal autoscalers to automatically adjust compute capacity based on incoming QPS."]}], "critical_failures": ["Attempting to deploy Streamlit directly to high-traffic production environments without addressing its script rerun execution model.", "Failing to explain why embedded local ChromaDB cannot scale to multi-user distributed workloads.", "Omitting container orchestration, autoscaling, or response streaming in the production architecture."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'Which embedding model did you use, and how does the Sentence Transformer architecture work?', '{"subcategory": "Embedding Model Selection & Sentence Transformer Architecture Mechanics", "key_points": [{"id": "KP1", "description": "Embedding model selection criteria and choice: utilizing high-performance bi-encoders (e.g. BGE-large / MiniLM).", "required": true, "acceptable_evidence": ["Technical keywords: BAAI/bge-large-en, all-MiniLM-L6-v2, MTEB benchmark, cosine similarity, vector dimensionality (1024 / 384), domain alignment.", "Selected BGE-large-en based on top rankings on the Massive Text Embedding Benchmark (MTEB) for retrieval tasks.", "Balances embedding representation quality against vector storage size and latency budgets."]}, {"id": "KP2", "description": "Sentence Transformer (SBERT) architecture mechanics: Siamese neural networks and mean pooling.", "required": true, "acceptable_evidence": ["Technical keywords: Siamese network architecture, shared weights, mean pooling (average token embeddings), fixed-size vector representation, bi-encoder.", "Uses a Siamese / dual-encoder transformer architecture that maps variable-length text into fixed-size dense vector embeddings.", "Applies mean pooling over contextualized token vectors (accounting for attention masks) to derive an expressive sentence representation."]}, {"id": "KP3", "description": "Contrastive training loss and similarity optimization: cosine distance and semantic space alignment.", "required": true, "acceptable_evidence": ["Technical keywords: contrastive loss (MultipleNegativesRankingLoss), in-batch negatives, cosine similarity optimization, semantic vector space.", "Trained using contrastive loss functions that pull semantically related question-passage pairs close together while pushing negative passages apart.", "Enables ultra-fast approximate nearest neighbor (ANN) search using cosine similarity or inner product dot products."]}], "critical_failures": ["Confusing Sentence Transformer bi-encoders with cross-encoder rerankers.", "Failing to explain the role of pooling (mean pooling) in generating fixed-size sentence vectors from transformer outputs.", "Omitting contrastive learning objectives or MTEB benchmark criteria in model selection."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Which models and tools did you use in your RAG pipeline, and how were they integrated into the system architecture?', '{"subcategory": "RAG Pipeline Toolchain Integration: Models, Databases & System Architecture", "key_points": [{"id": "KP1", "description": "Document ingestion and embedding tools: Docling layout parsing and Sentence Transformers.", "required": true, "acceptable_evidence": ["Technical keywords: Docling / Unstructured, layout-aware parsing, TableFormer, Sentence Transformers (bge-large-en), 512-token chunking.", "Parses unstructured enterprise PDFs into structured Markdown with Docling, preserving complex tables and section hierarchies.", "Generates 1024-dimensional dense vectors using Sentence Transformers for ingestion into the storage layer."]}, {"id": "KP2", "description": "Hybrid storage, search, and reranking tools: Milvus, BM25, and BGE Cross-Encoder.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed, HNSW index, BM25 sparse search, Reciprocal Rank Fusion (RRF), bge-reranker-large.", "Indexes vectors into Milvus and text tokens into BM25, executing hybrid queries to combine semantic and exact keyword signals.", "Re-ranks fused top-50 candidate passages using a cross-encoder to extract the top-5 highest-confidence contexts."]}, {"id": "KP3", "description": "Orchestration, generation, and serving tools: LangGraph, AWS Bedrock (Claude 3.5 Sonnet), and FastAPI.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, AWS Bedrock (Claude 3.5 Sonnet), FastAPI backend, Presidio PII masking, Server-Sent Events (SSE).", "Orchestrates multi-turn dialogue, tool calls, and prompt assembly using LangGraph state graphs.", "Invokes Claude 3.5 Sonnet on AWS Bedrock under strict citation constraints and streams responses to users via FastAPI."]}], "critical_failures": ["Listing tools without explaining how they connect and pass data across each stage of the pipeline.", "Omitting document parsing or cross-encoder reranking from the architecture.", "Failing to specify how the foundation model is orchestrated and served in production."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Why did you transition from a RAG-based system to a multi-agent architecture, and what improvements did it bring?', '{"subcategory": "Transition Rationale: RAG to Multi-Agent Architecture & Operational Improvements", "key_points": [{"id": "KP1", "description": "Key drivers for transitioning: overcoming the limitations of single-prompt linear RAG.", "required": true, "acceptable_evidence": ["Technical keywords: linear RAG limitations, single-prompt bloat, tool confusion, lack of multi-step planning, passive lookup vs active workflow.", "A single RAG prompt struggled when queries required multiple distinct capabilities (e.g. diagnosing a technical error AND booking an appointment).", "Linear RAG could not self-correct when initial retrieved context was incomplete or irrelevant."]}, {"id": "KP2", "description": "Multi-agent architecture design: role specialization and supervisory orchestration via LangGraph.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, supervisor router, specialized worker agents (triage, diagnostic, scheduling), scoped system prompts.", "Decomposed the monolithic system into specialized worker agents, each scoped with domain tools and dedicated system instructions.", "Configured a supervisor agent to decompose user intent, dispatch sub-tasks, and synthesize findings into a unified answer."]}, {"id": "KP3", "description": "Concrete improvements delivered: end-to-end task automation, error recovery, and deflection.", "required": true, "acceptable_evidence": ["Technical keywords: end-to-end task automation, self-correction loops, inquiry deflection rate increase, AHT reduction, customer satisfaction.", "Enabled autonomous execution of write actions via enterprise APIs (e.g. creating tickets, updating customer records) with Human-in-the-Loop gates.", "Increased customer self-service deflection from 15% to 42% while reducing average handling time by 35%."]}], "critical_failures": ["Describing the change as simply writing longer prompts with more instructions.", "Failing to explain how multi-agent coordination, routing, and shared state were architected in code.", "Omitting tool isolation, state checkpointing, or Human-in-the-Loop safety additions."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Why did you transition from a RAG-based system to an agentic system, and what additional capabilities did agents provide over traditional RAG?', '{"subcategory": "Agentic Capabilities vs. Traditional RAG: Dynamic Problem-Solving & Tool Agency", "key_points": [{"id": "KP1", "description": "Autonomous planning and goal decomposition: formulating multi-step execution plans vs single-shot generation.", "required": true, "acceptable_evidence": ["Technical keywords: autonomous planning, plan-and-solve, goal decomposition, iterative reasoning, sub-goal generation.", "Traditional RAG executes a single pass: query $\\rightarrow$ retrieve $\\rightarrow$ generate.", "Agents evaluate a complex goal, decompose it into sequential sub-tasks, and adjust subsequent steps based on intermediate tool findings."]}, {"id": "KP2", "description": "Active tool execution and system side-effects: calling APIs and executing database mutations.", "required": true, "acceptable_evidence": ["Technical keywords: tool agency, API mutation, database writes, external integration, transactional operations.", "Traditional RAG is strictly read-only, producing static text advice.", "Agents possess execution capability: querying live systems, checking inventory, making reservations, and updating customer records."]}, {"id": "KP3", "description": "Iterative reflection, error recovery, and self-correction: autonomously recovering from failures.", "required": true, "acceptable_evidence": ["Technical keywords: self-correction loop, reflection pattern, error recovery, cyclic graph execution, validation feedback.", "If a tool call returns an error or incomplete information, an agent inspects the error message, refines its arguments, and retries.", "Provides superior robustness compared to static RAG which outputs plausible hallucinations when context is missing."]}], "critical_failures": ["Treating Agentic AI simply as RAG with a different prompt style.", "Failing to explain the ability of agents to execute real-world API actions and modify system state.", "Omitting planning, iterative self-correction, and error recovery capabilities."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'Can you explain how you transitioned from a basic RAG system to a multi-model agent architecture, and what improvements it introduced?', '{"subcategory": "Transitioning from Basic RAG to Multi-Model Agent Architecture: Benefits & Design", "key_points": [{"id": "KP1", "description": "Multi-model specialization: routing distinct sub-tasks to cost-optimized and specialized LLMs.", "required": true, "acceptable_evidence": ["Technical keywords: multi-model routing, model specialization, cost-performance tiering, lightweight vs frontier models (Claude 3.5 Sonnet vs Haiku / Llama-3-8B).", "Uses lightweight, fast models (e.g. Haiku, Llama-3-8B) for fast intent classification, query rewriting, and entity extraction.", "Reserves heavy frontier models (Claude 3.5 Sonnet, GPT-4o) exclusively for complex multi-agent synthesis and nuanced diagnostic reasoning."]}, {"id": "KP2", "description": "Agentic orchestration and dynamic model dispatch: managing heterogeneous model execution in LangGraph.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, dynamic model binding, node-specific LLM instances, structured output schemas.", "Binds different LLM clients to specific graph nodes based on task requirements (e.g. coding model for SQL generation, conversational model for triage).", "Enforces structured outputs (Pydantic) to ensure seamless data handoffs between different models in the graph."]}, {"id": "KP3", "description": "Operational benefits delivered: dramatic cost reduction, lower latency, and improved task accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: token cost optimization (60%+ savings), end-to-end latency reduction, error reduction, operational efficiency.", "Cuts overall system token spend by over 60% by avoiding frontier model invocations for simple routing and extraction tasks.", "Reduces average latency while improving accuracy through domain-specialized model selection."]}], "critical_failures": ["Using a single monolithic model for all tasks and calling it a ''multi-model architecture''.", "Failing to explain how tasks are routed to different models based on complexity and cost.", "Omitting the cost and latency benefits of multi-model tiered architectures."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'Describe the vector retrieval strategy used, including hierarchical navigable small world (HNSW) indexing, re-ranking strategies, and cross-encoder techniques, and explain how you manage metadata for document versioning.', '{"subcategory": "Vector Retrieval Strategy: HNSW Indexing, Cross-Encoder Reranking & Metadata Versioning", "key_points": [{"id": "KP1", "description": "Hierarchical Navigable Small World (HNSW) graph indexing: tuning parameters for speed and recall.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW indexing, M (bi-directional links), efConstruction (build exploration), efSearch (query exploration), approximate nearest neighbor (ANN).", "Configures HNSW graph parameters (e.g. M=16, efConstruction=200, efSearch=64) to achieve >95% recall@50 with sub-15ms search latencies.", "Balances index build memory overhead against real-time vector search query throughput."]}, {"id": "KP2", "description": "Cross-Encoder reranking strategy: scoring query-chunk pairs with full cross-attention.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranker (bge-reranker-large), cross-attention, candidate pruning (top-50 to top-5), score calibration.", "Passes the top-50 vector search candidates into a cross-encoder that evaluates full cross-attention between query and chunk tokens.", "Prunes low-scoring distractor chunks, returning only the top-5 highest-relevance passages to the generator."]}, {"id": "KP3", "description": "Document versioning and metadata management: handling updates, deprecations, and schema evolution.", "required": true, "acceptable_evidence": ["Technical keywords: document versioning, doc_version tag, is_active flag, metadata filtering, soft deletion, zero-downtime reindexing.", "Attaches explicit version metadata (`doc_version`, `effective_date`, `is_active`) to every stored chunk in the vector database.", "Uses metadata pre-filtering during queries to exclude deprecated guidelines without requiring full collection rebuilds."]}], "critical_failures": ["Failing to explain how HNSW parameters (M, efConstruction, efSearch) impact search performance.", "Confusing cross-encoders with bi-encoders or failing to explain their role in precision reranking.", "Omitting metadata versioning strategies to handle document updates and deprecation."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did techniques like structure-aware chunking, semantic chunking, overlapping chunks, and cross-encoder re-ranking improve your system performance?', '{"subcategory": "Chunking Strategies & Reranking: Structure-Aware, Semantic & Cross-Encoder Optimizations", "key_points": [{"id": "KP1", "description": "Structure-aware and semantic chunking: preserving document layout, headings, and semantic coherence.", "required": true, "acceptable_evidence": ["Technical keywords: structure-aware chunking, semantic chunking, layout-aware parsing (Docling), heading hierarchy, table integrity.", "Splits documents along natural semantic boundaries (Markdown headers, section breaks, paragraphs) rather than arbitrary character counts.", "Preserves table rows and column headers in unified markdown blocks to prevent breaking diagnostic data across chunk seams."]}, {"id": "KP2", "description": "Chunk sizing and overlapping strategies: balancing semantic density with contextual continuity.", "required": true, "acceptable_evidence": ["Technical keywords: chunk size (512 tokens), chunk overlap (10-20% / 50-100 tokens), sliding window, boundary context preservation.", "Selects 512-token chunk boundaries to capture complete operational thoughts without exceeding embedding model attention budgets.", "Maintains 15% overlap between adjacent chunks to ensure sentences spanning chunk boundaries are not semantically truncated."]}, {"id": "KP3", "description": "Cross-encoder reranking synergy: refining retrieval candidates and suppressing hallucination.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder reranker, Precision@5 boost, distractor suppression, hallucination reduction, context density.", "Applies a cross-encoder to re-score overlapping candidate chunks, filtering out redundant fragments and ranking the most informative chunk first.", "Boosts precision@5 from 62% to over 88%, directly reducing LLM generation errors caused by noisy retrieved context."]}], "critical_failures": ["Advocating for fixed-character naive chunking that cuts tables and sentences in half.", "Failing to explain the role of chunk overlap in preserving cross-boundary semantic context.", "Omitting how cross-encoder reranking complements chunking to eliminate noise."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and implement the RAG pipeline for your chatbot, and what were the key architectural components involved?', '{"subcategory": "Chatbot RAG Pipeline Design & Core Architectural Components", "key_points": [{"id": "KP1", "description": "Document ingestion and preprocessing components: layout extraction, chunking, and embedding generation.", "required": true, "acceptable_evidence": ["Technical keywords: Docling / Unstructured, layout-aware parsing, structure-aware chunking, Sentence Transformers (BGE-large), metadata tagging.", "Extracts text, tables, and section hierarchies from enterprise PDF manuals and operational guides.", "Chunks content into 512-token segments with metadata tags (product_line, section, document_id) and embeds them into vector representations."]}, {"id": "KP2", "description": "Retrieval, ranking, and memory components: hybrid search, cross-encoders, and multi-turn state.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus vector store, BM25 keyword search, Reciprocal Rank Fusion, Cross-Encoder reranker, conversational memory buffer.", "Executes hybrid retrieval combining dense vector similarity with sparse BM25 keyword matching.", "Reranks candidate chunks with a cross-encoder and incorporates active multi-turn conversation history into query understanding."]}, {"id": "KP3", "description": "Generation, safety guardrails, and API serving components: constrained synthesis and streaming.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI backend, AWS Bedrock (Claude 3.5 Sonnet), Presidio PII masking, strict citation grounding, Server-Sent Events (SSE).", "Injects retrieved context into prompts with strict negative fallbacks: ''Answer strictly using provided context; cite sources.''", "Streams generated responses to the frontend via FastAPI SSE while redacting sensitive PII with Microsoft Presidio."]}], "critical_failures": ["Describing a naive single-component script without separating ingestion, retrieval, ranking, and generation layers.", "Failing to address table extraction and document structure in the preprocessing stage.", "Omitting conversational memory, citations, or security guardrails in the chatbot design."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you design the framework that allowed multiple teams to create their own RAG-based AI assistants with custom knowledge bases?', '{"subcategory": "Multi-Tenant Enterprise RAG Framework Design: Self-Service Assistant Creation", "key_points": [{"id": "KP1", "description": "Multi-tenant data isolation and partitioned knowledge bases: segregating team documents securely.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenant architecture, tenant_id partition key, collection-level isolation, metadata pre-filtering, RBAC access control.", "Partitions vector and document storage using strict `tenant_id` and `team_id` partition keys in Milvus / S3.", "Enforces tenant pre-filtering on all vector searches to guarantee that teams can only query their authorized knowledge bases."]}, {"id": "KP2", "description": "Self-service ingestion and configuration APIs: enabling teams to define custom parsing, chunking, and assistant personas.", "required": true, "acceptable_evidence": ["Technical keywords: self-service REST APIs, custom assistant configuration, configurable system prompts, ingestion pipelines, webhook triggers.", "Exposes administrative APIs allowing teams to upload proprietary documents and configure custom assistant instructions and tool permissions.", "Automates background parsing, chunking, and vector indexing upon document upload without manual engineering intervention."]}, {"id": "KP3", "description": "Centralized platform governance, resource quotas, and cost attribution: managing enterprise shared infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting, token quotas per tenant, cost attribution / chargeback, centralized telemetry, OpenTelemetry.", "Tracks token consumption and vector storage per team to enable accurate departmental chargebacks and prevent noisy-neighbor quota exhaustion.", "Provides centralized observability dashboards monitoring query latency, error rates, and evaluation benchmarks across all deployed assistants."]}], "critical_failures": ["Allowing multiple teams to share a single unpartitioned vector space without tenant metadata pre-filtering (severe data leakage).", "Requiring manual code deployment by the central platform team whenever a team wants to add documents or create an assistant.", "Omitting rate limiting, tenant cost attribution, or centralized platform governance."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'HARD', 'BROAD', 120, 'How did you design the overall system architecture, including frontend, backend, vector database, and LLM layers?', '{"subcategory": "Overall System Architecture Design: Frontend, Backend, Vector DB & LLM Layers", "key_points": [{"id": "KP1", "description": "Presentation tier (Frontend): building interactive user interfaces with progressive token streaming and citations.", "required": true, "acceptable_evidence": ["Technical keywords: React / Next.js frontend, Server-Sent Events (SSE) streaming, interactive citation chips, chat state management, user feedback UI.", "Consumes backend SSE streams to render progressive token output, minimizing perceived user latency.", "Displays clickable citation pills linked to source document previews and captures user thumbs up/down feedback."]}, {"id": "KP2", "description": "Application & orchestration tier (Backend): managing session state, guardrails, and retrieval pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservices, LangGraph StateGraph, Pydantic validation, Presidio PII masking, connection pooling.", "Validates incoming payloads, applies PII sanitization, and orchestrates query analysis and retrieval workflows.", "Maintains multi-turn conversation sessions using Redis-backed state checkpointers."]}, {"id": "KP3", "description": "Data and model tiers (Vector DB & LLM): distributed storage, hybrid retrieval, and managed foundation models.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed vector DB, HNSW index, BM25 keyword search, cross-encoder reranker, AWS Bedrock (Claude 3.5 Sonnet).", "Indexes document chunks in Milvus with HNSW graphs for fast ANN similarity search alongside BM25 sparse indexes.", "Reranks candidates and passes grounded context to Claude 3.5 Sonnet on AWS Bedrock under strict system prompt constraints."]}], "critical_failures": ["Describing components as disconnected pieces without explaining the complete end-to-end data and control flow.", "Failing to detail how the backend orchestrates retrieval between the Vector DB and the LLM layer.", "Omitting frontend streaming, security guardrails, or state persistence across the architecture."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you ensure accurate retrieval and minimize hallucinations in your RAG system, including the use of metadata filtering and context control?', '{"subcategory": "Minimizing Hallucinations in RAG: Metadata Filtering, Reranking & Context Constraints", "key_points": [{"id": "KP1", "description": "Metadata pre-filtering and temporal scoping: ensuring retrieval precision and document freshness.", "required": true, "acceptable_evidence": ["Technical keywords: metadata pre-filtering, document versioning, active status filter, temporal scoping, domain partitioning.", "Restricts vector queries to active, authorized document versions using database pre-filtering (`is_active == true and version == ''2.4''`).", "Eliminates hallucinations caused by retrieving deprecated, outdated, or superseded technical guidelines."]}, {"id": "KP2", "description": "Cross-encoder reranking and noise suppression: maximizing context density and eliminating distractor chunks.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranker (bge-reranker-large), candidate pruning, score thresholding, distractor filtering.", "Scores first-stage retrieval candidates with a cross-encoder and discards passages below strict relevance score thresholds.", "Prevents feeding semantically tangential but factually irrelevant text into the prompt context window."]}, {"id": "KP3", "description": "System prompt negative constraints, citation grounding, and evaluation: enforcing strict factual adherence.", "required": true, "acceptable_evidence": ["Technical keywords: negative constraints (''I don''t know'' fallback), citation grounding, source attribution, RAGAS Faithfulness evaluation.", "Instructs the LLM: ''Answer strictly using the provided context. If the answer cannot be found in the context, explicitly state that you do not have enough information.''", "Requires the model to provide source chunk citations for every factual claim, validated continuously with RAGAS Faithfulness metrics."]}], "critical_failures": ["Relying on temperature tuning alone to solve hallucinations without addressing retrieval noise or prompt constraints.", "Failing to filter out outdated or deprecated document versions via metadata pre-filtering.", "Omitting negative prompt constraints (''I don''t know'' fallback) or cross-encoder distractor filtering."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'How did you ensure scalability and performance improvements when transitioning from PGVector to Milvus?', '{"subcategory": "Scaling Vector Search: Migrating from PGVector to Milvus & Performance Gains", "key_points": [{"id": "KP1", "description": "Motivations for migrating from PGVector: resource contention, memory saturation, and horizontal scaling limits.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector bottlenecks, shared relational resources, memory saturation (shared_buffers), vacuum overhead, lack of horizontal sharding.", "As vector collections grew beyond 5 million vectors, HNSW index maintenance consumed PostgreSQL CPU and RAM, degrading relational queries.", "PostgreSQL''s single-node monolithic architecture could not scale compute and storage independently for heavy vector workloads."]}, {"id": "KP2", "description": "Milvus distributed architecture advantages: disaggregated compute and storage, dedicated indexing nodes, and sharding.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed, disaggregated architecture, QueryNodes, IndexNodes, DataNodes, MinIO/S3 object storage, horizontal sharding.", "Milvus decouples query serving (QueryNodes) from background index creation (IndexNodes) and persistent object storage (MinIO/S3).", "Allows scaling query nodes horizontally to handle high QPS without impacting write ingestion or relational database performance."]}, {"id": "KP3", "description": "Measured performance improvements and migration execution: zero-downtime dual-write and latency gains.", "required": true, "acceptable_evidence": ["Technical keywords: latency reduction (sub-15ms P99), QPS throughput scaling (10x gain), dual-write migration strategy, partition keys.", "Executed a zero-downtime migration by dual-writing new embeddings to both databases, backfilling historical vectors, and cutover switching.", "Reduced P99 vector search latency from 180ms to 12ms while increasing concurrent query throughput by over 10x."]}], "critical_failures": ["Failing to identify the resource contention issues that occur when running heavy vector indexes inside a transactional relational database.", "Lacking understanding of Milvus''s disaggregated compute-storage architecture.", "Omitting concrete performance metrics or the zero-downtime migration strategy."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'EASY', 'SPECIFIC', 60, 'How did you generate embeddings and why did you choose sentence transformer models?', '{"subcategory": "Embedding Generation Strategy: Sentence Transformer Models & Selection Rationale", "key_points": [{"id": "KP1", "description": "Embedding model selection criteria: domain evaluation, MTEB benchmark performance, and dimensionality.", "required": true, "acceptable_evidence": ["Technical keywords: Sentence Transformers (bge-large-en, all-MiniLM-L6-v2), MTEB retrieval benchmark, embedding dimension (768 / 1024), cosine similarity.", "Selected Sentence Transformer bi-encoders based on top retrieval rankings on MTEB and domain evaluation on enterprise technical manuals.", "Balances dense semantic representation quality against vector index memory footprint and search latency."]}, {"id": "KP2", "description": "Sentence Transformer (SBERT) architecture mechanics: Siamese networks, bi-encoder processing, and mean pooling.", "required": true, "acceptable_evidence": ["Technical keywords: Siamese network, bi-encoder, mean pooling, attention mask, contextual token embeddings, fixed-size vector representation.", "Processes text through shared-weight transformer backbones, applying mean pooling over non-masked token vectors to yield a fixed-size embedding.", "Allows independently precomputing document embeddings offline and encoding live queries in milliseconds for real-time similarity search."]}, {"id": "KP3", "description": "Operational advantages over closed third-party embedding APIs: latency, cost predictability, privacy, and self-hosting.", "required": true, "acceptable_evidence": ["Technical keywords: self-hosted embeddings, latency predictability, zero API token costs, data privacy / zero egress, GPU batch inference (Triton/vLLM).", "Self-hosting Sentence Transformers on internal GPUs eliminates third-party API latency spikes, network egress costs, and rate limit throttling.", "Ensures proprietary enterprise documents never leave secure VPC boundaries during embedding generation."]}], "critical_failures": ["Confusing Sentence Transformer bi-encoders with cross-encoders.", "Failing to explain how Siamese networks and mean pooling produce fixed-size sentence vectors.", "Omitting the operational and privacy advantages of self-hosted open-source embeddings over commercial third-party APIs."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement access control and ensure users only retrieve documents they are authorized to see?', '{"subcategory": "Enforcing Access Control & Data Isolation in Vector Retrieval", "key_points": [{"id": "KP1", "description": "Identity verification and claims extraction: extracting authenticated user roles and tenant IDs at the API gateway.", "required": true, "acceptable_evidence": ["Technical keywords: JSON Web Tokens (JWT), OAuth2 / OIDC, claims extraction, user_id, tenant_id, role-based access control (RBAC).", "Validates cryptographically signed JWT tokens on incoming requests, extracting user department, clearance level, and tenant identifiers.", "Attaches verified identity context to the internal query execution context without trusting client-supplied parameters."]}, {"id": "KP2", "description": "Database-level metadata pre-filtering: executing secure vector searches restricted to authorized documents.", "required": true, "acceptable_evidence": ["Technical keywords: metadata pre-filtering, vector database filter (Milvus/Pinecone), scalar expression, ACL lists, partition isolation.", "Injects user permissions directly into vector search query filters: e.g. `filter=''tenant_id == \"T1\" and department in [\"Sales\", \"Public\"]''`. ", "Guarantees that unauthorized documents are never traversed, scored, or included in similarity candidate pools."]}, {"id": "KP3", "description": "Defense-in-depth and compliance audit logging: preventing leakage and verifying data isolation.", "required": true, "acceptable_evidence": ["Technical keywords: defense-in-depth, immutable audit trail, query logging, document access logging, prompt leakage prevention.", "Never relies on LLM system prompt instructions (''do not look at secret files'') as an access control mechanism.", "Records immutable audit logs pairing requesting user IDs with accessed document chunk IDs for compliance auditing."]}], "critical_failures": ["Relying on system prompts to enforce access control (instructing the model not to mention secret data), causing severe prompt injection vulnerability.", "Using post-retrieval filtering that drops unauthorized chunks after ANN search, degrading recall and leaking existence.", "Omitting JWT validation or database metadata pre-filtering."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'How did you integrate knowledge graph relationships with vector-based retrieval using frameworks like LangGraph?', '{"subcategory": "Integrating Knowledge Graph Relationships with Vector Retrieval in LangGraph", "key_points": [{"id": "KP1", "description": "Knowledge graph modeling and entity-relation extraction: extracting structured subgraphs from unstructured manuals.", "required": true, "acceptable_evidence": ["Technical keywords: Knowledge Graph, Neo4j, Cypher query, entity extraction, triplet extraction (head, relation, tail), GraphRAG.", "Extracts typed domain entities (e.g. BatteryModule, Inverter, DTC_Code) and relationships (POWERS, CONNECTS_TO, TRIGGERS) into a graph database.", "Captures explicit multi-hop dependencies that dense semantic vectors cannot reliably model."]}, {"id": "KP2", "description": "Orchestrating hybrid graph-vector retrieval in LangGraph: coordinating parallel retrieval nodes.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, parallel retrieval nodes, vector search node (Milvus), graph traversal node (Neo4j), entity linker.", "Extracts entities from the user query and dispatches parallel graph nodes: one queries Milvus for text chunks, another executes Cypher graph traversals.", "Aggregates relational pathways (e.g. connected diagnostic components) into the shared graph state alongside text passages."]}, {"id": "KP3", "description": "Synthesis and context fusion: combining relational structure with detailed textual chunks in LLM generation.", "required": true, "acceptable_evidence": ["Technical keywords: context fusion, structured relationship injection, multi-hop reasoning, hallucination reduction, response synthesis.", "Formats graph triplets into structured relationship trees placed directly above relevant text chunks in the generation prompt.", "Enables the model to reason accurately across multi-component system failures without hallucinating missing connections."]}], "critical_failures": ["Treating knowledge graphs as flat vector metadata tags rather than an explicit entity-relationship network.", "Failing to explain how LangGraph coordinates retrieval between the graph database and vector store.", "Omitting how graph structure and vector chunks are fused into the generation prompt."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you structure your data pipelines for handling live data ingestion, ETL processes, and storage for experimentation?', '{"subcategory": "Data Pipeline Architecture: Live Ingestion, ETL Processes & Experimentation Storage", "key_points": [{"id": "KP1", "description": "Decoupled streaming and batch ingestion: capturing live operational data via message queues.", "required": true, "acceptable_evidence": ["Technical keywords: event-driven ingestion, Apache Kafka, AWS Kinesis / SQS, change data capture (CDC), streaming vs batch.", "Captures real-time customer support logs, chat transcripts, and telemetry via Kafka/Kinesis streaming queues.", "Buffers high-velocity events to protect downstream transformation workers from sudden traffic spikes."]}, {"id": "KP2", "description": "Scalable ETL processing and validation: cleaning, transforming, and validating records.", "required": true, "acceptable_evidence": ["Technical keywords: distributed ETL (Apache Spark / AWS Glue), Pydantic validation, Great Expectations, deduplication, schema enforcement.", "Executes automated data cleansing, deduplication, and schema validation on incoming raw records.", "Normalizes diverse data structures into standardized schemas, routing malformed payloads to dead-letter queues."]}, {"id": "KP3", "description": "Storage tiering for analytics, retrieval, and experimentation: managing data lakes, vector stores, and warehouses.", "required": true, "acceptable_evidence": ["Technical keywords: data lake (Amazon S3 / Delta Lake), data warehouse (Snowflake / Redshift), vector store (Milvus), experimentation storage.", "Persists raw and processed parquet logs to S3 Delta Lake tables for offline data science experimentation and model evaluation.", "Ingests text features and embeddings into Milvus for real-time semantic retrieval while syncing structured aggregates into Snowflake."]}], "critical_failures": ["Proposing monolithic point-to-point data loads without message queues or distributed ETL tools.", "Failing to include automated data validation and cleaning steps in pipeline design.", "Omitting dedicated storage tiering for machine learning experimentation versus production serving."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How does a cross-encoder re-ranker improve retrieval results compared to initial embedding-based retrieval?', '{"subcategory": "Cross-Encoder Re-Ranking: Mechanics & Accuracy Improvements Over Initial Retrieval", "key_points": [{"id": "KP1", "description": "Bi-encoder retrieval limitations: independent representation encoding without query-document cross-attention.", "required": true, "acceptable_evidence": ["Technical keywords: Bi-encoder limitations, independent vector encoding, dot product / cosine similarity, representation bottleneck, lack of cross-attention.", "Bi-encoders compress an entire document into a single fixed vector before ever seeing the query, losing fine-grained contextual nuances.", "Similarity search computes simple cosine distance, often returning semantically adjacent text that lacks the exact factual answer."]}, {"id": "KP2", "description": "Cross-Encoder architecture mechanics: joint full token cross-attention across concatenated pairs.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder (bge-reranker-large), joint cross-attention, concatenated input [CLS] query [SEP] passage [SEP], all-to-all attention.", "Feeds the query and document together through all transformer layers, enabling every query token to attend directly to every passage token.", "Produces an uncompressed, calibrated relevance score that accurately captures syntactic negation, conditional clauses, and exact keyword matches."]}, {"id": "KP3", "description": "Quantifiable accuracy gains and context window optimization: filtering distractors and boosting precision.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@K boost, NDCG@K, distractor chunk elimination, hallucination reduction, context window density.", "Prunes top-50 initial retrieval candidates down to the top-5 most relevant passages, eliminating noisy distractor chunks.", "Dramatically improves Precision@5 (e.g. from 60% to 88%), directly reducing LLM generation errors and hallucinations."]}], "critical_failures": ["Claiming Cross-Encoders are faster than Bi-Encoders and can be used to index millions of documents offline.", "Failing to explain the core architectural difference (joint cross-attention vs independent vector encoding).", "Omitting the impact of cross-encoders on filtering distractor chunks to reduce hallucinations."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you advise someone building a similar RAG or agentic system to approach evaluation and system design?', '{"subcategory": "Strategic Advice on Approaching Evaluation & System Design for RAG & Agents", "key_points": [{"id": "KP1", "description": "Evaluation-first development methodology: establishing immutable golden test datasets and metrics before building.", "required": true, "acceptable_evidence": ["Technical keywords: evaluation-first mindset, golden test dataset, synthetic data generation, RAGAS metrics (Faithfulness, Recall), baseline benchmarks.", "Advises establishing a human-verified golden Q&A dataset representing real-world distribution before tuning prompts or frameworks.", "Measures baseline retrieval metrics (Hit Rate@K, MRR) and generation metrics (Faithfulness) to quantitatively guide architectural choices."]}, {"id": "KP2", "description": "Pragmatic modular system design: decoupling ingestion, retrieval, and reasoning with standardized interfaces.", "required": true, "acceptable_evidence": ["Technical keywords: modular architecture, separation of concerns, provider abstraction (LiteLLM), standardized protocols (MCP), loose coupling.", "Start with clean modular components (document parser, vector DB, LLM gateway) rather than complex monolithic frameworks.", "Ensures models, embedding providers, and vector databases can be swapped independently as technologies evolve."]}, {"id": "KP3", "description": "Progressive complexity and bounded autonomy: start with solid RAG before expanding into cyclic multi-agent graphs.", "required": true, "acceptable_evidence": ["Technical keywords: progressive complexity, solid RAG baseline, bounded autonomy, Human-in-the-Loop gates, telemetry/observability.", "Do not jump straight to complex multi-agent swarms if a deterministic hybrid RAG pipeline solves the business problem.", "Introduce agentic workflows (LangGraph) only when task execution or dynamic planning is required, enforcing strict recursion limits and HITL safety."]}], "critical_failures": ["Advising teams to immediately build complex autonomous multi-agent networks without an evaluation baseline or solid retrieval foundation.", "Relying on manual ''vibe checks'' instead of automated quantitative evaluation datasets.", "Ignoring modularity, latency constraints, and bounded autonomy in production system design."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a RAG ingestion pipeline for unstructured data such as PDFs, internal documents, and web content?', '{"subcategory": "Designing Robust Ingestion Pipelines for Unstructured Data (PDFs, Docs, Web)", "key_points": [{"id": "KP1", "description": "Multi-modal and layout-aware document extraction: handling tables, columns, and headings via modern parsers.", "required": true, "acceptable_evidence": ["Technical keywords: Docling / Unstructured, layout-aware parsing, TableFormer, OCR (Tesseract), multi-column reading order, HTML/Markdown conversion.", "Employs Docling to parse complex multi-column PDFs, extracting tables into structured Markdown while preserving cell alignment.", "Applies vision-based layout analysis to strip repetitive headers, footers, and page numbers that degrade retrieval."]}, {"id": "KP2", "description": "Hierarchy-aware and semantic chunking: respecting document structure and context continuity.", "required": true, "acceptable_evidence": ["Technical keywords: hierarchy-aware chunking, Markdown header splitting, chunk size (512 tokens), overlap (15%), metadata enrichment.", "Splits documents along natural structural boundaries (H1, H2, H3 headers, table blocks) rather than blind character cutoffs.", "Attaches parent section titles, document source, and department tags to chunk metadata to preserve surrounding context."]}, {"id": "KP3", "description": "Asynchronous batch processing, deduplication, and dual indexing: scaling ingestion into vector and lexical stores.", "required": true, "acceptable_evidence": ["Technical keywords: Celery / AWS SQS task queue, SHA-256 document hashing, idempotent upserts, Milvus dense indexing, BM25 sparse index.", "Computes cryptographic document hashes (SHA-256) to detect duplicate or unchanged documents, avoiding redundant re-embedding costs.", "Dispatches chunks into distributed vector collections (Milvus HNSW) and lexical keyword indexes (BM25) via parallel batch jobs."]}], "critical_failures": ["Using naive fixed-character chunking that slices through tables and sentences without layout awareness.", "Failing to handle document deduplication or idempotent reindexing.", "Omitting metadata preservation (headers, document provenance) during chunk extraction."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'How would you design a centralized knowledge base using for semantic search and retrieval?', '{"subcategory": "Designing a Centralized Enterprise Knowledge Base for Semantic Search", "key_points": [{"id": "KP1", "description": "Unified multi-source ingestion architecture: aggregating disparate enterprise repositories into a centralized data lake.", "required": true, "acceptable_evidence": ["Technical keywords: multi-source ingestion, enterprise connectors (SharePoint, Confluence, S3, Jira), normalized schema, layout parsing.", "Connects to fragmented enterprise knowledge silos via automated sync connectors, ingesting technical manuals, FAQs, and policies.", "Normalizes heterogeneous document formats into structured Markdown with standardized metadata tags (source, author, date, access_level)."]}, {"id": "KP2", "description": "Scalable hybrid indexing and vector storage: combining dense vectors with sparse keyword search in Milvus.", "required": true, "acceptable_evidence": ["Technical keywords: distributed vector database (Milvus), HNSW index, BM25 sparse search, scalar indexing, partition keys.", "Stores high-dimensional dense embeddings in Milvus alongside scalar metadata indexes for rapid filtered similarity search.", "Maintains an inverted keyword index (BM25) to ensure exact matches for domain-specific acronyms, error codes, and part numbers."]}, {"id": "KP3", "description": "Continuous synchronization, document lifecycle, and version control: managing real-time updates and deprecation.", "required": true, "acceptable_evidence": ["Technical keywords: incremental synchronization, change data capture (CDC), document versioning, soft deletion, zero-downtime reindexing.", "Runs incremental sync pipelines that detect modified or deleted files at the source, updating the vector database via idempotent upserts.", "Flags deprecated documents with version metadata to prevent outdated information from surfacing in search results."]}], "critical_failures": ["Proposing a static, one-time bulk upload without mechanisms for incremental document updates or deletion sync.", "Failing to include hybrid search (dense + sparse) for enterprise terminology and error codes.", "Omitting access control and metadata filtering across diverse organizational departments."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a semantic search or AI platform that can be reused across multiple teams and use cases?', '{"subcategory": "Designing a Reusable Multi-Tenant Semantic Search & AI Platform Across Teams", "key_points": [{"id": "KP1", "description": "Multi-tenant data isolation and security architecture: partitioned collections and RBAC pre-filtering.", "required": true, "acceptable_evidence": ["Technical keywords: multi-tenancy, tenant_id partition key, collection-level isolation, metadata pre-filtering, JWT authentication, RBAC.", "Enforces strict logical or physical separation of vector collections using tenant and team partition keys in Milvus.", "Validates caller identity tokens at the API gateway and injects tenant filter expressions into all database queries."]}, {"id": "KP2", "description": "Self-service developer APIs and customizable pipeline configurations: supporting diverse team use cases.", "required": true, "acceptable_evidence": ["Technical keywords: self-service REST APIs, configurable chunking strategies, pluggable embedding models, custom prompt templates.", "Provides intuitive REST endpoints allowing different engineering teams to provision knowledge bases, upload files, and query search.", "Allows teams to customize pipeline hyperparameters (chunk size, similarity threshold, top-k) to match their specific domain needs."]}, {"id": "KP3", "description": "Platform governance, rate limiting, and cost attribution: managing shared cluster compute and billing.", "required": true, "acceptable_evidence": ["Technical keywords: rate limiting (token bucket), tenant quotas, cost attribution / chargeback, OpenTelemetry, centralized monitoring.", "Enforces per-team rate limits and query quotas to prevent a single team''s burst traffic from degrading cluster performance.", "Tracks token consumption and storage footprint per team to provide transparent departmental cost attribution and billing."]}], "critical_failures": ["Allowing cross-team data access in a shared unpartitioned index without tenant security filters.", "Requiring central platform engineering intervention for every new document upload or team onboarding.", "Omitting rate limiting, resource quotas, or departmental cost attribution."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a system to ensure that document retrieval is restricted to a specific department using metadata filtering?', '{"subcategory": "Restricting Document Retrieval to Specific Departments via Metadata Filtering", "key_points": [{"id": "KP1", "description": "Departmental metadata enrichment during document ingestion: tagging chunks with organizational access attributes.", "required": true, "acceptable_evidence": ["Technical keywords: metadata tagging, department_id, access_control_list (ACL), security_tier, ingestion enrichment, scalar fields.", "Extracts departmental ownership during document ingestion and stores it as an indexed scalar field (e.g. `department: ''Finance''`) in chunk metadata.", "Applies scalar indexing (e.g. inverted index) on categorical fields in the vector database to support rapid filtering."]}, {"id": "KP2", "description": "Runtime user token validation and query filter injection: enforcing access control at the database level.", "required": true, "acceptable_evidence": ["Technical keywords: JWT claims extraction, user department validation, metadata pre-filtering, Milvus boolean expression, zero data leakage.", "Extracts the user''s verified department from cryptographically signed JWT authorization headers at the API gateway.", "Injects the condition directly into the vector search query: `filter=''department in [\"Engineering\", \"Public\"]''`, ensuring no cross-department chunks are retrieved."]}, {"id": "KP3", "description": "Pre-filtering vs. post-filtering security guarantee: why pre-filtering is essential for enterprise RBAC.", "required": true, "acceptable_evidence": ["Technical keywords: pre-filtering security guarantee, post-filtering failure, candidate exhaustion, access boundary enforcement, audit logging.", "Pre-filtering restricts the search space before vector similarity computation, ensuring unauthorized records are never accessed or leaked.", "Post-filtering risks returning zero valid results if the top-k nearest neighbors all belong to unauthorized departments, causing retrieval failure."]}], "critical_failures": ["Suggesting prompt-based access control (asking the LLM to ignore retrieved confidential department text).", "Failing to explain how user identity/department is validated from authentication tokens.", "Omitting the distinction between pre-filtering (secure) and post-filtering (insecure/unreliable)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design unit tests and fallback mechanisms to improve the robustness of a retrieval system?', '{"subcategory": "Designing Unit Tests & Fallback Mechanisms for Retrieval System Robustness", "key_points": [{"id": "KP1", "description": "Multi-tier unit and integration testing strategy: testing parsing, indexing, and search logic deterministically.", "required": true, "acceptable_evidence": ["Technical keywords: unit testing (pytest), mock vector database, synthetic test queries, edge-case validation, empty retrieval handling.", "Tests document chunking and metadata extraction functions on synthetic documents containing corrupted tables and special characters.", "Uses mocked vector database clients to verify that query formatting, scalar filtering, and rank scoring execute correctly without network calls."]}, {"id": "KP2", "description": "Multi-stage fallback mechanisms: graceful degradation when primary retrieval channels fail.", "required": true, "acceptable_evidence": ["Technical keywords: retrieval fallback hierarchy, dense vector failure fallback to BM25, keyword search fallback, cached FAQs, circuit breaker.", "If the primary vector database (Milvus) experiences a timeout or outage, the system automatically falls back to sparse BM25 keyword search.", "If both search channels fail, falls back to a curated static FAQ cache or gracefully displays an operational status message."]}, {"id": "KP3", "description": "Low-confidence detection and generator negative rejection: preventing hallucinations on unanswerable queries.", "required": true, "acceptable_evidence": ["Technical keywords: similarity thresholding, cross-encoder score cutoff, negative constraint fallback (''I do not know''), human escalation.", "Evaluates cross-encoder relevance scores; if all candidate chunks fall below a strict confidence threshold (e.g. <0.4), triggers a negative fallback.", "The system outputs a deterministic response indicating lack of verified knowledge and offers to connect the user to a human specialist."]}], "critical_failures": ["Failing to implement fallback mechanisms when the primary vector database experiences timeouts or outages.", "Lacking confidence score thresholds, allowing low-scoring irrelevant chunks to generate hallucinated answers.", "Omitting unit testing practices for document chunking and query assembly logic."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle a scenario where relevant information is distributed across multiple chunks but the LLM has limited context length?', '{"subcategory": "Handling Information Distributed Across Multiple Chunks with Context Length Limits", "key_points": [{"id": "KP1", "description": "Map-Reduce and hierarchical summarization: compressing distributed evidence before final generation.", "required": true, "acceptable_evidence": ["Technical keywords: Map-Reduce summarization, hierarchical compression, intermediate extraction, token budget allocation, context window management.", "Applies a Map step to summarize or extract key factual points from each retrieved chunk independently.", "Consolidates intermediate extractions into a compact Reduce prompt that fits cleanly within the LLM''s context window."]}, {"id": "KP2", "description": "Parent Document Retrieval and hierarchical chunking: storing small chunks for search but loading larger context.", "required": true, "acceptable_evidence": ["Technical keywords: ParentDocumentRetriever, small-to-big retrieval, sentence-window retrieval, parent doc ID, context expansion.", "Indexes small semantic chunks (e.g. 128 tokens) to optimize similarity search accuracy while linking them to parent sections (e.g. 1024 tokens).", "Retrieves parent sections dynamically, deduplicating overlapping parents to maximize contextual continuity without redundant token waste."]}, {"id": "KP3", "description": "Cross-encoder deduplication and strategic context placement: maximizing information density and mitigating lost-in-the-middle.", "required": true, "acceptable_evidence": ["Technical keywords: cross-encoder score pruning, maximal marginal relevance (MMR), lost-in-the-middle mitigation, evidence fusion.", "Uses MMR or cross-encoder thresholding to eliminate redundant overlapping chunks that consume token space without adding new facts.", "Places the most critical complementary evidence at the top and bottom of the context window to counteract attention decay in long prompts."]}], "critical_failures": ["Simply stuffing all raw retrieved chunks into the prompt until it exceeds token limits or causes out-of-memory errors.", "Failing to explain Map-Reduce summarization or Parent Document Retrieval as concrete solutions.", "Omitting context deduplication and placement strategies to handle context window constraints."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'HARD', 'SPECIFIC', 120, 'Walk me through the technology selection process, detailing the different embedding models (OpenAI, sentence transformers) and (ChromaDB, Milvus) evaluated from proof-of-concept (POC) to production, and the criteria for moving the final solution to production.', '{"subcategory": "Technology Selection Process: Embedding Models & Vector DBs from POC to Production", "key_points": [{"id": "KP1", "description": "Embedding model evaluation: comparing proprietary APIs (OpenAI) vs open-weights models (Sentence Transformers / BGE).", "required": true, "acceptable_evidence": ["Technical keywords: embedding model evaluation, OpenAI text-embedding-3 vs BAAI/bge-large-en, MTEB benchmarks, latency, cost per token, data privacy.", "POC used OpenAI text-embedding-ada/3 for rapid zero-setup prototyping.", "For production, evaluated BGE-large and MiniLM on internal technical documents, choosing BGE-large for superior technical terminology recall, zero data egress, and predictable GPU hosting costs."]}, {"id": "KP2", "description": "Vector database evaluation: comparing local embedded stores (ChromaDB) vs distributed systems (Milvus / Pinecone).", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB vs Milvus vs Pinecone, embedded single-node vs distributed cluster, HNSW indexing, multi-tenancy, high QPS throughput.", "POC utilized ChromaDB due to quick embedded setup without infrastructure provisioning.", "Production required migrating to distributed Milvus on Kubernetes: needed horizontal sharding across 10M+ vectors, sub-15ms P99 latency, and partition-level access control."]}, {"id": "KP3", "description": "Production readiness criteria: establishing objective technical gates for moving to production.", "required": true, "acceptable_evidence": ["Technical keywords: production promotion criteria, P95/P99 latency SLA (<2s), RAGAS evaluation thresholds (Faithfulness > 0.90), high availability, cost attribution.", "Established strict production criteria: latency SLA under peak load, automated evaluation scores exceeding baseline thresholds, and zero data leakage.", "Validated operational monitoring, disaster recovery backups, and role-based access control before final cutover."]}], "critical_failures": ["Presenting technology choices as arbitrary personal preferences rather than structured benchmarking and trade-off analysis.", "Failing to explain why embedded POC tools (ChromaDB) were replaced with distributed systems (Milvus) for production.", "Omitting the specific evaluation criteria and production readiness gates required for promotion."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'What is your experience with RAG-based architecture, and how have you designed and deployed such pipelines?', '{"subcategory": "RAG-Based Architecture Experience: Design, Deployment & Operational Lifecycles", "key_points": [{"id": "KP1", "description": "End-to-end RAG architecture design: architecting layout parsing, hybrid indexing, and foundation model synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: layout-aware parsing (Docling), structure-aware chunking, hybrid retrieval (Milvus HNSW + BM25), cross-encoder reranker, AWS Bedrock.", "Architected enterprise RAG platforms ingesting complex multi-page technical documentation, preserving tables and section hierarchies.", "Implemented hybrid search fused with RRF, scored with cross-encoders, and synthesized with strict citation grounding."]}, {"id": "KP2", "description": "Containerized microservice deployment and cloud infrastructure on AWS: managing Kubernetes and streaming APIs.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservices, Amazon EKS, Docker containerization, Horizontal Pod Autoscaler, Server-Sent Events (SSE) streaming.", "Deployed backend services as containerized FastAPI microservices on Amazon EKS with auto-scaling node groups.", "Delivered real-time token streaming to frontend clients via Server-Sent Events, achieving sub-second time-to-first-token."]}, {"id": "KP3", "description": "Operational governance, security, and automated evaluation: ensuring ongoing accuracy and compliance.", "required": true, "acceptable_evidence": ["Technical keywords: Presidio PII masking, RBAC metadata filtering, RAGAS automated evaluation (Faithfulness, Relevance), CloudWatch telemetry.", "Enforced enterprise security via PII redaction and metadata pre-filtering, and established automated CI/CD evaluation pipelines.", "Monitored live production latency, cost, and hallucination rates through centralized dashboards."]}], "critical_failures": ["Describing simple tutorial scripts without enterprise scale, complex document parsing, or production cloud infrastructure.", "Failing to detail the technical components across all pipeline stages (ingestion, retrieval, ranking, generation).", "Omitting security guardrails, evaluation benchmarking, or operational monitoring."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What retrieval techniques did you use in your RAG pipeline, and how did hybrid search and cross-encoder re-ranking improve performance?', '{"subcategory": "Hybrid Search Retrieval & Cross-Encoder Reranking Performance Gains in RAG", "key_points": [{"id": "KP1", "description": "Hybrid search synergy: combining dense semantic embeddings with sparse lexical keyword matching.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid retrieval, dense vector search (Milvus HNSW), sparse lexical search (BM25 / SPLADE), Reciprocal Rank Fusion (RRF), alpha weighting.", "Dense vectors excel at semantic concepts, paraphrasing, and cross-lingual meaning, but miss exact alphanumeric part numbers and diagnostic codes.", "Sparse BM25 guarantees precision on exact keyword tokens, model numbers, and acronyms.", "Fuses both candidate streams using Reciprocal Rank Fusion (RRF) to produce a high-recall candidate pool."]}, {"id": "KP2", "description": "Cross-Encoder precision reranking mechanics: joint cross-attention scoring on fused candidates.", "required": true, "acceptable_evidence": ["Technical keywords: Cross-Encoder reranker (bge-reranker-large), joint cross-attention, candidate pool pruning (top-50 to top-5), score calibration.", "Evaluates the top-50 fused candidates with a cross-encoder model that computes all-to-all cross-attention between query and chunk tokens.", "Discards irrelevant distractor passages and reorders the most accurate factual evidence to the top."]}, {"id": "KP3", "description": "Quantifiable retrieval quality and business performance metrics: boosting Hit Rate and reducing hallucinations.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, MRR (Mean Reciprocal Rank), Precision@5, hallucination rate reduction, RAGAS Context Precision.", "Hybrid retrieval boosts candidate recall from 74% to 93%, while cross-encoder reranking increases Precision@5 from 62% to 89%.", "Directly reduces downstream generator hallucinations by eliminating misleading distractors from the prompt context."]}], "critical_failures": ["Relying on dense vector search alone without explaining why sparse BM25 is critical for exact terms and part numbers.", "Confusing Cross-Encoders with Bi-Encoders and failing to explain their joint attention scoring mechanism.", "Omitting the quantitative performance improvements achieved by combining hybrid search with reranking."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'What role did LangChain and LangGraph play in your system, and how did you extend RAG into agentic workflows?', '{"subcategory": "LangChain & LangGraph in Production: Extending Static RAG into Agentic Workflows", "key_points": [{"id": "KP1", "description": "Role of LangChain in pipeline components: managing document processing, prompt templates, and model integrations.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain LCEL, Document loaders, TextSplitters, vector store abstractions (Milvus), prompt templates.", "Provides standardized abstractions for document loading, chunking, and vector database querying.", "Acts as the component-level toolkit for integrating foundation models and formatting prompt inputs."]}, {"id": "KP2", "description": "Role of LangGraph in stateful orchestration: moving beyond DAG chains to cyclic multi-agent graphs.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, cyclic graphs, supervisor routing, state persistence (checkpointers), conditional branching.", "Introduces cyclic graph topology where execution can evaluate intermediate findings, loop back, and branch dynamically.", "Maintains typed state across multi-turn user sessions and coordinates specialized worker agent nodes."]}, {"id": "KP3", "description": "Extending static RAG into agentic workflows: incorporating dynamic query reformulation, tools, and HITL gates.", "required": true, "acceptable_evidence": ["Technical keywords: agentic RAG, dynamic query rewriting, tool calling (CRM, booking), self-correction, Human-in-the-Loop interrupt.", "Enables the agent to inspect retrieval sufficiency; if retrieved context is inadequate, the agent reformulates queries or calls external tools.", "Embeds Human-in-the-Loop approval interrupts before executing sensitive external API write actions."]}], "critical_failures": ["Treating LangChain and LangGraph as interchangeable tools without recognizing DAG linear chains vs cyclic state graphs.", "Failing to explain how LangGraph enables dynamic query reformulation, tool invocation, and stateful loops.", "Omitting Human-in-the-Loop controls or self-correction mechanisms in agentic RAG workflows."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement re-ranking in your retrieval pipeline, and what role did cross-encoders play in improving results?', '{"subcategory": "Re-Ranking Implementation in Retrieval Pipelines: Role of Cross-Encoders", "key_points": [{"id": "KP1", "description": "Implementation architecture: inserting cross-encoder rerankers between initial retrieval and prompt assembly.", "required": true, "acceptable_evidence": ["Technical keywords: two-stage retrieval pipeline, first-stage vector/BM25 retrieval (top-50), reranking layer (bge-reranker-large), top-5 pruning.", "Inserts a cross-encoder scoring stage immediately following first-stage hybrid retrieval.", "Takes the top-50 candidate chunks returned by Milvus and BM25 and scores each query-chunk pair through the cross-encoder model."]}, {"id": "KP2", "description": "Cross-Encoder cross-attention scoring mechanics: deep pairwise token interaction.", "required": true, "acceptable_evidence": ["Technical keywords: full cross-attention, concatenated input [CLS] query [SEP] passage [SEP], uncompressed semantic alignment, score calibration.", "Unlike bi-encoders which compress text into isolated vectors, cross-encoders compute joint cross-attention across all query and chunk tokens.", "Accurately scores subtle semantic nuances, negations, and exact entity matches that vector cosine distance overlooks."]}, {"id": "KP3", "description": "Impact on retrieval precision and prompt efficiency: maximizing context density and minimizing noise.", "required": true, "acceptable_evidence": ["Technical keywords: Precision@5 improvement, Context Precision, noise filtering, token budget optimization, hallucination suppression.", "Prunes candidate pools down to the top-5 highest-confidence chunks, discarding distractor noise.", "Concentrates factual density in the prompt, dramatically cutting generator hallucinations while reducing unnecessary token consumption."]}], "critical_failures": ["Failing to place the reranker in a two-stage retrieval funnel (broad recall first stage $\\rightarrow$ precision reranking).", "Confusing cross-encoders with bi-encoders or vector index re-sorting.", "Omitting the impact of cross-encoders on reducing prompt token waste and hallucinations."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How do you evaluate the performance of RAG systems, and what metrics such as RAGAS or BERTScore have you used?', '{"subcategory": "RAG System Performance Evaluation: RAGAS Framework & BERTScore Metrics", "key_points": [{"id": "KP1", "description": "RAGAS component-level evaluation framework: separating retrieval metrics from generation metrics.", "required": true, "acceptable_evidence": ["Technical keywords: RAGAS framework, Context Precision, Context Recall, Faithfulness, Answer Relevance, LLM-as-a-judge.", "Evaluates the retrieval stage independently using Context Precision (relevance of retrieved chunks) and Context Recall (coverage of reference facts).", "Evaluates the generation stage using Faithfulness (absence of hallucination / context entailment) and Answer Relevance (directness to user query)."]}, {"id": "KP2", "description": "BERTScore evaluation mechanics: soft semantic embedding matching against reference answers.", "required": true, "acceptable_evidence": ["Technical keywords: BERTScore (F1, Precision, Recall), contextual embeddings (RoBERTa/DeBERTa), token cosine similarity, greedy matching.", "Computes pairwise token cosine similarities between generated responses and human-curated reference answers.", "Captures semantic equivalence and synonyms robustly, overcoming the rigid lexical limitations of BLEU and ROUGE."]}, {"id": "KP3", "description": "Production integration and automated regression gates: continuous benchmarking in CI/CD pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: golden evaluation dataset, CI/CD regression testing, automated evaluation gates, performance thresholds, regression alerting.", "Runs automated RAGAS and BERTScore evaluation pipelines against golden test sets on every prompt or index modification in CI/CD.", "Enforces minimum thresholds (e.g. Faithfulness >= 0.90, Answer Relevance >= 0.85) to gate production deployments."]}], "critical_failures": ["Relying on manual anecdotal testing (''vibe checks'') without automated quantitative evaluation frameworks.", "Failing to separate retrieval evaluation (Context Precision/Recall) from generation evaluation (Faithfulness).", "Omitting how evaluation metrics are automated as regression gates in production CI/CD pipelines."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'SPECIFIC', 90, 'How have you used frameworks like LangGraph and such as PGVector in designing agentic AI systems?', '{"subcategory": "Designing Agentic AI Systems Using LangGraph & Vector Stores (PGVector/Milvus)", "key_points": [{"id": "KP1", "description": "LangGraph stateful orchestration: modeling agent decision trees, tool execution, and cyclic reflection.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, conditional edges, supervisor router, tool nodes, cyclic reflection, state persistence.", "Defines stateful graphs where agent nodes evaluate user inquiries, invoke specialized tools, and inspect results cyclically.", "Enables dynamic self-correction loops when intermediate retrieval or tool outputs require refinement."]}, {"id": "KP2", "description": "Vector store integration as an agent tool: exposing semantic search and metadata filtering to graph nodes.", "required": true, "acceptable_evidence": ["Technical keywords: vector store tool (PGVector / Milvus), semantic retrieval node, metadata pre-filtering, dynamic query generation.", "Wraps vector search functions into structured tools callable by agent nodes with dynamically generated search queries and filters.", "Enforces metadata filtering at the database layer to ensure agents retrieve only authorized and contextually relevant passages."]}, {"id": "KP3", "description": "State management, session persistence, and Human-in-the-Loop governance: ensuring durable execution.", "required": true, "acceptable_evidence": ["Technical keywords: persistent checkpointer (Postgres / Redis), thread_id, Human-in-the-Loop (HITL) interrupt, Pydantic validation.", "Persists conversation state across multi-turn sessions using database checkpointers bound to unique session threads.", "Integrates interrupt approval nodes to pause execution for human verification before the agent executes consequential actions."]}], "critical_failures": ["Describing simple linear retrieval chains without cyclic graph orchestration or tool nodes.", "Failing to explain how vector search is integrated as an invokable tool within the agent graph.", "Omitting state checkpointing and Human-in-the-Loop governance."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How would you design an evaluation pipeline to identify issues in preprocessing, chunking, or retrieval?', '{"subcategory": "Designing Comprehensive Evaluation Pipelines to Diagnose Preprocessing, Chunking & Retrieval Issues", "key_points": [{"id": "KP1", "description": "Preprocessing and parsing stage evaluation: measuring document extraction fidelity, table integrity, and OCR accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: document parsing evaluation, table extraction accuracy, cell alignment, OCR character error rate (CER), visual layout fidelity.", "Evaluates document extraction by comparing parsed Markdown against ground-truth document structure.", "Measures table reconstruction fidelity and flags formatting corruption that leads to broken semantic relationships."]}, {"id": "KP2", "description": "Chunking strategy evaluation: diagnosing information fragmentation and semantic boundary cutoffs.", "required": true, "acceptable_evidence": ["Technical keywords: chunking boundary evaluation, context fragmentation, semantic coherence, chunk size vs density, sentence boundary preservation.", "Tests whether critical operational steps or sentences are split across chunk seams, causing incomplete semantic context.", "Audits chunk size and overlap ratios against downstream embedding model attention limits."]}, {"id": "KP3", "description": "Retrieval and ranking stage evaluation: benchmarking candidate recall and ranking precision.", "required": true, "acceptable_evidence": ["Technical keywords: Hit Rate@K, Mean Reciprocal Rank (MRR), NDCG@K, RAGAS Context Recall, Cross-Encoder score distribution.", "Measures whether gold-standard passages are present in the top-50 initial candidate pool (Hit Rate@50).", "Evaluates whether the cross-encoder correctly ranks the most relevant chunk at rank 1 or 2 (NDCG@5, MRR), pinpointing retrieval bottlenecks."]}], "critical_failures": ["Evaluating only the final LLM text output without isolating intermediate preprocessing, chunking, and retrieval stages.", "Failing to define metrics for document parsing and table extraction accuracy.", "Omitting retrieval benchmark metrics (Hit Rate@K, MRR, Context Recall) in the diagnostic pipeline."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'SPECIFIC', 90, 'What considerations led you to choose different like ChromaDB, PGVector, and Milvus, and how did you evaluate their performance and scalability?', '{"subcategory": "Vector Database Selection Rationale: ChromaDB vs. PGVector vs. Milvus Across Performance & Scale", "key_points": [{"id": "KP1", "description": "ChromaDB evaluation profile: lightweight embedded store for rapid POCs and local experimentation.", "required": true, "acceptable_evidence": ["Technical keywords: ChromaDB, embedded vector database, local prototyping, zero infrastructure, single-node limitations.", "Selected for rapid POC experimentation due to zero-configuration local installation and simple Python SDK.", "Disqualified for production due to lack of distributed sharding, multi-tenancy, and high-concurrency scalability."]}, {"id": "KP2", "description": "PGVector evaluation profile: relational extension for small-to-medium datasets within PostgreSQL ecosystems.", "required": true, "acceptable_evidence": ["Technical keywords: PGVector, PostgreSQL extension, relational joins, ACID compliance, HNSW index, resource contention.", "Attractive for applications already using PostgreSQL, enabling joint SQL and vector queries in a single transaction.", "Encountered scaling bottlenecks at scale (>5M vectors): high RAM usage, shared buffer saturation, and vacuum performance degradation."]}, {"id": "KP3", "description": "Milvus evaluation profile: purpose-built distributed vector database for enterprise production at massive scale.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus distributed, cloud-native architecture, disaggregated compute/storage, horizontal sharding, sub-15ms P99 latency, multi-tenancy.", "Chosen for enterprise production: handles tens of millions of vectors with sub-15ms latency and thousands of concurrent QPS.", "Provides disaggregated storage/compute scaling on Kubernetes, partition keys for tenant isolation, and enterprise high availability."]}], "critical_failures": ["Recommending ChromaDB for high-throughput distributed enterprise production serving.", "Failing to explain how PGVector enables relational SQL joins with vector embeddings in PostgreSQL.", "Omitting Milvus''s distributed compute-storage disaggregation and multi-tenant scaling capabilities."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'HARD', 'SPECIFIC', 120, 'Which embedding models and have you used, and how do they compare in terms of performance and scalability?', '{"subcategory": "Embedding Model Comparative Analysis: Performance, Scalability & Architecture", "key_points": [{"id": "KP1", "description": "Comparative evaluation of embedding architectures: open-weights models (BGE, MiniLM) vs proprietary APIs (OpenAI text-embedding-3).", "required": true, "acceptable_evidence": ["Technical keywords: BAAI/bge-large-en, all-MiniLM-L6-v2, OpenAI text-embedding-3, MTEB benchmarks, representation quality, dimensionality.", "Evaluated models across retrieval accuracy benchmarks: BGE-large achieves top MTEB scores with 1024-dim dense vectors for complex technical text.", "all-MiniLM-L6-v2 offers ultra-fast inference and low memory (384-dim), ideal for edge or CPU deployments.", "OpenAI text-embedding-3 provides high quality with zero hosting management but incurs recurring per-token API costs and latency."]}, {"id": "KP2", "description": "Scalability, inference throughput, and hardware acceleration: self-hosting on GPU clusters.", "required": true, "acceptable_evidence": ["Technical keywords: GPU batch inference, Triton Inference Server / vLLM, TensorRT / ONNX Runtime, throughput (tokens/sec), FP16 / INT8 quantization.", "Self-hosting Sentence Transformers on GPU nodes with Triton Inference Server maximizes batch inference throughput for bulk document indexing.", "Applies FP16 and ONNX Runtime optimizations to cut embedding latency by over 50% under concurrent traffic."]}, {"id": "KP3", "description": "Operational trade-offs: data privacy, network egress, rate limits, and cost economics.", "required": true, "acceptable_evidence": ["Technical keywords: data privacy, zero egress, compliance boundaries, third-party API rate limits, cost predictability.", "Self-hosted open models guarantee enterprise data never leaves private VPC boundaries, meeting strict compliance requirements.", "Eliminates third-party API rate limiting, network egress costs, and unexpected provider pricing changes."]}], "critical_failures": ["Failing to compare embedding models across representation quality (MTEB), latency, and dimensional trade-offs.", "Ignoring the operational differences between self-hosted models (GPU inference, privacy) and closed commercial APIs.", "Omitting hardware acceleration or batch throughput optimization in embedding generation."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'SPECIFIC', 120, 'You mentioned using LangGraph and other tools. Why did you choose LangChain and LangGraph for your RAG system? System Design & Architecture', '{"subcategory": "System Architecture Rationale: Choosing LangChain & LangGraph for Enterprise RAG", "key_points": [{"id": "KP1", "description": "LangChain''s modular component ecosystem: standardizing document loaders, text splitters, and model integrations.", "required": true, "acceptable_evidence": ["Technical keywords: LangChain ecosystem, modular abstractions, Document loaders, TextSplitters, vector store integrations (Milvus), prompt templates.", "Leverages LangChain''s mature ecosystem of connectors to integrate heterogeneous data sources, chunkers, and embedding models cleanly.", "Eliminates custom boilerplate for interacting with foundational models and vector databases."]}, {"id": "KP2", "description": "LangGraph''s cyclic stateful orchestration: enabling multi-agent coordination, branching, and self-correction.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph StateGraph, cyclic workflows, supervisor routing, state persistence (checkpointers), conditional edges, self-correction.", "Selected LangGraph over rigid DAG pipelines to support cyclic agent workflows that evaluate intermediate outputs and retry.", "Enables supervisory routing across specialized domain agents, dynamic tool execution, and stateful multi-turn memory."]}, {"id": "KP3", "description": "Production durability and Human-in-the-Loop governance: managing checkpoints and approval gates.", "required": true, "acceptable_evidence": ["Technical keywords: persistent checkpointer (Postgres/Redis), thread checkpointing, Human-in-the-Loop (HITL) interrupt, production auditability.", "Provides native checkpointing primitives allowing long-running multi-turn sessions to survive server restarts.", "Enables first-class Human-in-the-Loop interrupt gates to pause workflows for operator authorization before high-risk tool actions."]}], "critical_failures": ["Treating LangChain and LangGraph as redundant duplicates rather than complementary toolkits (components vs cyclic orchestration).", "Failing to explain why cyclic graph execution and state checkpointing are essential for production agentic workflows.", "Omitting Human-in-the-Loop governance and error recovery capabilities."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 120, 'Can you describe an end-to-end AI/ML project you worked on, including system architecture, tools used, and your specific contributions?', '{"subcategory": "End-to-End AI/ML Project Architecture: System Design, Toolchain & Technical Contributions", "key_points": [{"id": "KP1", "description": "System architecture and technical problem framing: architecting an enterprise conversational AI platform.", "required": true, "acceptable_evidence": ["Technical keywords: enterprise AI project, EV customer call center assistant / TalentScreen, system topology, unstructured ingestion, knowledge retrieval.", "Architected an end-to-end RAG and multi-agent assistant designed to resolve complex customer vehicle inquiries and automate support tickets.", "Decomposed the platform into decoupled microservices: ingestion pipeline, hybrid search service, and multi-agent orchestrator."]}, {"id": "KP2", "description": "Toolchain selection and technical implementation: integrating parsing, vector databases, rerankers, and foundation models.", "required": true, "acceptable_evidence": ["Technical keywords: Docling layout parsing, Milvus distributed vector DB, BM25 keyword search, cross-encoder (bge-reranker-large), LangGraph, Claude 3.5 Sonnet on AWS Bedrock.", "Employed Docling for table-aware document extraction, Milvus and BM25 for hybrid retrieval, and cross-encoders for precision ranking.", "Orchestrated multi-agent workflows using LangGraph with state persistence and transactional tool execution."]}, {"id": "KP3", "description": "Individual technical contributions, production engineering, and measurable impact: owning architecture and outcomes.", "required": true, "acceptable_evidence": ["Technical keywords: individual contributions, FastAPI microservices on Amazon EKS, Presidio PII masking, RAGAS automated CI/CD evaluation, 35% AHT reduction, deflection.", "Personally designed the hybrid retrieval and reranking logic, implemented PII sanitization guardrails, and established automated CI/CD evaluation suites.", "Deployed services to Amazon EKS, achieving sub-1.5s P95 streaming latency and reducing average support handle time by 35%."]}], "critical_failures": ["Describing team achievements without specifying individual technical contributions and architectural ownership.", "Failing to detail the concrete toolchain and system architecture across the entire pipeline.", "Omitting quantitative operational metrics and production business outcomes."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 120, 'Can you describe your most recent AI project, including its overall architecture and key use cases?', '{"subcategory": "Recent AI Project Deep Dive: Overall Architecture, Key Use Cases & Technical Delivery", "key_points": [{"id": "KP1", "description": "Project context and core enterprise use cases: automating high-consequence customer operations.", "required": true, "acceptable_evidence": ["Technical keywords: recent AI project, EV customer call center assistant, diagnostic troubleshooting, warranty validation, appointment booking.", "Delivered an intelligent customer care platform addressing multi-faceted vehicle inquiries: error code troubleshooting, warranty verification, and technician dispatch.", "Transformed customer support operations from manual agent lookup to automated end-to-end resolution."]}, {"id": "KP2", "description": "Multi-tier system architecture: ingestion, hybrid retrieval, agentic orchestration, and foundation model serving.", "required": true, "acceptable_evidence": ["Technical keywords: Docling parsing, Milvus distributed, BM25, cross-encoder reranker, LangGraph StateGraph, AWS Bedrock (Claude 3.5 Sonnet).", "Ingested technical manuals and dealer bulletins using Docling, indexing chunks into Milvus and BM25 for hybrid search.", "Employed LangGraph multi-agent supervisors to dynamically coordinate between technical diagnostic agents and transactional booking tools."]}, {"id": "KP3", "description": "Production performance, safety guardrails, and business outcomes: ensuring reliability and scale.", "required": true, "acceptable_evidence": ["Technical keywords: Presidio PII masking, Server-Sent Events (SSE) streaming, RAGAS evaluation, Amazon EKS deployment, 42% deflection rate.", "Protected user privacy via automated PII redaction and ensured low-latency streaming responses via FastAPI on Amazon EKS.", "Achieved 42% automated call deflection and reduced support costs while maintaining 91% answer faithfulness."]}], "critical_failures": ["Speaking in vague generalities without defining the concrete business use cases or technical architecture.", "Failing to detail how retrieval, reranking, and multi-agent coordination were implemented.", "Omitting safety guardrails, deployment infrastructure, or business impact metrics."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you describe your professional background and experience leading AI system development and architecture?', '{"subcategory": "Leadership & Technical Ownership in AI System Development and Architecture", "key_points": [{"id": "KP1", "description": "Architectural leadership and technical vision: defining standards, framework selection, and system blueprints.", "required": true, "acceptable_evidence": ["Technical keywords: technical leadership, architectural decision records (ADRs), system design blueprints, framework selection (LangGraph vs alternatives), technical governance.", "Led architectural design for enterprise AI initiatives, authoring technical RFCs and establishing standards for state schemas, tool contracts, and model gateways.", "Guided teams through complex architectural evaluations, balancing time-to-market against long-term maintainability."]}, {"id": "KP2", "description": "Cross-functional collaboration and engineering enablement: mentoring teams and bridging technical and business domains.", "required": true, "acceptable_evidence": ["Technical keywords: cross-functional leadership, mentoring junior engineers, code reviews, stakeholder communication, translating AI capabilities into business ROI.", "Mentored engineering teams on probabilistic AI patterns: debugging agent trajectories, designing regression test suites, and handling non-deterministic failures.", "Partnered closely with product management and executive stakeholders to align AI technical roadmaps with business KPIs."]}, {"id": "KP3", "description": "Accountability for operational excellence, security, and production outcomes: ensuring reliability at scale.", "required": true, "acceptable_evidence": ["Technical keywords: production accountability, P95/P99 latency SLAs, security compliance (RBAC, PII), automated CI/CD evaluation, incident response.", "Held end-to-end accountability for production uptime, latency budgets, token expenditure, and data isolation.", "Instituted automated evaluation gates in CI/CD to prevent regressions and maintained a blameless post-mortem culture for operational incidents."]}], "critical_failures": ["Portraying oneself purely as an individual feature coder without demonstrating architectural leadership or governance.", "Failing to articulate how technical decisions were communicated and aligned across cross-functional teams.", "Omitting operational accountability for system reliability, security, and business outcomes."]}', 1),
('HIRING_MANAGER', 'Behavioral & Leadership', 'Career Trajectory & Background', 'MEDIUM', 'BROAD', 90, 'Can you walk through your professional experience across different roles and technologies, highlighting your transition from frontend to full-stack development?', '{"subcategory": "Career Progression: Frontend to Full-Stack Engineering & AI Systems Architecture", "key_points": [{"id": "KP1", "description": "Frontend engineering roots: mastering user experience, responsive state management, and asynchronous client communication.", "required": true, "acceptable_evidence": ["Technical keywords: frontend foundation, React.js, TypeScript, state management, asynchronous event handling, user-centric engineering.", "Began career developing responsive web interfaces, building deep expertise in client-side state, event-driven architectures, and performance optimization.", "Established a strong user-centric mindset that prioritizes intuitive, low-latency interactions in modern software."]}, {"id": "KP2", "description": "Evolution into Full-Stack & Systems Engineering: mastering backend microservices, databases, and cloud infrastructure.", "required": true, "acceptable_evidence": ["Technical keywords: full-stack transition, backend API design (FastAPI, Node.js), relational/NoSQL databases, Docker, distributed systems, CI/CD.", "Expanded scope into backend engineering: designing REST/gRPC APIs, architecting database schemas, and managing containerized cloud deployments.", "Developed end-to-end systems fluency, understanding how data flows from database storage through API gateways to the client UI."]}, {"id": "KP3", "description": "Culmination in Generative AI & Agentic Platforms: building seamless end-to-end AI applications.", "required": true, "acceptable_evidence": ["Technical keywords: AI engineering, Server-Sent Events (SSE) streaming, conversational UI, LangGraph, RAG pipelines, full-stack AI delivery.", "Combines frontend user experience strengths with backend AI orchestration: building real-time token streaming interfaces, citation popups, and Human-in-the-Loop review portals.", "Demonstrates unique versatility: capable of owning the entire AI product lifecycle from data ingestion to interactive user presentation."]}], "critical_failures": ["Treating frontend background as a liability rather than a core strength in building modern streaming AI interfaces.", "Failing to explain the technical steps and milestones undertaken to master backend systems and cloud infrastructure.", "Omitting how full-stack capabilities directly enable building end-to-end Generative AI products."]}', 1);
